window.CARDS=window.CARDS||{};CARDS["story-v-y2v4-index"]=[{"i":"sc-amasawa-ichika-y2v4-p4-1","v":"y2v4","y":2,"o":19,"k":"","w":"amasawa-ichika","q":"amasawa ichika amasawa mentioned in passing front matter name hits only  table of contents  amasawa s name appears on the toc page with the chapter titles","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v4-p4-1\"><h3><span class=\"ttl\"><a href=\"../../../people/amasawa-ichika.html#sc-amasawa-ichika-y2v4-p4-1\">Amasawa mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.4<\/span><span class=\"by\">notes on <a href=\"../../../people/amasawa-ichika.html\">Amasawa Ichika<\/a><\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Front-matter name hits only (table of contents): Amasawa&#x27;s name appears on the TOC page with the chapter titles.<span class=\"pg\">p.4<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v4-p5-1\">→ After: Prologue: Amasawa&#x27;s monologue on the White Room<\/button><\/div><\/article>"},{"i":"sc-kouenji-rokusuke-y2v4-p4-1","v":"y2v4","y":2,"o":19,"k":"","w":"kouenji-rokusuke","q":"koenji rokusuke koenji mentioned in passing front matter name hits only  table of contents  koenji s name appears on the toc page with the chapter titles","h":"<article class=\"card\" id=\"sc-kouenji-rokusuke-y2v4-p4-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kouenji-rokusuke.html#sc-kouenji-rokusuke-y2v4-p4-1\">Kōenji mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.4<\/span><span class=\"by\">notes on <a href=\"../../../people/kouenji-rokusuke.html\">Kōenji Rokusuke<\/a><\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Front-matter name hits only (table of contents): Kōenji&#x27;s name appears on the TOC page with the chapter titles.<span class=\"pg\">p.4<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kouenji-rokusuke-y2v4-p42-1\">→ After: Kōenji mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-tsukishiro-y2v4-p4-1","v":"y2v4","y":2,"o":19,"k":"","w":"tsukishiro","q":"tsukishiro tsukishiro mentioned in passing front matter name hits only  table of contents  tsukishiro s name appears on the toc page with the chapter titles","h":"<article class=\"card\" id=\"sc-tsukishiro-y2v4-p4-1\"><h3><span class=\"ttl\"><a href=\"../../../people/tsukishiro.html#sc-tsukishiro-y2v4-p4-1\">Tsukishiro mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.4<\/span><span class=\"by\">notes on <a href=\"../../../people/tsukishiro.html\">Tsukishiro<\/a><\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Front-matter name hits only (table of contents): Tsukishiro&#x27;s name appears on the TOC page with the chapter titles.<span class=\"pg\">p.4<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsukishiro-y2v4-p18-1\">→ After: Tsukishiro mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-amasawa-ichika-y2v4-p5-1","v":"y2v4","y":2,"o":19,"k":"narration","w":"ayanokouji-kiyotaka amasawa-ichika","q":"amasawa ichika prologue  amasawa s monologue on the white room in her own monologue  she reveals she is an ivf  test tube  baby brought into the white room  with no knowledge of her parents   i am one of those born from that very process  a human brought about through in vitro fertilization   my existence runs in direct conflict with that of the white room   i personally concluded long ago that it s impossible to homogenize intellect  personality  and ethics   wouldn t that be like  you know  kinda pathetic  wouldn t you want to live more freely   ayanokoji kiyotaka  the being whose preeminent success stood out from the rest of the white room   however  i m sorry senpai  i really want to take your side  but that s just not how fate is going to play out   as one of your faithful admirers  i ll be looking on from a distance once  that time  finally comes  proud of being different  secretly questions the white room s purpose  it seeks to prove ability comes from environment  not genetics   her existence refutes it  and admires ayanokoji from afar  resolved not to devote her life to the facility s ideals  hints she has aligned with people she s known much longer  not ayanokoji  despite admiring him  she idolizes him but says fate prevents her from taking his side","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v4-p5-1\"><h3><span class=\"ttl\"><a href=\"../../../people/amasawa-ichika.html#sc-amasawa-ichika-y2v4-p5-1\">Prologue: Amasawa&#x27;s monologue on the White Room<\/a><\/span><span class=\"meta\">Y2V4 · p.5–7<\/span><span class=\"by\">notes on <a href=\"../../../people/amasawa-ichika.html\">Amasawa Ichika<\/a><\/span><\/h3><p class=\"setup\">In her own monologue, she reveals she is an IVF (“test-tube”) baby brought into the White Room, with no knowledge of her parents.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Amasawa Ichika<\/b> “I am one of those born from that very process. A human brought about through in vitro fertilization.”<span class=\"pg\">p.5<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Amasawa Ichika<\/b> “my existence runs in direct conflict with that of the White Room.”<span class=\"pg\">p.5<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Amasawa Ichika<\/b> “I personally concluded long ago that it’s impossible to homogenize intellect, personality, and ethics.”<span class=\"pg\">p.6<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> “Wouldn’t that be like, you know, kinda pathetic? Wouldn’t you want to live more freely?”<span class=\"pg\">p.6<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> “Ayanokōji Kiyotaka. The being whose preeminent success stood out from the rest of the White Room.”<span class=\"pg\">p.6<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> “However, I’m sorry Senpai. I really want to take your side, but that’s just not how fate is going to play out.”<span class=\"pg\">p.7<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> “As one of your faithful admirers, I’ll be looking on from a distance once ‘that time’ finally comes.”<span class=\"pg\">p.7<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Proud of being different, secretly questions the White Room’s purpose (it seeks to prove ability comes from environment, not genetics — her existence refutes it), and admires Ayanokōji from afar; resolved not to devote her life to the facility’s ideals; hints she has aligned with people she’s known much longer (not Ayanokōji), despite admiring him.<span class=\"pg\">p.5–7<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> She idolizes him but says fate prevents her from taking his side.<span class=\"pg\">p.6–7<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v4-p4-1\">← Before: Amasawa mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v4-p8-1\">→ After: Ch.1: Amasawa confronts them in the rain<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v4-p5-1","v":"y2v4","y":2,"o":19,"k":"","w":"ayanokouji-kiyotaka","q":"ayanokoji kiyotaka prologue note  amasawa s monologue   her own page  the prologue is amasawa ichika s own monologue  an ivf test tube  baby raised in the white room    recorded on her own page  not attributed here   ayanokoji kiyotaka  the being whose preeminent success stood out from the rest of the white room    amasawa s monologue","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v4-p5-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v4-p5-1\">Prologue note (Amasawa&#x27;s monologue — her own page)<\/a><\/span><span class=\"meta\">Y2V4 · p.5–7<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> The prologue is Amasawa Ichika’s own monologue (an IVF/“test-tube” baby raised in the White Room) — recorded on her own page, not attributed here.<span class=\"pg\">p.5<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Ayanokōji Kiyotaka. The being whose preeminent success stood out from the rest of the White Room.” — Amasawa’s monologue.<span class=\"pg\">p.6<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p8-1\">→ After: Ch.1: Amasawa appears in the rain<\/button><\/div><\/article>"},{"i":"sc-shibata-sou-y2v4-p5-1","v":"y2v4","y":2,"o":19,"k":"","w":"shibata-sou","q":"shibata so shibata not present page locator found zero matches for shibata in year 2  vol  4  he is not on any page of this volume","h":"<article class=\"card\" id=\"sc-shibata-sou-y2v4-p5-1\"><h3><span class=\"ttl\"><a href=\"../../../people/shibata-sou.html#sc-shibata-sou-y2v4-p5-1\">Shibata not present<\/a><\/span><span class=\"meta\">Y2V4 · p.5–284<\/span><span class=\"by\">notes on <a href=\"../../../people/shibata-sou.html\">Shibata Sō<\/a><\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Page locator found zero matches for Shibata in Year 2, Vol. 4; he is not on any page of this volume.<span class=\"pg\">p.5–284<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-yamamura-miki-y2v4-p5-1","v":"y2v4","y":2,"o":19,"k":"","w":"yamamura-miki","q":"yamamura miki yamamura not present page locator found zero matches for yamamura miki in year 2  vol  4  she is not on any page of this volume","h":"<article class=\"card\" id=\"sc-yamamura-miki-y2v4-p5-1\"><h3><span class=\"ttl\"><a href=\"../../../people/yamamura-miki.html#sc-yamamura-miki-y2v4-p5-1\">Yamamura not present<\/a><\/span><span class=\"meta\">Y2V4 · p.5–284<\/span><span class=\"by\">notes on <a href=\"../../../people/yamamura-miki.html\">Yamamura Miki<\/a><\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Page locator found zero matches for Yamamura Miki in Year 2, Vol. 4; she is not on any page of this volume.<span class=\"pg\">p.5–284<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-amasawa-ichika-y2v4-p8-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"nanase-tsubasa ayanokouji-kiyotaka amasawa-ichika","q":"amasawa ichika ch 1  amasawa confronts them in the rain in the downpour  an ominous presence stops behind ayanokoji and nanase   she is standing there in the rain  red hair swaying  class 1 a s amasawa ichika  empty handed except for a thick wooden stick clasped in her left hand  no backpack or tablet  tracked them via table  gps relay  or tailing   seems it s gonna really start coming down  huh sen pai   oh  nanase chan  shouldn t you be happy to see me  how aw fully cold you are to a dear companion from your very own group  wait  are you perhaps nervous about this little stick friend of mine   how me an  how could you say something like that  i m super duper cute   jeez  i m not some bad guy  right ayanokoji senpai  i just wanna chat for a bit  kay   you were about to lay your hands on ayanokoji senpai  weren t you   back then  the one watching us from the shadows was you  wasn t it amasawa san   ahaha  so i was seen after all   eh  aren t you just  like  jumping to conclusions  maybe i just happened to be in the neighborhood   i can swear it  sure  but it doesn t really matter whether i keep my word or not  right   ding ding ding  correct  whether intentionally done or not  a broken watch is a broken watch  and you can get it replaced for free too   poking holes in the rules is standard practice  if the school can t even find any evidence  you re free to do whatever you want   same difference  be it my broken gps or my presence at the scene of the crime  it would only end with suspicion at best  she admits to tailing them at the slope  nanase caught her red hair  baits nanase s interrogation and stonewalls on the komiya kinoshita attack  she shows them the broken watch to prove she could erase her gps  she correctly reads that a first year with a spotless record will not be found guilty without evidence   and that shinohara only saw a vague figure  theatre and evasion   arrives conspicuously  tosses the stick down as a show of good faith  p 9  laughs off being caught red handed  turns nanase s accusation into wordplay  ayanokoji notes she has  extraordinary acting skills and the uncanny ability to put plans into action   p 10  nanase orders her  you  cannot be trusted  and stays between her and ayanokoji  amasawa needles nanase as his  knight in shining armor   p 15  she approaches him uninvited carrying a weapon she never uses  he says nothing to signal trust either way","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v4-p8-1\"><h3><span class=\"ttl\"><a href=\"../../../people/amasawa-ichika.html#sc-amasawa-ichika-y2v4-p8-1\">Ch.1: Amasawa confronts them in the rain<\/a><\/span><span class=\"meta\">Y2V4 · p.8–14<\/span><span class=\"by\">notes on <a href=\"../../../people/amasawa-ichika.html\">Amasawa Ichika<\/a><\/span><\/h3><p class=\"setup\">In the downpour, an ominous presence stops behind Ayanokōji and Nanase — she is standing there in the rain, red hair swaying; Class 1-A’s Amasawa Ichika; empty-handed except for a thick wooden stick clasped in her left hand, no backpack or tablet (tracked them via Table, GPS relay, or tailing).<\/p><p class=\"with\">with <a href=\"../../../people/nanase-tsubasa.html\">Nanase Tsubasa<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Amasawa Ichika<\/b> “Seems it’s gonna really start coming down, huh Sen~pai?”<span class=\"pg\">p.8<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Amasawa Ichika<\/b> “Oh? Nanase-chan, shouldn’t you be happy to see me? How aw~fully cold you are to a dear companion from your very own group. Wait, are you perhaps nervous about this little stick friend of mine~?”<span class=\"pg\">p.9<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Amasawa Ichika<\/b> “How me~an. How could you say something like that? I’m super-duper cute~!”<span class=\"pg\">p.9<\/span><\/li><\/ul><details class=\"more\"><summary>13 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Jeez. I’m not some bad guy, right Ayanokōji-senpai~? I just wanna chat for a bit, kay?”<span class=\"pg\">p.9<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You were about to lay your hands on Ayanokōji-senpai, weren’t you?”<span class=\"pg\">p.9<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Back then, the one watching us from the shadows was you, wasn’t it Amasawa-san?”<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ahaha, so I was seen after all.”<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Eh? Aren’t you just, like, jumping to conclusions? Maybe I just happened to be in the neighborhood.”<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I can swear it, sure, but it doesn’t really matter whether I keep my word or not, right?”<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ding ding ding~ Correct~! Whether intentionally done or not, a broken watch is a broken watch. And you can get it replaced for free too!”<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Poking holes in the rules is standard practice. If the school can’t even find any evidence, you’re free to do whatever you want.”<span class=\"pg\">p.13<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Same difference. Be it my broken GPS or my presence at the scene of the crime, it would only end with suspicion at best.”<span class=\"pg\">p.14<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> She admits to tailing them at the slope (Nanase caught her red hair), baits Nanase’s interrogation and stonewalls on the Komiya/Kinoshita attack; she shows them the broken watch to prove she could erase her GPS; she correctly reads that a first-year with a spotless record will not be found guilty without evidence — and that Shinohara only saw a vague figure.<span class=\"pg\">p.11–14<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Theatre and evasion — arrives conspicuously, tosses the stick down as a show of good faith (p.9), laughs off being caught red-handed, turns Nanase’s accusation into wordplay; Ayanokōji notes she has “extraordinary acting skills and the uncanny ability to put plans into action” (p.10).<span class=\"pg\">p.8–14<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nanase Tsubasa<\/b> Nanase orders her “You─ cannot be trusted.” and stays between her and Ayanokōji; Amasawa needles Nanase as his “knight in shining armor” (p.15).<span class=\"pg\">p.9–14<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> She approaches him uninvited carrying a weapon she never uses; he says nothing to signal trust either way.<span class=\"pg\">p.8–14<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v4-p5-1\">← Before: Prologue: Amasawa&#x27;s monologue on the White Room<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v4-p15-1\">→ After: Ch.1: The White Room reveal<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v4-p8-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"amasawa-ichika nanase-tsubasa ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 1  amasawa appears in the rain in the storm after the fight with nanase  an ominous presence stops behind him   amasawa stands there in the rain  red hair swaying  holding a whittled wooden stick  no backpack or tablet  tracked them via the same table  or gps relay  or a long tail   seems it s gonna really start coming down  huh sen pai   how me an  how could you say something like that  i m super duper cute   ahaha  so i was seen after all   ding ding ding  correct  whether intentionally done or not  a broken watch is a broken watch  and you can get it replaced for free too   please get behind me  senpai   you  cannot be trusted   please don t listen to her  she s dangerous   back then  the one watching us from the shadows was you  wasn t it amasawa san  he weighs how she found them  tracked them  empty handed from the start  or a relay  and why she carries a stick   her  extraordinary acting skills and the uncanny ability to put plans into action   p 10  he remains formally courteous while treating her as a live threat  komiya and kinoshita went down on the fourth day under an intact gps night raid  she appears before him in the rain  neither trusts her  she tosses the stick down as a show of good faith  he calls for restraint without revealing what he knows  now his ally  she steps in front of him and grabs amasawa s arm  accuses amasawa of pushing komiya kinoshita  he will not echo the accusation  komiya and kinoshita  retired from the exam after the fourth day attack on the slope near f6 d7  were the reason ike ran  amasawa s signal was the only one missing at the time  nanase saw her fleeing","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v4-p8-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v4-p8-1\">Ch.1: Amasawa appears in the rain<\/a><\/span><span class=\"meta\">Y2V4 · p.8–14<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">In the storm after the fight with Nanase, an ominous presence stops behind him — Amasawa stands there in the rain, red hair swaying, holding a whittled wooden stick; no backpack or tablet (tracked them via the same Table, or GPS relay, or a long tail).<\/p><p class=\"with\">with <a href=\"../../../people/amasawa-ichika.html\">Amasawa Ichika<\/a> · <a href=\"../../../people/nanase-tsubasa.html\">Nanase Tsubasa<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Amasawa Ichika<\/b> “Seems it’s gonna really start coming down, huh Sen~pai?”<span class=\"pg\">p.8<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Amasawa Ichika<\/b> “How me~an. How could you say something like that? I’m super-duper cute~!”<span class=\"pg\">p.9<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Amasawa Ichika<\/b> “Ahaha, so I was seen after all.”<span class=\"pg\">p.11<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Ding ding ding~ Correct~! Whether intentionally done or not, a broken watch is a broken watch. And you can get it replaced for free too!”<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Please get behind me, Senpai.”<span class=\"pg\">p.9<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You─ cannot be trusted.”<span class=\"pg\">p.9<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Please don’t listen to her, she’s dangerous.”<span class=\"pg\">p.10<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Back then, the one watching us from the shadows was you, wasn’t it Amasawa-san?”<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> He weighs how she found them (tracked them, empty-handed from the start, or a relay) and why she carries a stick — her “extraordinary acting skills and the uncanny ability to put plans into action” (p.10); he remains formally courteous while treating her as a live threat; Komiya and Kinoshita went down on the fourth day under an intact-GPS night raid.<span class=\"pg\">p.8–14<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Amasawa Ichika<\/b> She appears before him in the rain; neither trusts her; she tosses the stick down as a show of good faith; he calls for restraint without revealing what he knows.<span class=\"pg\">p.8–14<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nanase Tsubasa<\/b> Now his ally, she steps in front of him and grabs Amasawa’s arm; accuses Amasawa of pushing Komiya/Kinoshita; he will not echo the accusation.<span class=\"pg\">p.8–14<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Komiya and Kinoshita (retired from the exam after the fourth-day attack on the slope near F6/D7) were the reason Ike ran; Amasawa’s signal was the only one missing at the time; Nanase saw her fleeing.<span class=\"pg\">p.10–11<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p5-1\">← Before: Prologue note (Amasawa&#x27;s monologue — her own page)<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p15-1\">→ After: Ch.1: The White Room reveal<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v4-p8-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"amasawa-ichika ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa ch 1  she guards him  names the slope watcher in the rain  sensing the presences behind them  she notices amasawa at once and points the earlier watcher out   please get behind me  senpai   you  cannot be trusted   please don t listen to her  she s dangerous   while you were gone  i noticed that someone had been watching us from nearby  so i tried chasing after them   back then  the one watching us from the shadows was you  wasn t it amasawa san   you also hurt komiya senpai and kinoshita senpai  didn t you   i don t believe you  not at all   then  can you swear to me that you weren t the one who hurt them   if a girl came running at you with a scary look on her face  who wouldn t run away   but even if you broke your gps before the attack  wouldn t the school have taken notice   that s how it is  nanase chan  she slowly raises her right arm toward amasawa  identifying her as the fourth day shadow  she saw the hair  her testimony is circumstantial   she never saw the push  she wanted to testify that she saw amasawa at the scene  ayanokoji tells her it would only ever end in suspicion without conclusive evidence  she puts herself between ayanokoji and amasawa with zero hesitation  interrogates amasawa relentlessly  and correctly clocks the broken watch and the missing gps  and does not relax even after the stick is tossed down  accuses her of the cliff attack  sharpest suspicion in the exam  devoted guard  obeys his orders to stand down","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v4-p8-1\"><h3><span class=\"ttl\"><a href=\"../../../people/nanase-tsubasa.html#sc-nanase-tsubasa-y2v4-p8-1\">Ch.1: She guards him; names the slope watcher<\/a><\/span><span class=\"meta\">Y2V4 · p.8–14<\/span><span class=\"by\">notes on <a href=\"../../../people/nanase-tsubasa.html\">Nanase Tsubasa<\/a><\/span><\/h3><p class=\"setup\">In the rain, sensing the presences behind them, she notices Amasawa at once and points the earlier watcher out.<\/p><p class=\"with\">with <a href=\"../../../people/amasawa-ichika.html\">Amasawa Ichika<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> “Please get behind me, Senpai.”<span class=\"pg\">p.9<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> “You─ cannot be trusted.”<span class=\"pg\">p.9<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> “Please don’t listen to her, she’s dangerous.”<span class=\"pg\">p.10<\/span><\/li><\/ul><details class=\"more\"><summary>12 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “While you were gone, I noticed that someone had been watching us from nearby, so I tried chasing after them.”<span class=\"pg\">p.10<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Back then, the one watching us from the shadows was you, wasn’t it Amasawa-san?”<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You also hurt Komiya-senpai and Kinoshita-senpai, didn’t you?”<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don’t believe you. Not at all.”<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Then, can you swear to me that you weren’t the one who hurt them?”<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If a girl came running at you with a scary look on her face, who wouldn’t run away?”<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But even if you broke your GPS before the attack, wouldn’t the school have taken notice?”<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That’s how it is, Nanase-chan.”<span class=\"pg\">p.14<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> She slowly raises her right arm toward Amasawa, identifying her as the fourth-day shadow (she saw the hair); her testimony is circumstantial — she never saw the push; she wanted to testify that she saw Amasawa at the scene; Ayanokōji tells her it would only ever end in suspicion without conclusive evidence.<span class=\"pg\">p.11–14<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> She puts herself between Ayanokōji and Amasawa with zero hesitation, interrogates Amasawa relentlessly (and correctly clocks the broken watch and the missing GPS), and does not relax even after the stick is tossed down.<span class=\"pg\">p.8–14<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Amasawa Ichika<\/b> Accuses her of the cliff attack; sharpest suspicion in the exam.<span class=\"pg\">p.8–14<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Devoted guard; obeys his orders to stand down.<span class=\"pg\">p.8–14<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v4-p15-1\">→ After: Ch.1: Left out of the private talk<\/button><\/div><\/article>"},{"i":"sc-ike-kanji-y2v4-p10-1","v":"y2v4","y":2,"o":19,"k":"","w":"ike-kanji","q":"ike kanji ike mentioned in passing  back when shinohara senpai s group was attacked and komiya senpai and kinoshita senpai retired from the exam  do you remember how you left to climb the slope with ike senpai    amasawa to ayanokoji on the fourth day slope incident  ike heard a sound and took off in a panic thinking shinohara might be at the top   although i could talk to people like horikita and ike  it had always felt like there was some sort of distance between us","h":"<article class=\"card\" id=\"sc-ike-kanji-y2v4-p10-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ike-kanji.html#sc-ike-kanji-y2v4-p10-1\">Ike mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.10, 19<\/span><span class=\"by\">notes on <a href=\"../../../people/ike-kanji.html\">Ike Kanji<\/a><\/span><\/h3><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “Back when Shinohara-senpai’s group was attacked and Komiya-senpai and Kinoshita-senpai retired from the exam, do you remember how you left to climb the slope with Ike-senpai?” — Amasawa to Ayanokōji on the fourth-day slope incident; Ike heard a sound and took off in a panic thinking Shinohara might be at the top.<span class=\"pg\">p.10<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Although I could talk to people like Horikita and Ike, it had always felt like there was some sort of distance between us.”<span class=\"pg\">p.19<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-kinoshita-minori-y2v4-p10-1","v":"y2v4","y":2,"o":19,"k":"","w":"kinoshita-minori","q":"kinoshita minori kinoshita mentioned in passing  back when shinohara senpai s group was attacked and komiya senpai and kinoshita senpai retired from the exam  do you remember how you left to climb the slope with ike senpai    amasawa to ayanokoji   you also hurt komiya senpai and kinoshita senpai  didn t you    nanase accuses amasawa   since shinohara herself had testified that they had been attacked by someone  the school would definitely investigate the case in detail   what s more  komiya and kinoshita didn t even testify that they had been attacked in the first place  and shinohara herself had only been able to make a vague statement  unable to say who it was she saw   back when komiya and kinoshita were attacked  i found some footprints nearby the scene of the crime  from what i can tell  i m fairly confident that they re the same size as amasawa s   from what we knew  someone had pushed komiya and kinoshita down the slope  and  judging from the fact that there were no other gps signals in the area at the time  it was clear that it had been a premeditated attack  rather than something done in the heat of the moment","h":"<article class=\"card\" id=\"sc-kinoshita-minori-y2v4-p10-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kinoshita-minori.html#sc-kinoshita-minori-y2v4-p10-1\">Kinoshita mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.10–14, 21–32<\/span><span class=\"by\">notes on <a href=\"../../../people/kinoshita-minori.html\">Kinoshita Minori<\/a><\/span><\/h3><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “Back when Shinohara-senpai’s group was attacked and Komiya-senpai and Kinoshita-senpai retired from the exam, do you remember how you left to climb the slope with Ike-senpai?” — Amasawa to Ayanokōji.<span class=\"pg\">p.10<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “You also hurt Komiya-senpai and Kinoshita-senpai, didn’t you?” — Nanase accuses Amasawa.<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Since Shinohara herself had testified that they had been attacked by someone, the school would definitely investigate the case in detail.”<span class=\"pg\">p.13<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “What’s more, Komiya and Kinoshita didn’t even testify that they had been attacked in the first place, and Shinohara herself had only been able to make a vague statement, unable to say who it was she saw.”<span class=\"pg\">p.14<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Back when Komiya and Kinoshita were attacked, I found some footprints nearby the scene of the crime. From what I can tell, I’m fairly confident that they’re the same size as Amasawa’s.”<span class=\"pg\">p.21<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “From what we knew: someone had pushed Komiya and Kinoshita down the slope. And, judging from the fact that there were no other GPS signals in the area at the time, it was clear that it had been a premeditated attack, rather than something done in the heat of the moment.”<span class=\"pg\">p.32<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kinoshita-minori-y2v4-p23-1\">→ After: Kinoshita mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-komiya-kyogo-y2v4-p10-1","v":"y2v4","y":2,"o":19,"k":"","w":"komiya-kyogo","q":"komiya kyogo komiya mentioned in passing  back when shinohara senpai s group was attacked and komiya senpai and kinoshita senpai retired from the exam  do you remember how you left to climb the slope with ike senpai    amasawa to ayanokoji   you also hurt komiya senpai and kinoshita senpai  didn t you    nanase accuses amasawa of the cliff attack   since shinohara herself had testified that they had been attacked by someone  the school would definitely investigate the case in detail    shinohara s testimony forces an investigation   what s more  komiya and kinoshita didn t even testify that they had been attacked in the first place  and shinohara herself had only been able to make a vague statement  unable to say who it was she saw   back when komiya and kinoshita were attacked  i found some footprints nearby the scene of the crime  from what i can tell  i m fairly confident that they re the same size as amasawa s    ayanokoji to nanase   in other words  amasawa had definitely been there  just like nanase claimed she was   from what we knew  someone had pushed komiya and kinoshita down the slope  and  judging from the fact that there were no other gps signals in the area at the time  it was clear that it had been a premeditated attack  rather than something done in the heat of the moment","h":"<article class=\"card\" id=\"sc-komiya-kyogo-y2v4-p10-1\"><h3><span class=\"ttl\"><a href=\"../../../people/komiya-kyogo.html#sc-komiya-kyogo-y2v4-p10-1\">Komiya mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.10–14, 21–26, 32<\/span><span class=\"by\">notes on <a href=\"../../../people/komiya-kyogo.html\">Komiya Kyogo<\/a><\/span><\/h3><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “Back when Shinohara-senpai’s group was attacked and Komiya-senpai and Kinoshita-senpai retired from the exam, do you remember how you left to climb the slope with Ike-senpai?” — Amasawa to Ayanokōji.<span class=\"pg\">p.10<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “You also hurt Komiya-senpai and Kinoshita-senpai, didn’t you?” — Nanase accuses Amasawa of the cliff attack.<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Since Shinohara herself had testified that they had been attacked by someone, the school would definitely investigate the case in detail.” — Shinohara’s testimony forces an investigation.<span class=\"pg\">p.13<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “What’s more, Komiya and Kinoshita didn’t even testify that they had been attacked in the first place, and Shinohara herself had only been able to make a vague statement, unable to say who it was she saw.”<span class=\"pg\">p.14<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Back when Komiya and Kinoshita were attacked, I found some footprints nearby the scene of the crime. From what I can tell, I’m fairly confident that they’re the same size as Amasawa’s.” — Ayanokōji to Nanase.<span class=\"pg\">p.21<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “In other words, Amasawa had definitely been there, just like Nanase claimed she was.”<span class=\"pg\">p.23<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “From what we knew: someone had pushed Komiya and Kinoshita down the slope. And, judging from the fact that there were no other GPS signals in the area at the time, it was clear that it had been a premeditated attack, rather than something done in the heat of the moment.”<span class=\"pg\">p.32<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-komiya-kyogo-y2v4-p31-1\">→ After: Komiya mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-shinohara-satsuki-y2v4-p10-1","v":"y2v4","y":2,"o":19,"k":"","w":"shinohara-satsuki","q":"shinohara satsuki shinohara mentioned in passing  back when shinohara senpai s group was attacked and komiya senpai and kinoshita senpai retired from the exam  do you remember how you left to climb the slope with ike senpai    amasawa to ayanokoji   since shinohara herself had testified that they had been attacked by someone  the school would definitely investigate the case in detail   what s more  komiya and kinoshita didn t even testify that they had been attacked in the first place  and shinohara herself had only been able to make a vague statement  unable to say who it was she saw","h":"<article class=\"card\" id=\"sc-shinohara-satsuki-y2v4-p10-1\"><h3><span class=\"ttl\"><a href=\"../../../people/shinohara-satsuki.html#sc-shinohara-satsuki-y2v4-p10-1\">Shinohara mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.10–14<\/span><span class=\"by\">notes on <a href=\"../../../people/shinohara-satsuki.html\">Shinohara Satsuki<\/a><\/span><\/h3><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “Back when Shinohara-senpai’s group was attacked and Komiya-senpai and Kinoshita-senpai retired from the exam, do you remember how you left to climb the slope with Ike-senpai?” — Amasawa to Ayanokōji.<span class=\"pg\">p.10<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Since Shinohara herself had testified that they had been attacked by someone, the school would definitely investigate the case in detail.”<span class=\"pg\">p.13<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “What’s more, Komiya and Kinoshita didn’t even testify that they had been attacked in the first place, and Shinohara herself had only been able to make a vague statement, unable to say who it was she saw.”<span class=\"pg\">p.14<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-shinohara-satsuki-y2v4-p55-1\">→ After: Shinohara mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y2v4-p10-1","v":"y2v4","y":2,"o":19,"k":"","w":"sudou-ken","q":"sudo ken sudo mentioned in passing  while you were gone  i noticed that someone had been watching us from nearby  so i tried chasing after them    nanase names the third day slope watch  sudo was elsewhere with the group   is sudo senpai okay  horikita senpai    amasawa asks","h":"<article class=\"card\" id=\"sc-sudou-ken-y2v4-p10-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sudou-ken.html#sc-sudou-ken-y2v4-p10-1\">Sudō mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.10, 221<\/span><span class=\"by\">notes on <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a><\/span><\/h3><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “While you were gone, I noticed that someone had been watching us from nearby, so I tried chasing after them.” — Nanase names the third-day slope watch; Sudō was elsewhere with the group.<span class=\"pg\">p.10<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Is Sudo-senpai okay? Horikita-senpai.” — Amasawa asks.<span class=\"pg\">p.221<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y2v4-p14-1\">→ After: Sudō mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-ryuuen-kakeru-y2v4-p14-1","v":"y2v4","y":2,"o":19,"k":"","w":"ryuuen-kakeru","q":"ryuen kakeru ryuen mentioned in passing  if it had been one of the more problematic students like sudo or ryuen  who had a history of highly violent behavior  the school might have been more suspicious   on the fifth day of the exam  i approached both ryuen and sakayanagi with a certain proposal of sorts  to clear specific tasks together with the help of a  select portion  of the second year student body   in terms of pure combat power  you could say that amasawa was even a step above the likes of sudo and ryuen    ayanokoji privately compares amasawa to the likes of sudo and ryuen","h":"<article class=\"card\" id=\"sc-ryuuen-kakeru-y2v4-p14-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ryuuen-kakeru.html#sc-ryuuen-kakeru-y2v4-p14-1\">Ryūen mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.14, 42, 47<\/span><span class=\"by\">notes on <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/span><\/h3><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “If it had been one of the more problematic students like Sudō or Ryūen, who had a history of highly violent behavior, the school might have been more suspicious.”<span class=\"pg\">p.14<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “On the fifth day of the exam, I approached both Ryūen and Sakayanagi with a certain proposal of sorts: to clear specific Tasks together with the help of a ‘select portion’ of the second-year student body.”<span class=\"pg\">p.42<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “In terms of pure combat power, you could say that Amasawa was even a step above the likes of Sudō and Ryūen.” — Ayanokōji privately compares Amasawa to the likes of Sudō and Ryūen.<span class=\"pg\">p.47<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ryuuen-kakeru-y2v4-p48-1\">→ After: Ryūen mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y2v4-p14-1","v":"y2v4","y":2,"o":19,"k":"","w":"sudou-ken","q":"sudo ken sudo mentioned in passing  if it had been one of the more problematic students like sudo or ryuen  who had a history of highly violent behavior  the school might have been more suspicious    the school s suspicion calculus on the cliff attack   as an example  certain class 2 a groups would help class 2 d with increasing the maximum group size of sudo s group  and in exchange we would help them increase the maximum size of one of their own that needed it   while they may have her beat in terms of raw physical strength  she d definitely be far  far ahead of them when it comes to technique and experience    ayanokoji privately compares amasawa to the likes of sudo and ryuen","h":"<article class=\"card\" id=\"sc-sudou-ken-y2v4-p14-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sudou-ken.html#sc-sudou-ken-y2v4-p14-1\">Sudō mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.14, 42, 47<\/span><span class=\"by\">notes on <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a><\/span><\/h3><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “If it had been one of the more problematic students like Sudō or Ryūen, who had a history of highly violent behavior, the school might have been more suspicious.” — the school’s suspicion calculus on the cliff attack.<span class=\"pg\">p.14<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “As an example, certain Class 2-A groups would help Class 2-D with increasing the maximum group size of Sudō’s group, and in exchange we would help them increase the maximum size of one of their own that needed it.”<span class=\"pg\">p.42<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “While they may have her beat in terms of raw physical strength, she’d definitely be far, far ahead of them when it comes to technique and experience.” — Ayanokōji privately compares Amasawa to the likes of Sudō and Ryūen.<span class=\"pg\">p.47<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y2v4-p10-1\">← Before: Sudō mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-amasawa-ichika-y2v4-p15-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"ayanokouji-kiyotaka nanase-tsubasa amasawa-ichika","q":"amasawa ichika ch 1  the white room reveal she stalls the conversation  offers to pitch camp and spend the night  just the two of us  nanase seizes her arm  and she confesses she is the white room student  he motions nanase away so the rain masks a private talk   what s with this  nanase chan   since when were you his knight in shining armor  weren t you like  plotting to get him expelled together with hosen kun   i just happened to get lost  so i came to try and ask you guys for help   well there s no way i could do that  it has to do with the white room  after all   i d like to chat with ayanokoji senpai  so could you let go and step aside   do you get it now  little miss outsider   senpai  the curriculum you took back when you were 10 years old included systems  theory based on project 5  and at the age of 11 it was the theory of relativity based on project 7  i took part in both myself  so i remember them well   the classrooms  the corridors  our assigned living chambers  everything was a world of pure white   sure sure  i figured you d be curious about that  it s cuz i wanted to tell you that i m not your enemy  senpai   you wouldn t know this as part of the fourth generation  ayanokoji senpai  but the later generations harbor immense feelings of jealousy when it comes to you  the higher ups probably thought that they could select someone promising and manipulate this jealousy to force your expulsion  however  they chose the wrong person  they didn t predict that i was but a young maiden who secretly idolized you   well  no matter how much you might idolize someone  that s just like  all in your head  you know  you ve gotta talk with them and meet face to face before your admiration starts to feel justified  that takes time   i know exactly what you mean  senpai  i too have thought about how nice it d be if i could just enjoy being a student like this up until graduation  i ve thought about it several times  actually  i suck at making friends though  so i just don t have very many people to talk to   it s said that  before the fifth generation  children were often crushed one after another due to their excessive individualism   in my generation  on the other hand  all children were required to maintain a minimum level of interpersonal communication   still don t believe me   you re awfully calm and composed for someone who believes that i m a white room student  perhaps you don t think i ll be a threat to you   jeez  didn t i tell you already  i admire you  ayanokoji senpai  that s all   so please  don t go and get yourself crushed without my permission  okay  she draws the reveal out deliberately  stalling for time  his childhood curricula and the pure white facility are white room only knowledge  she frames her allegiance as the younger generation s jealousy misdirected into her admiration  the fifth generation s interpersonal training is her claimed edge over him  she confesses her white room past outright  claims she is not his enemy  pushes  ordinary high schooler  dreams  and admits she is bad at making friends  then leaves with a cryptic blessing warning after brushing his cheek with wet fingers  p 20  reveals herself as the white room student  claims admiration  not enmity  her warning leaves the  crushed without my permission  hanging  calls her nanase chan his loyal dog  nanase releases her arm only on his order  she is excluded from the private talk","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v4-p15-1\"><h3><span class=\"ttl\"><a href=\"../../../people/amasawa-ichika.html#sc-amasawa-ichika-y2v4-p15-1\">Ch.1: The White Room reveal<\/a><\/span><span class=\"meta\">Y2V4 · p.15–20<\/span><span class=\"by\">notes on <a href=\"../../../people/amasawa-ichika.html\">Amasawa Ichika<\/a><\/span><\/h3><p class=\"setup\">She stalls the conversation (offers to pitch camp and spend the night “just the two of us”), Nanase seizes her arm, and she confesses she is the White Room student; he motions Nanase away so the rain masks a private talk.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/nanase-tsubasa.html\">Nanase Tsubasa<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Amasawa Ichika<\/b> “What’s with this, Nanase-chan?”<span class=\"pg\">p.15<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Amasawa Ichika<\/b> “Since when were you his knight in shining armor? Weren’t you like, plotting to get him expelled together with Hōsen-kun?”<span class=\"pg\">p.15<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Amasawa Ichika<\/b> “I just happened to get lost, so I came to try and ask you guys for help.”<span class=\"pg\">p.15<\/span><\/li><\/ul><details class=\"more\"><summary>19 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Well there’s no way I could do that. It has to do with the White Room, after all~”<span class=\"pg\">p.16<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’d like to chat with Ayanokōji-senpai, so could you let go and step aside?”<span class=\"pg\">p.16<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Do you get it now? Little miss outsider~”<span class=\"pg\">p.16<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Senpai, the curriculum you took back when you were 10 years old included Systems’ Theory based on Project 5. And at the age of 11 it was the Theory of Relativity based on Project 7. I took part in both myself, so I remember them well.”<span class=\"pg\">p.17<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The classrooms, the corridors, our assigned living chambers… everything was a world of pure white.”<span class=\"pg\">p.18<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Sure sure, I figured you’d be curious about that. It’s cuz I wanted to tell you that I’m not your enemy, Senpai.”<span class=\"pg\">p.18<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You wouldn’t know this as part of the fourth generation, Ayanokōji-senpai, but the later generations harbor immense feelings of jealousy when it comes to you. The higher-ups probably thought that they could select someone promising and manipulate this jealousy to force your expulsion. However, they chose the wrong person. They didn’t predict that I was but a young maiden who secretly idolized you.”<span class=\"pg\">p.18<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, no matter how much you might idolize someone, that’s just like, all in your head, you know? You’ve gotta talk with them and meet face-to-face before your admiration starts to feel justified. That takes time.”<span class=\"pg\">p.19<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I know exactly what you mean, Senpai. I too have thought about how nice it’d be if I could just enjoy being a student like this up until graduation. I’ve thought about it several times, actually. I suck at making friends though, so I just don’t have very many people to talk to.”<span class=\"pg\">p.19<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s said that, before the fifth generation, children were often crushed one after another due to their excessive individualism.”<span class=\"pg\">p.20<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “In my generation, on the other hand, all children were required to maintain a minimum level of interpersonal communication.”<span class=\"pg\">p.20<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Still don’t believe me?”<span class=\"pg\">p.20<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You’re awfully calm and composed for someone who believes that I’m a White Room student. Perhaps you don’t think I’ll be a threat to you?”<span class=\"pg\">p.20<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Jeez~ Didn’t I tell you already~? I admire you, Ayanokōji-senpai. That’s all.”<span class=\"pg\">p.20<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So please, don’t go and get yourself crushed without my permission, okay?”<span class=\"pg\">p.20<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> She draws the reveal out deliberately (stalling for time); his childhood curricula and the pure-white facility are White Room-only knowledge; she frames her allegiance as the younger generation’s jealousy misdirected into her admiration; the fifth generation’s interpersonal training is her claimed edge over him.<span class=\"pg\">p.17–20<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> She confesses her White Room past outright, claims she is not his enemy, pushes “ordinary high schooler” dreams (and admits she is bad at making friends), then leaves with a cryptic blessing/warning after brushing his cheek with wet fingers (p.20).<span class=\"pg\">p.15–20<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Reveals herself as the White Room student; claims admiration, not enmity; her warning leaves the “crushed without my permission” hanging.<span class=\"pg\">p.15–20<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nanase Tsubasa<\/b> Calls her Nanase-chan his loyal dog; Nanase releases her arm only on his order; she is excluded from the private talk.<span class=\"pg\">p.15–16<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v4-p8-1\">← Before: Ch.1: Amasawa confronts them in the rain<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v4-p21-1\">→ After: Ch.1: The aftermath she left behind<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v4-p15-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"amasawa-ichika nanase-tsubasa ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 1  the white room reveal he lets the white room reveal happen in the rain  once nanase is sent off with a motion  he gets the direct confession with the pure white facility detail   since when were you his knight in shining armor  weren t you like  plotting to get him expelled together with hosen kun   i just happened to get lost  so i came to try and ask you guys for help   well there s no way i could do that  it has to do with the white room  after all   senpai  the curriculum you took back when you were 10 years old included systems  theory based on project 5  and at the age of 11 it was the theory of relativity based on project 7  i took part in both myself  so i remember them well   the classrooms  the corridors  our assigned living chambers  everything was a world of pure white   sure sure  i figured you d be curious about that  it s cuz i wanted to tell you that i m not your enemy  senpai   you wouldn t know this as part of the fourth generation  ayanokoji senpai  but the later generations harbor immense feelings of jealousy when it comes to you  the higher ups probably thought that they could select someone promising and manipulate this jealousy to force your expulsion  however  they chose the wrong person  they didn t predict that i was but a young maiden who secretly idolized you   well  no matter how much you might idolize someone  that s just like  all in your head  you know  you ve gotta talk with them and meet face to face before your admiration starts to feel justified  that takes time   i suck at making friends though  so i just don t have very many people to talk to   do you understand   it s said that  before the fifth generation  children were often crushed one after another due to their excessive individualism   in my generation  on the other hand  all children were required to maintain a minimum level of interpersonal communication   i believe you re from the white room  but i m not convinced with the reason you gave me for why you revealed your identity   so please  don t go and get yourself crushed without my permission  okay   ayanokoji senpai  are you alright  she didn t do anything to you right  her curriculum details  project 5 systems  theory at 10  project 7 theory of relativity at 11  the pure white facility  are white room only knowledge  he concludes her guilt on origin but doubts her motive   she is the first white room fifth generation member to reveal herself openly  the fifth generation s interpersonal communication training is her claimed difference from him  he keeps his composure against a self declared white room student  he neither confirms nor denies being her idol  he stays silent when she asks if he thinks she ll be a threat  p 20  she reveals her identity and her admiration  her warning not to get himself crushed without her permission hangs over the exam s endgame  he waves her away so the rain covers a private talk  she obeys reluctantly","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v4-p15-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v4-p15-1\">Ch.1: The White Room reveal<\/a><\/span><span class=\"meta\">Y2V4 · p.15–20<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">He lets the White Room reveal happen in the rain; once Nanase is sent off with a motion, he gets the direct confession with the pure-white-facility detail.<\/p><p class=\"with\">with <a href=\"../../../people/amasawa-ichika.html\">Amasawa Ichika<\/a> · <a href=\"../../../people/nanase-tsubasa.html\">Nanase Tsubasa<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Amasawa Ichika<\/b> “Since when were you his knight in shining armor? Weren’t you like, plotting to get him expelled together with Hōsen-kun?”<span class=\"pg\">p.15<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Amasawa Ichika<\/b> “I just happened to get lost, so I came to try and ask you guys for help.”<span class=\"pg\">p.15<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Amasawa Ichika<\/b> “Well there’s no way I could do that. It has to do with the White Room, after all~”<span class=\"pg\">p.16<\/span><\/li><\/ul><details class=\"more\"><summary>16 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Senpai, the curriculum you took back when you were 10 years old included Systems’ Theory based on Project 5. And at the age of 11 it was the Theory of Relativity based on Project 7. I took part in both myself, so I remember them well.”<span class=\"pg\">p.17<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The classrooms, the corridors, our assigned living chambers… everything was a world of pure white.”<span class=\"pg\">p.18<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Sure sure, I figured you’d be curious about that. It’s cuz I wanted to tell you that I’m not your enemy, Senpai.”<span class=\"pg\">p.18<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You wouldn’t know this as part of the fourth generation, Ayanokōji-senpai, but the later generations harbor immense feelings of jealousy when it comes to you. The higher-ups probably thought that they could select someone promising and manipulate this jealousy to force your expulsion. However, they chose the wrong person. They didn’t predict that I was but a young maiden who secretly idolized you.”<span class=\"pg\">p.18<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, no matter how much you might idolize someone, that’s just like, all in your head, you know? You’ve gotta talk with them and meet face-to-face before your admiration starts to feel justified. That takes time.”<span class=\"pg\">p.19<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I suck at making friends though, so I just don’t have very many people to talk to.”<span class=\"pg\">p.19<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Do you understand?”<span class=\"pg\">p.19<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s said that, before the fifth generation, children were often crushed one after another due to their excessive individualism.”<span class=\"pg\">p.20<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “In my generation, on the other hand, all children were required to maintain a minimum level of interpersonal communication.”<span class=\"pg\">p.20<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I believe you’re from the White Room, but I’m not convinced with the reason you gave me for why you revealed your identity.”<span class=\"pg\">p.20<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So please, don’t go and get yourself crushed without my permission, okay?”<span class=\"pg\">p.20<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ayanokōji-senpai, are you alright? She didn’t do anything to you right?”<span class=\"pg\">p.21<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Her curriculum details (Project 5 Systems’ Theory at 10, Project 7 Theory of Relativity at 11; the pure-white facility) are White Room-only knowledge; he concludes her guilt on origin but doubts her motive — she is the first White Room fifth-generation member to reveal herself openly; the fifth generation’s interpersonal-communication training is her claimed difference from him.<span class=\"pg\">p.16–21<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> He keeps his composure against a self-declared White Room student; he neither confirms nor denies being her idol; he stays silent when she asks if he thinks she’ll be a threat (p.20).<span class=\"pg\">p.15–20<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Amasawa Ichika<\/b> She reveals her identity and her admiration; her warning not to get himself crushed without her permission hangs over the exam’s endgame.<span class=\"pg\">p.15–20<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nanase Tsubasa<\/b> He waves her away so the rain covers a private talk; she obeys reluctantly.<span class=\"pg\">p.17<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p8-1\">← Before: Ch.1: Amasawa appears in the rain<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p21-1\">→ After: Ch.1: The footprints; the whittled stick; the GPS verdict<\/button><\/div><\/article>"},{"i":"sc-housen-kazuomi-y2v4-p15-1","v":"y2v4","y":2,"o":19,"k":"","w":"housen-kazuomi","q":"hosen kazuomi hosen mentioned in passing  since when were you his knight in shining armor  weren t you like  plotting to get him expelled together with hosen kun    amasawa needles nanase about her own alliance   you have your other group member  hosen  to watch out for as well    ayanokoji warns nanase","h":"<article class=\"card\" id=\"sc-housen-kazuomi-y2v4-p15-1\"><h3><span class=\"ttl\"><a href=\"../../../people/housen-kazuomi.html#sc-housen-kazuomi-y2v4-p15-1\">Hōsen mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.15, 47<\/span><span class=\"by\">notes on <a href=\"../../../people/housen-kazuomi.html\">Hōsen Kazuomi<\/a><\/span><\/h3><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “Since when were you his knight in shining armor? Weren’t you like, plotting to get him expelled together with Hōsen-kun?” — Amasawa needles Nanase about her own alliance.<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “You have your other group member, Hōsen, to watch out for as well.” — Ayanokōji warns Nanase.<span class=\"pg\">p.47<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-housen-kazuomi-y2v4-p53-1\">→ After: Hōsen mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v4-p15-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"amasawa-ichika ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa ch 1  left out of the private talk  jeez  i m not some bad guy  right ayanokoji senpai  i just wanna chat for a bit  kay   what s with this  nanase chan   you were about to lay your hands on ayanokoji senpai  weren t you   ah  are you worried about breaking the rules  it s fine  it s fine  even the school can t monitor everything  you know   that  that has nothing to do with you  why did you come here   let go of her arm nanase   wow  you re such a good girl nanase chan  it s like you re his loyal dog  it s a better look for you than i thought   why don t you just talk from where you are   now then  where oh where should i start  he motions her away so the rain masks a private conversation  reluctant to leave him alone with amasawa  she eventually gives in and steps back a few meters away   too far to hear  she does not hear the substance of the white room reveal  she only sees the two of them standing close in the rain","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v4-p15-1\"><h3><span class=\"ttl\"><a href=\"../../../people/nanase-tsubasa.html#sc-nanase-tsubasa-y2v4-p15-1\">Ch.1: Left out of the private talk<\/a><\/span><span class=\"meta\">Y2V4 · p.15–20<\/span><span class=\"by\">notes on <a href=\"../../../people/nanase-tsubasa.html\">Nanase Tsubasa<\/a><\/span><\/h3><p class=\"setup\">He motions her away so the rain masks a private conversation; reluctant to leave him alone with Amasawa, she eventually gives in and steps back a few meters away — too far to hear.<\/p><p class=\"with\">with <a href=\"../../../people/amasawa-ichika.html\">Amasawa Ichika<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Amasawa Ichika<\/b> “Jeez. I’m not some bad guy, right Ayanokōji-senpai~? I just wanna chat for a bit, kay?”<span class=\"pg\">p.9<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Amasawa Ichika<\/b> “What’s with this, Nanase-chan?”<span class=\"pg\">p.15<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> “You were about to lay your hands on Ayanokōji-senpai, weren’t you?”<span class=\"pg\">p.15<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Ah, are you worried about breaking the rules? It’s fine, it’s fine. Even the school can’t monitor everything, you know?”<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That… That has nothing to do with you. Why did you come here?”<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Let go of her arm Nanase.”<span class=\"pg\">p.16<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Wow, you’re such a good girl Nanase-chan~! It’s like you’re his loyal dog; it’s a better look for you than I thought.”<span class=\"pg\">p.16<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Why don’t you just talk from where you are?”<span class=\"pg\">p.16<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Now then, where oh where should I start~?”<span class=\"pg\">p.17<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> She does not hear the substance of the White Room reveal; she only sees the two of them standing close in the rain.<span class=\"pg\">p.16–17<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v4-p8-1\">← Before: Ch.1: She guards him; names the slope watcher<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v4-p18-1\">→ After: Nanase mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v4-p18-1","v":"y2v4","y":2,"o":19,"k":"","w":"nanase-tsubasa","q":"nanase tsubasa nanase mentioned in passing  nanase did    ayanokoji s interior confirms she was the one who caught sight of amasawa fleeing   slightly behind schedule due to what happened with nanase and the rough patch of weather  i had finally secured the strategic position that i d been aiming for since the very beginning    ayanokoji   however  compared to when i had nanase accompanying me  i was currently a boy traveling on his own    ayanokoji   the information nanase had risked so much to tell me about the trick of the 12th was empty    ayanokoji   remembering what was heard from nanase the other day  instinctively  today is when the first graders are installed    ayanokoji   nanase s words   if they find you  you will become a victim of violence  will come true    ayanokoji   ayanokouji explains that nanase was one of the assassins sent by tsukishiro  since sakayanagi knows the story of the acting director    narration   i know nanase came to see you to gently warn you    hosen   nanase s defeat to me and going our separate ways  he wanted to act just to make a plan to hide around 11th place targeting higher ranks    narration   unlike what happened with nanase  i don t think my method of evading attacks is going to work    ayanokoji","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v4-p18-1\"><h3><span class=\"ttl\"><a href=\"../../../people/nanase-tsubasa.html#sc-nanase-tsubasa-y2v4-p18-1\">Nanase mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.18, 61, 63, 125, 151, 153, 162, 168, 253, 254<\/span><span class=\"by\">notes on <a href=\"../../../people/nanase-tsubasa.html\">Nanase Tsubasa<\/a><\/span><\/h3><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “Nanase did.” — Ayanokōji&#x27;s interior confirms she was the one who caught sight of Amasawa fleeing.<span class=\"pg\">p.18<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “...slightly behind schedule due to what happened with Nanase and the rough patch of weather, I had finally secured the strategic position that I&#x27;d been aiming for since the very beginning.” — Ayanokōji.<span class=\"pg\">p.61<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “However, compared to when I had Nanase accompanying me, I was currently a boy traveling on his own.” — Ayanokōji.<span class=\"pg\">p.63<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “The information Nanase had risked so much to tell me about the trick of the 12th was empty.” — Ayanokōji.<span class=\"pg\">p.125<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Remembering what was heard from Nanase the other day, instinctively. Today is when the first graders are installed.” — Ayanokōji.<span class=\"pg\">p.151<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Nanase&#x27;s words, “If they find you, you will become a victim of violence,” will come true.” — Ayanokōji.<span class=\"pg\">p.152<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Ayanokouji explains that Nanase was one of the assassins sent by Tsukishiro, since Sakayanagi knows the story of the Acting Director.” — narration.<span class=\"pg\">p.162<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “I know Nanase came to see you to gently warn you.” — Hōsen.<span class=\"pg\">p.168<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Nanase&#x27;s defeat to me and going our separate ways. He wanted to act just to make a plan to hide around 11th place targeting higher ranks.” — narration.<span class=\"pg\">p.253<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Unlike what happened with Nanase, I don&#x27;t think my method of evading attacks is going to work.” — Ayanokōji.<span class=\"pg\">p.254<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v4-p15-1\">← Before: Ch.1: Left out of the private talk<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v4-p21-1\">→ After: Ch.1: The footprints; she pushes the GPS idea<\/button><\/div><\/article>"},{"i":"sc-tsukishiro-y2v4-p18-1","v":"y2v4","y":2,"o":19,"k":"","w":"tsukishiro","q":"tsukishiro tsukishiro mentioned in passing  and it was too hard for me to imagine that she had heard about it from tsukishiro  he would never talk about the inner workings of the white room with someone unrelated   an outsider  as such  it was probably safe to conclude amasawa s guilt    he reasons about who sent her   she said  don t go and get yourself crushed  but by whom  tsukishiro  the first years who had their sights set on the twenty million private point bounty  or  perhaps   honestly  i find it hard to believe that someone sent here by tsukishiro would make a mistake like that","h":"<article class=\"card\" id=\"sc-tsukishiro-y2v4-p18-1\"><h3><span class=\"ttl\"><a href=\"../../../people/tsukishiro.html#sc-tsukishiro-y2v4-p18-1\">Tsukishiro mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.18, 21, 23<\/span><span class=\"by\">notes on <a href=\"../../../people/tsukishiro.html\">Tsukishiro<\/a><\/span><\/h3><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “And it was too hard for me to imagine that she had heard about it from Tsukishiro. He would never talk about the inner workings of the White Room with someone unrelated – an outsider. As such, it was probably safe to conclude Amasawa’s guilt.” — he reasons about who sent her.<span class=\"pg\">p.18<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “She said ‘don’t go and get yourself crushed’… but by whom? Tsukishiro? The first-years who had their sights set on the twenty million private point bounty? Or, perhaps…”<span class=\"pg\">p.21<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Honestly, I find it hard to believe that someone sent here by Tsukishiro would make a mistake like that.”<span class=\"pg\">p.23<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsukishiro-y2v4-p4-1\">← Before: Tsukishiro mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-tsukishiro-y2v4-p162-1\">→ After: Tsukishiro mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-horikita-suzune-y2v4-p19-1","v":"y2v4","y":2,"o":19,"k":"","w":"horikita-suzune","q":"horikita suzune horikita mentioned in passing  although i could talk to people like horikita and ike  it had always felt like there was some sort of distance between us","h":"<article class=\"card\" id=\"sc-horikita-suzune-y2v4-p19-1\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-suzune.html#sc-horikita-suzune-y2v4-p19-1\">Horikita mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.19<\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “Although I could talk to people like Horikita and Ike, it had always felt like there was some sort of distance between us.”<span class=\"pg\">p.19<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y2v4-p55-1\">→ After: Ch.2: Horikita rejoins him at F7<\/button><\/div><\/article>"},{"i":"sc-amasawa-ichika-y2v4-p21-1","v":"y2v4","y":2,"o":19,"k":"","w":"ayanokouji-kiyotaka amasawa-ichika","q":"amasawa ichika ch 1  the aftermath she left behind after she departs  ayanokoji and nanase trace her footprints  clean and steady on approach  preceded by a larger mystery set that closed in then fled  the whittled down stick suggests she did not carry the weapon   a third party did  the footprints likely were the mystery person s  ayanokoji declines a gps search as bait  she may have come to protect him from whoever made those tracks  the mystery his side discusses in her absence   her own tracks are measured against a bigger  fleeing set","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v4-p21-1\"><h3><span class=\"ttl\"><a href=\"../../../people/amasawa-ichika.html#sc-amasawa-ichika-y2v4-p21-1\">Ch.1: The aftermath she left behind<\/a><\/span><span class=\"meta\">Y2V4 · p.21–26<\/span><span class=\"by\">notes on <a href=\"../../../people/amasawa-ichika.html\">Amasawa Ichika<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> After she departs, Ayanokōji and Nanase trace her footprints (clean and steady on approach) preceded by a larger mystery set that closed in then fled; the whittled-down stick suggests she did not carry the weapon — a third party did; the footprints likely were the mystery person’s; Ayanokōji declines a GPS Search as bait; she may have come to protect him from whoever made those tracks.<span class=\"pg\">p.21–26<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> The mystery his side discusses in her absence — her own tracks are measured against a bigger, fleeing set.<span class=\"pg\">p.21–26<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v4-p15-1\">← Before: Ch.1: The White Room reveal<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v4-p27-1\">→ After: Ch.1: Talking about her (mention records)<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v4-p21-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"nanase-tsubasa ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 1  the footprints  the whittled stick  the gps verdict  the rain  we d better hurry   amasawa san s  footprints  is there something wrong with her footprints   i found some footprints nearby the scene of the crime  from what i can tell  i m fairly confident that they re the same size as amasawa s   as i thought  there s something about each and every one of amasawa s actions that can t be overlooked   do you think she was going to use this to try and attack you  ayanokoji senpai   if amasawa really planned on attacking me  then she should ve tried to catch me off guard instead of calling out like she did   you still can t be absolutely certain  she s well aware that you re an opponent she ought to be wary of  so it s reasonable to assume that she took any and all precautions necessary   i won t be using the gps search   senpai  let s do a gps search right now  reads her approach tracks  steady  unhurried  against a larger fleeing set that stopped at her tracks and turned back  the whittled stick was the third party s  not hers  amasawa had no intention of attacking   she likely wanted to be seen  the mystery person likely did not break their watch  declines the gps search as bait   the 10 missing points were for the ten hourly screenshots instead  she wants the search  he vetoes it as a trap  the two concur the culprit is  certainly the most likely  reading being amasawa  but neither has proof","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v4-p21-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v4-p21-1\">Ch.1: The footprints; the whittled stick; the GPS verdict<\/a><\/span><span class=\"meta\">Y2V4 · p.21–27<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/nanase-tsubasa.html\">Nanase Tsubasa<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “The rain. We’d better hurry.”<span class=\"pg\">p.21<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> “Amasawa-san’s… footprints? Is there something wrong with her footprints?”<span class=\"pg\">p.21<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “I found some footprints nearby the scene of the crime. From what I can tell, I’m fairly confident that they’re the same size as Amasawa’s.”<span class=\"pg\">p.22<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “As I thought, there’s something about each and every one of Amasawa’s actions that can’t be overlooked.”<span class=\"pg\">p.23<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Do you think she was going to use this to try and attack you, Ayanokōji-senpai?”<span class=\"pg\">p.25<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If Amasawa really planned on attacking me, then she should’ve tried to catch me off-guard instead of calling out like she did.”<span class=\"pg\">p.25<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You still can’t be absolutely certain. She’s well aware that you’re an opponent she ought to be wary of, so it’s reasonable to assume that she took any and all precautions necessary.”<span class=\"pg\">p.26<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I won’t be using the GPS Search.”<span class=\"pg\">p.27<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Senpai, let’s do a GPS Search right now!”<span class=\"pg\">p.26<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> Reads her approach tracks (steady, unhurried) against a larger fleeing set that stopped at her tracks and turned back; the whittled stick was the third party’s, not hers; Amasawa had no intention of attacking — she likely wanted to be seen; the mystery person likely did not break their watch; declines the GPS Search as bait — the 10 missing points were for the ten hourly screenshots instead.<span class=\"pg\">p.21–27<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nanase Tsubasa<\/b> She wants the search; he vetoes it as a trap; the two concur the culprit is “certainly the most likely” reading being Amasawa, but neither has proof.<span class=\"pg\">p.21–27<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p15-1\">← Before: Ch.1: The White Room reveal<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p28-1\">→ After: Ch.1: The exam canceled; the storm splits the plan<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v4-p21-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"nanase-tsubasa","q":"nanase tsubasa ch 1  the footprints  she pushes the gps idea  senpai   amasawa san s  footprints  is there something wrong with her footprints   senpai  let s do a gps search right now  it hasn t been that long since amasawa san first approached us  even if this mystery person ran away at full speed  they shouldn t have been able to get very far with the weather like this  right   then that s our guy   it s worth our while to spend the point on a search then  right   it still feels like a bit of a waste to not even check  she overrules herself  amasawa s footprints were clean  the mystery set was larger  she is frustrated by his gps veto but cannot disprove the  bait  theory  she accepts his judgment  both textbook detective and loyal ally  she cannot let a suspect walk away but yields to his read of the board","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v4-p21-1\"><h3><span class=\"ttl\"><a href=\"../../../people/nanase-tsubasa.html#sc-nanase-tsubasa-y2v4-p21-1\">Ch.1: The footprints; she pushes the GPS idea<\/a><\/span><span class=\"meta\">Y2V4 · p.21–27<\/span><span class=\"by\">notes on <a href=\"../../../people/nanase-tsubasa.html\">Nanase Tsubasa<\/a><\/span><\/h3><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> “Senpai…?”<span class=\"pg\">p.21<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> “Amasawa-san’s… footprints? Is there something wrong with her footprints?”<span class=\"pg\">p.21<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> “Senpai, let’s do a GPS Search right now! It hasn’t been that long since Amasawa-san first approached us. Even if this mystery person ran away at full speed, they shouldn’t have been able to get very far with the weather like…”<span class=\"pg\">p.26<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Senpai, let’s do a GPS Search right now! It hasn’t been that long since Amasawa-san first approached us. Even if this mystery person ran away at full speed, they shouldn’t have been able to get very far with the weather like this, right?”<span class=\"pg\">p.26<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…Then that’s our guy.”<span class=\"pg\">p.26<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s worth our while to spend the point on a search then, right?”<span class=\"pg\">p.26<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It still feels like a bit of a waste to not even check.”<span class=\"pg\">p.27<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> She overrules herself: Amasawa’s footprints were clean; the mystery set was larger; she is frustrated by his GPS veto but cannot disprove the “bait” theory; she accepts his judgment.<span class=\"pg\">p.21–27<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Both textbook detective and loyal ally; she cannot let a suspect walk away but yields to his read of the board.<span class=\"pg\">p.21–27<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v4-p18-1\">← Before: Nanase mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v4-p28-1\">→ After: Ch.1: The tent visit; her confession of hostility<\/button><\/div><\/article>"},{"i":"sc-kinoshita-minori-y2v4-p23-1","v":"y2v4","y":2,"o":19,"k":"","w":"kinoshita-minori","q":"kinoshita minori kinoshita mentioned in passing  honestly  i find it hard to believe that someone sent here by tsukishiro would make a mistake like that    ayanokoji   i convinced myself that amasawa san was the one who pushed komiya senpai and kinoshita senpai down the slope    nanase   i do have a pretty good idea which table everyone belongs to    ayanokoji","h":"<article class=\"card\" id=\"sc-kinoshita-minori-y2v4-p23-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kinoshita-minori.html#sc-kinoshita-minori-y2v4-p23-1\">Kinoshita mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.23, 31, 34<\/span><span class=\"by\">notes on <a href=\"../../../people/kinoshita-minori.html\">Kinoshita Minori<\/a><\/span><\/h3><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “Honestly, I find it hard to believe that someone sent here by Tsukishiro would make a mistake like that.” — Ayanokōji.<span class=\"pg\">p.23<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “I convinced myself that Amasawa-san was the one who pushed Komiya-senpai and Kinoshita-senpai down the slope.” — Nanase.<span class=\"pg\">p.31<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “I do have a pretty good idea which Table everyone belongs to.” — Ayanokōji.<span class=\"pg\">p.34<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kinoshita-minori-y2v4-p10-1\">← Before: Kinoshita mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kinoshita-minori-y2v4-p56-1\">→ After: Kinoshita mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-amasawa-ichika-y2v4-p27-1","v":"y2v4","y":2,"o":19,"k":"","w":"amasawa-ichika","q":"amasawa ichika ch 1  talking about her  mention records   amasawa aside  if we did a search right now and there was only one student with a missing signal  what then    ayanokoji s reasoning about a gps search   we were probably going to be stuck here for the rest of the day  at the very least    the school notification lands  her file   i haven t been able to get the image of amasawa san out of my mind  showing up out of nowhere in the rain    nanase   it d be weird if amasawa san was completely unrelated  right    nanase   and to top it all off  i just  happened  to catch sight of her as she fled the scene    nanase   catch sight of her as she fled the scene    nanase   that s  i imagine that s because she was interested in what happened to komiya senpai and kinoshita senpai  it s the same mentality as how an arsonist always returns to the scene of the crime    nanase   i do have a pretty good idea which table everyone belongs to    ayanokoji  amasawa s table is his example","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v4-p27-1\"><h3><span class=\"ttl\"><a href=\"../../../people/amasawa-ichika.html#sc-amasawa-ichika-y2v4-p27-1\">Ch.1: Talking about her (mention records)<\/a><\/span><span class=\"meta\">Y2V4 · p.27–34<\/span><span class=\"by\">notes on <a href=\"../../../people/amasawa-ichika.html\">Amasawa Ichika<\/a><\/span><\/h3><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “Amasawa aside, if we did a search right now and there was only one student with a missing signal, what then?” — Ayanokōji&#x27;s reasoning about a GPS search.<span class=\"pg\">p.27<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “We were probably going to be stuck here for the rest of the day, at the very least.” — the school notification lands; her file.<span class=\"pg\">p.28<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “I haven&#x27;t been able to get the image of Amasawa-san out of my mind, showing up out of nowhere in the rain.” — Nanase.<span class=\"pg\">p.31<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “It&#x27;d be weird if Amasawa-san was completely unrelated, right?” — Nanase.<span class=\"pg\">p.32<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “And to top it all off, I just ‘happened’ to catch sight of her as she fled the scene?” — Nanase.<span class=\"pg\">p.32<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “catch sight of her as she fled the scene?” — Nanase.<span class=\"pg\">p.32<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “That&#x27;s… I imagine that&#x27;s because she was interested in what happened to Komiya-senpai and Kinoshita-senpai. It&#x27;s the same mentality as how an arsonist always returns to the scene of the crime.” — Nanase.<span class=\"pg\">p.33<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “I do have a pretty good idea which Table everyone belongs to.” — Ayanokōji; Amasawa&#x27;s table is his example.<span class=\"pg\">p.34<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v4-p21-1\">← Before: Ch.1: The aftermath she left behind<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v4-p43-1\">→ After: Ch.1: Her signal, reconstructed<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v4-p28-1","v":"y2v4","y":2,"o":19,"k":"","w":"ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 1  the exam canceled  the storm splits the plan he peels off drenched clothes  receives the school s cancellation notice for the seventh day  his all out second half plan is now toothless with every group fresh   the cancellation could not have come at a worse time  the school hints compensation for lost tasks movements will be announced when the weather clears","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v4-p28-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v4-p28-1\">Ch.1: The exam canceled; the storm splits the plan<\/a><\/span><span class=\"meta\">Y2V4 · p.28–30<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">He peels off drenched clothes; receives the school’s cancellation notice for the seventh day; his all-out second-half plan is now toothless with every group fresh — the cancellation could not have come at a worse time.<\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> The school hints compensation for lost Tasks/movements will be announced when the weather clears.<span class=\"pg\">p.28<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p21-1\">← Before: Ch.1: The footprints; the whittled stick; the GPS verdict<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p31-1\">→ After: Ch.1: Nanase’s visit; the trust test<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v4-p28-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"nanase-tsubasa","q":"nanase tsubasa ch 1  the tent visit  her confession of hostility from across in her own tent she calls out through the rain and joins him  she sits in his tent dripping wet with a towel draped over her   i d like to talk to you for a bit  senpai  is it alright if i come and join you   hah  i m sorry for intruding upon your rest  senpai   i m pretty shameless  aren t i   i treated you with such hostility for the longest time  senpai  saying all sorts of terrible things straight to your face  you must be annoyed that i m reaching out all buddy buddy like this   i haven t been able to get the image of amasawa san out of my mind  showing up out of nowhere in the rain  when i started thinking about all the hardships you ve been put through  i just  i felt like i had to call out to you   i convinced myself that amasawa san was the one who pushed komiya senpai and kinoshita senpai down the slope  i thought that she was just hiding her true nature because she wanted to hide the truth  but then you said that she wasn t necessarily the culprit and now i just don t know what to believe anymore   that  uhm  wouldn t that be strange though   even if amasawa san isn t the real culprit  they d still have to be someone she knows  right  therefore  isn t it also possible that she s an accomplice of some sort   i suppose it s not hard to imagine that amasawa san is capable of exercising violence in much the same way   it d be weird if amasawa san was completely unrelated  right  i mean  her watch just  happened  to be broken when komiya and kinoshita just  happened  to get attacked  and she just  happened  to be watching from somewhere nearby  and to top it all off  i just  happened  to catch sight of her as she fled the scene   what  no  thank you for placing your trust in me  i m very grateful  overwhelmed by guilt  she apologizes for months of hostility  she is moved by his trust  points hidden from her  walkie talkie level screenshot knowledge  she pushes the theory that amasawa s associate is the real attacker","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v4-p28-1\"><h3><span class=\"ttl\"><a href=\"../../../people/nanase-tsubasa.html#sc-nanase-tsubasa-y2v4-p28-1\">Ch.1: The tent visit; her confession of hostility<\/a><\/span><span class=\"meta\">Y2V4 · p.28–36<\/span><span class=\"by\">notes on <a href=\"../../../people/nanase-tsubasa.html\">Nanase Tsubasa<\/a><\/span><\/h3><p class=\"setup\">From across in her own tent she calls out through the rain and joins him; she sits in his tent dripping wet with a towel draped over her.<\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> “I’d like to talk to you for a bit, Senpai! Is it alright if I come and join you!?”<span class=\"pg\">p.29<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> “Hah… I’m sorry for intruding upon your rest, Senpai.”<span class=\"pg\">p.30<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> “I’m pretty shameless, aren’t I?”<span class=\"pg\">p.30<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “I treated you with such hostility for the longest time, Senpai. Saying all sorts of terrible things straight to your face… You must be annoyed that I’m reaching out all buddy-buddy like this.”<span class=\"pg\">p.30<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I haven’t been able to get the image of Amasawa-san out of my mind, showing up out of nowhere in the rain… When I started thinking about all the hardships you’ve been put through, I just… I felt like I had to call out to you.”<span class=\"pg\">p.31<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I convinced myself that Amasawa-san was the one who pushed Komiya-senpai and Kinoshita-senpai down the slope. I thought that she was just hiding her true nature because she wanted to hide the truth, but then you said that she wasn’t necessarily the culprit and now I just don’t know what to believe anymore…”<span class=\"pg\">p.31<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That… Uhm, wouldn’t that be strange though?”<span class=\"pg\">p.32<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Even if Amasawa-san isn’t the real culprit, they’d still have to be someone she knows, right? Therefore, isn’t it also possible that she’s an accomplice of some sort?”<span class=\"pg\">p.32<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I suppose it’s not hard to imagine that Amasawa-san is capable of exercising violence in much the same way.”<span class=\"pg\">p.33<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’d be weird if Amasawa-san was completely unrelated, right? I mean, her watch just ‘happened’ to be broken when Komiya and Kinoshita just ‘happened’ to get attacked, and she just ‘happened’ to be watching from somewhere nearby? And to top it all off, I just ‘happened’ to catch sight of her as she fled the scene?”<span class=\"pg\">p.32<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What? No! Thank you for placing your trust in me! I’m very grateful!”<span class=\"pg\">p.34<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Overwhelmed by guilt, she apologizes for months of hostility; she is moved by his trust (points hidden from her, walkie-talkie-level screenshot knowledge); she pushes the theory that Amasawa’s associate is the real attacker.<span class=\"pg\">p.28–36<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v4-p21-1\">← Before: Ch.1: The footprints; she pushes the GPS idea<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v4-p36-1\">→ After: Ch.1: The screenshots; the 10-point gap; the fish-school strategy<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v4-p31-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"nanase-tsubasa ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 1  nanase s visit  the trust test in the rain she flies into his tent  less than a second in the rain  she apologizes for her months of hostility and finally comes to terms with her guilty conscience   hah  i m sorry for intruding upon your rest  senpai   i m pretty shameless  aren t i   i treated you with such hostility for the longest time  senpai  saying all sorts of terrible things straight to your face  you must be annoyed that i m reaching out all buddy buddy like this   i really don t mind  so please stop apologizing   i haven t been able to get the image of amasawa san out of my mind  showing up out of nowhere in the rain  when i started thinking about all the hardships you ve been put through  i just  i felt like i had to call out to you   i convinced myself that amasawa san was the one who pushed komiya senpai and kinoshita senpai down the slope  i thought that she was just hiding her true nature because she wanted to hide the truth  but then you said that she wasn t necessarily the culprit and now i just don t know what to believe anymore   that  uhm  wouldn t that be strange though   even if amasawa san isn t the real culprit  they d still have to be someone she knows  right  therefore  isn t it also possible that she s an accomplice of some sort   nanase  i thought we had a relationship where we could trust each other without hiding anything  or was that just a misunderstanding on my part   what  no  thank you for placing your trust in me  i m very grateful   i m surprised you noticed  properly speaking  i should have 88 points right now  she asks what the culprit s goal is   he counsels that they cannot know  she worries his score is off  she computes he should have 88  he explains the ten hourly gps searches and the screenshot archive  he keeps the points analysis to himself until she asks  her scent fills the tent  he puzzles over how she smells good after days of sweat  he chalks it up to deodorant","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v4-p31-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v4-p31-1\">Ch.1: Nanase’s visit; the trust test<\/a><\/span><span class=\"meta\">Y2V4 · p.31–36<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">In the rain she flies into his tent (less than a second in the rain); she apologizes for her months of hostility and finally comes to terms with her guilty conscience.<\/p><p class=\"with\">with <a href=\"../../../people/nanase-tsubasa.html\">Nanase Tsubasa<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> “Hah… I’m sorry for intruding upon your rest, Senpai.”<span class=\"pg\">p.30<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> “I’m pretty shameless, aren’t I?”<span class=\"pg\">p.30<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> “I treated you with such hostility for the longest time, Senpai. Saying all sorts of terrible things straight to your face… You must be annoyed that I’m reaching out all buddy-buddy like this.”<span class=\"pg\">p.30<\/span><\/li><\/ul><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “I really don’t mind, so please stop apologizing.”<span class=\"pg\">p.31<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I haven’t been able to get the image of Amasawa-san out of my mind, showing up out of nowhere in the rain… When I started thinking about all the hardships you’ve been put through, I just… I felt like I had to call out to you.”<span class=\"pg\">p.31<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I convinced myself that Amasawa-san was the one who pushed Komiya-senpai and Kinoshita-senpai down the slope. I thought that she was just hiding her true nature because she wanted to hide the truth, but then you said that she wasn’t necessarily the culprit and now I just don’t know what to believe anymore…”<span class=\"pg\">p.31<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That… Uhm, wouldn’t that be strange though?”<span class=\"pg\">p.32<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Even if Amasawa-san isn’t the real culprit, they’d still have to be someone she knows, right? Therefore, isn’t it also possible that she’s an accomplice of some sort?”<span class=\"pg\">p.32<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Nanase, I thought we had a relationship where we could trust each other without hiding anything. Or was that just a misunderstanding on my part?”<span class=\"pg\">p.34<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What? No! Thank you for placing your trust in me! I’m very grateful!”<span class=\"pg\">p.34<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m surprised you noticed. Properly speaking, I should have 88 points right now.”<span class=\"pg\">p.35<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> She asks what the culprit’s goal is — he counsels that they cannot know; she worries his score is off; she computes he should have 88; he explains the ten hourly GPS searches and the screenshot archive; he keeps the points analysis to himself until she asks.<span class=\"pg\">p.31–36<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Her scent fills the tent; he puzzles over how she smells good after days of sweat; he chalks it up to deodorant.<span class=\"pg\">p.33<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p28-1\">← Before: Ch.1: The exam canceled; the storm splits the plan<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p36-1\">→ After: Ch.1: Ten screenshots; the third-year coalition<\/button><\/div><\/article>"},{"i":"sc-komiya-kyogo-y2v4-p31-1","v":"y2v4","y":2,"o":19,"k":"","w":"komiya-kyogo","q":"komiya kyogo komiya mentioned in passing  i convinced myself that amasawa san was the one who pushed komiya senpai and kinoshita senpai down the slope    nanase   i do have a pretty good idea which table everyone belongs to    ayanokoji","h":"<article class=\"card\" id=\"sc-komiya-kyogo-y2v4-p31-1\"><h3><span class=\"ttl\"><a href=\"../../../people/komiya-kyogo.html#sc-komiya-kyogo-y2v4-p31-1\">Komiya mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.31, 34<\/span><span class=\"by\">notes on <a href=\"../../../people/komiya-kyogo.html\">Komiya Kyogo<\/a><\/span><\/h3><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “I convinced myself that Amasawa-san was the one who pushed Komiya-senpai and Kinoshita-senpai down the slope.” — Nanase.<span class=\"pg\">p.31<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “I do have a pretty good idea which Table everyone belongs to.” — Ayanokōji.<span class=\"pg\">p.34<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-komiya-kyogo-y2v4-p10-1\">← Before: Komiya mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-komiya-kyogo-y2v4-p56-1\">→ After: Komiya mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v4-p36-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"nanase-tsubasa ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 1  ten screenshots  the third year coalition  there are arrival bonuses  early bird bonuses  and tasks   but you only have 78  10 points less  i don t think i forgot a penalty or something either   for this special exam  designated areas are announced four times per day as students move throughout the island  this time window lasts for ten hours per day  from 7 00 am to 5 00 pm   the gps searching feature is an extremely convenient tool that allows you to find out the location of every student on the island  however  if used only a single time  you d just get a glimpse at everyone s current location  so its overall usefulness is marginal   besides  since we ve been moving together  you should already be able to get a rough estimate of how many points i ve earned just by thinking back on it   i didn t even realize that you had done this  senpai   i say this with all due respect  but is this really worth paying ten whole points for  if it was possible to share the screenshots with someone  then there might be some added value  but it d take a considerable amount of time for one person to analyze the movement patterns on their own  wouldn t it   there are so many groups moving around together  almost like they re a school of fish   are they  doing this to monopolize tasks   most likely  the point is to have nagumo effortlessly secure first place in any task they come across by fixing the competition in his favor   they  they re all from groups down at the bottom of the rankings   tell me  what s stopping students from working together to have a specific group come out on top   that would be due to class points and the overarching threat of expulsion  of course   the strength of this strategy is that the groups down at the bottom of the rankings are free to do anything they want during the exam  when you re in last place  there s no difference between having one point and having fifty  at the end of the day  you ll still lose class points and get expelled all the same   behind the scenes  nagumo has probably prepared some relief measures of his own   it s impossible for the other third year classes to graduate as class a by coming out on top through special exams  that being said  what if it s possible to get into class a by agreeing to work together with nagumo instead  decodes the third year plot from b8 hour by hour  bottom rank groups appear at nagumo s locations at 8 9 am  then travel as one conglomerate  the point poor design prevents conspicuous zero point tells  each supporting group keeps at least one member hitting designated areas to mask the coalition  the third years have effectively conceded the class competition and are bidding class a admission from nagumo   on the fifth day of the exam  i approached both ryuen and sakayanagi with a certain proposal of sorts  to clear specific tasks together with the help of a  select portion  of the second year student body   i think i understand now  you re saying that  for you  it wasn t a very big risk to spend ten points in exchange for this information  right senpai   somewhat  i haven t exactly done away with my goal of reaching the top or anything   koenji was indeed amazing  but the truth behind what was going on here was probably a little bit different  his second year counter strategy  allied groups clear designated tasks together  points not concentrated in any one group  was already in motion before this storm day  he keeps the truth of koenji s  race  quiet as well  a mask nagumo runs to hide the third year coalition","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v4-p36-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v4-p36-1\">Ch.1: Ten screenshots; the third-year coalition<\/a><\/span><span class=\"meta\">Y2V4 · p.36–44<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/nanase-tsubasa.html\">Nanase Tsubasa<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> “There are Arrival Bonuses, Early Bird Bonuses, and Tasks…”<span class=\"pg\">p.35<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> “But you only have 78, 10 points less. I don’t think I forgot a penalty or something either…”<span class=\"pg\">p.35<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “For this special exam, designated areas are announced four times per day as students move throughout the island. This time window lasts for ten hours per day, from 7:00 AM to 5:00 PM.”<span class=\"pg\">p.36<\/span><\/li><\/ul><details class=\"more\"><summary>19 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “The GPS searching feature is an extremely convenient tool that allows you to find out the location of every student on the island. However, if used only a single time, you’d just get a glimpse at everyone’s current location, so its overall usefulness is marginal.”<span class=\"pg\">p.36<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Besides, since we’ve been moving together, you should already be able to get a rough estimate of how many points I’ve earned just by thinking back on it.”<span class=\"pg\">p.36<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…I didn’t even realize that you had done this, Senpai.”<span class=\"pg\">p.37<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I say this with all due respect, but is this really worth paying ten whole points for? If it was possible to share the screenshots with someone, then there might be some added value, but it’d take a considerable amount of time for one person to analyze the movement patterns on their own, wouldn’t it?”<span class=\"pg\">p.37<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There are so many groups moving around together… almost like they’re a school of fish.”<span class=\"pg\">p.38<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Are they… doing this to monopolize Tasks?”<span class=\"pg\">p.38<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Most likely, the point is to have Nagumo effortlessly secure first-place in any Task they come across by fixing the competition in his favor.”<span class=\"pg\">p.39<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “They… they’re all from groups down at the bottom of the rankings…”<span class=\"pg\">p.39<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Tell me, what’s stopping students from working together to have a specific group come out on top?”<span class=\"pg\">p.40<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That would be due to class points and the overarching threat of expulsion, of course.”<span class=\"pg\">p.40<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The strength of this strategy is that the groups down at the bottom of the rankings are free to do anything they want during the exam. When you’re in last place, there’s no difference between having one point and having fifty. At the end of the day, you’ll still lose class points and get expelled all the same.”<span class=\"pg\">p.40<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Behind the scenes, Nagumo has probably prepared some relief measures of his own.”<span class=\"pg\">p.41<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s impossible for the other third-year classes to graduate as Class A by coming out on top through special exams. That being said, what if it’s possible to get into Class A by agreeing to work together with Nagumo instead?”<span class=\"pg\">p.41<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> Decodes the third-year plot from B8 hour-by-hour: bottom-rank groups appear at Nagumo’s locations at 8–9 AM, then travel as one conglomerate; the point-poor design prevents conspicuous zero-point tells; each supporting group keeps at least one member hitting designated areas to mask the coalition; the third years have effectively conceded the class competition and are bidding Class A admission from Nagumo.<span class=\"pg\">p.38–41<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “On the fifth day of the exam, I approached both Ryūen and Sakayanagi with a certain proposal of sorts: to clear specific Tasks together with the help of a ‘select portion’ of the second-year student body.”<span class=\"pg\">p.42<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I think I understand now. You’re saying that, for you, it wasn’t a very big risk to spend ten points in exchange for this information, right Senpai?”<span class=\"pg\">p.42<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Somewhat. I haven’t exactly done away with my goal of reaching the top or anything.”<span class=\"pg\">p.42<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Kōenji was indeed amazing, but the truth behind what was going on here was probably a little bit different.”<span class=\"pg\">p.43<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> His second-year counter-strategy (allied groups clear designated Tasks together, points not concentrated in any one group) was already in motion before this storm day; he keeps the truth of Kōenji’s “race” quiet as well (a mask Nagumo runs to hide the third-year coalition).<span class=\"pg\">p.42–43<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p31-1\">← Before: Ch.1: Nanase’s visit; the trust test<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p45-1\">→ After: Ch.1: Compensation; his standing; the storm hangs<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v4-p36-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"nagumo-miyabi kouenji-rokusuke amasawa-ichika nanase-tsubasa","q":"nanase tsubasa ch 1  the screenshots  the 10 point gap  the fish school strategy  wait  isn t your score somehow  lower than expected   there are arrival bonuses  early bird bonuses  and tasks  then subtracting points for any penalties  ah  i m also assuming that you took first place in the tasks you took part in while i was taking a break   but you only have 78  10 points less  i don t think i forgot a penalty or something either   uhm  i already understand what you used your points on  senpai  and i agree that if you know where everyone s moving on an hourly basis  you might be able to find out which tables they belong to  however  it didn t seem like you were doing very much with your tablet yesterday  and it s not very easy information to memorize either  are you  are you really telling me that you memorized everything in an instant   i say this with all due respect  but is this really worth paying ten whole points for  if it was possible to share the screenshots with someone  then there might be some added value  but it d take a considerable amount of time for one person to analyze the movement patterns on their own  wouldn t it   i didn t even realize that you had done this  senpai   there are so many groups moving around together  almost like they re a school of fish   are they  doing this to monopolize tasks   however  groups other than president nagumo s won t be able to score points as a result  right  i can t imagine that they re all part of the same table either  working together for the success of a specific group  it s an idea that pretty much anyone could come up with  but it d be impossible to put it into practice effectively   they  they re all from groups down at the bottom of the rankings   that would be due to class points and the overarching threat of expulsion  of course   would they really want to let nagumo win  even at the cost of their own expulsion  even if they can t rise up to class a  i can t imagine that they d want to leave the school  right   in a way  i can t even tell who s running this exam anymore  the school or the student council president   i think i understand now  you re saying that  for you  it wasn t a very big risk to spend ten points in exchange for this information  right senpai   koenji senpai sure is amazing  isn t he  giving president nagumo a run for his money all by himself   senpai  this looks like it could end up changing everything   eh  ah  sorry   i ll head back to my own tent then   as soon as the rain stops  i think i m going to try to chase after amasawa san  it s clear enough that she s from the white room  and i m concerned with what she s planning to do after this  her arithmetic is nearly perfect   she catches the 10 point discrepancy from arrival early bird bonuses and his solo first places  she reads the third year coalition as  a school of fish  can t tell who runs the exam anymore  she falls asleep mid conversation after exerting herself beyond her limits  mountain climb   nanase ayanokoji fight  and vows to trail amasawa once the rain stops  she pieces together the third year coalition from b8 hour by hours  admires his brilliance and fears the class competition is already lost for the third years  she calls him amazing for giving nagumo a run for his money alone  swears to chase her when the rain stops","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v4-p36-1\"><h3><span class=\"ttl\"><a href=\"../../../people/nanase-tsubasa.html#sc-nanase-tsubasa-y2v4-p36-1\">Ch.1: The screenshots; the 10-point gap; the fish-school strategy<\/a><\/span><span class=\"meta\">Y2V4 · p.36–46<\/span><span class=\"by\">notes on <a href=\"../../../people/nanase-tsubasa.html\">Nanase Tsubasa<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/nagumo-miyabi.html\">Nagumo Miyabi<\/a> · <a href=\"../../../people/kouenji-rokusuke.html\">Kōenji Rokusuke<\/a> · <a href=\"../../../people/amasawa-ichika.html\">Amasawa Ichika<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> “Wait, isn’t your score somehow… lower than expected?”<span class=\"pg\">p.35<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> “There are Arrival Bonuses, Early Bird Bonuses, and Tasks… then subtracting points for any penalties─ Ah, I’m also assuming that you took first place in the Tasks you took part in while I was taking a break.”<span class=\"pg\">p.35<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> “But you only have 78, 10 points less. I don’t think I forgot a penalty or something either…”<span class=\"pg\">p.35<\/span><\/li><\/ul><details class=\"more\"><summary>20 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Uhm, I already understand what you used your points on, Senpai. And I agree that if you know where everyone’s moving on an hourly basis, you might be able to find out which Tables they belong to. However, it didn’t seem like you were doing very much with your tablet yesterday, and it’s not very easy information to memorize either… Are you… Are you really telling me that you memorized everything in an instant?”<span class=\"pg\">p.36<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I say this with all due respect, but is this really worth paying ten whole points for? If it was possible to share the screenshots with someone, then there might be some added value, but it’d take a considerable amount of time for one person to analyze the movement patterns on their own, wouldn’t it?”<span class=\"pg\">p.37<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…I didn’t even realize that you had done this, Senpai.”<span class=\"pg\">p.37<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There are so many groups moving around together… almost like they’re a school of fish.”<span class=\"pg\">p.38<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Are they… doing this to monopolize Tasks?”<span class=\"pg\">p.38<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “However, groups other than President Nagumo’s won’t be able to score points as a result, right? I can’t imagine that they’re all part of the same Table either. Working together for the success of a specific group… It’s an idea that pretty much anyone could come up with, but it’d be impossible to put it into practice effectively.”<span class=\"pg\">p.39<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “They… they’re all from groups down at the bottom of the rankings…”<span class=\"pg\">p.39<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That would be due to class points and the overarching threat of expulsion, of course.”<span class=\"pg\">p.39<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Would they really want to let Nagumo win, even at the cost of their own expulsion? Even if they can’t rise up to Class A, I can’t imagine that they’d want to leave the school, right?”<span class=\"pg\">p.41<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “In a way, I can’t even tell who’s running this exam anymore: the school or the student council president.”<span class=\"pg\">p.41<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I think I understand now. You’re saying that, for you, it wasn’t a very big risk to spend ten points in exchange for this information, right Senpai?”<span class=\"pg\">p.42<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Kōenji-senpai sure is amazing, isn’t he? Giving President Nagumo a run for his money all by himself.”<span class=\"pg\">p.43<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Senpai, this looks like it could end up changing everything.”<span class=\"pg\">p.45<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Eh? Ah…! Sorry!”<span class=\"pg\">p.46<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…I’ll head back to my own tent then.”<span class=\"pg\">p.46<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “As soon as the rain stops, I think I’m going to try to chase after Amasawa-san. It’s clear enough that she’s from the White Room, and I’m concerned with what she’s planning to do after this.”<span class=\"pg\">p.46<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Her arithmetic is nearly perfect — she catches the 10-point discrepancy from arrival/early-bird bonuses and his solo first places; she reads the third-year coalition as “a school of fish,” can’t tell who runs the exam anymore; she falls asleep mid-conversation after exerting herself beyond her limits (mountain climb + Nanase–Ayanokōji fight) and vows to trail Amasawa once the rain stops.<span class=\"pg\">p.36–46<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> She pieces together the third-year coalition from B8 hour-by-hours; admires his brilliance and fears the class competition is already lost for the third years.<span class=\"pg\">p.38–41<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> She calls him amazing for giving Nagumo a run for his money alone.<span class=\"pg\">p.43<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Amasawa Ichika<\/b> Swears to chase her when the rain stops.<span class=\"pg\">p.46<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v4-p28-1\">← Before: Ch.1: The tent visit; her confession of hostility<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v4-p47-1\">→ After: Ch.1: Sent off with warnings<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y2v4-p38-1","v":"y2v4","y":2,"o":19,"k":"","w":"kiriyama-ikuto","q":"kiriyama ikuto kiriyama mentioned in passing  for example  some third year groups moved fairly unusually throughout the day yesterday  furthermore  these groups are always closely related to nagumo s group or kiriyama s group  when i looked into it  i noticed something pretty interesting   3rd place  third year group kiriyama   150 points    the printed top ten","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y2v4-p38-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kiriyama-ikuto.html#sc-kiriyama-ikuto-y2v4-p38-1\">Kiriyama mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.38, 48<\/span><span class=\"by\">notes on <a href=\"../../../people/kiriyama-ikuto.html\">Kiriyama Ikuto<\/a><\/span><\/h3><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “For example, some third-year groups moved fairly unusually throughout the day yesterday. Furthermore, these groups are always closely related to Nagumo’s group or Kiriyama’s group. When I looked into it, I noticed something pretty interesting.”<span class=\"pg\">p.38<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “3rd Place: Third-Year Group Kiriyama – 150 Points” — the printed top-ten.<span class=\"pg\">p.48<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y2v4-p95-1\">→ After: Ch.4: The plan against Kouenji<\/button><\/div><\/article>"},{"i":"sc-nagumo-miyabi-y2v4-p38-1","v":"y2v4","y":2,"o":19,"k":"","w":"nagumo-miyabi","q":"nagumo miyabi nagumo mentioned in passing  for example  some third year groups moved fairly unusually throughout the day yesterday  furthermore  these groups are always closely related to nagumo s group or kiriyama s group  when i looked into it  i noticed something pretty interesting   to begin with  nagumo s group was in area b8 at 7 00 am that morning   most likely  the point is to have nagumo effortlessly secure first place in any task they come across by fixing the competition in his favor   behind the scenes  nagumo has probably prepared some relief measures of his own   that was exactly why nagumo s strategy was so brilliant  if multiple groups all had zero points  it would be far too conspicuous   it s impossible for the other third year classes to graduate as class a by coming out on top through special exams  that being said  what if it s possible to get into class a by agreeing to work together with nagumo instead   in a sense  we should also assume that the groups supporting him are competing with each other   honestly  you re probably onto something there as well  nagumo has the entire third year in the palm of his hand after all  he s not here to follow the rules  he s here to make and dictate them to the rest of us   it probably wouldn t be an exaggeration to say that  throughout the entire history of the advanced nurturing high school  nagumo was and will be the first and last of his kind   in reality  however  nagumo s group was most likely just putting on an act as they slowed down to match pace with koenji   2nd place  third year group nagumo   166 points    the printed top ten   if koenji were to maintain his current pace and keep diligently racking up points  he d end up with a final score of around 350  so if i wanted to bridge the gap  i d have to earn close to 40 points per day for the rest of the exam   furthermore  there would definitely be groups looking to conserve their stamina for the double points being offered on the final day as well","h":"<article class=\"card\" id=\"sc-nagumo-miyabi-y2v4-p38-1\"><h3><span class=\"ttl\"><a href=\"../../../people/nagumo-miyabi.html#sc-nagumo-miyabi-y2v4-p38-1\">Nagumo mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.38–43, 48–50<\/span><span class=\"by\">notes on <a href=\"../../../people/nagumo-miyabi.html\">Nagumo Miyabi<\/a><\/span><\/h3><details class=\"more\"><summary>13 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “For example, some third-year groups moved fairly unusually throughout the day yesterday. Furthermore, these groups are always closely related to Nagumo’s group or Kiriyama’s group. When I looked into it, I noticed something pretty interesting.”<span class=\"pg\">p.38<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “To begin with, Nagumo’s group was in area B8 at 7:00 AM that morning.”<span class=\"pg\">p.38<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Most likely, the point is to have Nagumo effortlessly secure first-place in any Task they come across by fixing the competition in his favor.”<span class=\"pg\">p.39<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Behind the scenes, Nagumo has probably prepared some relief measures of his own.”<span class=\"pg\">p.39<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “That was exactly why Nagumo’s strategy was so brilliant. If multiple groups all had zero points, it would be far too conspicuous.”<span class=\"pg\">p.40<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “It’s impossible for the other third-year classes to graduate as Class A by coming out on top through special exams. That being said, what if it’s possible to get into Class A by agreeing to work together with Nagumo instead?”<span class=\"pg\">p.41<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “In a sense, we should also assume that the groups supporting him are competing with each other.”<span class=\"pg\">p.41<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Honestly, you’re probably onto something there as well. Nagumo has the entire third-year in the palm of his hand after all. He’s not here to follow the rules; He’s here to make and dictate them to the rest of us.”<span class=\"pg\">p.41<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “It probably wouldn’t be an exaggeration to say that, throughout the entire history of the Advanced Nurturing High School, Nagumo was and will be the first and last of his kind.”<span class=\"pg\">p.42<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “In reality, however, Nagumo’s group was most likely just putting on an act as they slowed down to match pace with Kōenji.”<span class=\"pg\">p.43<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “2nd Place: Third-Year Group Nagumo – 166 Points” — the printed top-ten.<span class=\"pg\">p.48<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “If Kōenji were to maintain his current pace and keep diligently racking up points, he’d end up with a final score of around 350, so if I wanted to bridge the gap, I’d have to earn close to 40 points per day for the rest of the exam.”<span class=\"pg\">p.49<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Furthermore, there would definitely be groups looking to conserve their stamina for the double points being offered on the final day as well.”<span class=\"pg\">p.50<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y2v4-p61-1\">→ After: Nagumo mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-kouenji-rokusuke-y2v4-p42-1","v":"y2v4","y":2,"o":19,"k":"","w":"kouenji-rokusuke","q":"koenji rokusuke koenji mentioned in passing  koenji was indeed amazing  but the truth behind what was going on here was probably a little bit different   fortunately  koenji has been putting in a lot of work of his own  so instead  i ve been focused on gathering the resources necessary to support my peers who need help   koenji senpai sure is amazing  isn t he  giving president nagumo a run for his money all by himself    nanase to ayanokoji   in reality  however  nagumo s group was most likely just putting on an act as they slowed down to match pace with koenji   and then  once the rankings were hidden again  he and his group would pick up the pace for the final two days of the exam   1st place  second year group koenji   168 points    the printed top ten   there was a full  90 point difference between myself and koenji  who was all the way up in first place   if koenji were to maintain his current pace and keep diligently racking up points  he d end up with a final score of around 350  so if i wanted to bridge the gap  i d have to earn close to 40 points per day for the rest of the exam","h":"<article class=\"card\" id=\"sc-kouenji-rokusuke-y2v4-p42-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kouenji-rokusuke.html#sc-kouenji-rokusuke-y2v4-p42-1\">Kōenji mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.42–43, 48–50<\/span><span class=\"by\">notes on <a href=\"../../../people/kouenji-rokusuke.html\">Kōenji Rokusuke<\/a><\/span><\/h3><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “Kōenji was indeed amazing, but the truth behind what was going on here was probably a little bit different.”<span class=\"pg\">p.42<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Fortunately, Kōenji has been putting in a lot of work of his own, so instead, I’ve been focused on gathering the resources necessary to support my peers who need help.”<span class=\"pg\">p.42<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Kōenji-senpai sure is amazing, isn’t he? Giving President Nagumo a run for his money all by himself.” — Nanase to Ayanokōji.<span class=\"pg\">p.43<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “In reality, however, Nagumo’s group was most likely just putting on an act as they slowed down to match pace with Kōenji.”<span class=\"pg\">p.43<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “And then, once the rankings were hidden again, he and his group would pick up the pace for the final two days of the exam.”<span class=\"pg\">p.43<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “1st Place: Second-Year Group Kōenji – 168 Points” — the printed top-ten.<span class=\"pg\">p.48<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “There was a full, 90 point difference between myself and Kōenji, who was all the way up in first place.”<span class=\"pg\">p.48<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “If Kōenji were to maintain his current pace and keep diligently racking up points, he’d end up with a final score of around 350, so if I wanted to bridge the gap, I’d have to earn close to 40 points per day for the rest of the exam.”<span class=\"pg\">p.49<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kouenji-rokusuke-y2v4-p4-1\">← Before: Kōenji mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kouenji-rokusuke-y2v4-p62-1\">→ After: Kōenji mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-sakayanagi-arisu-y2v4-p42-1","v":"y2v4","y":2,"o":19,"k":"","w":"sakayanagi-arisu","q":"sakayanagi arisu sakayanagi mentioned in passing  on the fifth day of the exam  i approached both ryuen and sakayanagi with a certain proposal of sorts  to clear specific tasks together with the help of a  select portion  of the second year student body   7th place  second year group sakayanagi   127 points    the printed top ten","h":"<article class=\"card\" id=\"sc-sakayanagi-arisu-y2v4-p42-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sakayanagi-arisu.html#sc-sakayanagi-arisu-y2v4-p42-1\">Sakayanagi mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.42, 48<\/span><span class=\"by\">notes on <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/span><\/h3><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “On the fifth day of the exam, I approached both Ryūen and Sakayanagi with a certain proposal of sorts: to clear specific Tasks together with the help of a ‘select portion’ of the second-year student body.”<span class=\"pg\">p.42<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “7th Place: Second-Year Group Sakayanagi – 127 Points” — the printed top-ten.<span class=\"pg\">p.48<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sakayanagi-arisu-y2v4-p55-1\">→ After: Sakayanagi mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-amasawa-ichika-y2v4-p43-1","v":"y2v4","y":2,"o":19,"k":"","w":"amasawa-ichika","q":"amasawa ichika ch 1  her signal  reconstructed on the sixth day screenshots  her gps signal shows two areas south of their designated area  alone  then a faster than foot route to b6  then c6 one area right  she participated in three or so tasks as she diligently made her way to designated areas  nothing suspicious as of 5 00 pm  he reads it as her taking the exam seriously  or at least leaving no gps searchable openings  named throughout the reconstruction  not present on these pages","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v4-p43-1\"><h3><span class=\"ttl\"><a href=\"../../../people/amasawa-ichika.html#sc-amasawa-ichika-y2v4-p43-1\">Ch.1: Her signal, reconstructed<\/a><\/span><span class=\"meta\">Y2V4 · p.43–44<\/span><span class=\"by\">notes on <a href=\"../../../people/amasawa-ichika.html\">Amasawa Ichika<\/a><\/span><\/h3><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> On the sixth-day screenshots, her GPS signal shows two areas south of their designated area, alone, then a faster-than-foot route to B6, then C6 one area right; she participated in three or so Tasks as she diligently made her way to designated areas; nothing suspicious as of 5:00 PM; he reads it as her taking the exam seriously (or at least leaving no GPS-searchable openings).<span class=\"pg\">p.43<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Named throughout the reconstruction; not present on these pages.<span class=\"pg\">p.43–44<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v4-p27-1\">← Before: Ch.1: Talking about her (mention records)<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v4-p45-1\">→ After: Ch.1: The storm passes (mention records)<\/button><\/div><\/article>"},{"i":"sc-amasawa-ichika-y2v4-p45-1","v":"y2v4","y":2,"o":19,"k":"","w":"amasawa-ichika","q":"amasawa ichika ch 1  the storm passes  mention records   as soon as the rain stops  i think i m going to try to chase after amasawa san  it s clear enough that she s from the white room  and i m concerned with what she s planning to do after this    nanase   in terms of pure combat power  you could say that amasawa was even a step above the likes of sudo and ryuen  while they may have her beat in terms of raw physical strength  she d definitely be far  far ahead of them when it comes to technique and experience    ayanokoji s analysis","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v4-p45-1\"><h3><span class=\"ttl\"><a href=\"../../../people/amasawa-ichika.html#sc-amasawa-ichika-y2v4-p45-1\">Ch.1: The storm passes (mention records)<\/a><\/span><span class=\"meta\">Y2V4 · p.45–50<\/span><span class=\"by\">notes on <a href=\"../../../people/amasawa-ichika.html\">Amasawa Ichika<\/a><\/span><\/h3><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “As soon as the rain stops, I think I&#x27;m going to try to chase after Amasawa-san. It&#x27;s clear enough that she&#x27;s from the White Room, and I&#x27;m concerned with what she&#x27;s planning to do after this.” — Nanase.<span class=\"pg\">p.46<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “In terms of pure combat power, you could say that Amasawa was even a step above the likes of Sudō and Ryūen. While they may have her beat in terms of raw physical strength, she&#x27;d definitely be far, far ahead of them when it comes to technique and experience.” — Ayanokōji&#x27;s analysis.<span class=\"pg\">p.47<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v4-p43-1\">← Before: Ch.1: Her signal, reconstructed<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v4-p51-1\">→ After: Amasawa mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v4-p45-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"nanase-tsubasa kouenji-rokusuke ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 1  compensation  his standing  the storm hangs the school posts that only one fourth of the day s task movement quota was done  all arrival bonus  early bird bonus and task points on the final day will be doubled  the forecast expects the weather to improve before tomorrow morning   senpai  this looks like it could end up changing everything   the school was right to tell us about this so far ahead of time  it ll give groups the chance to reassess their plans for the second half of the exam   eh  ah  sorry   i ll head back to my own tent then   as soon as the rain stops  i think i m going to try to chase after amasawa san  it s clear enough that she s from the white room  and i m concerned with what she s planning to do after this   you have your other group member  hosen  to watch out for as well   i m not afraid of getting expelled  ayanokoji senpai  i ll do anything if it means protecting you  no matter the cost   i want you to avoid doing anything that may put me at risk   if that s really true  then in any case  i just ask that you be careful  got it  he reads the public top ten  koenji 168  nagumo 166  kiriyama 150  mizoe 133  ochiai 133  ryuen 128  sakayanagi 127  takahashi 115  kanzaki 104  kuronaga 101  he is 49th with 78  a first place early bird streak  11 pts each  four chances day  would close the gap in nine more first places  koenji s estimated final  350  he plans to silently rise through the lower ranks in the second half  the 10th place score acts as the barrier between public knowledge and anonymity  the storm day may have triggered a spike of activity for the next two days  he evaluates the cancellation s damage but recasts the news as an opening for the second half  warns nanase off amasawa hosen   her careless actions may cause him unintended problems  koenji 168 pts leads  ayanokoji notes his own 90 point gap and koenji s likely  350 final  sends her off with a warning   she vows anything for him  he tells her to protect him by protecting herself","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v4-p45-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v4-p45-1\">Ch.1: Compensation; his standing; the storm hangs<\/a><\/span><span class=\"meta\">Y2V4 · p.45–50<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/nanase-tsubasa.html\">Nanase Tsubasa<\/a> · <a href=\"../../../people/kouenji-rokusuke.html\">Kōenji Rokusuke<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> “Senpai, this looks like it could end up changing everything.”<span class=\"pg\">p.45<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “The school was right to tell us about this so far ahead of time. It’ll give groups the chance to reassess their plans for the second half of the exam.”<span class=\"pg\">p.45<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> “Eh? Ah…! Sorry!”<span class=\"pg\">p.46<\/span><\/li><\/ul><details class=\"more\"><summary>12 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> The school posts that only one-fourth of the day’s Task/movement quota was done; all Arrival Bonus, Early Bird Bonus and Task points on the final day will be doubled; the forecast expects the weather to improve before tomorrow morning.<span class=\"pg\">p.45<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…I’ll head back to my own tent then.”<span class=\"pg\">p.46<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “As soon as the rain stops, I think I’m going to try to chase after Amasawa-san. It’s clear enough that she’s from the White Room, and I’m concerned with what she’s planning to do after this.”<span class=\"pg\">p.46<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You have your other group member, Hōsen, to watch out for as well.”<span class=\"pg\">p.47<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m not afraid of getting expelled, Ayanokōji-senpai. I’ll do anything if it means protecting you, no matter the cost.”<span class=\"pg\">p.47<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I want you to avoid doing anything that may put me at risk.”<span class=\"pg\">p.47<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If that’s really true, then in any case, I just ask that you be careful. Got it?”<span class=\"pg\">p.48<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> He reads the public top-ten: Kōenji 168, Nagumo 166, Kiriyama 150, Mizoe 133, Ochiai 133, Ryūen 128, Sakayanagi 127, Takahashi 115, Kanzaki 104, Kuronaga 101; he is 49th with 78; a first-place Early Bird streak (11 pts each; four chances/day) would close the gap in nine more first places; Kōenji’s estimated final ~350.<span class=\"pg\">p.48<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> He plans to silently rise through the lower ranks in the second half; the 10th-place score acts as the barrier between public knowledge and anonymity; the storm day may have triggered a spike of activity for the next two days.<span class=\"pg\">p.49<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> He evaluates the cancellation’s damage but recasts the news as an opening for the second half; warns Nanase off Amasawa/Hōsen — her careless actions may cause him unintended problems.<span class=\"pg\">p.45–50<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> Kōenji 168 pts leads; Ayanokōji notes his own 90-point gap and Kōenji’s likely ~350 final.<span class=\"pg\">p.48–50<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nanase Tsubasa<\/b> Sends her off with a warning — she vows anything for him; he tells her to protect him by protecting herself.<span class=\"pg\">p.46–48<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p36-1\">← Before: Ch.1: Ten screenshots; the third-year coalition<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p51-1\">→ After: Day eight: food shortage; parting with Nanase<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v4-p47-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"housen-kazuomi nanase-tsubasa","q":"nanase tsubasa ch 1  sent off with warnings  i m not clear on all the details  but from what you re saying she must be an extremely dangerous opponent   yes  given his sheer strength  he s not an opponent i can handle either   i m not afraid of getting expelled  ayanokoji senpai  i ll do anything if it means protecting you  no matter the cost   that  that would be unacceptable of me  i can t be causing you any more trouble than i already have   i understand  i promise  she hears the warning  hosen  no underestimating amasawa by gender age  as a rallying cry and vows to protect him at any cost  he reframes it   her carelessness may cost him  she tears up and promises to be careful  her other group member  he tells her hosen is beyond her handling  she concedes it","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v4-p47-1\"><h3><span class=\"ttl\"><a href=\"../../../people/nanase-tsubasa.html#sc-nanase-tsubasa-y2v4-p47-1\">Ch.1: Sent off with warnings<\/a><\/span><span class=\"meta\">Y2V4 · p.47–50<\/span><span class=\"by\">notes on <a href=\"../../../people/nanase-tsubasa.html\">Nanase Tsubasa<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/housen-kazuomi.html\">Hōsen Kazuomi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> “I’m not clear on all the details, but from what you’re saying she must be an extremely dangerous opponent.”<span class=\"pg\">p.47<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> “Yes. Given his sheer strength, he’s not an opponent I can handle either.”<span class=\"pg\">p.47<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> “I’m not afraid of getting expelled, Ayanokōji-senpai. I’ll do anything if it means protecting you, no matter the cost.”<span class=\"pg\">p.47<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “That… That would be unacceptable of me. I can’t be causing you any more trouble than I already have…”<span class=\"pg\">p.48<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I understand, I promise.”<span class=\"pg\">p.48<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> She hears the warning (Hōsen, no underestimating Amasawa by gender/age) as a rallying cry and vows to protect him at any cost; he reframes it — her carelessness may cost him; she tears up and promises to be careful.<span class=\"pg\">p.47–50<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> Her other group member; he tells her Hōsen is beyond her handling; she concedes it.<span class=\"pg\">p.47<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v4-p36-1\">← Before: Ch.1: The screenshots; the 10-point gap; the fish-school strategy<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v4-p51-1\">→ After: Ch.2: Parting at area E3<\/button><\/div><\/article>"},{"i":"sc-mizoe-y2v4-p48-1","v":"y2v4","y":2,"o":19,"k":"","w":"mizoe","q":"mizoe mizoe in the printed top ten  4th place  third year group mizoe   133 points    the printed top ten","h":"<article class=\"card\" id=\"sc-mizoe-y2v4-p48-1\"><h3><span class=\"ttl\">Mizoe in the printed top-ten<\/span><span class=\"meta\">Y2V4 · p.48<\/span><span class=\"by\">notes on <a href=\"../../../people/index.html#mizoe\">Mizoe<\/a><\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “4th Place: Third-Year Group Mizoe – 133 Points” — the printed top-ten.<span class=\"pg\">p.48<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-ochiai-y2v4-p48-1","v":"y2v4","y":2,"o":19,"k":"","w":"ochiai","q":"ochiai ochiai in the printed top ten  4th place  third year group ochiai   133 points    the printed top ten","h":"<article class=\"card\" id=\"sc-ochiai-y2v4-p48-1\"><h3><span class=\"ttl\">Ochiai in the printed top-ten<\/span><span class=\"meta\">Y2V4 · p.48<\/span><span class=\"by\">notes on <a href=\"../../../people/index.html#ochiai\">Ochiai<\/a><\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “4th Place: Third-Year Group Ochiai – 133 Points” — the printed top-ten.<span class=\"pg\">p.48<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-ryuuen-kakeru-y2v4-p48-1","v":"y2v4","y":2,"o":19,"k":"","w":"ryuuen-kakeru","q":"ryuen kakeru ryuen mentioned in passing  6th place  second year group ryuen   128 points    the printed top ten   i hadn t seen what ryuen s food situation was like back when i crossed paths with him    ayanokoji   even if ryuen was here right now  i had my doubts that even he would be able to solve her problem    ayanokoji   ibuki has hated me ever since she found out that i was the  x  ryuen had been looking for    ayanokoji   if it was one of the top ten  it was ryuuen s second year group  sakayanagi s group  or utomiya s group and the others in first year    narration   but it seems that ryuuen s class is also starting to change little by little    ayanokoji   the details of first year d class are unknown  but housen is a person who uses a type of power similar to ryuuen s to control the class and act    ayanokoji   yes  i was able to contact ryuuen kun and horikita san  we are progressing smoothly    ayanokoji to sakayanagi   he got into a fight with a boy named ryuuen from the 2nd class  grade b  and they both got very injured    tsubaki recounting housen s fight   after housen went into a confrontation with the ryuuen and was resolved  it was evident in the subsequent search that all the groups withdrew and returned to the special exam    ayanokoji   of course  ryuuen kun  please tell me when the time comes    sakayanagi   as for the scores  ryuuen and katsuragi s group also fought hard    narration","h":"<article class=\"card\" id=\"sc-ryuuen-kakeru-y2v4-p48-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ryuuen-kakeru.html#sc-ryuuen-kakeru-y2v4-p48-1\">Ryūen mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.48, 67, 70, 78, 97, 120, 122, 161, 184, 191, 277, 280<\/span><span class=\"by\">notes on <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/span><\/h3><details class=\"more\"><summary>12 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “6th Place: Second-Year Group Ryūen – 128 Points” — the printed top-ten.<span class=\"pg\">p.48<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “I hadn&#x27;t seen what Ryūen&#x27;s food situation was like back when I crossed paths with him” — Ayanokōji.<span class=\"pg\">p.67<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Even if Ryūen was here right now, I had my doubts that even he would be able to solve her problem.” — Ayanokōji.<span class=\"pg\">p.70<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Ibuki has hated me ever since she found out that I was the ‘X’ Ryūen had been looking for.” — Ayanokōji.<span class=\"pg\">p.78<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “if it was one of the top ten, it was Ryuuen&#x27;s second year group, Sakayanagi&#x27;s group, or Utomiya&#x27;s group and the others in first year.” — narration.<span class=\"pg\">p.97<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “but it seems that Ryuuen&#x27;s class is also starting to change little by little.” — Ayanokōji.<span class=\"pg\">p.120<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “The details of first-year D-class are unknown, but Housen is a person who uses a type of power similar to Ryuuen&#x27;s to control the class and act.” — Ayanokōji.<span class=\"pg\">p.122<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Yes. I was able to contact Ryuuen-kun and Horikita-san. We are progressing smoothly.” — Ayanokōji to Sakayanagi.<span class=\"pg\">p.161<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “He got into a fight with a boy named Ryuuen from the 2nd class. grade B, and they both got very injured.” — Tsubaki recounting Housen&#x27;s fight.<span class=\"pg\">p.184<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “after Housen went into a confrontation with the Ryuuen and was resolved, it was evident in the subsequent search that all the groups withdrew and returned to the special exam.” — Ayanokōji.<span class=\"pg\">p.191<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Of course, Ryuuen-kun. Please tell me when the time comes.” — Sakayanagi.<span class=\"pg\">p.277<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “As for the scores, Ryuuen and Katsuragi&#x27;s group also fought hard,” — narration.<span class=\"pg\">p.280<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ryuuen-kakeru-y2v4-p14-1\">← Before: Ryūen mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ryuuen-kakeru-y2v4-p168-1\">→ After: Ch.5: The one-on-one<\/button><\/div><\/article>"},{"i":"sc-takahashi-osamu-y2v4-p48-1","v":"y2v4","y":2,"o":19,"k":"","w":"takahashi-osamu","q":"takahashi osamu takahashi in the printed top ten  8th place  first year group takahashi   115 points    the printed top ten","h":"<article class=\"card\" id=\"sc-takahashi-osamu-y2v4-p48-1\"><h3><span class=\"ttl\"><a href=\"../../../people/takahashi-osamu.html#sc-takahashi-osamu-y2v4-p48-1\">Takahashi in the printed top-ten<\/a><\/span><span class=\"meta\">Y2V4 · p.48<\/span><span class=\"by\">notes on <a href=\"../../../people/takahashi-osamu.html\">Takahashi Osamu<\/a><\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “8th Place: First-Year Group Takahashi – 115 Points” — the printed top-ten.<span class=\"pg\">p.48<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-takahashi-osamu-y2v4-p121-1\">→ After: Takahashi mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-kanzaki-ryuuji-y2v4-p49-1","v":"y2v4","y":2,"o":19,"k":"","w":"kanzaki-ryuuji","q":"kanzaki ryuji kanzaki in the printed top ten  9th place  second year group kanzaki   104 points    the printed top ten","h":"<article class=\"card\" id=\"sc-kanzaki-ryuuji-y2v4-p49-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kanzaki-ryuuji.html#sc-kanzaki-ryuuji-y2v4-p49-1\">Kanzaki in the printed top-ten<\/a><\/span><span class=\"meta\">Y2V4 · p.49<\/span><span class=\"by\">notes on <a href=\"../../../people/kanzaki-ryuuji.html\">Kanzaki Ryūji<\/a><\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “9th Place: Second-Year Group Kanzaki – 104 Points” — the printed top-ten.<span class=\"pg\">p.49<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-kuronaga-y2v4-p49-1","v":"y2v4","y":2,"o":19,"k":"","w":"kuronaga","q":"kuronaga kuronaga in the printed top ten  10th place  third year group kuronaga   101 points    the printed top ten","h":"<article class=\"card\" id=\"sc-kuronaga-y2v4-p49-1\"><h3><span class=\"ttl\">Kuronaga in the printed top-ten<\/span><span class=\"meta\">Y2V4 · p.49<\/span><span class=\"by\">notes on <a href=\"../../../people/index.html#kuronaga\">Kuronaga<\/a><\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “10th Place: Third-Year Group Kuronaga – 101 Points” — the printed top-ten.<span class=\"pg\">p.49<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kuronaga-y2v4-p59-1\">→ After: Kuronaga mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-amasawa-ichika-y2v4-p51-1","v":"y2v4","y":2,"o":19,"k":"","w":"amasawa-ichika","q":"amasawa ichika amasawa mentioned in passing  amasawa s most likely just going to head to the next designated area  right    nanase   amasawa san was following us as of the evening of the sixth day or the morning of the seventh  right    nanase   naturally  i ve referenced this with the data on my tablet already  but  as far as i recall  our score didn t go down whatsoever yesterday    nanase   although it s unknown where on the island amasawa san was that morning  you and i were traveling quite fast at the time  it wouldn t have been very easy for her to catch up to us unless she was already somewhere nearby  right    nanase   how do you plan on joining up with amasawa and hosen    nanase","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v4-p51-1\"><h3><span class=\"ttl\"><a href=\"../../../people/amasawa-ichika.html#sc-amasawa-ichika-y2v4-p51-1\">Amasawa mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.51–54<\/span><span class=\"by\">notes on <a href=\"../../../people/amasawa-ichika.html\">Amasawa Ichika<\/a><\/span><\/h3><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “Amasawa’s most likely just going to head to the next designated area, right?” — Nanase.<span class=\"pg\">p.52<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Amasawa-san was following us as of the evening of the sixth day or the morning of the seventh, right?” — Nanase.<span class=\"pg\">p.52<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Naturally, I’ve referenced this with the data on my tablet already, but… as far as I recall, our score didn’t go down whatsoever yesterday.” — Nanase.<span class=\"pg\">p.52<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Although it’s unknown where on the island Amasawa-san was that morning, you and I were traveling quite fast at the time. It wouldn’t have been very easy for her to catch up to us unless she was already somewhere nearby, right?” — Nanase.<span class=\"pg\">p.52<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “How do you plan on joining up with Amasawa and Hōsen?” — Nanase.<span class=\"pg\">p.53<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v4-p45-1\">← Before: Ch.1: The storm passes (mention records)<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v4-p55-1\">→ After: Ch.2: The alliance widens (mention records)<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v4-p51-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"nanase-tsubasa amasawa-ichika ayanokouji-kiyotaka","q":"ayanokoji kiyotaka day eight  food shortage  parting with nanase after the storm clears by 6 00 am  he sits with his food shortage   never having undergone starvation training  his immune system is at risk  his only real source is tasks  nanase approaches with her backpack ready   i ll have to address the food shortage sooner rather than later   i m all packed and ready to go   amasawa s most likely just going to head to the next designated area  right   without putting too much thought into it  it s probably safe to assume that she approached us using a gps search on the morning of the seventh   naturally  i ve referenced this with the data on my tablet already  but  as far as i recall  our score didn t go down whatsoever yesterday   that s probably why she came up with a clever plan to help close the distance   i m guessing she used a trick of some sort to find out my exact location  nanase s tablet data  she is a group member  rules out a group gps search  amasawa traveled light and likely had someone else disclose his location   he cannot be certain of the method  at area e3 they part ways   she heads off with a one point arrival bonus  chasing her own plan  poke around among the first years and report anything suspicious   it looks like this is where we part ways  senpai  at least for now   i can t imagine that i d cross paths with them by aimlessly wandering around the island  but it s not like i can waste a bunch of points searching for them either  with that being the case  i ll start out by using the point i just got and try my best to chase after their gps signals  if i can t find them after that  i guess i ll just travel to the next designated area   i think it ll take a first year student like me to poke around and find out what other first years are up to  if i catch wind that something bad is going down  i ll come running and let you know  ayanokoji senpai   just don t overdo it  he is glad she is going after amasawa hosen but fears she will end up lost  he sends her off with minimal warning  she sets off with her tablet  they travel together to e3  then part  she goes undercover among the first years as his eyes and ears  he concludes she found him by a trick  not by a group gps search","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v4-p51-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v4-p51-1\">Day eight: food shortage; parting with Nanase<\/a><\/span><span class=\"meta\">Y2V4 · p.51–54<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">After the storm clears by 6:00 AM, he sits with his food shortage — never having undergone starvation training, his immune system is at risk; his only real source is Tasks; Nanase approaches with her backpack ready. At area E3 they part ways — she heads off with a one-point Arrival Bonus, chasing her own plan: poke around among the first-years and report anything suspicious.<\/p><p class=\"with\">with <a href=\"../../../people/nanase-tsubasa.html\">Nanase Tsubasa<\/a> · <a href=\"../../../people/amasawa-ichika.html\">Amasawa Ichika<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “I’ll have to address the food shortage sooner rather than later…”<span class=\"pg\">p.51<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> “I’m all packed and ready to go.”<span class=\"pg\">p.51<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> “Amasawa’s most likely just going to head to the next designated area, right?”<span class=\"pg\">p.52<\/span><\/li><\/ul><details class=\"more\"><summary>12 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Without putting too much thought into it, it’s probably safe to assume that she approached us using a GPS Search on the morning of the seventh.”<span class=\"pg\">p.52<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Naturally, I’ve referenced this with the data on my tablet already, but… as far as I recall, our score didn’t go down whatsoever yesterday.”<span class=\"pg\">p.52<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That’s probably why she came up with a clever plan to help close the distance.”<span class=\"pg\">p.52<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m guessing she used a trick of some sort to find out my exact location.”<span class=\"pg\">p.53<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> Nanase’s tablet data (she is a group member) rules out a group GPS Search; Amasawa traveled light and likely had someone else disclose his location — he cannot be certain of the method.<span class=\"pg\">p.52–53<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It looks like this is where we part ways, Senpai. At least for now.”<span class=\"pg\">p.53<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I can’t imagine that I’d cross paths with them by aimlessly wandering around the island, but it’s not like I can waste a bunch of points searching for them either. With that being the case, I’ll start out by using the point I just got and try my best to chase after their GPS signals. If I can’t find them after that, I guess I’ll just travel to the next designated area.”<span class=\"pg\">p.53<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I think it’ll take a first-year student like me to poke around and find out what other first-years are up to. If I catch wind that something bad is going down, I’ll come running and let you know, Ayanokōji-senpai.”<span class=\"pg\">p.54<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Just don’t overdo it.”<span class=\"pg\">p.54<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> He is glad she is going after Amasawa/Hōsen but fears she will end up lost; he sends her off with minimal warning; she sets off with her tablet.<span class=\"pg\">p.54<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nanase Tsubasa<\/b> They travel together to E3, then part; she goes undercover among the first-years as his eyes and ears.<span class=\"pg\">p.51–54<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Amasawa Ichika<\/b> He concludes she found him by a trick, not by a group GPS Search.<span class=\"pg\">p.51–53<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p45-1\">← Before: Ch.1: Compensation; his standing; the storm hangs<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p55-1\">→ After: Ch.2: Reuniting with Horikita<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v4-p51-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"ayanokouji-kiyotaka amasawa-ichika nanase-tsubasa","q":"nanase tsubasa ch 2  parting at area e3 after the rain clears by 6 00 am she tells him she s all packed  the two walk together to e3  both heading to the same area  on the way they compare notes on amasawa s movements   amasawa s most likely just going to head to the next designated area  right   amasawa san was following us as of the evening of the sixth day or the morning of the seventh  right   without putting too much thought into it  it s probably safe to assume that she approached us using a gps search on the morning of the seventh   naturally  i ve referenced this with the data on my tablet already  but  as far as i recall  our score didn t go down whatsoever yesterday   although it s unknown where on the island amasawa san was that morning  you and i were traveling quite fast at the time  it wouldn t have been very easy for her to catch up to us unless she was already somewhere nearby  right   it looks like this is where we part ways  senpai  at least for now   how do you plan on joining up with amasawa and hosen   i can t imagine that i d cross paths with them by aimlessly wandering around the island  but it s not like i can waste a bunch of points searching for them either  with that being the case  i ll start out by using the point i just got and try my best to chase after their gps signals  if i can t find them after that  i guess i ll just travel to the next designated area   i think it ll take a first year student like me to poke around and find out what other first years are up to  if i catch wind that something bad is going down  i ll come running and let you know  ayanokoji senpai  sober about amasawa s surveillance abilities  no group gps search used   score unchanged  proposes tailing her with minimalist searches  knows he is stronger  so she volunteers to infiltrate first year circles for intelligence  walks with him  parts at e3 with her own plan to spy on the first years for him  her target  she intends to chase amasawa with gps searches and watch the first years","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v4-p51-1\"><h3><span class=\"ttl\"><a href=\"../../../people/nanase-tsubasa.html#sc-nanase-tsubasa-y2v4-p51-1\">Ch.2: Parting at area E3<\/a><\/span><span class=\"meta\">Y2V4 · p.51–54<\/span><span class=\"by\">notes on <a href=\"../../../people/nanase-tsubasa.html\">Nanase Tsubasa<\/a><\/span><\/h3><p class=\"setup\">After the rain clears by 6:00 AM she tells him she’s all packed; the two walk together to E3, both heading to the same area; on the way they compare notes on Amasawa’s movements.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/amasawa-ichika.html\">Amasawa Ichika<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> “Amasawa’s most likely just going to head to the next designated area, right?”<span class=\"pg\">p.52<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> “Amasawa-san was following us as of the evening of the sixth day or the morning of the seventh, right?”<span class=\"pg\">p.52<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Without putting too much thought into it, it’s probably safe to assume that she approached us using a GPS Search on the morning of the seventh.”<span class=\"pg\">p.52<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Naturally, I’ve referenced this with the data on my tablet already, but… as far as I recall, our score didn’t go down whatsoever yesterday.”<span class=\"pg\">p.52<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Although it’s unknown where on the island Amasawa-san was that morning, you and I were traveling quite fast at the time. It wouldn’t have been very easy for her to catch up to us unless she was already somewhere nearby, right?”<span class=\"pg\">p.52<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It looks like this is where we part ways, Senpai. At least for now.”<span class=\"pg\">p.53<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “How do you plan on joining up with Amasawa and Hōsen?”<span class=\"pg\">p.53<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I can’t imagine that I’d cross paths with them by aimlessly wandering around the island, but it’s not like I can waste a bunch of points searching for them either. With that being the case, I’ll start out by using the point I just got and try my best to chase after their GPS signals. If I can’t find them after that, I guess I’ll just travel to the next designated area.”<span class=\"pg\">p.53<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I think it’ll take a first-year student like me to poke around and find out what other first-years are up to. If I catch wind that something bad is going down, I’ll come running and let you know, Ayanokōji-senpai.”<span class=\"pg\">p.54<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Sober about Amasawa’s surveillance abilities (no group GPS Search used — score unchanged); proposes tailing her with minimalist searches; knows he is stronger, so she volunteers to infiltrate first-year circles for intelligence.<span class=\"pg\">p.51–54<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Walks with him; parts at E3 with her own plan to spy on the first-years for him.<span class=\"pg\">p.51–54<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Amasawa Ichika<\/b> Her target; she intends to chase Amasawa with GPS searches and watch the first-years.<span class=\"pg\">p.51–54<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v4-p47-1\">← Before: Ch.1: Sent off with warnings<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v4-p120-1\">→ After: Ch.4: 2:30 a.m.; Nanase&#x27;s warning<\/button><\/div><\/article>"},{"i":"sc-housen-kazuomi-y2v4-p53-1","v":"y2v4","y":2,"o":19,"k":"","w":"housen-kazuomi","q":"hosen kazuomi hosen mentioned in passing  how do you plan on joining up with amasawa and hosen    nanase asks ayanokoji about finding both group members","h":"<article class=\"card\" id=\"sc-housen-kazuomi-y2v4-p53-1\"><h3><span class=\"ttl\"><a href=\"../../../people/housen-kazuomi.html#sc-housen-kazuomi-y2v4-p53-1\">Hōsen mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.53<\/span><span class=\"by\">notes on <a href=\"../../../people/housen-kazuomi.html\">Hōsen Kazuomi<\/a><\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “How do you plan on joining up with Amasawa and Hōsen?” — Nanase asks Ayanokōji about finding both group members.<span class=\"pg\">p.53<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-housen-kazuomi-y2v4-p15-1\">← Before: Hōsen mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-housen-kazuomi-y2v4-p120-1\">→ After: Ch.4: The feigning cooperator<\/button><\/div><\/article>"},{"i":"sc-amasawa-ichika-y2v4-p55-1","v":"y2v4","y":2,"o":19,"k":"","w":"amasawa-ichika","q":"amasawa ichika ch 2  the alliance widens  mention records   of course  i kept certain things to myself  such as the fact that amasawa had been watching from the shadows    ayanokoji","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v4-p55-1\"><h3><span class=\"ttl\"><a href=\"../../../people/amasawa-ichika.html#sc-amasawa-ichika-y2v4-p55-1\">Ch.2: The alliance widens (mention records)<\/a><\/span><span class=\"meta\">Y2V4 · p.55–59<\/span><span class=\"by\">notes on <a href=\"../../../people/amasawa-ichika.html\">Amasawa Ichika<\/a><\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “Of course, I kept certain things to myself, such as the fact that Amasawa had been watching from the shadows.” — Ayanokōji.<span class=\"pg\">p.57<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v4-p51-1\">← Before: Amasawa mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v4-p62-1\">→ After: Ch.3: Her name in the night (mention records)<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v4-p55-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"horikita-suzune ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 2  reuniting with horikita he crosses the path of horikita for the first time since day one  at area f7 by a task site  she s surprisingly fresh and heading to g8  he s to f8  they travel together   ayanokoji kun   it s been eight days  huh   did you come for the task  or are you simply passing through  where are you headed after this  horikita   i m heading to g8  i ended up passing through here on the way  what about yourself   is it really so hard for you to believe that i m still in such good shape   most of the students i ve come across have looked awfully tired   hmm  did something unusual happen   yes  i am  it s troublesome in many ways  but being alone tends to make many things easier as well","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v4-p55-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v4-p55-1\">Ch.2: Reuniting with Horikita<\/a><\/span><span class=\"meta\">Y2V4 · p.55–56<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">He crosses the path of Horikita for the first time since day one, at area F7 by a Task site; she’s surprisingly fresh and heading to G8; he’s to F8; they travel together.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “Ayanokōji-kun?”<span class=\"pg\">p.55<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “It’s been eight days, huh?”<span class=\"pg\">p.55<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Did you come for the Task, or are you simply passing through? Where are you headed after this, Horikita?”<span class=\"pg\">p.55<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “I’m heading to G8. I ended up passing through here on the way. What about yourself?”<span class=\"pg\">p.56<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Is it really so hard for you to believe that I’m still in such good shape?”<span class=\"pg\">p.56<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Most of the students I’ve come across have looked awfully tired.”<span class=\"pg\">p.56<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Hmm. Did something unusual happen?”<span class=\"pg\">p.56<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yes, I am. It’s troublesome in many ways, but being alone tends to make many things easier as well.”<span class=\"pg\">p.56<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p51-1\">← Before: Day eight: food shortage; parting with Nanase<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p56-1\">→ After: Ch.2: The Shinohara rescue plan, coordinated<\/button><\/div><\/article>"},{"i":"sc-horikita-suzune-y2v4-p55-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"ayanokouji-kiyotaka sakayanagi-arisu horikita-suzune","q":"horikita suzune ch 2  horikita rejoins him at f7 she crosses paths with him at f7   day eight  the first reunion since day one  she looks a little surprised but unusually fresh  she s heading to g8  he s to f8  they walk together   ayanokoji kun   that it has   i m heading to g8  i ended up passing through here on the way  what about yourself   is it really so hard for you to believe that i m still in such good shape   yes  to be exact  i heard about it today  in light of that  i m glad that i ran into you   hmm  did something unusual happen  somebody from class 2 a reached out to her near the starting area earlier today and urged her to meet with sakayanagi  sakayanagi told her of the retirements of komiya and kinoshita and proposed a plan  the two began to negotiate  never in the bottom ten once during the exam   she moves with a strange calm  her interest in the cliff incident is sudden and purposeful  sakayanagi s contact reached her  summoned to meet her near the starting area  negotiated terms with her over the shinohara rescue","h":"<article class=\"card\" id=\"sc-horikita-suzune-y2v4-p55-1\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-suzune.html#sc-horikita-suzune-y2v4-p55-1\">Ch.2: Horikita rejoins him at F7<\/a><\/span><span class=\"meta\">Y2V4 · p.55–56<\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/span><\/h3><p class=\"setup\">She crosses paths with him at F7 — day eight, the first reunion since day one; she looks a little surprised but unusually fresh; she’s heading to G8, he’s to F8; they walk together.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “Ayanokōji-kun?”<span class=\"pg\">p.55<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “That it has.”<span class=\"pg\">p.55<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “I’m heading to G8. I ended up passing through here on the way. What about yourself?”<span class=\"pg\">p.56<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Is it really so hard for you to believe that I’m still in such good shape?”<span class=\"pg\">p.56<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yes. To be exact, I heard about it today. In light of that, I’m glad that I ran into you.”<span class=\"pg\">p.56<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Hmm. Did something unusual happen?”<span class=\"pg\">p.56<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Somebody from Class 2-A reached out to her near the starting area earlier today and urged her to meet with Sakayanagi; Sakayanagi told her of the retirements of Komiya and Kinoshita and proposed a plan; the two began to negotiate.<span class=\"pg\">p.56<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Never in the bottom ten once during the exam — she moves with a strange calm; her interest in the cliff incident is sudden and purposeful; Sakayanagi’s contact reached her.<span class=\"pg\">p.55–56<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Summoned to meet her near the starting area; negotiated terms with her over the Shinohara rescue.<span class=\"pg\">p.56<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y2v4-p19-1\">← Before: Horikita mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y2v4-p57-1\">→ After: Ch.2: The rescue, coordinated<\/button><\/div><\/article>"},{"i":"sc-sakayanagi-arisu-y2v4-p55-1","v":"y2v4","y":2,"o":19,"k":"","w":"sakayanagi-arisu","q":"sakayanagi arisu sakayanagi mentioned in passing  apparently it had gone something like this  somebody from class 2 a had reached out to horikita while she was near the starting area earlier today  and they had urged her to meet with sakayanagi  whereupon she was informed of komiya and kinoshita s retirement   yes  to be exact  i heard about it today    horikita to ayanokoji  she and horikita negotiated the rescue terms after she relayed the retirements and his proposed strategy for the second years","h":"<article class=\"card\" id=\"sc-sakayanagi-arisu-y2v4-p55-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sakayanagi-arisu.html#sc-sakayanagi-arisu-y2v4-p55-1\">Sakayanagi mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.55–57<\/span><span class=\"by\">notes on <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/span><\/h3><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “Apparently it had gone something like this: somebody from Class 2-A had reached out to Horikita while she was near the starting area earlier today, and they had urged her to meet with Sakayanagi, whereupon she was informed of Komiya and Kinoshita’s retirement.”<span class=\"pg\">p.56<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Yes. To be exact, I heard about it today.” — Horikita to Ayanokōji.<span class=\"pg\">p.56<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> She and Horikita negotiated the rescue terms after she relayed the retirements and his proposed strategy for the second-years.<span class=\"pg\">p.57<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sakayanagi-arisu-y2v4-p42-1\">← Before: Sakayanagi mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sakayanagi-arisu-y2v4-p59-1\">→ After: Sakayanagi mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-shinohara-satsuki-y2v4-p55-1","v":"y2v4","y":2,"o":19,"k":"","w":"shinohara-satsuki","q":"shinohara satsuki shinohara mentioned in passing  unusual  ah  now that you mention it  have you heard about what happened with shinohara    horikita to ayanokoji   i had no reason to do that  i had to prevent shinohara san from getting kicked out of school    horikita   shinohara san s group ranking has been dropping lower and lower every day  currently  she s placed seventh from the bottom    horikita","h":"<article class=\"card\" id=\"sc-shinohara-satsuki-y2v4-p55-1\"><h3><span class=\"ttl\"><a href=\"../../../people/shinohara-satsuki.html#sc-shinohara-satsuki-y2v4-p55-1\">Shinohara mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.55–59<\/span><span class=\"by\">notes on <a href=\"../../../people/shinohara-satsuki.html\">Shinohara Satsuki<\/a><\/span><\/h3><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “Unusual? Ah… now that you mention it, have you heard about what happened with Shinohara?” — Horikita to Ayanokōji.<span class=\"pg\">p.56<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “I had no reason to do that; I had to prevent Shinohara-san from getting kicked out of school.” — Horikita.<span class=\"pg\">p.57<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Shinohara-san’s group ranking has been dropping lower and lower every day. Currently, she’s placed seventh from the bottom.” — Horikita.<span class=\"pg\">p.57<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-shinohara-satsuki-y2v4-p10-1\">← Before: Shinohara mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-shinohara-satsuki-y2v4-p59-1\">→ After: Shinohara mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v4-p56-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"horikita-suzune shinohara-satsuki sakayanagi-arisu ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 2  the shinohara rescue plan  coordinated she tells him what she knows  earlier today a class 2 a contact pulled her near the starting area  urged her to see sakayanagi  sakayanagi relayed the retirements of komiya and kinoshita and proposed terms  the two began to negotiate  shinohara is seventh from the bottom and will hit expulsion by day s end   unusual  ah  now that you mention it  have you heard about what happened with shinohara   yes  to be exact  i heard about it today  in light of that  i m glad that i ran into you  apparently  narrated  it had gone something like this  somebody from class 2 a reached out to horikita near the starting area earlier today  urged her to meet with sakayanagi  and sakayanagi informed her of komiya and kinoshita s retirement   you didn t refuse to cooperate  right   i had no reason to do that  i had to prevent shinohara san from getting kicked out of school  i heard that you were one of the first on the scene at the time  do you know the details of what happened   no  not really  i think it could ve been both an incident or an accident   shinohara san s group ranking has been dropping lower and lower every day  currently  she s placed seventh from the bottom  at this rate  it seems she ll fall far enough to qualify for expulsion by the end of the day today  so we have to hurry  if worse comes to worst and we can t find another group for her to join  i ll take matters into my own hands  before i ran into you  i was lucky enough to secure first place in a task that rewarded me with three additional spaces in my group   but if that s how things play out  then it ll be just you and shinohara scoring all the points   at any rate  over these past eight days that i ve been walking around the island  i ve really come to realize that a lot more groups have walkie talkies than i anticipated  he shares only what he knows  the slope incident could be incident or accident  keeps the amasawa surveillance to himself  he notes walkie talkies are spreading among upper class groups  he joins her plan to hit the food task  reunion  she wins him over to the rescue cause  travel toward a food task together  seventh from bottom  expulsion imminent by day s end  he hopes sakayanagi s group merge goes through  the class 2 a contact summoned horikita to meet her  the two negotiated the fifth day rescue proposal  she told her about his strategy","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v4-p56-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v4-p56-1\">Ch.2: The Shinohara rescue plan, coordinated<\/a><\/span><span class=\"meta\">Y2V4 · p.56–58<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">She tells him what she knows: earlier today a Class 2-A contact pulled her near the starting area, urged her to see Sakayanagi; Sakayanagi relayed the retirements of Komiya and Kinoshita and proposed terms; the two began to negotiate; Shinohara is seventh from the bottom and will hit expulsion by day’s end.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/shinohara-satsuki.html\">Shinohara Satsuki<\/a> · <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Unusual? Ah… now that you mention it, have you heard about what happened with Shinohara?”<span class=\"pg\">p.56<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “Yes. To be exact, I heard about it today. In light of that, I’m glad that I ran into you.”<span class=\"pg\">p.56<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “You didn’t refuse to cooperate, right?”<span class=\"pg\">p.57<\/span><\/li><\/ul><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Apparently (narrated) it had gone something like this: somebody from Class 2-A reached out to Horikita near the starting area earlier today, urged her to meet with Sakayanagi, and Sakayanagi informed her of Komiya and Kinoshita’s retirement.<span class=\"pg\">p.56<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I had no reason to do that; I had to prevent Shinohara-san from getting kicked out of school. I heard that you were one of the first on the scene at the time, do you know the details of what happened?”<span class=\"pg\">p.57<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No, not really. I think it could’ve been both an incident or an accident.”<span class=\"pg\">p.57<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Shinohara-san’s group ranking has been dropping lower and lower every day. Currently, she’s placed seventh from the bottom. At this rate, it seems she’ll fall far enough to qualify for expulsion by the end of the day today, so we have to hurry. If worse comes to worst and we can’t find another group for her to join, I’ll take matters into my own hands. Before I ran into you, I was lucky enough to secure first place in a Task that rewarded me with three additional spaces in my group.”<span class=\"pg\">p.57<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But if that’s how things play out, then it’ll be just you and Shinohara scoring all the points.”<span class=\"pg\">p.57<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “At any rate, over these past eight days that I’ve been walking around the island, I’ve really come to realize that a lot more groups have walkie-talkies than I anticipated.”<span class=\"pg\">p.57<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> He shares only what he knows (the slope incident could be incident or accident), keeps the Amasawa surveillance to himself; he notes walkie-talkies are spreading among upper-class groups; he joins her plan to hit the food Task.<span class=\"pg\">p.56–58<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Reunion; she wins him over to the rescue cause; travel toward a food Task together.<span class=\"pg\">p.55–59<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shinohara Satsuki<\/b> Seventh from bottom; expulsion imminent by day’s end; he hopes Sakayanagi’s group merge goes through.<span class=\"pg\">p.57<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> The Class 2-A contact summoned Horikita to meet her; the two negotiated the fifth-day rescue proposal; she told her about his strategy.<span class=\"pg\">p.56–57<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p55-1\">← Before: Ch.2: Reuniting with Horikita<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p58-1\">→ After: Ch.2: The food Task; the day-eight tally<\/button><\/div><\/article>"},{"i":"sc-kinoshita-minori-y2v4-p56-1","v":"y2v4","y":2,"o":19,"k":"","w":"kinoshita-minori","q":"kinoshita minori kinoshita mentioned in passing  whereupon she was informed of komiya and kinoshita s retirement    narrated  sakayanagi told horikita","h":"<article class=\"card\" id=\"sc-kinoshita-minori-y2v4-p56-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kinoshita-minori.html#sc-kinoshita-minori-y2v4-p56-1\">Kinoshita mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.56–57<\/span><span class=\"by\">notes on <a href=\"../../../people/kinoshita-minori.html\">Kinoshita Minori<\/a><\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “whereupon she was informed of Komiya and Kinoshita’s retirement.” — narrated; Sakayanagi told Horikita.<span class=\"pg\">p.56<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kinoshita-minori-y2v4-p23-1\">← Before: Kinoshita mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-komiya-kyogo-y2v4-p56-1","v":"y2v4","y":2,"o":19,"k":"","w":"komiya-kyogo","q":"komiya kyogo komiya mentioned in passing  whereupon she was informed of komiya and kinoshita s retirement    narrated  sakayanagi told horikita","h":"<article class=\"card\" id=\"sc-komiya-kyogo-y2v4-p56-1\"><h3><span class=\"ttl\"><a href=\"../../../people/komiya-kyogo.html#sc-komiya-kyogo-y2v4-p56-1\">Komiya mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.56–57<\/span><span class=\"by\">notes on <a href=\"../../../people/komiya-kyogo.html\">Komiya Kyogo<\/a><\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “whereupon she was informed of Komiya and Kinoshita’s retirement.” — narrated; Sakayanagi told Horikita.<span class=\"pg\">p.56<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-komiya-kyogo-y2v4-p31-1\">← Before: Komiya mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-horikita-suzune-y2v4-p57-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"shinohara-satsuki ayanokouji-kiyotaka horikita-suzune","q":"horikita suzune ch 2  the rescue  coordinated walking with him  she relays the rescue plan and her own stake   a task first place that rewarded three extra group slots  shinohara seventh from the bottom and falling toward expulsion by day s end   i had no reason to do that  i had to prevent shinohara san from getting kicked out of school  i heard that you were one of the first on the scene at the time  do you know the details of what happened   shinohara san s group ranking has been dropping lower and lower every day  currently  she s placed seventh from the bottom  at this rate  it seems she ll fall far enough to qualify for expulsion by the end of the day today  so we have to hurry  if worse comes to worst and we can t find another group for her to join  i ll take matters into my own hands  before i ran into you  i was lucky enough to secure first place in a task that rewarded me with three additional spaces in my group   at any rate  over these past eight days that i ve been walking around the island  i ve really come to realize that a lot more groups have walkie talkies than i anticipated  i ve seen students making use of them all over the place  sakayanagi san telling her fellow classmates about what happened to shinohara san is only one such example   if we trusted one another a little more  i wonder  if we could ve done that as well   that s true enough  honest with him about her stake  shinohara  and her prize  three extra slots  she notes the spread of walkie talkies  especially among upper year groups  she concedes that inter class trust could have enabled the same among them  seventh from bottom  fighting to prevent her expulsion today  travels together  coordinates the rescue  both divert to the food task","h":"<article class=\"card\" id=\"sc-horikita-suzune-y2v4-p57-1\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-suzune.html#sc-horikita-suzune-y2v4-p57-1\">Ch.2: The rescue, coordinated<\/a><\/span><span class=\"meta\">Y2V4 · p.57<\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/span><\/h3><p class=\"setup\">Walking with him, she relays the rescue plan and her own stake — a Task first place that rewarded three extra group slots; Shinohara seventh from the bottom and falling toward expulsion by day’s end.<\/p><p class=\"with\">with <a href=\"../../../people/shinohara-satsuki.html\">Shinohara Satsuki<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “I had no reason to do that; I had to prevent Shinohara-san from getting kicked out of school. I heard that you were one of the first on the scene at the time, do you know the details of what happened?”<span class=\"pg\">p.57<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “Shinohara-san’s group ranking has been dropping lower and lower every day. Currently, she’s placed seventh from the bottom. At this rate, it seems she’ll fall far enough to qualify for expulsion by the end of the day today, so…”<span class=\"pg\">p.57<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “At any rate, over these past eight days that I’ve been walking around the island, I’ve really come to realize that a lot more groups have walkie-talkies than I anticipated. I’ve seen students making use of them all over the…”<span class=\"pg\">p.57<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Shinohara-san’s group ranking has been dropping lower and lower every day. Currently, she’s placed seventh from the bottom. At this rate, it seems she’ll fall far enough to qualify for expulsion by the end of the day today, so we have to hurry. If worse comes to worst and we can’t find another group for her to join, I’ll take matters into my own hands. Before I ran into you, I was lucky enough to secure first place in a Task that rewarded me with three additional spaces in my group.”<span class=\"pg\">p.57<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “At any rate, over these past eight days that I’ve been walking around the island, I’ve really come to realize that a lot more groups have walkie-talkies than I anticipated. I’ve seen students making use of them all over the place, Sakayanagi-san telling her fellow classmates about what happened to Shinohara-san is only one such example.”<span class=\"pg\">p.57<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If we trusted one another a little more, I wonder… if we could’ve done that as well…?”<span class=\"pg\">p.58<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That’s true enough.”<span class=\"pg\">p.58<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Honest with him about her stake (Shinohara) and her prize (three extra slots); she notes the spread of walkie-talkies, especially among upper-year groups; she concedes that inter-class trust could have enabled the same among them.<span class=\"pg\">p.57–58<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shinohara Satsuki<\/b> Seventh from bottom; fighting to prevent her expulsion today.<span class=\"pg\">p.57<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Travels together; coordinates the rescue; both divert to the food Task.<span class=\"pg\">p.55–59<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y2v4-p55-1\">← Before: Ch.2: Horikita rejoins him at F7<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y2v4-p58-1\">→ After: Ch.2: The food Task together<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v4-p58-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"horikita-suzune kuronaga ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 2  the food task  the day eight tally they divert to a food for participation task with up to fifteen slots   first years  third years and second years converge on it  horikita and he race there  arrival too late for early bird bonus  they mingle and trade information   i m running low on food  so i think i d like to drop by this task  how about you horikita   i don t have that much food remaining either  so i ll drop by the task as well   look who s talking  if you ve really run low on food  then you ought to be a bit more pressed yourself   i just don t have the energy to run anymore   and i m in the same boat  the exam holds course  classmates still unaware of shinohara s situation  he falls asleep hoping the next designated area leads near the starting area  his day eight tally  4 points from arrival bonuses   14 from four tasks   18  overall 96 points  23rd place  no top ten changes  kuronaga s group still tenth with 111 points  tenth place  111 points  holding the top ten barrier","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v4-p58-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v4-p58-1\">Ch.2: The food Task; the day-eight tally<\/a><\/span><span class=\"meta\">Y2V4 · p.58–59<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">They divert to a food-for-participation Task with up to fifteen slots — first-years, third-years and second-years converge on it; Horikita and he race there; arrival too late for Early Bird Bonus; they mingle and trade information.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/index.html#kuronaga\">Kuronaga<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “I’m running low on food, so I think I’d like to drop by this Task. How about you Horikita?”<span class=\"pg\">p.58<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “I don’t have that much food remaining either, so I’ll drop by the Task as well.”<span class=\"pg\">p.58<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “Look who’s talking. If you’ve really run low on food, then you ought to be a bit more pressed yourself.”<span class=\"pg\">p.59<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “I just don’t have the energy to run anymore.”<span class=\"pg\">p.59<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “And I’m in the same boat.”<span class=\"pg\">p.59<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The exam holds course: classmates still unaware of Shinohara’s situation; he falls asleep hoping the next designated area leads near the starting area.<span class=\"pg\">p.59<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> His day-eight tally: 4 points from Arrival Bonuses + 14 from four Tasks = 18; overall 96 points, 23rd place; no top-ten changes; Kuronaga’s group still tenth with 111 points.<span class=\"pg\">p.59<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kuronaga<\/b> Tenth place, 111 points, holding the top-ten barrier.<span class=\"pg\">p.59<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p56-1\">← Before: Ch.2: The Shinohara rescue plan, coordinated<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p60-1\">→ After: Ch.3: The 11th-place plan holds<\/button><\/div><\/article>"},{"i":"sc-horikita-suzune-y2v4-p58-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"horikita-suzune","q":"horikita suzune ch 2  the food task together both nearly out of food  they change course to a participatory food task with fifteen slots  the site swarms with first  second  and third year groups  they arrive too late for early bird bonuses and spend the last minutes trading information   i don t have that much food remaining either  so i ll drop by the task as well   look who s talking  if you ve really run low on food  then you ought to be a bit more pressed yourself   and i m in the same boat  no early bird bonuses today   with food at zero they chose the task together  her stamina is as managed as his  she accepts the late arrival without complaint","h":"<article class=\"card\" id=\"sc-horikita-suzune-y2v4-p58-1\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-suzune.html#sc-horikita-suzune-y2v4-p58-1\">Ch.2: The food Task together<\/a><\/span><span class=\"meta\">Y2V4 · p.58–59<\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/span><\/h3><p class=\"setup\">Both nearly out of food; they change course to a participatory food Task with fifteen slots; the site swarms with first-, second- and third-year groups; they arrive too late for Early Bird Bonuses and spend the last minutes trading information.<\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “I don’t have that much food remaining either, so I’ll drop by the Task as well.”<span class=\"pg\">p.58<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “Look who’s talking. If you’ve really run low on food, then you ought to be a bit more pressed yourself.”<span class=\"pg\">p.59<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “And I’m in the same boat.”<span class=\"pg\">p.59<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> No Early Bird Bonuses today — with food at zero they chose the Task together; her stamina is as managed as his; she accepts the late arrival without complaint.<span class=\"pg\">p.58–59<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y2v4-p57-1\">← Before: Ch.2: The rescue, coordinated<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y2v4-p67-1\">→ After: Horikita mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-kuronaga-y2v4-p59-1","v":"y2v4","y":2,"o":19,"k":"","w":"kuronaga","q":"kuronaga kuronaga mentioned in passing  the eighth day  which i had otherwise expected to devolve into a fierce battle  hadn t actually been that bad in the end  there hadn t been any significant changes in the scores of the top ten either  as the kuronaga group was still in tenth place with a total of 111 points","h":"<article class=\"card\" id=\"sc-kuronaga-y2v4-p59-1\"><h3><span class=\"ttl\">Kuronaga mentioned in passing<\/span><span class=\"meta\">Y2V4 · p.59<\/span><span class=\"by\">notes on <a href=\"../../../people/index.html#kuronaga\">Kuronaga<\/a><\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “The eighth day, which I had otherwise expected to devolve into a fierce battle, hadn’t actually been that bad in the end. There hadn’t been any significant changes in the scores of the top ten either, as the Kuronaga group was still in tenth place with a total of 111 points.”<span class=\"pg\">p.59<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kuronaga-y2v4-p49-1\">← Before: Kuronaga in the printed top-ten<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kuronaga-y2v4-p61-1\">→ After: Kuronaga in the standings<\/button><\/div><\/article>"},{"i":"sc-sakayanagi-arisu-y2v4-p59-1","v":"y2v4","y":2,"o":19,"k":"","w":"sakayanagi-arisu","q":"sakayanagi arisu sakayanagi mentioned in passing  tomorrow  my goal was to maintain an ideal rank and  if possible  meet up with sakayanagi once again    ayanokoji   make it back to the starting area and meet up with sakayanagi    ayanokoji   after deciding to put aside the whole situation with sakayanagi for the time being  i    ayanokoji   being a c class sophomore it should now have a deep connection to class a s sakayanagi    ayanokoji  hearing the lost girl in the dark   ichinose s class now cooperates with sakayanagi s class  of course  there are some friendship groups that transcend these borders  but most of them are created by the agreements of the central nucleus    ayanokoji   if it was one of the top ten  it was ryuuen s second year group  sakayanagi s group  or utomiya s group and the others in first year    narration","h":"<article class=\"card\" id=\"sc-sakayanagi-arisu-y2v4-p59-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sakayanagi-arisu.html#sc-sakayanagi-arisu-y2v4-p59-1\">Sakayanagi mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.59–97<\/span><span class=\"by\">notes on <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/span><\/h3><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “Tomorrow, my goal was to maintain an ideal rank and, if possible, meet up with Sakayanagi once again.” — Ayanokōji.<span class=\"pg\">p.59<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “make it back to the starting area and meet up with Sakayanagi.” — Ayanokōji.<span class=\"pg\">p.60<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “After deciding to put aside the whole situation with Sakayanagi for the time being, I” — Ayanokōji.<span class=\"pg\">p.61<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “being a C class sophomore it should now have a deep connection to Class A&#x27;s Sakayanagi.” — Ayanokōji, hearing the lost girl in the dark.<span class=\"pg\">p.86<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Ichinose&#x27;s class now cooperates with Sakayanagi&#x27;s class. Of course, there are some friendship groups that transcend these borders, but most of them are created by the agreements of the central nucleus.” — Ayanokōji.<span class=\"pg\">p.88<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “if it was one of the top ten, it was Ryuuen&#x27;s second year group, Sakayanagi&#x27;s group, or Utomiya&#x27;s group and the others in first year.” — narration.<span class=\"pg\">p.97<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sakayanagi-arisu-y2v4-p55-1\">← Before: Sakayanagi mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sakayanagi-arisu-y2v4-p93-1\">→ After: Sakayanagi mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-shinohara-satsuki-y2v4-p59-1","v":"y2v4","y":2,"o":19,"k":"","w":"shinohara-satsuki","q":"shinohara satsuki shinohara mentioned in passing  moreover  many of our classmates still didn t know about what kind of situation shinohara had been put in    ayanokoji","h":"<article class=\"card\" id=\"sc-shinohara-satsuki-y2v4-p59-1\"><h3><span class=\"ttl\"><a href=\"../../../people/shinohara-satsuki.html#sc-shinohara-satsuki-y2v4-p59-1\">Shinohara mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.59<\/span><span class=\"by\">notes on <a href=\"../../../people/shinohara-satsuki.html\">Shinohara Satsuki<\/a><\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “Moreover, many of our classmates still didn&#x27;t know about what kind of situation Shinohara had been put in.” — Ayanokōji.<span class=\"pg\">p.59<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-shinohara-satsuki-y2v4-p55-1\">← Before: Shinohara mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v4-p60-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"kuronaga kouenji-rokusuke ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 3  the 11th place plan holds arrives at the fourth designated area  d5  at 3 00 pm  a punishing walk from h9   skips a decent task en route to avoid a penalty  takes third place in the early bird bonus pool  still no sign of reaching the starting area   so with all the points i earned today  i ve upped my total score to 112  huh   with the way things are going  even if i don t win  i won t have any complaints as long as koenji takes first or second  112 points  now 13th  kuronaga s 123 is 11 ahead   exactly the buffer he designed  11th place strategy  public top ten   sabotage magnet  all it needs now is for the 10th place not to inflate or collapse  he has aimed for 11th place since before the exam  being publicly visible would make him a target  the strategy is hostage to the 10th place group s score and the top groups  willingness to let each other run  nagumo s camp shows no interference against koenji yet   most likely pouring everything into scoring  possibly simply letting koenji stay ahead  patient and disciplined  he wants koenji first or second  being in the top ten is the one outcome he refuses  123 points  10th place  holding the public anonymous barrier above him  his unspoken preferred winner  koenji first or second would satisfy his quiet bet","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v4-p60-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v4-p60-1\">Ch.3: The 11th-place plan holds<\/a><\/span><span class=\"meta\">Y2V4 · p.60–62<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Arrives at the fourth designated area (D5) at 3:00 PM, a punishing walk from H9 — skips a decent Task en route to avoid a penalty; takes third place in the Early Bird Bonus pool; still no sign of reaching the starting area.<\/p><p class=\"with\">with <a href=\"../../../people/index.html#kuronaga\">Kuronaga<\/a> · <a href=\"../../../people/kouenji-rokusuke.html\">Kōenji Rokusuke<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “So with all the points I earned today, I’ve upped my total score to 112, huh?”<span class=\"pg\">p.61<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “With the way things are going, even if I don’t win, I won’t have any complaints as long as Kōenji takes first or second.”<span class=\"pg\">p.62<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Inference, not stated<\/span> 112 points, now 13th; Kuronaga’s 123 is 11 ahead — exactly the buffer he designed: 11th-place strategy (public top-ten = sabotage magnet); all it needs now is for the 10th place not to inflate or collapse.<span class=\"pg\">p.60–62<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> He has aimed for 11th place since before the exam; being publicly visible would make him a target; the strategy is hostage to the 10th place group’s score and the top groups’ willingness to let each other run.<span class=\"pg\">p.61<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Nagumo’s camp shows no interference against Kōenji yet — most likely pouring everything into scoring; possibly simply letting Kōenji stay ahead.<span class=\"pg\">p.62<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Patient and disciplined; he wants Kōenji first or second; being in the top ten is the one outcome he refuses.<span class=\"pg\">p.60–62<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kuronaga<\/b> 123 points, 10th place, holding the public/anonymous barrier above him.<span class=\"pg\">p.61–62<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> His unspoken preferred winner; Kōenji first or second would satisfy his quiet bet.<span class=\"pg\">p.62<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p58-1\">← Before: Ch.2: The food Task; the day-eight tally<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p63-1\">→ After: Ch.3: The lone tent in the clearing<\/button><\/div><\/article>"},{"i":"sc-kuronaga-y2v4-p61-1","v":"y2v4","y":2,"o":19,"k":"","w":"kuronaga","q":"kuronaga kuronaga in the standings  the kuronaga group  who had maintained their 10th place spot  had a comprehensive score of 123 points  a mere 11 points ahead of me  who had risen up to 13th","h":"<article class=\"card\" id=\"sc-kuronaga-y2v4-p61-1\"><h3><span class=\"ttl\">Kuronaga in the standings<\/span><span class=\"meta\">Y2V4 · p.61<\/span><span class=\"by\">notes on <a href=\"../../../people/index.html#kuronaga\">Kuronaga<\/a><\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “The Kuronaga group, who had maintained their 10th place spot, had a comprehensive score of 123 points, a mere 11 points ahead of me, who had risen up to 13th.”<span class=\"pg\">p.61<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kuronaga-y2v4-p59-1\">← Before: Kuronaga mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kuronaga-y2v4-p80-1\">→ After: Kuronaga mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-nagumo-miyabi-y2v4-p61-1","v":"y2v4","y":2,"o":19,"k":"","w":"nagumo-miyabi","q":"nagumo miyabi nagumo mentioned in passing  i was curious about what nagumo was going to do moving forward  it seemed like it d be a good idea for him to take on countermeasures of some sort to deal with koenji  his foremost competitor for the top spot   everyone is competing with each other for the podium  i could not continue with that game  however  if miyabi nagumo collapses down  the story could be a little different    kiryuin   do you think nagumo is going to release kouenji as he is right now    ayanokoji","h":"<article class=\"card\" id=\"sc-nagumo-miyabi-y2v4-p61-1\"><h3><span class=\"ttl\"><a href=\"../../../people/nagumo-miyabi.html#sc-nagumo-miyabi-y2v4-p61-1\">Nagumo mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.61–62, 83–84<\/span><span class=\"by\">notes on <a href=\"../../../people/nagumo-miyabi.html\">Nagumo Miyabi<\/a><\/span><\/h3><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “I was curious about what Nagumo was going to do moving forward. It seemed like it&#x27;d be a good idea for him to take on countermeasures of some sort to deal with Kōenji, his foremost competitor for the top spot.”<span class=\"pg\">p.62<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Everyone is competing with each other for the podium. I could not continue with that game. However, if Miyabi Nagumo collapses down, the story could be a little different.” — Kiryūin.<span class=\"pg\">p.83<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Do you think Nagumo is going to release Kouenji as he is right now?” — Ayanokōji.<span class=\"pg\">p.83<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y2v4-p38-1\">← Before: Nagumo mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y2v4-p95-1\">→ After: Nagumo mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-amasawa-ichika-y2v4-p62-1","v":"y2v4","y":2,"o":19,"k":"","w":"amasawa-ichika","q":"amasawa ichika ch 3  her name in the night  mention records   and even if i were to have my progress stunted via sabotage by amasawa or one of the other first years  i wouldn t have to worry about dropping all the way down to the bottom of the leaderboards    ayanokoji   maybe it s amasawa who came to do something to me  is she looking for me    ayanokoji  hearing a flashlight","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v4-p62-1\"><h3><span class=\"ttl\"><a href=\"../../../people/amasawa-ichika.html#sc-amasawa-ichika-y2v4-p62-1\">Ch.3: Her name in the night (mention records)<\/a><\/span><span class=\"meta\">Y2V4 · p.62–94<\/span><span class=\"by\">notes on <a href=\"../../../people/amasawa-ichika.html\">Amasawa Ichika<\/a><\/span><\/h3><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “And even if I were to have my progress stunted via sabotage by Amasawa or one of the other first-years, I wouldn’t have to worry about dropping all the way down to the bottom of the leaderboards.” — Ayanokōji.<span class=\"pg\">p.62<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Maybe it&#x27;s Amasawa who came to do something to me, is she looking for me?” — Ayanokōji, hearing a flashlight.<span class=\"pg\">p.86<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v4-p55-1\">← Before: Ch.2: The alliance widens (mention records)<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v4-p120-1\">→ After: Ch.4: The empty leak (mention records)<\/button><\/div><\/article>"},{"i":"sc-kouenji-rokusuke-y2v4-p62-1","v":"y2v4","y":2,"o":19,"k":"","w":"kouenji-rokusuke","q":"koenji rokusuke koenji mentioned in passing  with the way things are going  even if i don t win  i won t have any complaints as long as koenji takes first or second    ayanokoji   do you think nagumo is going to release kouenji as he is right now    kiryuin to ayanokoji  the two leads are deadlocked","h":"<article class=\"card\" id=\"sc-kouenji-rokusuke-y2v4-p62-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kouenji-rokusuke.html#sc-kouenji-rokusuke-y2v4-p62-1\">Kōenji mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.62, 83<\/span><span class=\"by\">notes on <a href=\"../../../people/kouenji-rokusuke.html\">Kōenji Rokusuke<\/a><\/span><\/h3><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “With the way things are going, even if I don&#x27;t win, I won&#x27;t have any complaints as long as Kōenji takes first or second.” — Ayanokōji.<span class=\"pg\">p.62<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Do you think Nagumo is going to release Kouenji as he is right now?” — Kiryūin to Ayanokōji; the two leads are deadlocked.<span class=\"pg\">p.83<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kouenji-rokusuke-y2v4-p42-1\">← Before: Kōenji mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kouenji-rokusuke-y2v4-p99-1\">→ After: Ch.4: Surrounded at dawn; he simply bolts<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v4-p63-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"ibuki-mio ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 3  the lone tent in the clearing at sunset he spots an isolated one man tent at the clearing s edge   entrance zipped in the heat  no one inside detectable  he waits ten minutes  calls out  pitches his own tent at a distance  and finds out who the owner is   what a nice spot   is anyone there   sorry  but i d like to set up my tent nearby  please let me know if you have a problem with that   i really can t imagine it   did i make too much noise   i thought i heard some weirdo show up  but to think it was you of all people   not really   you got a minute   i d like to ask you something   i m gonna unzip the flap  okay   what do you want  a lone one man tent guaranteed a class 2 b or 2 c loner   he assumed  he kept his distance  called out  and only unzipped after 30 seconds with zero response  found ibuki inside chewing on something  alone by choice  but unnerved by the one man tent  he stays and confirms the occupant before committing to camp","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v4-p63-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v4-p63-1\">Ch.3: The lone tent in the clearing<\/a><\/span><span class=\"meta\">Y2V4 · p.63–65<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">At sunset he spots an isolated one-man tent at the clearing’s edge — entrance zipped in the heat; no one inside detectable; he waits ten minutes, calls out, pitches his own tent at a distance, and finds out who the owner is.<\/p><p class=\"with\">with <a href=\"../../../people/ibuki-mio.html\">Ibuki Mio<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “What a nice spot.”<span class=\"pg\">p.63<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Is anyone there?”<span class=\"pg\">p.63<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Sorry, but I’d like to set up my tent nearby. Please let me know if you have a problem with that.”<span class=\"pg\">p.64<\/span><\/li><\/ul><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “…I really can’t imagine it.”<span class=\"pg\">p.64<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Did I make too much noise?”<span class=\"pg\">p.65<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I thought I heard some weirdo show up, but to think it was you of all people.”<span class=\"pg\">p.64<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Not really.”<span class=\"pg\">p.65<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You got a minute?”<span class=\"pg\">p.65<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’d like to ask you something.”<span class=\"pg\">p.65<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m gonna unzip the flap, okay?”<span class=\"pg\">p.65<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…What do you want?”<span class=\"pg\">p.65<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> A lone one-man tent guaranteed a Class 2-B or 2-C loner — he assumed; he kept his distance, called out, and only unzipped after 30 seconds with zero response; found Ibuki inside chewing on something.<span class=\"pg\">p.63–65<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Alone by choice, but unnerved by the one-man tent; he stays and confirms the occupant before committing to camp.<span class=\"pg\">p.63–65<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p60-1\">← Before: Ch.3: The 11th-place plan holds<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p66-1\">→ After: Ch.3: Ibuki, dehydrated; the water-for-food trade<\/button><\/div><\/article>"},{"i":"sc-ibuki-mio-y2v4-p64-1","v":"y2v4","y":2,"o":19,"k":"","w":"ibuki-mio","q":"ibuki mio ibuki mentioned in passing  apparently  the owner of the lone tent just across the way was none other than ibuki    ayanokoji   upon looking inside  i was met with the sight of a seated ibuki who seemed to be chewing on something    ayanokoji   by the time i had finished getting ready and stepped foot out of my tent  ibuki was already nowhere to be seen    ayanokoji   i think horikita and ibuki are doing better than me    ayanokoji   it s a rare combination horikita  strolling with ibuki  is it going to rain hail today    kiryuin   why are you and ibuki here  there is no homework around  right    ayanokoji   i m not sure  but through this exam horikita and ibuki have become friends     ayanokoji","h":"<article class=\"card\" id=\"sc-ibuki-mio-y2v4-p64-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ibuki-mio.html#sc-ibuki-mio-y2v4-p64-1\">Ibuki mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.64–65, 81, 123, 273–275<\/span><span class=\"by\">notes on <a href=\"../../../people/ibuki-mio.html\">Ibuki Mio<\/a><\/span><\/h3><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “Apparently, the owner of the lone tent just across the way was none other than Ibuki.” — Ayanokōji.<span class=\"pg\">p.64<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Upon looking inside, I was met with the sight of a seated Ibuki who seemed to be chewing on something.” — Ayanokōji.<span class=\"pg\">p.65<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “By the time I had finished getting ready and stepped foot out of my tent, Ibuki was already nowhere to be seen.” — Ayanokōji.<span class=\"pg\">p.81<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “I think Horikita and Ibuki are doing better than me.” — Ayanokōji.<span class=\"pg\">p.123<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “It&#x27;s a rare combination Horikita. Strolling with Ibuki, is it going to rain hail today?” — Kiryūin.<span class=\"pg\">p.273<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Why are you and Ibuki here? There is no homework around, right?” — Ayanokōji.<span class=\"pg\">p.274<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “I&#x27;m not sure, but through this exam Horikita and Ibuki have become friends ......?” — Ayanokōji.<span class=\"pg\">p.275<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ibuki-mio-y2v4-p67-1\">→ After: Ch.3: Ibuki, dehydrated and alone<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v4-p66-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"ibuki-mio horikita-suzune ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 3  ibuki  dehydrated  the water for food trade inside the tent  ibuki mio sits chewing on jerky   class 2 b s class wide strategy of homemade jerky  fresh meat not prepacked  cheaper than the school s prices  she s emaciated  dark circles  hasn t spoken to anyone but horikita since day one   you re really  wait  no  what are you eating   jerky   jerky  that wasn t included in the uninhabited island manuel they handed out to us before the exam  though   what s it matter to you  it s none of your business   how many people have you spoken with since the exam started   wha   just horikita  you heard me say i wouldn t lose to her  right  you were there   in other words  you re saying you haven t had a proper conversation with someone since day one   you should try and find someone to talk to  even if only a little bit   ain t no way i m gonna talk with my enemies   then talk with a classmate  if you wander around long enough  you re sure to come across someone   i don t think of my classmates as  friends   get out already   how many points you got right now   we re mutual enemies  you do know that right   so you won t tell me   whatever  it was a waste of time to bother with askin  you anyway   fair enough  besides  your true target here is horikita  right   when you next see that bitch  do me a solid and tell her that i ll absolutely never lose to her   that s fine and all  but i m probably not the one you should be giving the middle finger to   you  her  same difference  after all  you two are on real good terms with each other   hold on a moment   haaa  you tryna pull somethin   that wasn t my intention here at all  but   the hell are you doing   i ll admit i can t beat you  sure  but one of these days  i swear i m gonna get the satisfaction of kickin  your teeth in   so  did horikita put you up to this  tryna get in my way   your pulse is racing   the inside of your mouth looks dry too  not to mention how cracked your lips are  you re obviously dehydrated   i m not all that thirsty  anymore   anymore  so then  you re saying you were thirsty at one point   mind your own business  there ain t anything wrong with me   wait  wha  what are you doing   show me what s inside   haaa  no way in hell i mma show a guy  no  i wouldn t even do it for a girl either   fair enough   hey  i said no   how long have you been out of water   i don t have to tell you anythi   i said  how long have you been out of water   a full day  and then some   nope  i ve been resting here all day today   what an obvious lie  there were no gps signals anywhere near here this morning   you did a gps search   has your first warning alert gone off yet   it did about an hour ago  that s why i reluctantly decided to turn in early for the night   if you don t rehydrate at some point  it ll keep ringing even if you rest   i ll handle it tomorrow  and if push comes to shove i ll even go back to the starting area  so drop it and leave me alone   it s more than two kilometers from here to the starting area  if you were to collapse along the way  it d be all over   then i ll just do a nearby task or some shit   you can t do that though  can you  otherwise you wouldn t be in the state you re in now   trade me   what   it just so happens that i m running short on food  on the other hand  i have a bit of an oversupply of water  i m asking you to negotiate with me since i think we can make a fair trade   how about it  i ll say it again just to be sure  but i m looking to make a fair trade here  you ll have to give me a suitable amount of food in exchange   who the hell do you think you are to   feel free to say no  but i won t be giving you a chance to change your mind   if you retire due to dehydration like this  you ll definitely lose to horikita  in fact  i met with horikita a little while ago  her complexion was perfectly fine  and she didn t seem to be having any problems with water or food either   i get it  i ll trade with you  but  how much do you want from me   half of your remaining food  that should be enough   only that much   it s at least better than sustaining myself by eating random weeds   i m not gonna thank you if that s what you re after  it s supposed to be a fair trade  remember   i don t want you to thank me   then whatta you want   if you re not doing too badly with points  how about you spend most of the day tomorrow resting  that  or switch to a strategy where you only focus on acquiring food and water   so you re sayin  for me to give up on scoring points  you ve gotta be kidding me   i m not puttin  in all this work  cause i don t wanna get expelled  my only goal here is beating horikita   i ve got nothin  more to say to you  he spots the dehydration pattern instantly  pulse  dry mouth  cracked lips  empty bottle  bluffs a gps search to trap her lying about resting  engineers a fair trade offer using horikita s name as the lever   the only thing that moves her  she accepts the trade and walks out  she hates him  he s  x  but she takes the water  he sees her as a lone cannon aimed at horikita  she bolts without a word  he uses horikita as leverage   ibuki s entire drive is the match against her","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v4-p66-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v4-p66-1\">Ch.3: Ibuki, dehydrated; the water-for-food trade<\/a><\/span><span class=\"meta\">Y2V4 · p.66–78<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Inside the tent: Ibuki Mio sits chewing on jerky — Class 2-B’s class-wide strategy of homemade jerky (fresh meat not prepacked, cheaper than the school’s prices); she’s emaciated, dark circles, hasn’t spoken to anyone but Horikita since day one.<\/p><p class=\"with\">with <a href=\"../../../people/ibuki-mio.html\">Ibuki Mio<\/a> · <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “You’re really─ Wait, no, what are you eating?”<span class=\"pg\">p.67<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ibuki Mio<\/b> “Jerky.”<span class=\"pg\">p.67<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Jerky…? That wasn’t included in the Uninhabited Island Manuel they handed out to us before the exam, though?”<span class=\"pg\">p.67<\/span><\/li><\/ul><details class=\"more\"><summary>69 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “What’s it matter to you? It’s none of your business.”<span class=\"pg\">p.67<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “How many people have you spoken with since the exam started?”<span class=\"pg\">p.68<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Wha…?”<span class=\"pg\">p.68<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…Just Horikita. You heard me say I wouldn’t lose to her, right? You were there.”<span class=\"pg\">p.68<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “In other words, you’re saying you haven’t had a proper conversation with someone since day one?”<span class=\"pg\">p.68<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You should try and find someone to talk to, even if only a little bit.”<span class=\"pg\">p.68<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ain’t no way I’m gonna talk with my enemies.”<span class=\"pg\">p.68<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Then talk with a classmate. If you wander around long enough, you’re sure to come across someone.”<span class=\"pg\">p.68<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don’t think of my classmates as ‘friends’.”<span class=\"pg\">p.69<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Get out already.”<span class=\"pg\">p.69<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “How many points you got right now?”<span class=\"pg\">p.70<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “We’re mutual enemies, you do know that right?”<span class=\"pg\">p.70<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So you won’t tell me.”<span class=\"pg\">p.70<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…Whatever. It was a waste of time to bother with askin’ you anyway.”<span class=\"pg\">p.71<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Fair enough. Besides, your true target here is Horikita, right?”<span class=\"pg\">p.71<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “When you next see that bitch, do me a solid and tell her that I’ll absolutely never lose to her.”<span class=\"pg\">p.71<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That’s fine and all, but I’m probably not the one you should be giving the middle finger to.”<span class=\"pg\">p.71<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You, her, same difference. After all, you two are on real good terms with each other.”<span class=\"pg\">p.71<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Hold on a moment.”<span class=\"pg\">p.71<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Haaa? You tryna pull somethin’?”<span class=\"pg\">p.72<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That wasn’t my intention here at all, but─”<span class=\"pg\">p.72<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The hell are you doing!?”<span class=\"pg\">p.72<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’ll admit I can’t beat you, sure, but one of these days, I swear I’m gonna get the satisfaction of kickin’ your teeth in.”<span class=\"pg\">p.72<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So? Did Horikita put you up to this? Tryna get in my way?”<span class=\"pg\">p.72<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Your pulse is racing.”<span class=\"pg\">p.72<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The inside of your mouth looks dry too, not to mention how cracked your lips are. You’re obviously dehydrated.”<span class=\"pg\">p.73<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m not all that thirsty… anymore.”<span class=\"pg\">p.73<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Anymore? So then, you’re saying you were thirsty at one point?”<span class=\"pg\">p.73<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Mind your own business. There ain’t anything wrong with me.”<span class=\"pg\">p.73<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Wait, wha─? What are you doing!?”<span class=\"pg\">p.74<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Show me what’s inside.”<span class=\"pg\">p.74<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Haaa!? No way in hell I’mma show a guy. No, I wouldn’t even do it for a girl either.”<span class=\"pg\">p.74<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Fair enough.”<span class=\"pg\">p.74<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Hey! I said no!”<span class=\"pg\">p.74<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “How long have you been out of water?”<span class=\"pg\">p.74<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don’t have to tell you anythi─”<span class=\"pg\">p.74<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I said, how long have you been out of water?”<span class=\"pg\">p.74<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…A full day… and then some.”<span class=\"pg\">p.74<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Nope. I’ve been resting here all day today.”<span class=\"pg\">p.74<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What an obvious lie. There were no GPS signals anywhere near here this morning.”<span class=\"pg\">p.74<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You did a GPS Search?”<span class=\"pg\">p.74<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Has your first Warning Alert gone off yet?”<span class=\"pg\">p.74<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…It did about an hour ago. That’s why I reluctantly decided to turn in early for the night.”<span class=\"pg\">p.74<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If you don’t rehydrate at some point, it’ll keep ringing even if you rest.”<span class=\"pg\">p.75<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’ll handle it tomorrow, and if push comes to shove I’ll even go back to the starting area, so drop it and leave me alone.”<span class=\"pg\">p.75<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s more than two kilometers from here to the starting area. If you were to collapse along the way, it’d be all over.”<span class=\"pg\">p.75<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Then I’ll just do a nearby Task or some shit.”<span class=\"pg\">p.75<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You can’t do that though, can you? Otherwise you wouldn’t be in the state you’re in now.”<span class=\"pg\">p.75<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Trade me.”<span class=\"pg\">p.75<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What?”<span class=\"pg\">p.75<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It just so happens that I’m running short on food. On the other hand, I have a bit of an oversupply of water. I’m asking you to negotiate with me since I think we can make a fair trade.”<span class=\"pg\">p.75<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “How about it? I’ll say it again just to be sure, but I’m looking to make a fair trade here. You’ll have to give me a suitable amount of food in exchange.”<span class=\"pg\">p.76<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Who the hell do you think you are to─”<span class=\"pg\">p.76<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Feel free to say no, but I won’t be giving you a chance to change your mind.”<span class=\"pg\">p.76<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If you retire due to dehydration like this, you’ll definitely lose to Horikita. In fact, I met with Horikita a little while ago. Her complexion was perfectly fine, and she didn’t seem to be having any problems with water or food either.”<span class=\"pg\">p.76<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I get it… I’ll trade with you. But, how much do you want from me?”<span class=\"pg\">p.76<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Half of your remaining food. That should be enough.”<span class=\"pg\">p.76<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Only that much?”<span class=\"pg\">p.76<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s at least better than sustaining myself by eating random weeds.”<span class=\"pg\">p.76<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m not gonna thank you if that’s what you’re after. It’s supposed to be a fair trade, remember?”<span class=\"pg\">p.77<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don’t want you to thank me.”<span class=\"pg\">p.77<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Then whatta you want?”<span class=\"pg\">p.77<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If you’re not doing too badly with points, how about you spend most of the day tomorrow resting? That, or switch to a strategy where you only focus on acquiring food and water?”<span class=\"pg\">p.77<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So you’re sayin’ for me to give up on scoring points? You’ve gotta be kidding me.”<span class=\"pg\">p.77<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m not puttin’ in all this work ‘cause I don’t wanna get expelled. My only goal here is beating Horikita.”<span class=\"pg\">p.77<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’ve got nothin’ more to say to you.”<span class=\"pg\">p.78<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> He spots the dehydration pattern instantly (pulse, dry mouth, cracked lips, empty bottle); bluffs a GPS Search to trap her lying about resting; engineers a fair-trade offer using Horikita’s name as the lever — the only thing that moves her; she accepts the trade and walks out.<span class=\"pg\">p.66–78<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ibuki Mio<\/b> She hates him (he’s ‘X’), but she takes the water; he sees her as a lone cannon aimed at Horikita; she bolts without a word.<span class=\"pg\">p.66–78<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> He uses Horikita as leverage — Ibuki’s entire drive is the match against her.<span class=\"pg\">p.76<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p63-1\">← Before: Ch.3: The lone tent in the clearing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p79-1\">→ After: Ch.3: The backpack rummaged; the 12-point buffer<\/button><\/div><\/article>"},{"i":"sc-horikita-suzune-y2v4-p67-1","v":"y2v4","y":2,"o":19,"k":"","w":"horikita-suzune","q":"horikita suzune horikita mentioned in passing  she had started out by provoking horikita before immediately setting off for the first designated area    ayanokoji s knowledge of ibuki s day one plan   just horikita  you heard me say i wouldn t lose to her  right  you were there    ibuki   besides  your true target here is horikita  right    ayanokoji   so  did horikita put you up to this  tryna get in my way    ibuki   with how desperate she was to beat horikita  i couldn t imagine that she d willingly choose to take a break    ayanokoji   if you retire due to dehydration like this  you ll definitely lose to horikita    ayanokoji uses her as leverage   my only goal here is beating horikita    ibuki   how adamant she was about her match with horikita    ayanokoji   the only man nagumo recognized  the only thing left of manabu horikita    narration   i think horikita and ibuki are doing better than me    ayanokoji   yes  i was able to contact ryuuen kun and horikita san  we are progressing smoothly    ayanokoji to sakayanagi   but the one which he named was none other but you  the only man that horikita senpai trusted    nagumo   let me see if you  who hold the expectations of horikita senpai  have the strength worthy of my expectations    nagumo   nagumo  who had been chasing after horikita manabu  wanted to see his shadow on me    narration   unfortunately  the leader of class 2 d is horikita    ayanokoji   you have the status of being a senpai worthy of my respect    ayanokoji   it s a rare combination horikita  strolling with ibuki  is it going to rain hail today    kiryuin   horikita stands by my side and confirms it again by whispering to me    narration   i m not sure  but through this exam horikita and ibuki have become friends     ayanokoji   kouenji turned his gaze to horikita and said     i m sure you understand  right    narration","h":"<article class=\"card\" id=\"sc-horikita-suzune-y2v4-p67-1\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-suzune.html#sc-horikita-suzune-y2v4-p67-1\">Horikita mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.67–78, 97, 123, 161, 204–212, 273–275, 281<\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/span><\/h3><details class=\"more\"><summary>20 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “she had started out by provoking Horikita before immediately setting off for the first designated area.” — Ayanokōji&#x27;s knowledge of Ibuki&#x27;s day-one plan.<span class=\"pg\">p.67<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “…Just Horikita. You heard me say I wouldn&#x27;t lose to her, right? You were there.” — Ibuki.<span class=\"pg\">p.68<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Besides, your true target here is Horikita, right?” — Ayanokōji.<span class=\"pg\">p.71<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “So? Did Horikita put you up to this? Tryna get in my way?” — Ibuki.<span class=\"pg\">p.72<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “With how desperate she was to beat Horikita, I couldn&#x27;t imagine that she&#x27;d willingly choose to take a break.” — Ayanokōji.<span class=\"pg\">p.74<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “If you retire due to dehydration like this, you&#x27;ll definitely lose to Horikita.” — Ayanokōji uses her as leverage.<span class=\"pg\">p.76<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “My only goal here is beating Horikita.” — Ibuki.<span class=\"pg\">p.77<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “how adamant she was about her match with Horikita...” — Ayanokōji.<span class=\"pg\">p.78<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “The only man Nagumo recognized, the only thing left of Manabu Horikita.” — narration.<span class=\"pg\">p.97<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “I think Horikita and Ibuki are doing better than me.” — Ayanokōji.<span class=\"pg\">p.123<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Yes. I was able to contact Ryuuen-kun and Horikita-san. We are progressing smoothly.” — Ayanokōji to Sakayanagi.<span class=\"pg\">p.161<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “But the one which he named was none other but you, the only man that Horikita-senpai trusted.” — Nagumo.<span class=\"pg\">p.204<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Let me see if you, who hold the expectations of Horikita-senpai, have the strength worthy of my expectations...” — Nagumo.<span class=\"pg\">p.205<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Nagumo, who had been chasing after Horikita Manabu, wanted to see his shadow on me.” — narration.<span class=\"pg\">p.209<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Unfortunately, the leader of Class 2-D is Horikita.” — Ayanokōji.<span class=\"pg\">p.210<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “you have the status of being a senpai worthy of my respect...” — Ayanokōji.<span class=\"pg\">p.212<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “It&#x27;s a rare combination Horikita. Strolling with Ibuki, is it going to rain hail today?” — Kiryūin.<span class=\"pg\">p.273<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Horikita stands by my side and confirms it again by whispering to me” — narration.<span class=\"pg\">p.274<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “I&#x27;m not sure, but through this exam Horikita and Ibuki have become friends ......?” — Ayanokōji.<span class=\"pg\">p.275<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Kouenji turned his gaze to Horikita and said: - “I&#x27;m sure you understand, right?”” — narration.<span class=\"pg\">p.281<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y2v4-p58-1\">← Before: Ch.2: The food Task together<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y2v4-p214-1\">→ After: Ch.6: The note; she marches north<\/button><\/div><\/article>"},{"i":"sc-ibuki-mio-y2v4-p67-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"ayanokouji-kiyotaka horikita-suzune ibuki-mio","q":"ibuki mio ch 3  ibuki  dehydrated and alone on day nine he finds her one man tent pitched in a clearing  inside  ibuki sits chewing on jerky   class 2 b s class wide jerky strategy  everything handmade  cheap  shelf stable  fresh meat somehow processed first   what s it matter to you  it s none of your business   jerky  that wasn t included in the uninhabited island manuel they handed out to us before the exam  though    his line about the manual   how many people have you spoken with since the exam started   just horikita  you heard me say i wouldn t lose to her  right  you were there   in other words  you re saying you haven t had a proper conversation with someone since day one   you should try and find someone to talk to  even if only a little bit   ain t no way i m gonna talk with my enemies   then talk with a classmate  if you wander around long enough  you re sure to come across someone   i don t think of my classmates as  friends   get out already  the uninhabited island manual listed no jerky   the meat had to be fresh before dehydration  meaning a group of class 2 b was tasked with making it for the class  premade dried meat is too expensive at school prices  dark circles under her eyes  nine days without a real conversation since day one  only horikita  cracked lips  staring wreck   the exam s pressure is eating her alive  her sole human contact  the benchmark she refuses to lose to  he warns her off in friendly fashion  she treats him as horikita s errand boy and drives him off","h":"<article class=\"card\" id=\"sc-ibuki-mio-y2v4-p67-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ibuki-mio.html#sc-ibuki-mio-y2v4-p67-1\">Ch.3: Ibuki, dehydrated and alone<\/a><\/span><span class=\"meta\">Y2V4 · p.67–70<\/span><span class=\"by\">notes on <a href=\"../../../people/ibuki-mio.html\">Ibuki Mio<\/a><\/span><\/h3><p class=\"setup\">On day nine he finds her one-man tent pitched in a clearing; inside, Ibuki sits chewing on jerky — Class 2-B’s class-wide jerky strategy (everything handmade, cheap, shelf-stable), fresh meat somehow processed first.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ibuki Mio<\/b> “What’s it matter to you? It’s none of your business.”<span class=\"pg\">p.67<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Jerky…? That wasn’t included in the Uninhabited Island Manuel they handed out to us before the exam, though?” — his line about the Manual.<span class=\"pg\">p.67<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “How many people have you spoken with since the exam started?”<span class=\"pg\">p.68<\/span><\/li><\/ul><details class=\"more\"><summary>11 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “…Just Horikita. You heard me say I wouldn’t lose to her, right? You were there.”<span class=\"pg\">p.68<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “In other words, you’re saying you haven’t had a proper conversation with someone since day one?”<span class=\"pg\">p.68<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You should try and find someone to talk to, even if only a little bit.”<span class=\"pg\">p.68<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ain’t no way I’m gonna talk with my enemies.”<span class=\"pg\">p.68<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Then talk with a classmate. If you wander around long enough, you’re sure to come across someone.”<span class=\"pg\">p.68<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don’t think of my classmates as ‘friends’.”<span class=\"pg\">p.69<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Get out already.”<span class=\"pg\">p.70<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The Uninhabited Island Manual listed no jerky — the meat had to be fresh before dehydration, meaning a group of Class 2-B was tasked with making it for the class; premade dried meat is too expensive at school prices.<span class=\"pg\">p.67<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Dark circles under her eyes; nine days without a real conversation since day one (only Horikita); cracked lips; staring wreck — the exam’s pressure is eating her alive.<span class=\"pg\">p.67–70<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Her sole human contact; the benchmark she refuses to lose to.<span class=\"pg\">p.67–70<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> He warns her off in friendly fashion; she treats him as Horikita’s errand boy and drives him off.<span class=\"pg\">p.67–70<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ibuki-mio-y2v4-p64-1\">← Before: Ibuki mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ibuki-mio-y2v4-p70-1\">→ After: Ch.3: The pulse check; the Warning Alert<\/button><\/div><\/article>"},{"i":"sc-ibuki-mio-y2v4-p70-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"ayanokouji-kiyotaka ibuki-mio","q":"ibuki mio ch 3  the pulse check  the warning alert she emerges from her tent  wobbling  hands in pockets  and follows him out to demand his point total   how many points you got right now   we re mutual enemies  you do know that right    his line   so you won t tell me   whatever  it was a waste of time to bother with askin  you anyway   fair enough  besides  your true target here is horikita  right   when you next see that bitch  do me a solid and tell her that i ll absolutely never lose to her   that s fine and all  but i m probably not the one you should be giving the middle finger to   you  her  same difference  after all  you two are on real good terms with each other   haaa  you tryna pull somethin   i ll admit i can t beat you  sure  but one of these days  i swear i m gonna get the satisfaction of kickin  your teeth in   so  did horikita put you up to this  tryna get in my way   your pulse is racing   the inside of your mouth looks dry too  not to mention how cracked your lips are  you re obviously dehydrated   i m not all that thirsty  anymore   anymore  so then  you re saying you were thirsty at one point   mind your own business  there ain t anything wrong with me   how long have you been out of water   a full day  and then some   nope  i ve been resting here all day today   what an obvious lie  there were no gps signals anywhere near here this morning   you did a gps search   it did about an hour ago  that s why i reluctantly decided to turn in early for the night  he bluffs a gps search   he never ran one  he just knows she wouldn t rest here voluntarily given horikita  her first warning alert went off about an hour before he arrived  seethes at horikita  trusts nobody as horikita s ally  her warning alert fired without her drinking a drop since the day before  her body is shutting down  she assumes he s acting on horikita s orders  cannot be reached by reason  her pulse betrays the dehydration","h":"<article class=\"card\" id=\"sc-ibuki-mio-y2v4-p70-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ibuki-mio.html#sc-ibuki-mio-y2v4-p70-1\">Ch.3: The pulse check; the Warning Alert<\/a><\/span><span class=\"meta\">Y2V4 · p.70–74<\/span><span class=\"by\">notes on <a href=\"../../../people/ibuki-mio.html\">Ibuki Mio<\/a><\/span><\/h3><p class=\"setup\">She emerges from her tent, wobbling, hands in pockets, and follows him out to demand his point total.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ibuki Mio<\/b> “How many points you got right now?”<span class=\"pg\">p.70<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “We’re mutual enemies, you do know that right?” — his line.<span class=\"pg\">p.70<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ibuki Mio<\/b> “So you won’t tell me.”<span class=\"pg\">p.70<\/span><\/li><\/ul><details class=\"more\"><summary>22 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “…Whatever. It was a waste of time to bother with askin’ you anyway.”<span class=\"pg\">p.71<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Fair enough. Besides, your true target here is Horikita, right?”<span class=\"pg\">p.71<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “When you next see that bitch, do me a solid and tell her that I’ll absolutely never lose to her.”<span class=\"pg\">p.71<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That’s fine and all, but I’m probably not the one you should be giving the middle finger to.”<span class=\"pg\">p.71<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You, her, same difference. After all, you two are on real good terms with each other.”<span class=\"pg\">p.71<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Haaa? You tryna pull somethin’?”<span class=\"pg\">p.72<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’ll admit I can’t beat you, sure, but one of these days, I swear I’m gonna get the satisfaction of kickin’ your teeth in.”<span class=\"pg\">p.72<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So? Did Horikita put you up to this? Tryna get in my way?”<span class=\"pg\">p.72<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Your pulse is racing.”<span class=\"pg\">p.72<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The inside of your mouth looks dry too, not to mention how cracked your lips are. You’re obviously dehydrated.”<span class=\"pg\">p.73<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m not all that thirsty… anymore.”<span class=\"pg\">p.73<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Anymore? So then, you’re saying you were thirsty at one point?”<span class=\"pg\">p.73<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Mind your own business. There ain’t anything wrong with me.”<span class=\"pg\">p.73<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “How long have you been out of water?”<span class=\"pg\">p.74<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…A full day… and then some.”<span class=\"pg\">p.74<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Nope. I’ve been resting here all day today.”<span class=\"pg\">p.74<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What an obvious lie. There were no GPS signals anywhere near here this morning.”<span class=\"pg\">p.74<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You did a GPS Search?”<span class=\"pg\">p.74<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…It did about an hour ago. That’s why I reluctantly decided to turn in early for the night.”<span class=\"pg\">p.74<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> He bluffs a GPS search — he never ran one; he just knows she wouldn’t rest here voluntarily given Horikita; her first Warning Alert went off about an hour before he arrived.<span class=\"pg\">p.74<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Seethes at Horikita; trusts nobody as Horikita’s ally; her Warning Alert fired without her drinking a drop since the day before; her body is shutting down.<span class=\"pg\">p.70–74<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> She assumes he’s acting on Horikita’s orders; cannot be reached by reason; her pulse betrays the dehydration.<span class=\"pg\">p.70–74<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ibuki-mio-y2v4-p67-1\">← Before: Ch.3: Ibuki, dehydrated and alone<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ibuki-mio-y2v4-p75-1\">→ After: Ch.3: The water-for-food trade<\/button><\/div><\/article>"},{"i":"sc-ibuki-mio-y2v4-p75-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"ayanokouji-kiyotaka horikita-suzune ibuki-mio","q":"ibuki mio ch 3  the water for food trade he fetches two 500ml bottles from his own cache and proposes a fair trade  she gags down half a bottle before he finishes the sentence  he demands half her remaining food   if you don t rehydrate at some point  it ll keep ringing even if you rest   i ll handle it tomorrow  and if push comes to shove i ll even go back to the starting area  so drop it and leave me alone   trade me   it just so happens that i m running short on food  on the other hand  i have a bit of an oversupply of water  i m asking you to negotiate with me since i think we can make a fair trade   how about it  i ll say it again just to be sure  but i m looking to make a fair trade here  you ll have to give me a suitable amount of food in exchange   who the hell do you think you are to   feel free to say no  but i won t be giving you a chance to change your mind   if you retire due to dehydration like this  you ll definitely lose to horikita  in fact  i met with horikita a little while ago  her complexion was perfectly fine  and she didn t seem to be having any problems with water or food either   i get it  i ll trade with you  but  how much do you want from me   half of your remaining food  that should be enough   only that much   it s at least better than sustaining myself by eating random weeds   i m not gonna thank you if that s what you re after  it s supposed to be a fair trade  remember   then whatta you want   if you re not doing too badly with points  how about you spend most of the day tomorrow resting  that  or switch to a strategy where you only focus on acquiring food and water   so you re sayin  for me to give up on scoring points  you ve gotta be kidding me   i m not puttin  in all this work  cause i don t wanna get expelled  my only goal here is beating horikita   i ve got nothin  more to say to you  her last reserves go into the trade  she downs half a bottle before answering  she flares at the suggestion of rest   her only goal is beating horikita  not survival  she storms off without a word when he tries once more  he trades two water bottles for half her jerky   any separation from horikita is the reason he offers  she suspects a trick to her being horikita s debt  the single reason he uses to move her  he tells her horikita is fine  supplied and out of food worries","h":"<article class=\"card\" id=\"sc-ibuki-mio-y2v4-p75-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ibuki-mio.html#sc-ibuki-mio-y2v4-p75-1\">Ch.3: The water-for-food trade<\/a><\/span><span class=\"meta\">Y2V4 · p.75–78<\/span><span class=\"by\">notes on <a href=\"../../../people/ibuki-mio.html\">Ibuki Mio<\/a><\/span><\/h3><p class=\"setup\">He fetches two 500ml bottles from his own cache and proposes a fair trade; she gags down half a bottle before he finishes the sentence; he demands half her remaining food.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “If you don’t rehydrate at some point, it’ll keep ringing even if you rest.”<span class=\"pg\">p.75<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ibuki Mio<\/b> “I’ll handle it tomorrow, and if push comes to shove I’ll even go back to the starting area, so drop it and leave me alone.”<span class=\"pg\">p.75<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Trade me.”<span class=\"pg\">p.75<\/span><\/li><\/ul><details class=\"more\"><summary>18 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “It just so happens that I’m running short on food. On the other hand, I have a bit of an oversupply of water. I’m asking you to negotiate with me since I think we can make a fair trade.”<span class=\"pg\">p.75<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “How about it? I’ll say it again just to be sure, but I’m looking to make a fair trade here. You’ll have to give me a suitable amount of food in exchange.”<span class=\"pg\">p.76<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Who the hell do you think you are to─”<span class=\"pg\">p.76<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Feel free to say no, but I won’t be giving you a chance to change your mind.”<span class=\"pg\">p.76<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If you retire due to dehydration like this, you’ll definitely lose to Horikita. In fact, I met with Horikita a little while ago. Her complexion was perfectly fine, and she didn’t seem to be having any problems with water or food either.”<span class=\"pg\">p.76<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I get it… I’ll trade with you. But, how much do you want from me?”<span class=\"pg\">p.76<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Half of your remaining food. That should be enough.”<span class=\"pg\">p.76<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Only that much?”<span class=\"pg\">p.76<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s at least better than sustaining myself by eating random weeds.”<span class=\"pg\">p.76<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m not gonna thank you if that’s what you’re after. It’s supposed to be a fair trade, remember?”<span class=\"pg\">p.77<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Then whatta you want?”<span class=\"pg\">p.77<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If you’re not doing too badly with points, how about you spend most of the day tomorrow resting? That, or switch to a strategy where you only focus on acquiring food and water?”<span class=\"pg\">p.77<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So you’re sayin’ for me to give up on scoring points? You’ve gotta be kidding me.”<span class=\"pg\">p.77<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m not puttin’ in all this work ‘cause I don’t wanna get expelled. My only goal here is beating Horikita.”<span class=\"pg\">p.77<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’ve got nothin’ more to say to you.”<span class=\"pg\">p.78<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Her last reserves go into the trade; she downs half a bottle before answering; she flares at the suggestion of rest — her only goal is beating Horikita, not survival; she storms off without a word when he tries once more.<span class=\"pg\">p.75–78<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> He trades two water bottles for half her jerky — any separation from Horikita is the reason he offers; she suspects a trick to her being Horikita’s debt.<span class=\"pg\">p.75–78<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> The single reason he uses to move her; he tells her Horikita is fine, supplied and out of food worries.<span class=\"pg\">p.75–78<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ibuki-mio-y2v4-p70-1\">← Before: Ch.3: The pulse check; the Warning Alert<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ibuki-mio-y2v4-p79-1\">→ After: Ch.3: The backpack check<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v4-p79-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"ibuki-mio ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 3  the backpack rummaged  the 12 point buffer next morning she is caught rummaging through his backpack   checking whether the trade was fair  his tablet has a lock screen  he accepts the mistrust as fair retaliation for opening hers   what are you doing     were you trying to sneak a peek at my tablet  or was there something else you wanted   i wouldn t do somethin  like that  i just  i just wanted to make sure our trade was actually fair  that s all   you ve only got one bottle of water left in there  and you ve already drunk some of it  i thought you said you had too much water   so what  were you trying to help me out to get me to owe you a favor   grr    he privately notes her cheek twitched at his words   in other words  i m telling you that the truth doesn t matter  it was a fair trade either way   i ain t convinced  but  i get it  if that s the way it is  i m not gonna give any water back to you   if i did this to have you owe me a favor  would you pay it back   no way   is that so  at 7 00 am he spends one point on a gps search  kuronaga is close to him  the one point spend widens their gap to 12 points   even a first place early bird bonus keeps him just outside the top ten  three other groups could contest the bonus  he yields  his first trip to that bonus pool is to save stamina  he lets her win the argument about the trade but notes she can t bear to owe him  her distrust is mutual","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v4-p79-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v4-p79-1\">Ch.3: The backpack rummaged; the 12-point buffer<\/a><\/span><span class=\"meta\">Y2V4 · p.79–80<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Next morning she is caught rummaging through his backpack — checking whether the trade was fair; his tablet has a lock screen; he accepts the mistrust as fair retaliation for opening hers.<\/p><p class=\"with\">with <a href=\"../../../people/ibuki-mio.html\">Ibuki Mio<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “What are you doing?”<span class=\"pg\">p.79<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ibuki Mio<\/b> “!”<span class=\"pg\">p.79<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Were you trying to sneak a peek at my tablet, or was there something else you wanted?”<span class=\"pg\">p.79<\/span><\/li><\/ul><details class=\"more\"><summary>11 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “I wouldn’t do somethin’ like that! I just… I just wanted to make sure our trade was actually fair, that’s all.”<span class=\"pg\">p.79<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You’ve only got one bottle of water left in there, and you’ve already drunk some of it! I thought you said you had too much water?”<span class=\"pg\">p.79<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So what, were you trying to help me out to get me to owe you a favor?”<span class=\"pg\">p.79<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Grr…” — he privately notes her cheek twitched at his words.<span class=\"pg\">p.79<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “In other words, I’m telling you that the truth doesn’t matter. It was a fair trade either way.”<span class=\"pg\">p.80<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I ain’t convinced, but… I get it. If that’s the way it is, I’m not gonna give any water back to you.”<span class=\"pg\">p.80<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If I did this to have you owe me a favor, would you pay it back?”<span class=\"pg\">p.80<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No way.”<span class=\"pg\">p.80<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…Is that so?”<span class=\"pg\">p.80<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> At 7:00 AM he spends one point on a GPS Search; Kuronaga is close to him; the one-point spend widens their gap to 12 points — even a first-place Early Bird Bonus keeps him just outside the top ten. Three other groups could contest the bonus; he yields; his first trip to that bonus pool is to save stamina.<span class=\"pg\">p.80<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> He lets her win the argument about the trade but notes she can’t bear to owe him; her distrust is mutual.<span class=\"pg\">p.79–80<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p66-1\">← Before: Ch.3: Ibuki, dehydrated; the water-for-food trade<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p81-1\">→ After: Ch.3: Kiryūin Fuka sizes him up<\/button><\/div><\/article>"},{"i":"sc-ibuki-mio-y2v4-p79-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"ayanokouji-kiyotaka ibuki-mio","q":"ibuki mio ch 3  the backpack check next morning  she is caught rummaging through his backpack   checking whether the trade was fair  impossible third party tablet access  he lets it slide   were you trying to sneak a peek at my tablet  or was there something else you wanted   i wouldn t do somethin  like that  i just  i just wanted to make sure our trade was actually fair  that s all   you ve only got one bottle of water left in there  and you ve already drunk some of it  i thought you said you had too much water   so what  were you trying to help me out to get me to owe you a favor   if you hadn t gone through my backpack  you never would ve felt like you owed me anything though   in other words  i m telling you that the truth doesn t matter  it was a fair trade either way   i ain t convinced  but  i get it  if that s the way it is  i m not gonna give any water back to you   if i did this to have you owe me a favor  would you pay it back   no way  she leaves before dawn   gone by the time he wakes  her signal is not observed  he notes she clearly doesn t trust the trade  but it was fair  she checks his backpack covertly  he accepts the mistrust as mutual after he opened hers without permission","h":"<article class=\"card\" id=\"sc-ibuki-mio-y2v4-p79-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ibuki-mio.html#sc-ibuki-mio-y2v4-p79-1\">Ch.3: The backpack check<\/a><\/span><span class=\"meta\">Y2V4 · p.79–80<\/span><span class=\"by\">notes on <a href=\"../../../people/ibuki-mio.html\">Ibuki Mio<\/a><\/span><\/h3><p class=\"setup\">Next morning, she is caught rummaging through his backpack — checking whether the trade was fair; impossible third-party tablet access; he lets it slide.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Were you trying to sneak a peek at my tablet, or was there something else you wanted?”<span class=\"pg\">p.79<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ibuki Mio<\/b> “I wouldn’t do somethin’ like that! I just… I just wanted to make sure our trade was actually fair, that’s all.”<span class=\"pg\">p.79<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “You’ve only got one bottle of water left in there, and you’ve already drunk some of it! I thought you said you had too much water?”<span class=\"pg\">p.79<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “So what, were you trying to help me out to get me to owe you a favor?”<span class=\"pg\">p.80<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If you hadn’t gone through my backpack, you never would’ve felt like you owed me anything though…”<span class=\"pg\">p.80<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “In other words, I’m telling you that the truth doesn’t matter. It was a fair trade either way.”<span class=\"pg\">p.80<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I ain’t convinced, but… I get it. If that’s the way it is, I’m not gonna give any water back to you.”<span class=\"pg\">p.80<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If I did this to have you owe me a favor, would you pay it back?”<span class=\"pg\">p.80<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No way.”<span class=\"pg\">p.80<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> She leaves before dawn — gone by the time he wakes; her signal is not observed. He notes she clearly doesn’t trust the trade, but it was fair.<span class=\"pg\">p.80<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> She checks his backpack covertly; he accepts the mistrust as mutual after he opened hers without permission.<span class=\"pg\">p.79–80<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ibuki-mio-y2v4-p75-1\">← Before: Ch.3: The water-for-food trade<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ibuki-mio-y2v4-p216-1\">→ After: Ch.6: She catches Horikita<\/button><\/div><\/article>"},{"i":"sc-kuronaga-y2v4-p80-1","v":"y2v4","y":2,"o":19,"k":"","w":"kuronaga","q":"kuronaga kuronaga mentioned in passing  my score was so close to the 10th place kuronaga group that i might accidentally overtake them  by spending one point here  the gap between our scores would widen to 12 points  that way  even if i earned 11 points from taking the first place early bird bonus  i d still be just barely outside of the top ten","h":"<article class=\"card\" id=\"sc-kuronaga-y2v4-p80-1\"><h3><span class=\"ttl\">Kuronaga mentioned in passing<\/span><span class=\"meta\">Y2V4 · p.80<\/span><span class=\"by\">notes on <a href=\"../../../people/index.html#kuronaga\">Kuronaga<\/a><\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “My score was so close to the 10th place Kuronaga group that I might accidentally overtake them. By spending one point here, the gap between our scores would widen to 12 points. That way, even if I earned 11 points from taking the first-place Early Bird Bonus, I’d still be just barely outside of the top ten.”<span class=\"pg\">p.80<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kuronaga-y2v4-p61-1\">← Before: Kuronaga in the standings<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v4-p81-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"kiryuin-fuuka nagumo-miyabi ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 3  kiryuin fuka sizes him up a designated area arrival  he arrives late and catches fuka kiryuin at the overlook  she s just jumped from 11th or lower to 9th this morning  she debriefs him on the field   you have arrived quite late  ayanokouji   it looks like it is   i thought i had a tough competitor for the reward in order of arrival  but was it you   i don t know what s up with that  it s not uncommon for there to be different tables in the same area  more than that  i thought that kiryuuin senpai was not interested in the top ten groups   this uninhabited island test was more fun than i thought it would be  and i was thrilled beyond my age   i m going to continue with my current rhythm for a while longer   shouldn t you be aiming for number one   everyone is competing with each other for the podium  i could not continue with that game  however  if miyabi nagumo collapses down  the story could be a little different   in such a state of conflict and struggle  nor can i say that nagumo will ever win  sure you have been watching everything up to now  but the time has come for you to move your chips  depending on how things go  we could see a period where neither team scores   because hitting your opponent is an important part of a battle   don t you aspire to move to the top   i m sorry  but i don t see how can i be in the top ten   i see  i thought you would have scored almost as many points as i did   several groups will soon lose their performance  we just have to keep trying and not give up   that said  from what i see in the table so far  what do you think of the fact that no group has withdrawn   all i can say is that you can t let your guard down  not even for a moment   yesterday i went through the starting point to obtain information  it seems that groups that have started to suffer from food and water shortages are trying to get ahead by separating some of their members to avoid joint collapse   it is a wise decision   i am sure that the last 10 will have some hope  no matter which group will withdraw  a man who has lost his way will use whatever means at his disposal  stay alert  okay   shouldn t it be something a woman  kiryuuin senpai  should be worried about   hmm  it s true that  as a pretty and merciful maiden  i might also feel a sense of danger   well if it comes to that   i would just have to force it out  at this time  he believes there are at most two pools of openings for the challenge  if there are more than three rival groups and kiryuin also goes there  the odds that she participates collapse   so that s a  no  i dare you to go there and see for yourself  he catalogues her as a third year with an insight beyond the oaa   she already reads the three way koenji nagumo stalemate from the leaderboard and almost tells him too much about his own strategy  he demurs to stay out of her range  she is drawn to him  why she keeps pace for the score in a two stop race  and leaves him with a gambit of her own  he notes her cards are as visible as his  both expect the koenji nagumo deadlock to shatter at some point","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v4-p81-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v4-p81-1\">Ch.3: Kiryūin Fuka sizes him up<\/a><\/span><span class=\"meta\">Y2V4 · p.81–85<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">A designated-area arrival; he arrives late and catches Fuka Kiryūin at the overlook; she’s just jumped from 11th or lower to 9th this morning; she debriefs him on the field.<\/p><p class=\"with\">with <a href=\"../../../people/kiryuin-fuuka.html\">Kiryuin Fuuka<\/a> · <a href=\"../../../people/nagumo-miyabi.html\">Nagumo Miyabi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Kiryuin Fuuka<\/b> “You have arrived quite late, Ayanokouji.”<span class=\"pg\">p.81<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “It looks like it is”<span class=\"pg\">p.81<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kiryuin Fuuka<\/b> “I thought I had a tough competitor for the reward in order of arrival, but was it you?”<span class=\"pg\">p.81<\/span><\/li><\/ul><details class=\"more\"><summary>24 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “I don’t know what’s up with that. It’s not uncommon for there to be different tables in the same area. More than that, I thought that Kiryuuin-senpai was not interested in the top ten groups.”<span class=\"pg\">p.81<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “This uninhabited island test was more fun than I thought it would be, and I was thrilled beyond my age.”<span class=\"pg\">p.83<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m going to continue with my current rhythm for a while longer.”<span class=\"pg\">p.83<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Shouldn’t you be aiming for number one?”<span class=\"pg\">p.83<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Everyone is competing with each other for the podium. I could not continue with that game. However, if Miyabi Nagumo collapses down, the story could be a little different.”<span class=\"pg\">p.83<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “In such a state of conflict and struggle, Nor can I say that Nagumo will ever win. Sure you have been watching everything up to now, but the time has come for you to move your chips. Depending on how things go, we could see a period where neither team scores.”<span class=\"pg\">p.83<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Because hitting your opponent is an important part of a battle.”<span class=\"pg\">p.83<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don’t you aspire to move to the top?”<span class=\"pg\">p.83<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m sorry, but I don’t see how can I be in the top ten.”<span class=\"pg\">p.83<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I see. I thought you would have scored almost as many points as I did.”<span class=\"pg\">p.83<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Several groups will soon lose their performance. We just have to keep trying and not give up.”<span class=\"pg\">p.84<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That said, from what I see in the table so far, what do you think of the fact that no group has withdrawn?”<span class=\"pg\">p.84<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “All I can say is that you can’t let your guard down, not even for a moment.”<span class=\"pg\">p.84<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yesterday I went through the starting point to obtain information. It seems that groups that have started to suffer from food and water shortages are trying to get ahead by separating some of their members to avoid joint collapse.”<span class=\"pg\">p.84<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It is a wise decision.”<span class=\"pg\">p.84<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I am sure that the last 10 will have some hope, no matter which group will withdraw. A man who has lost his way will use whatever means at his disposal. Stay alert, okay?”<span class=\"pg\">p.84<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Shouldn’t it be something a woman, Kiryuuin-senpai, should be worried about?”<span class=\"pg\">p.84<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Hmm… It’s true that, as a pretty and merciful maiden, I might also feel a sense of danger”<span class=\"pg\">p.84<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well if it comes to that ......., I would just have to force it out.”<span class=\"pg\">p.84<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> At this time, he believes there are at most two pools of openings for the challenge; if there are more than three rival groups and Kiryūin also goes there, the odds that she participates collapse.<span class=\"pg\">p.85<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So that’s a.... no, I dare you to go there and see for yourself.”<span class=\"pg\">p.85<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> He catalogues her as a third-year with an insight beyond the OAA — she already reads the three-way Kōenji/Nagumo stalemate from the leaderboard and almost tells him too much about his own strategy; he demurs to stay out of her range.<span class=\"pg\">p.81–85<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kiryuin Fuuka<\/b> She is drawn to him (why she keeps pace for the score in a two-stop race) and leaves him with a gambit of her own; he notes her cards are as visible as his.<span class=\"pg\">p.81–85<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> Both expect the Kōenji–Nagumo deadlock to shatter at some point.<span class=\"pg\">p.83–84<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p79-1\">← Before: Ch.3: The backpack rummaged; the 12-point buffer<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p86-1\">→ After: Ch.3: The Shiranami night search; the walkie-talkie<\/button><\/div><\/article>"},{"i":"sc-kiryuin-fuuka-y2v4-p81-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"ayanokouji-kiyotaka nagumo-miyabi shiba-katsunori tsukishiro kiryuin-fuuka","q":"kiryuin fuuka ch 3  overlook greeting  the nagumo game on day nine at the designated area arrival he walks up to her at the overlook  she has jumped from 11th or lower to 9th this morning  she debriefs him on the field   you have arrived quite late  ayanokouji   it looks like it is   i thought i had a tough competitor for the reward in order of arrival  but was it you   i don t know what s up with that  it s not uncommon for there to be different tables in the same area  more than that  i thought that kiryuuin senpai was not interested in the top ten groups   this uninhabited island test was more fun than i thought it would be  and i was thrilled beyond my age   i m going to continue with my current rhythm for a while longer   shouldn t you be aiming for number one   everyone is competing with each other for the podium  i could not continue with that game  however  if miyabi nagumo collapses down  the story could be a little different   do you think nagumo is going to release kouenji as he is right now   in such a state of conflict and struggle  nor can i say that nagumo will ever win  sure you have been watching everything up to now  but the time has come for you to move your chips  depending on how things go  we could see a period where neither team scores   because hitting your opponent is an important part of a battle   don t you aspire to move to the top   i m sorry  but i don t see how can i be in the top ten   i see  i thought you would have scored almost as many points as i did   several groups will soon lose their performance  we just have to keep trying and not give up   all i can say is that you can t let your guard down  not even for a moment   yesterday i went through the starting point to obtain information  it seems that groups that have started to suffer from food and water shortages are trying to get ahead by separating some of their members to avoid joint collapse   it is a wise decision   i am sure that the last 10 will have some hope  no matter which group will withdraw  a man who has lost his way will use whatever means at his disposal  stay alert  okay   shouldn t it be something a woman  kiryuuin senpai  should be worried about   hmm  it s true that  as a pretty and merciful maiden  i might also feel a sense of danger   well if it comes to that   i would just have to force it out   so that s a  no  i dare you to go there and see for yourself  enjoys the game  watches from the third year leaderboard  reads the koenji nagumo stalemate as a deadlocked chess match  teases him about  a pretty and merciful maiden  and implies she might force it out  she lets him have the first trip to the bonus pool  sizes him up as a genuine competitor  he lies about not aspiring to the top ten  expects the koenji nagumo game to split at some point  appears during the 2 on 1 fight   had watched from behind a tree  deliberately broke her watch so her gps wouldn t show her approach   i wonder what the acting director and the classroom teacher do with a student in such a deserted place   actually  i ve been watching you from behind the big tree for a while  but i couldn t take the two on one situation   of course  as your senpai  shouldn t it be normal for me to protect my kouhai   i ll tell you  i ll hold them for a minute or two at least   keep your fists up and try to create an atmosphere of tension   i am a lady  what do you think    on whether she s hit anyone playful and bold   breaks her own watch to sneak up  appears to protect her  kouhai  holds shiba  a  ridiculous level  fighter  through defense alone  and teases ayanokoji into a fighting pose  afterward exhausted but proud  intervenes on his behalf  calls him  kouhai  and helps him win  holds him off while ayanokoji fights tsukishiro  confronts the acting director over fighting a student in a deserted place","h":"<article class=\"card\" id=\"sc-kiryuin-fuuka-y2v4-p81-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kiryuin-fuuka.html#sc-kiryuin-fuuka-y2v4-p81-1\">Ch.3: Overlook greeting; the Nagumo game<\/a><\/span><span class=\"meta\">Y2V4 · p.81–85<\/span><span class=\"by\">notes on <a href=\"../../../people/kiryuin-fuuka.html\">Kiryuin Fuuka<\/a><\/span><\/h3><p class=\"setup\">On day nine at the designated-area arrival he walks up to her at the overlook; she has jumped from 11th or lower to 9th this morning; she debriefs him on the field. Appears during the 2-on-1 fight — had watched from behind a tree, deliberately broke her watch so her GPS wouldn&#x27;t show her approach.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/nagumo-miyabi.html\">Nagumo Miyabi<\/a> · <a href=\"../../../people/shiba-katsunori.html\">Shiba Katsunori<\/a> · <a href=\"../../../people/tsukishiro.html\">Tsukishiro<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Kiryuin Fuuka<\/b> “You have arrived quite late, Ayanokouji.”<span class=\"pg\">p.81<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “It looks like it is”<span class=\"pg\">p.81<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kiryuin Fuuka<\/b> “I thought I had a tough competitor for the reward in order of arrival, but was it you?”<span class=\"pg\">p.81<\/span><\/li><\/ul><details class=\"more\"><summary>33 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “I don’t know what’s up with that. It’s not uncommon for there to be different tables in the same area. More than that, I thought that Kiryuuin-senpai was not interested in the top ten groups.”<span class=\"pg\">p.81<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “This uninhabited island test was more fun than I thought it would be, and I was thrilled beyond my age.”<span class=\"pg\">p.83<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m going to continue with my current rhythm for a while longer.”<span class=\"pg\">p.83<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Shouldn’t you be aiming for number one?”<span class=\"pg\">p.83<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Everyone is competing with each other for the podium. I could not continue with that game. However, if Miyabi Nagumo collapses down, the story could be a little different.”<span class=\"pg\">p.83<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Do you think Nagumo is going to release Kouenji as he is right now?”<span class=\"pg\">p.83<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “In such a state of conflict and struggle, Nor can I say that Nagumo will ever win. Sure you have been watching everything up to now, but the time has come for you to move your chips. Depending on how things go, we could see a period where neither team scores.”<span class=\"pg\">p.83<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Because hitting your opponent is an important part of a battle.”<span class=\"pg\">p.83<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don’t you aspire to move to the top?”<span class=\"pg\">p.83<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m sorry, but I don’t see how can I be in the top ten.”<span class=\"pg\">p.83<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I see. I thought you would have scored almost as many points as I did.”<span class=\"pg\">p.83<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Several groups will soon lose their performance. We just have to keep trying and not give up.”<span class=\"pg\">p.84<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “All I can say is that you can’t let your guard down, not even for a moment.”<span class=\"pg\">p.84<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yesterday I went through the starting point to obtain information. It seems that groups that have started to suffer from food and water shortages are trying to get ahead by separating some of their members to avoid joint collapse.”<span class=\"pg\">p.84<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It is a wise decision.”<span class=\"pg\">p.84<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I am sure that the last 10 will have some hope, no matter which group will withdraw. A man who has lost his way will use whatever means at his disposal. Stay alert, okay?”<span class=\"pg\">p.84<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Shouldn’t it be something a woman, Kiryuuin-senpai, should be worried about?”<span class=\"pg\">p.84<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Hmm… It’s true that, as a pretty and merciful maiden, I might also feel a sense of danger”<span class=\"pg\">p.84<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well if it comes to that ......., I would just have to force it out.”<span class=\"pg\">p.84<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So that’s a.... no, I dare you to go there and see for yourself.”<span class=\"pg\">p.85<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Enjoys the game, watches from the third-year leaderboard, reads the Kōenji–Nagumo stalemate as a deadlocked chess match; teases him about “a pretty and merciful maiden” and implies she might force it out; she lets him have the first trip to the bonus pool.<span class=\"pg\">p.81–85<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Sizes him up as a genuine competitor; he lies about not aspiring to the top ten.<span class=\"pg\">p.81–85<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> Expects the Kōenji–Nagumo game to split at some point.<span class=\"pg\">p.83–84<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I wonder what the Acting Director and the classroom teacher do with a student in such a deserted place.”<span class=\"pg\">p.261<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Actually, I&#x27;ve been watching you from behind the big tree for a while, but I couldn&#x27;t take the two-on-one situation.”<span class=\"pg\">p.262<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Of course. As your senpai, shouldn&#x27;t it be normal for me to protect my kouhai?”<span class=\"pg\">p.263<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;ll tell you. I&#x27;ll hold them for a minute or two at least.”<span class=\"pg\">p.263<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Keep your fists up and try to create an atmosphere of tension.”<span class=\"pg\">p.263<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I am a lady. What do you think?” — on whether she&#x27;s hit anyone<span class=\"pg\">p.264<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Playful and bold — breaks her own watch to sneak up, appears to protect her “kouhai,” holds Shiba (a “ridiculous level” fighter) through defense alone, and teases Ayanokōji into a fighting pose; afterward exhausted but proud.<span class=\"pg\">p.261–273<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Intervenes on his behalf, calls him “kouhai,” and helps him win.<span class=\"pg\">p.261–272<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiba Katsunori<\/b> Holds him off while Ayanokōji fights Tsukishiro.<span class=\"pg\">p.263–270<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsukishiro<\/b> Confronts the acting director over fighting a student in a deserted place.<span class=\"pg\">p.261<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v4-p86-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"shiranami-chihiro kobashi-yume takemoto-shigeru sakayanagi-arisu ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 3  the shiranami night search  the walkie talkie after nine at night he hears an unstable flashlight beam wandering the forest and a faint voice calling for  yume    shiranami chihiro  crying  he triangulates  only one yume in the school  kobashi of class 2 c   so the searcher is a classmate   um  ayanokouji kun   good night   it is quite dangerous to go out alone in the middle of the night  what happened to kobashi and takemoto   oh  i lost track of where i was   i was in a hurry and didn t know where i was going   how long has it been since you parted   i don t know   15 minutes or   about 20 minutes or so    in any case  wandering aimlessly will only make things worse   uh huh   there are a lot of bugs  you may want to get into the tent first   eh   i m not going in there  so don t worry   i m sorry   i was just resting and    nothing happened  instead  kokobashi and takemoto are fine right   yes   is there a plan in case someone gets lost   is the group still a small group of three  or is it growing to more than four   very good  you don t have to tell me the details of the situation  just listen to what i have to say   if i were a member of your group  i would be aware of the current situation  i would have concluded that my companion was wandering alone through the dark forest without being able to return    i don t know   i think we would go look for yume chan    even if it causes an additional disaster and they risk getting injured and retiring   i couldn t leave her because she s my friend   can you pay points  if you use it 2 times  would you be concerned about your rating after using it three times   that s   i wonder  i don t think it s good   how strong are you   what   do you have the strength to walk   uh huh  okay  but   let s move so we can unite from now on   but how   it is not a problem that can be solved by walking in the dark  we will use this   we can use the gps search to determine where we are going and the approximate distance travelled   but why are you going out your way to help me   why  since this exam is a battle based on the same year  that s one aspect of it   but even using a gps search is   if i must say  maybe it s because you re in ichinose s class   maybe   hmm   maybe it s because ayanokouji kun   and honami chan    thank you  ayanokouji kun  for helping chihiro chan   no  i think you would have found her eventually  it wasn t a big deal   yes it was  if we had gone further  we would have run in the risk of injuring ourselves and  above all  we would have had a hard time finding her   i have something to ask  do you have a walkie talkie   what  a walkie talkie  i have one  but    if you don t mind  i would like to have a little conversation with sakayanagi  i would like to ask her if any of the class d students she dealt with have returned to the starting point   i ll help you with that  give me a minute   i just want to talk to her in private   that s it  sakayanagi  sorry to bother you at this time of night   you saved me  i got the information i needed from sakayanagi   okay then  also  sakayanagi asked me to give this to you ayanokoji   oh thank you   no need  and again ayanokouji kun thank you for helping us  he asks takemoto to call sakayanagi  whether any class d students she dealt with have returned to the starting area  the confession on takak it s an exchange about sakayanagi s class d dealings  she hands him the walkie talkie via takemoto  effectively a gift to him  he sleeps to stories of classes a and c around him  he walks shiranami back in the dark with gps searches  gets their gratitude without revealing his own stake  the sakayanagi back channel   takemoto hands him the walkie talkie sakayanagi arranged  he walks her home through the dark  she owes him  she suspects the honami chan connection  the lost girl  her companions came searching  he thanks them for the find  loan of the walkie talkie  the relay into sakayanagi s channel  the back channel  he asks via takemoto about class d dropouts  sakayanagi answers and hands him her walkie talkie","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v4-p86-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v4-p86-1\">Ch.3: The Shiranami night search; the walkie-talkie<\/a><\/span><span class=\"meta\">Y2V4 · p.86–94<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">After nine at night he hears an unstable flashlight beam wandering the forest and a faint voice calling for “Yume” — Shiranami Chihiro, crying; he triangulates: only one Yume in the school, Kobashi of Class 2-C — so the searcher is a classmate.<\/p><p class=\"with\">with <a href=\"../../../people/shiranami-chihiro.html\">Shiranami Chihiro<\/a> · <a href=\"../../../people/kobashi-yume.html\">Kobashi Yume<\/a> · <a href=\"../../../people/takemoto-shigeru.html\">Takemoto Shigeru<\/a> · <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Shiranami Chihiro<\/b> “Um, Ayanokouji-kun ...... good night.”<span class=\"pg\">p.86<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “It is quite dangerous to go out alone in the middle of the night. What happened to Kobashi and Takemoto?”<span class=\"pg\">p.87<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Shiranami Chihiro<\/b> “Oh, I lost track of where I was ... I was in a hurry and didn&#x27;t know where I was going”<span class=\"pg\">p.87<\/span><\/li><\/ul><details class=\"more\"><summary>53 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “How long has it been since you parted?”<span class=\"pg\">p.87<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t know ...... 15 minutes or ... About 20 minutes or so ......?”<span class=\"pg\">p.87<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “In any case, wandering aimlessly will only make things worse.”<span class=\"pg\">p.87<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Uh-huh.”<span class=\"pg\">p.87<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There are a lot of bugs. You may want to get into the tent first.”<span class=\"pg\">p.87<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Eh!?”<span class=\"pg\">p.87<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;m not going in there, so don&#x27;t worry.”<span class=\"pg\">p.87<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;m sorry ...... I was just resting and ....”<span class=\"pg\">p.88<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Nothing happened. Instead, Kokobashi and Takemoto are fine right?”<span class=\"pg\">p.88<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yes.”<span class=\"pg\">p.88<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Is there a plan in case someone gets lost?”<span class=\"pg\">p.88<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Is the group still a small group of three? Or is it growing to more than four?”<span class=\"pg\">p.88<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Very good. You don&#x27;t have to tell me the details of the situation. Just listen to what I have to say.”<span class=\"pg\">p.88<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If I were a member of your group, I would be aware of the current situation. I would have concluded that my companion was wandering alone through the dark forest without being able to return.”<span class=\"pg\">p.88<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “... I don&#x27;t know ... I think we would go look for Yume-chan ...”<span class=\"pg\">p.88<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Even if it causes an additional disaster and they risk getting injured and retiring?”<span class=\"pg\">p.88<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I couldn&#x27;t leave her because she&#x27;s my friend.”<span class=\"pg\">p.88<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Can you pay points? If you use it 2 times, would you be concerned about your rating after using it three times?”<span class=\"pg\">p.89<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That&#x27;s ... I wonder. I don&#x27;t think it&#x27;s good.”<span class=\"pg\">p.89<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “How strong are you?”<span class=\"pg\">p.90<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What?”<span class=\"pg\">p.90<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Do you have the strength to walk?”<span class=\"pg\">p.90<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Uh-huh. Okay, but......”<span class=\"pg\">p.90<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Let&#x27;s move so we can unite from now on”<span class=\"pg\">p.90<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But how?”<span class=\"pg\">p.90<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It is not a problem that can be solved by walking in the dark. We will use this.”<span class=\"pg\">p.90<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “We can use the GPS search to determine where we are going and the approximate distance travelled.”<span class=\"pg\">p.90<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But why….are you going out your way to help me......?”<span class=\"pg\">p.90<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Why? Since this exam is a battle based on the same year, that&#x27;s one aspect of it.”<span class=\"pg\">p.90<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But even using a GPS search is...”<span class=\"pg\">p.90<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If I must say. Maybe it&#x27;s because you&#x27;re in Ichinose&#x27;s class.”<span class=\"pg\">p.90<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…Maybe...”<span class=\"pg\">p.91<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Hmm?”<span class=\"pg\">p.91<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…Maybe it&#x27;s because Ayanokouji-kun ... and Honami-chan ..”<span class=\"pg\">p.91<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Thank you, Ayanokouji-kun, for helping Chihiro-chan”<span class=\"pg\">p.93<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No, I think you would have found her eventually, it wasn&#x27;t a big deal.”<span class=\"pg\">p.93<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yes it was. If we had gone further, we would have run in the risk of injuring ourselves and, above all, we would have had a hard time finding her.”<span class=\"pg\">p.93<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I have something to ask, do you have a walkie-talkie?”<span class=\"pg\">p.93<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What? A walkie-talkie? I have one, but ...”<span class=\"pg\">p.93<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If you don&#x27;t mind, I would like to have a little conversation with Sakayanagi. I would like to ask her if any of the class D students she dealt with have returned to the starting point.”<span class=\"pg\">p.93<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;ll help you with that. Give me a minute.”<span class=\"pg\">p.93<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I just want to talk to her in private.”<span class=\"pg\">p.94<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That&#x27;s it, Sakayanagi. Sorry to bother you at this time of night.”<span class=\"pg\">p.94<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You saved me; I got the information I needed from Sakayanagi.”<span class=\"pg\">p.94<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Okay then. Also, Sakayanagi asked me to give this to you,Ayanokoji.”<span class=\"pg\">p.94<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Oh…thank you.”<span class=\"pg\">p.94<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No need, and again Ayanokouji-kun thank you for helping us.”<span class=\"pg\">p.94<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> He asks Takemoto to call Sakayanagi: whether any Class D students she dealt with have returned to the starting area; the confession on Takak—it&#x27;s an exchange about Sakayanagi&#x27;s Class D dealings; she hands him the walkie-talkie via Takemoto, effectively a gift to him; he sleeps to stories of Classes A and C around him.<span class=\"pg\">p.93–94<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> He walks Shiranami back in the dark with GPS searches; gets their gratitude without revealing his own stake; the Sakayanagi back-channel — Takemoto hands him the walkie-talkie Sakayanagi arranged.<span class=\"pg\">p.86–94<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiranami Chihiro<\/b> He walks her home through the dark; she owes him; she suspects the Honami-chan connection.<span class=\"pg\">p.86–94<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kobashi Yume<\/b> The lost girl; her companions came searching; he thanks them for the find.<span class=\"pg\">p.93–94<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Takemoto Shigeru<\/b> Loan of the walkie-talkie; the relay into Sakayanagi’s channel.<span class=\"pg\">p.93–94<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> The back-channel: he asks via Takemoto about Class D dropouts; Sakayanagi answers and hands him her walkie-talkie.<span class=\"pg\">p.93–94<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p81-1\">← Before: Ch.3: Kiryūin Fuka sizes him up<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p116-1\">→ After: Ch.4: The six-member group at the sunset<\/button><\/div><\/article>"},{"i":"sc-kobashi-yume-y2v4-p86-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"shiranami-chihiro takemoto-shigeru ayanokouji-kiyotaka kobashi-yume","q":"kobashi yume ch 3  kobashi lost in the dark  recovered with shiranami she is the girl in shiranami s group the school has only one  yume  for   class 2 c s kobashi yume  her groupmate shiranami chihiro lost track of her in the dark   yume  yume chan  kobashi  carrying a backpack  and takemoto from the same group arrived to look for shiranami  they had clearly come by gps search   thank you  ayanokouji kun  for helping chihiro chan   yes it was  if we had gone further  we would have run in the risk of injuring ourselves and  above all  we would have had a hard time finding her  her classmate  together they searched for each other and found her with ayanokoji  her other group member  their luggage moves with them  she thanks him for chihiro chan  he plays down the rescue","h":"<article class=\"card\" id=\"sc-kobashi-yume-y2v4-p86-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kobashi-yume.html#sc-kobashi-yume-y2v4-p86-1\">Ch.3: Kobashi lost in the dark; recovered with Shiranami<\/a><\/span><span class=\"meta\">Y2V4 · p.86–94<\/span><span class=\"by\">notes on <a href=\"../../../people/kobashi-yume.html\">Kobashi Yume<\/a><\/span><\/h3><p class=\"setup\">She is the girl in Shiranami’s group the school has only one “Yume” for — Class 2-C’s Kobashi Yume; her groupmate Shiranami Chihiro lost track of her in the dark. Kobashi, carrying a backpack, and Takemoto from the same group arrived to look for Shiranami; they had clearly come by GPS search.<\/p><p class=\"with\">with <a href=\"../../../people/shiranami-chihiro.html\">Shiranami Chihiro<\/a> · <a href=\"../../../people/takemoto-shigeru.html\">Takemoto Shigeru<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Shiranami Chihiro<\/b> “…Yume… Yume-chan”<span class=\"pg\">p.86<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kobashi Yume<\/b> “Thank you, Ayanokouji-kun, for helping Chihiro-chan”<span class=\"pg\">p.93<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kobashi Yume<\/b> “Yes it was. If we had gone further, we would have run in the risk of injuring ourselves and, above all, we would have had a hard time finding her.”<span class=\"pg\">p.93<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiranami Chihiro<\/b> Her classmate; together they searched for each other and found her with Ayanokōji.<span class=\"pg\">p.86–94<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Takemoto Shigeru<\/b> Her other group member; their luggage moves with them.<span class=\"pg\">p.93–94<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> She thanks him for Chihiro-chan; he plays down the rescue.<span class=\"pg\">p.93–94<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-shiranami-chihiro-y2v4-p86-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"ayanokouji-kiyotaka kobashi-yume takemoto-shigeru shiranami-chihiro","q":"shiranami chihiro ch 3  shiranami gets lost  walked home by ayanokoji on night ten at n area  crying and searching in the dark for  yume  ayanokoji finds her and recognizes her as kobashi s groupmate chihiro  he walks her home   yume  yume chan   um  ayanokouji kun   good night   oh  i lost track of where i was   i was in a hurry and didn t know where i was going   i don t know   15 minutes or   about 20 minutes or so    uh huh   eh   i m sorry   i was just resting and    yes   that s    i don t know   i think we would go look for yume chan    i couldn t leave her because she s my friend   that s   i wonder  i don t think it s good   what   uh huh  okay  but   but how   but why are you going out your way to help me   but even using a gps search is   maybe   maybe it s because ayanokouji kun   and honami chan   her worry is that something is happening between honami chan and ayanokoji kun   he can read it in her unfinished sentence and  after a startled pause  drops the subject  he finds her  walks her home in the dark  she owes him  her groupmate  she was out searching for kobashi  yume chan  when he found her  the third of their three person group  found her with kobashi","h":"<article class=\"card\" id=\"sc-shiranami-chihiro-y2v4-p86-1\"><h3><span class=\"ttl\"><a href=\"../../../people/shiranami-chihiro.html#sc-shiranami-chihiro-y2v4-p86-1\">Ch.3: Shiranami gets lost; walked home by Ayanokōji<\/a><\/span><span class=\"meta\">Y2V4 · p.86–94<\/span><span class=\"by\">notes on <a href=\"../../../people/shiranami-chihiro.html\">Shiranami Chihiro<\/a><\/span><\/h3><p class=\"setup\">On night ten at N-area, crying and searching in the dark for “Yume”; Ayanokōji finds her and recognizes her as Kobashi’s groupmate Chihiro; he walks her home.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/kobashi-yume.html\">Kobashi Yume<\/a> · <a href=\"../../../people/takemoto-shigeru.html\">Takemoto Shigeru<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Shiranami Chihiro<\/b> “…Yume… Yume-chan”<span class=\"pg\">p.86<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Shiranami Chihiro<\/b> “Um, Ayanokouji-kun ...... good night.”<span class=\"pg\">p.86<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Shiranami Chihiro<\/b> “Oh, I lost track of where I was ... I was in a hurry and didn&#x27;t know where I was going”<span class=\"pg\">p.87<\/span><\/li><\/ul><details class=\"more\"><summary>20 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t know ...... 15 minutes or ... About 20 minutes or so ......?”<span class=\"pg\">p.87<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Uh-huh.”<span class=\"pg\">p.87<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Eh!?”<span class=\"pg\">p.87<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;m sorry ...... I was just resting and ....”<span class=\"pg\">p.88<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yes.”<span class=\"pg\">p.88<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That&#x27;s……”<span class=\"pg\">p.88<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “... I don&#x27;t know ... I think we would go look for Yume-chan ...”<span class=\"pg\">p.88<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I couldn&#x27;t leave her because she&#x27;s my friend.”<span class=\"pg\">p.88<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That&#x27;s ... I wonder. I don&#x27;t think it&#x27;s good.”<span class=\"pg\">p.89<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What?”<span class=\"pg\">p.90<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Uh-huh. Okay, but......”<span class=\"pg\">p.90<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But how?”<span class=\"pg\">p.90<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But why….are you going out your way to help me......?”<span class=\"pg\">p.90<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But even using a GPS search is...”<span class=\"pg\">p.90<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…Maybe...”<span class=\"pg\">p.91<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…Maybe it&#x27;s because Ayanokouji-kun ... and Honami-chan ..”<span class=\"pg\">p.91<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Her worry is that something is happening between Honami-chan and Ayanokōji-kun — he can read it in her unfinished sentence and, after a startled pause, drops the subject.<span class=\"pg\">p.91<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> He finds her; walks her home in the dark; she owes him.<span class=\"pg\">p.86–94<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kobashi Yume<\/b> Her groupmate; she was out searching for Kobashi “Yume-chan” when he found her.<span class=\"pg\">p.86–94<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Takemoto Shigeru<\/b> The third of their three-person group; found her with Kobashi.<span class=\"pg\">p.87–94<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-takemoto-shigeru-y2v4-p87-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"ayanokouji-kiyotaka sakayanagi-arisu takemoto-shigeru","q":"takemoto shigeru ch 3  the walkie talkie lender he has been with shiranami and kobashi since the group scattered in the dark  he and kobashi come searching with their entire luggage  he lends his walkie talkie and bridges ayanokoji to sakayanagi   what  a walkie talkie  i have one  but    i ll help you with that  give me a minute   you saved me  i got the information i needed from sakayanagi   okay then  also  sakayanagi asked me to give this to you ayanokoji   no need  and again ayanokouji kun thank you for helping us  the school walkie talkies are digital with confidential mode  he makes the call for ayanokoji  sakayanagi answered and asked him to hand the walkie talkie over to ayanokoji kun directly  hands him the walkie talkie sakayanagi donated  the intermediary  she answers and instructs via confidential mode","h":"<article class=\"card\" id=\"sc-takemoto-shigeru-y2v4-p87-1\"><h3><span class=\"ttl\"><a href=\"../../../people/takemoto-shigeru.html#sc-takemoto-shigeru-y2v4-p87-1\">Ch.3: The walkie-talkie lender<\/a><\/span><span class=\"meta\">Y2V4 · p.87–94<\/span><span class=\"by\">notes on <a href=\"../../../people/takemoto-shigeru.html\">Takemoto Shigeru<\/a><\/span><\/h3><p class=\"setup\">He has been with Shiranami and Kobashi since the group scattered in the dark; he and Kobashi come searching with their entire luggage; he lends his walkie-talkie and bridges Ayanokōji to Sakayanagi.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Takemoto Shigeru<\/b> “What? A walkie-talkie? I have one, but ...”<span class=\"pg\">p.93<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Takemoto Shigeru<\/b> “I&#x27;ll help you with that. Give me a minute.”<span class=\"pg\">p.93<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Takemoto Shigeru<\/b> “You saved me; I got the information I needed from Sakayanagi.”<span class=\"pg\">p.94<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Okay then. Also, Sakayanagi asked me to give this to you,Ayanokoji.”<span class=\"pg\">p.94<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No need, and again Ayanokouji-kun thank you for helping us.”<span class=\"pg\">p.94<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The school walkie-talkies are digital with Confidential Mode; he makes the call for Ayanokōji; Sakayanagi answered and asked him to hand the walkie-talkie over to Ayanokōji-kun directly.<span class=\"pg\">p.93–94<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Hands him the walkie-talkie Sakayanagi donated.<span class=\"pg\">p.93–94<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> The intermediary; she answers and instructs via Confidential Mode.<span class=\"pg\">p.93–94<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-takemoto-shigeru-y2v4-p88-1\">→ After: Takemoto mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-takemoto-shigeru-y2v4-p88-1","v":"y2v4","y":2,"o":19,"k":"","w":"takemoto-shigeru","q":"takemoto shigeru takemoto mentioned in passing  nothing happened  instead  kokobashi and takemoto are fine right    ayanokoji asks shiranami   there is a possibility that takemoto will go out alone to look for shiranami  but there is also the possibility that would become an additional disaster    ayanokoji   in any case  wandering aimlessly will only make things worse    ayanokoji","h":"<article class=\"card\" id=\"sc-takemoto-shigeru-y2v4-p88-1\"><h3><span class=\"ttl\"><a href=\"../../../people/takemoto-shigeru.html#sc-takemoto-shigeru-y2v4-p88-1\">Takemoto mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.88–89<\/span><span class=\"by\">notes on <a href=\"../../../people/takemoto-shigeru.html\">Takemoto Shigeru<\/a><\/span><\/h3><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “Nothing happened. Instead, Kokobashi and Takemoto are fine right?” — Ayanokōji asks Shiranami.<span class=\"pg\">p.88<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “There is a possibility that Takemoto will go out alone to look for Shiranami, but there is also the possibility that would become an additional disaster.” — Ayanokōji.<span class=\"pg\">p.88<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “In any case, wandering aimlessly will only make things worse.” — Ayanokōji.<span class=\"pg\">p.89<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-takemoto-shigeru-y2v4-p87-1\">← Before: Ch.3: The walkie-talkie lender<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-takemoto-shigeru-y2v4-p159-1\">→ After: Ch.5: The walkie-talkie relay at midnight<\/button><\/div><\/article>"},{"i":"sc-ichinose-honami-y2v4-p89-1","v":"y2v4","y":2,"o":19,"k":"","w":"ichinose-honami","q":"ichinose honami ichinose mentioned in passing  it s a typical response from ichinose s class    narration   maybe it s because ayanokouji kun   and honami chan     shiranami trails off  she closes her mouth","h":"<article class=\"card\" id=\"sc-ichinose-honami-y2v4-p89-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ichinose-honami.html#sc-ichinose-honami-y2v4-p89-1\">Ichinose mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.89–91<\/span><span class=\"by\">notes on <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/span><\/h3><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “It&#x27;s a typical response from Ichinose&#x27;s class.” — narration.<span class=\"pg\">p.89<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “maybe it&#x27;s because Ayanokouji-kun ... and Honami-chan ..” — Shiranami trails off; she closes her mouth.<span class=\"pg\">p.91<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y2v4-p120-1\">→ After: Ichinose mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-sakayanagi-arisu-y2v4-p93-1","v":"y2v4","y":2,"o":19,"k":"","w":"sakayanagi-arisu","q":"sakayanagi arisu sakayanagi mentioned in passing  if you don t mind  i would like to have a little conversation with sakayanagi  i would like to ask her if any of the class d students she dealt with have returned to the starting point    ayanokoji asks takemoto   okay then  also  sakayanagi asked me to give this to you ayanokoji    takemoto hands over her walkie talkie","h":"<article class=\"card\" id=\"sc-sakayanagi-arisu-y2v4-p93-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sakayanagi-arisu.html#sc-sakayanagi-arisu-y2v4-p93-1\">Sakayanagi mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.93–94<\/span><span class=\"by\">notes on <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/span><\/h3><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “If you don&#x27;t mind, I would like to have a little conversation with Sakayanagi. I would like to ask her if any of the class D students she dealt with have returned to the starting point.” — Ayanokōji asks Takemoto.<span class=\"pg\">p.93<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Okay then. Also, Sakayanagi asked me to give this to you,Ayanokoji.” — Takemoto hands over her walkie-talkie.<span class=\"pg\">p.94<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sakayanagi-arisu-y2v4-p59-1\">← Before: Sakayanagi mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sakayanagi-arisu-y2v4-p159-1\">→ After: Ch.5: The second-grade countermove<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y2v4-p95-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"mikitani nagumo-miyabi kouenji-rokusuke kiriyama-ikuto","q":"kiriyama ikuto ch 4  the plan against kouenji on the tenth day after the test ended  ikuto kiriyama  third year of class b  closes his eyes once after a walkie talkie call   kouenji sits atop the podium with 230 points to nagumo s 236  six points apart  and kiriyama  nagumo s right hand  quietly closes his eyes at the news   kiriyama  don t you think nagumo s answer is a step backwards  if so  you would have been in a position to take the lead by starting of the second part of the test    mikitani   all i could think was   don t get carried away just because you re wealthy   the main reason why kouenji has not been appreciated is that he doesn t have a sincere attitude towards things   i don t know what happened  but kouenji has literally gone all out in this special survey of the uninhabited island   if left unchecked  kouenji will definitely finish the exam in the top three places  in some cases  it wouldn t even be possible for me to reach nagumo  losing to a group from the younger years was a problem  but losing to a loner would be a disgrace for the third year   the six groups that i have in custody  i am mobilizing them all   the only threat is kouenji  and other than that  there is plenty of time to go after destroying him  we will be able to see the results until the end of the 12th  in two days starting tomorrow  we will fully contain kouenji  once kouenji loses his momentum  he won t be able to surface again   i don t think you have to worry about that anymore  nagumo s fears are unfounded   an invisible ghost grabbed me by the shoulders  i am not surprised    no  this is mikitani s line  let me check  mikitani said  an invisible ghost  no   kiriyama says this  the speaker of  an invisible ghost grabbed me by the shoulders  i am not surprised  is kiriyama   do you want me to put you in charge    mikitani   unlike you  who have decided to win  i have to earn nagumo s reputation   but you also have to get second place  right  don t waste your time on unnecessary things    mikitani   there is no one who can stop kouenji except nagumo and me  that is the end of the story  calm strategist for nagumo   sees kouenji as the only real obstacle  plans an encirclement with six  free groups   nagumo s 15 reserved three person groups  two teams each free to act  and takes direct command personally to earn nagumo s reputation rather than  win  by his own count  his class b subordinate  groans at the six group plan  nagumo handed him the free groups  kiriyama acts as his eyes  the obstacle  230 vs 236  two days to contain him","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y2v4-p95-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kiriyama-ikuto.html#sc-kiriyama-ikuto-y2v4-p95-1\">Ch.4: The plan against Kouenji<\/a><\/span><span class=\"meta\">Y2V4 · p.95–99<\/span><span class=\"by\">notes on <a href=\"../../../people/kiriyama-ikuto.html\">Kiriyama Ikuto<\/a><\/span><\/h3><p class=\"setup\">On the tenth day after the test ended, Ikuto Kiriyama, third year of Class B, closes his eyes once after a walkie-talkie call — Kouenji sits atop the podium with 230 points to Nagumo’s 236, six points apart, and Kiriyama, Nagumo’s right hand, quietly closes his eyes at the news.<\/p><p class=\"with\">with <a href=\"../../../people/mikitani.html\">Mikitani<\/a> · <a href=\"../../../people/nagumo-miyabi.html\">Nagumo Miyabi<\/a> · <a href=\"../../../people/kouenji-rokusuke.html\">Kōenji Rokusuke<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Kiriyama Ikuto<\/b> “Kiriyama. Don’t you think Nagumo&#x27;s answer is a step backwards? If so, you would have been in a position to take the lead by starting of the second part of the test.” — Mikitani.<span class=\"pg\">p.95<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kiriyama Ikuto<\/b> “All I could think was: ‘Don&#x27;t get carried away just because you&#x27;re wealthy.’”<span class=\"pg\">p.95<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kiriyama Ikuto<\/b> “The main reason why Kouenji has not been appreciated is that he doesn’t have a sincere attitude towards things.”<span class=\"pg\">p.96<\/span><\/li><\/ul><details class=\"more\"><summary>14 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t know what happened, but Kouenji has literally gone all out in this special survey of the uninhabited island.”<span class=\"pg\">p.96<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If left unchecked, Kouenji will definitely finish the exam in the top three places. In some cases, it wouldn’t even be possible for me to reach Nagumo. Losing to a group from the younger years was a problem, but losing to a loner would be a disgrace for the third year.”<span class=\"pg\">p.96<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The six groups that I have in custody. I am mobilizing them all”.<span class=\"pg\">p.97<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The only threat is Kouenji, and other than that, there is plenty of time to go after destroying him. We will be able to see the results until the end of the 12th. In two days starting tomorrow, we will fully contain Kouenji. Once Kouenji loses his momentum, he won&#x27;t be able to surface again.”<span class=\"pg\">p.97<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t think you have to worry about that anymore. Nagumo&#x27;s fears are unfounded.”<span class=\"pg\">p.97<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “An invisible ghost grabbed me by the shoulders, I am not surprised.” — no, this is Mikitani&#x27;s line? Let me check: Mikitani said “An invisible ghost...”? No — Kiriyama says this. The speaker of “An invisible ghost grabbed me by the shoulders, I am not surprised.” is Kiriyama.<span class=\"pg\">p.97<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Do you want me to put you in charge?” — Mikitani.<span class=\"pg\">p.98<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Unlike you, who have decided to win, I have to earn Nagumo&#x27;s reputation.”<span class=\"pg\">p.98<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But you also have to get second place, right? Don&#x27;t waste your time on unnecessary things.” — Mikitani.<span class=\"pg\">p.98<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There is no one who can stop Kouenji except Nagumo and me. That is the end of the story.”<span class=\"pg\">p.98<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Calm strategist for Nagumo — sees Kouenji as the only real obstacle, plans an encirclement with six “Free Groups” (Nagumo’s 15 reserved three-person groups, two teams each free to act), and takes direct command personally to earn Nagumo’s reputation rather than “win” by his own count.<span class=\"pg\">p.95–99<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Mikitani<\/b> His Class B subordinate; groans at the six-group plan.<span class=\"pg\">p.95–99<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> Nagumo handed him the Free Groups; Kiriyama acts as his eyes.<span class=\"pg\">p.95–99<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> The obstacle: 230 vs 236; two days to contain him.<span class=\"pg\">p.95–99<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y2v4-p38-1\">← Before: Kiriyama mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y2v4-p100-1\">→ After: Ch.4: The morning siege; the departure<\/button><\/div><\/article>"},{"i":"sc-mikitani-y2v4-p95-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"kiriyama-ikuto nagumo-miyabi mikitani","q":"mikitani ch 4  kiriyama s spearhead  the six free groups deal he shows kiriyama the tablet  nagumo 236  kouenji 230  six points apart  with reward for arrival points to decide it all  he wants kiriyama to drop the plan   even if nagumo can get away with it  you ll finish third if you re not careful  if you lost to a loner sophomore  2nd year  our reputation as your supporters would take a nosedive     kiriyama  don t you think nagumo s answer is a step backwards  if so  you would have been in a position to take the lead by starting of the second part of the test   the main reason why kouenji has not been appreciated is that he doesn t have a sincere attitude towards things   i don t know what happened  but kouenji has literally gone all out in this special survey of the uninhabited island   well  you re right  so how many are you going to use   the six groups that i have in custody  i am mobilizing them all   six  are you serious  you re dealing with just one person  and no matter how many there are  four groups with my custody should be enough  the other two groups will be in your custody   the only threat is kouenji  and other than that  there is plenty of time to go after destroying him  we will be able to see the results until the end of the 12th  in two days starting tomorrow  we will fully contain kouenji  once kouenji loses his momentum  he won t be able to surface again   didn t nagumo say that there were other groups that interested him  if we attack kouenji with all the available groups  we will not have enough personnel to dedicate ourselves to the others   i don t think you have to worry about that anymore  nagumo s fears are unfounded  of course  kiriyama knew which group he was looking for  that group has not appeared in the top ten in ten days   an invisible ghost grabbed me by the shoulders  i am not surprised   so we ll let the six groups take care of kouenji and we ll just score points as usual  okay   no  i will take direct command to contain kouenji   you  that s a bit inefficient  don t you think  let me do it   but you also have to get second place  right  don t waste your time on unnecessary things   there is no one who can stop kouenji except nagumo and me  that is the end of the story   i think it will be easy to kick him out if we have two days  there are seven groups here  including the six from kiriyama  for a total of 18 people     don t let your guard down  it is a large forest  there are many possibilities that he will escape     i know he s a bad boy for a second year  but he s still younger than you   be cautious  recognize your opponent as your greatest enemy   the oldest  kiriyama thinks to himself  he cannot trust someone like mikitani with this  he handles the arithmetic for the free groups  tries to moderate the six group commitment to four  complains about the risk to kiriyama s second place race  ends up dragged into the plan as its spearhead  his commander  argues with his plans but follows  the 236 230 stakes are his tablet s  nagumo handed the six free groups to kiriyama","h":"<article class=\"card\" id=\"sc-mikitani-y2v4-p95-1\"><h3><span class=\"ttl\"><a href=\"../../../people/mikitani.html#sc-mikitani-y2v4-p95-1\">Ch.4: Kiriyama&#x27;s spearhead; the Six Free Groups deal<\/a><\/span><span class=\"meta\">Y2V4 · p.95–99<\/span><span class=\"by\">notes on <a href=\"../../../people/mikitani.html\">Mikitani<\/a><\/span><\/h3><p class=\"setup\">He shows Kiriyama the tablet: Nagumo 236, Kouenji 230, six points apart, with reward-for-arrival points to decide it all; he wants Kiriyama to drop the plan.<\/p><p class=\"with\">with <a href=\"../../../people/kiriyama-ikuto.html\">Kiriyama Ikuto<\/a> · <a href=\"../../../people/nagumo-miyabi.html\">Nagumo Miyabi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Mikitani<\/b> “Even if Nagumo can get away with it, you&#x27;ll finish third if you&#x27;re not careful. If you lost to a loner sophomore( 2nd year), our reputation as your supporters would take a nosedive. ”<span class=\"pg\">p.95<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Mikitani<\/b> “Kiriyama. Don&#x27;t you think Nagumo&#x27;s answer is a step backwards? If so, you would have been in a position to take the lead by starting of the second part of the test.”<span class=\"pg\">p.95<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Mikitani<\/b> “The main reason why Kouenji has not been appreciated is that he doesn’t have a sincere attitude towards things.”<span class=\"pg\">p.95<\/span><\/li><\/ul><details class=\"more\"><summary>23 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t know what happened, but Kouenji has literally gone all out in this special survey of the uninhabited island.”<span class=\"pg\">p.96<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, you&#x27;re right. So how many are you going to use?”<span class=\"pg\">p.97<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The six groups that I have in custody. I am mobilizing them all”.<span class=\"pg\">p.97<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Six? Are you serious? You&#x27;re dealing with just one person, and no matter how many there are, four groups with my custody should be enough. The other two groups will be in your custody...”<span class=\"pg\">p.97<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The only threat is Kouenji, and other than that, there is plenty of time to go after destroying him. We will be able to see the results until the end of the 12th. In two days starting tomorrow, we will fully contain Kouenji. Once Kouenji loses his momentum, he won&#x27;t be able to surface again.”<span class=\"pg\">p.97<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Didn&#x27;t Nagumo say that there were other groups that interested him? If we attack Kouenji with all the available groups, we will not have enough personnel to dedicate ourselves to the others.”<span class=\"pg\">p.97<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t think you have to worry about that anymore. Nagumo&#x27;s fears are unfounded.”<span class=\"pg\">p.97<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Of course, Kiriyama knew which group he was looking for. That group has not appeared in the top ten in ten days.<span class=\"pg\">p.97<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “An invisible ghost grabbed me by the shoulders, I am not surprised.”<span class=\"pg\">p.97<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So we&#x27;ll let the six groups take care of Kouenji and we&#x27;ll just score points as usual, okay?”<span class=\"pg\">p.98<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No, I will take direct command to contain Kouenji.”<span class=\"pg\">p.98<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You? That&#x27;s a bit inefficient, don&#x27;t you think? Let me do it.”<span class=\"pg\">p.98<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But you also have to get second place, right? Don&#x27;t waste your time on unnecessary things.”<span class=\"pg\">p.98<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There is no one who can stop Kouenji except Nagumo and me. That is the end of the story.”<span class=\"pg\">p.98<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I think it will be easy to kick him out if we have two days. There are seven groups here, including the six from Kiriyama, for a total of 18 people. ”<span class=\"pg\">p.99<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don&#x27;t let your guard down. It is a large forest, there are many possibilities that he will escape. ”<span class=\"pg\">p.99<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I know he&#x27;s a bad boy for a second year. But he&#x27;s still younger than you.”<span class=\"pg\">p.99<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Be cautious. Recognize your opponent as your greatest enemy.”<span class=\"pg\">p.99<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The oldest?”<span class=\"pg\">p.99<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Kiriyama thinks to himself: he cannot trust someone like Mikitani with this.<span class=\"pg\">p.99<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> He handles the arithmetic for the Free Groups; tries to moderate the six-group commitment to four; complains about the risk to Kiriyama&#x27;s second-place race; ends up dragged into the plan as its spearhead.<span class=\"pg\">p.95–99<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kiriyama Ikuto<\/b> His commander; argues with his plans but follows.<span class=\"pg\">p.95–99<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> The 236–230 stakes are his tablet&#x27;s; Nagumo handed the Six Free Groups to Kiriyama.<span class=\"pg\">p.95<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-mikitani-y2v4-p100-1\">→ After: The tent watch; the run<\/button><\/div><\/article>"},{"i":"sc-nagumo-miyabi-y2v4-p95-1","v":"y2v4","y":2,"o":19,"k":"","w":"nagumo-miyabi","q":"nagumo miyabi nagumo mentioned in passing  on the tenth day  he has been scoring points to stick with nagumo s group nothing close to impatience in kiriyama or nagumo    narration   enemy to be watched by nagumo long before    narration   the only man nagumo recognized  the only thing left of manabu horikita  it s no wonder that nagumo s eyes  which can see the battlefield with an eagle s eye  are clouded    narration   there is no one who can stop kouenji except nagumo and me    kiriyama to mikitani   the following is not a bad idea  if you are willing to follow it  if you have the student council president  nagumo  on your side  your school life will be more stable    kiriyama to kouenji   these are the soldiers  so to speak  that nagumo and kiriyama have brought together to monopolize many of the tasks    narration   and when nagumo found out about this result  he was very disappointed    narration   there is always someone who does not agree with your calculations  like nagumo    mikitani","h":"<article class=\"card\" id=\"sc-nagumo-miyabi-y2v4-p95-1\"><h3><span class=\"ttl\"><a href=\"../../../people/nagumo-miyabi.html#sc-nagumo-miyabi-y2v4-p95-1\">Nagumo mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.95–98, 102, 107, 109, 115<\/span><span class=\"by\">notes on <a href=\"../../../people/nagumo-miyabi.html\">Nagumo Miyabi<\/a><\/span><\/h3><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “on the tenth day, he has been scoring points to stick with Nagumo&#x27;s group...nothing close to impatience in Kiriyama or Nagumo.” — narration.<span class=\"pg\">p.95<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “enemy to be watched by Nagumo long before.” — narration.<span class=\"pg\">p.96<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “The only man Nagumo recognized, the only thing left of Manabu Horikita. It&#x27;s no wonder that Nagumo&#x27;s eyes, which can see the battlefield with an eagle&#x27;s eye, are clouded.” — narration.<span class=\"pg\">p.97<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “there is no one who can stop Kouenji except Nagumo and me.” — Kiriyama to Mikitani.<span class=\"pg\">p.98<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “The following is not a bad idea, if you are willing to follow it. If you have the student council president, Nagumo, on your side, your school life will be more stable.” — Kiriyama to Kouenji.<span class=\"pg\">p.102<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “These are the soldiers, so to speak, that Nagumo and Kiriyama have brought together to monopolize many of the tasks.” — narration.<span class=\"pg\">p.107<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “And when Nagumo found out about this result, he was very disappointed.” — narration.<span class=\"pg\">p.109<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “there is always someone who does not agree with your calculations. Like Nagumo.” — Mikitani.<span class=\"pg\">p.115<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y2v4-p61-1\">← Before: Nagumo mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y2v4-p152-1\">→ After: Nagumo mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-horikita-manabu-y2v4-p97-1","v":"y2v4","y":2,"o":19,"k":"","w":"horikita-manabu","q":"horikita manabu manabu named in the kiriyama camp  the only man nagumo recognized  the only thing left of manabu horikita    printed inside the kiriyama mikitani camp scene  the  me  in the preceding  an invisible ghost grabbed me by the shoulders  is not tagged in the print  kept unassigned   it s no wonder that nagumo s eyes  which can see the battlefield with an eagle s eye  are clouded    the horikita chase is the scene s buried motive","h":"<article class=\"card\" id=\"sc-horikita-manabu-y2v4-p97-1\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-manabu.html#sc-horikita-manabu-y2v4-p97-1\">Manabu named in the Kiriyama camp<\/a><\/span><span class=\"meta\">Y2V4 · p.97<\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-manabu.html\">Horikita Manabu<\/a><\/span><\/h3><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “The only man Nagumo recognized, the only thing left of Manabu Horikita.” — printed inside the Kiriyama–Mikitani camp scene; the “me” in the preceding “An invisible ghost grabbed me by the shoulders” is not tagged in the print; kept unassigned.<span class=\"pg\">p.97<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “It&#x27;s no wonder that Nagumo&#x27;s eyes, which can see the battlefield with an eagle&#x27;s eye, are clouded.” — the Horikita chase is the scene&#x27;s buried motive.<span class=\"pg\">p.97<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-manabu-y2v4-p204-1\">→ After: Nagumo sees Ayanokōji as Manabu&#x27;s man<\/button><\/div><\/article>"},{"i":"sc-utomiya-riku-y2v4-p97-1","v":"y2v4","y":2,"o":19,"k":"","w":"utomiya-riku","q":"utomiya riku utomiya mentioned in passing  if it was one of the top ten  it was ryuuen s second year group  sakayanagi s group  or utomiya s group and the others in first year    narration   the only thing we should avoid is getting in the way of our efforts to eliminate ayanokouji senpai  and the only person capable of eliminating ayanokouji senpai  apart from utomiya kun  is housen kun    yagami","h":"<article class=\"card\" id=\"sc-utomiya-riku-y2v4-p97-1\"><h3><span class=\"ttl\"><a href=\"../../../people/utomiya-riku.html#sc-utomiya-riku-y2v4-p97-1\">Utomiya mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.97, 166<\/span><span class=\"by\">notes on <a href=\"../../../people/utomiya-riku.html\">Utomiya Riku<\/a><\/span><\/h3><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “if it was one of the top ten, it was Ryuuen&#x27;s second year group, Sakayanagi&#x27;s group, or Utomiya&#x27;s group and the others in first year.” — narration.<span class=\"pg\">p.97<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “The only thing we should avoid is getting in the way of our efforts to eliminate Ayanokouji-senpai. And the only person capable of eliminating Ayanokouji-Senpai, apart from Utomiya-kun, is Housen-kun...” — Yagami.<span class=\"pg\">p.166<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-utomiya-riku-y2v4-p121-1\">→ After: Utomiya mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-kouenji-rokusuke-y2v4-p99-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"kiriyama-ikuto nagumo-miyabi kouenji-rokusuke","q":"koenji rokusuke ch 4  surrounded at dawn  he simply bolts besieged on day eleven by kiriyama s group plus six  free groups   18 third years  mobilized by nagumo s reserve corps to stop his top streak  he hums  takes his tablet  and departs on schedule   it s on the move  it s kouenji    mikitani  tracked in his own ledger   can you give me some time  kouenji   do you want something from me    kouenji   i didn t expect you to do so well in this special exam   you know what i mean  kouenji  you ve got too many points   i want you to stay where you are the rest of the day   does that mean you don t want me to earn points     kouenji   yes   i don t know who you are  but you only need to think a little to realize that it is an impossible proposal  but even so  the fact that you have brought so many people means that you are prepared to interfere with my plans even if i ignore it  right    kouenji   it is not good that you are in a group alone  i acknowledge that you have made great progress so far  but your results will most likely drop in the second half of the exam as you get tired     then you don t have to worry about me  right    kouenji   it is a matter of precaution  also  it is difficult for a third year student to accept the fact that he is competing for the highest position with you  a lonely student   the following is not a bad idea  if you are willing to follow it  if you have the student council president  nagumo  on your side  your school life will be more stable     i m not one to accept advice  kiriyama    no  that s later  p 106  kouenji says this line at p 106   i m going to hurry  so if you ll excuse me    kouenji to the 18 third years surrounding him  alone  unbothered  utterly in control of his pace   the 18 person encirclement fails to budge his routine  once the 7 00 zone announces  he simply bolts through them  his direct opponent in the siege  kiriyama cannot make him yield an inch  nagumo reserved six of his fifteen free groups for this containment  kouenji refuses his protection","h":"<article class=\"card\" id=\"sc-kouenji-rokusuke-y2v4-p99-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kouenji-rokusuke.html#sc-kouenji-rokusuke-y2v4-p99-1\">Ch.4: Surrounded at dawn; he simply bolts<\/a><\/span><span class=\"meta\">Y2V4 · p.99–102<\/span><span class=\"by\">notes on <a href=\"../../../people/kouenji-rokusuke.html\">Kōenji Rokusuke<\/a><\/span><\/h3><p class=\"setup\">Besieged on day eleven by Kiriyama’s group plus six “Free Groups” (18 third-years) mobilized by Nagumo’s reserve corps to stop his top-streak; he hums, takes his tablet, and departs on schedule.<\/p><p class=\"with\">with <a href=\"../../../people/kiriyama-ikuto.html\">Kiriyama Ikuto<\/a> · <a href=\"../../../people/nagumo-miyabi.html\">Nagumo Miyabi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Kōenji Rokusuke<\/b> “It&#x27;s on the move, it&#x27;s Kouenji!” — Mikitani; tracked in his own ledger.<span class=\"pg\">p.101<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kiriyama Ikuto<\/b> “Can you give me some time, Kouenji?”<span class=\"pg\">p.101<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kōenji Rokusuke<\/b> “Do you want something from me?” — Kouenji.<span class=\"pg\">p.101<\/span><\/li><\/ul><details class=\"more\"><summary>15 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “I didn&#x27;t expect you to do so well in this special exam.”<span class=\"pg\">p.101<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You know what I mean, Kouenji. You&#x27;ve got too many points.”<span class=\"pg\">p.101<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I want you to stay where you are the rest of the day.”<span class=\"pg\">p.101<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Does that mean you don&#x27;t want me to earn points ......?” — Kouenji.<span class=\"pg\">p.101<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yes.”<span class=\"pg\">p.101<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t know who you are, but you only need to think a little to realize that it is an impossible proposal. But even so, the fact that you have brought so many people means that you are prepared to interfere with my plans even if I ignore it, right?” — Kouenji.<span class=\"pg\">p.101<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It is not good that you are in a group alone. I acknowledge that you have made great progress so far, but your results will most likely drop in the second half of the exam as you get tired. ”<span class=\"pg\">p.101<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Then you don&#x27;t have to worry about me, right?” — Kouenji.<span class=\"pg\">p.102<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It is a matter of precaution. Also, it is difficult for a third year student to accept the fact that he is competing for the highest position with you, a lonely student.”<span class=\"pg\">p.102<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The following is not a bad idea, if you are willing to follow it. If you have the student council president, Nagumo, on your side, your school life will be more stable. ”<span class=\"pg\">p.102<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;m not one to accept advice, Kiriyama.” — no, that&#x27;s later (p.106); Kouenji says this line at p.106.<span class=\"pg\">p.102<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;m going to hurry, so if you&#x27;ll excuse me.” — Kouenji to the 18 third-years surrounding him.<span class=\"pg\">p.102<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Alone, unbothered, utterly in control of his pace — the 18-person encirclement fails to budge his routine; once the 7:00 zone announces, he simply bolts through them.<span class=\"pg\">p.99–102<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kiriyama Ikuto<\/b> His direct opponent in the siege; Kiriyama cannot make him yield an inch.<span class=\"pg\">p.99–102<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> Nagumo reserved six of his fifteen Free Groups for this containment; Kouenji refuses his protection.<span class=\"pg\">p.95–102<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kouenji-rokusuke-y2v4-p62-1\">← Before: Kōenji mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kouenji-rokusuke-y2v4-p103-1\">→ After: Ch.4: The nap reveal; the REM claim<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y2v4-p100-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"mikitani kouenji-rokusuke kiriyama-ikuto","q":"kiriyama ikuto ch 4  the morning siege  the departure six free groups plus kiriyama s group surround kouenji s tent at 6 30  he sleeps on through the approach  they decide to settle in at his departure   never within two meters   and gps is declared fallible  not teacher proof   hey  why don t we go around him and block him before he leaves the tent  if we make it impossible for him to leave the tent  kouenji won t be able to move   if we interfere with his departure  we can delay the time it takes to reach the designated area  but what would your excuse be if a third party saw the situation  if you are going to interfere  you must refrain from doing something that can be easily recognized   why don t you do a gps search  anyway  there are a lot of points to spend     our tablets don t know where the teachers are  do not forget that the search is not absolute  as originally planned  we ll be settling in when kouenji clears the tent and starts moving  if you come across a freshman or sophomore  or an adult on your way to set a task  immediately open a distance of at least two meters from kouenji   it s on the move  it s kouenji   go   can you give me some time  kouenji    the third years call out  not kiriyama alone   i didn t expect you to do so well in this special exam   you know what i mean  kouenji  you ve got too many points   i want you to stay where you are the rest of the day   then you don t have to worry about me  right    kouenji   it is a matter of precaution  also  it is difficult for a third year student to accept the fact that he is competing for the highest position with you  a lonely student  the plan is passive   surround  isolate  never touch  he trusts discipline over confrontation  the 7 00 designated zone timing is his weapon  kouenji bolts the moment the zone is revealed  his siege is intimidation  never contact  kouenji flees the moment the zone appears  his hothead  restrains him twice","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y2v4-p100-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kiriyama-ikuto.html#sc-kiriyama-ikuto-y2v4-p100-1\">Ch.4: The morning siege; the departure<\/a><\/span><span class=\"meta\">Y2V4 · p.100–102<\/span><span class=\"by\">notes on <a href=\"../../../people/kiriyama-ikuto.html\">Kiriyama Ikuto<\/a><\/span><\/h3><p class=\"setup\">Six free groups plus Kiriyama’s group surround Kouenji’s tent at 6:30; he sleeps on through the approach; they decide to settle in at his departure — never within two meters — and GPS is declared fallible (not teacher-proof).<\/p><p class=\"with\">with <a href=\"../../../people/mikitani.html\">Mikitani<\/a> · <a href=\"../../../people/kouenji-rokusuke.html\">Kōenji Rokusuke<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Mikitani<\/b> “Hey, why don&#x27;t we go around him and block him before he leaves the tent? If we make it impossible for him to leave the tent, Kouenji won&#x27;t be able to move.”<span class=\"pg\">p.100<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kiriyama Ikuto<\/b> “If we interfere with his departure, we can delay the time it takes to reach the designated area. But what would your excuse be if a third party saw the situation? If you are going to interfere, you must refrain from doing…”<span class=\"pg\">p.100<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kiriyama Ikuto<\/b> “Why don&#x27;t you do a GPS search? Anyway, there are a lot of points to spend. ”<span class=\"pg\">p.100<\/span><\/li><\/ul><details class=\"more\"><summary>13 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “If we interfere with his departure, we can delay the time it takes to reach the designated area. But what would your excuse be if a third party saw the situation? If you are going to interfere, you must refrain from doing something that can be easily recognized.”<span class=\"pg\">p.100<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Our tablets don&#x27;t know where the teachers are. Do not forget that the search is not absolute. As originally planned, we&#x27;ll be settling in when Kouenji clears the tent and starts moving. If you come across a freshman or sophomore, or an adult on your way to set a task, immediately open a distance of at least two meters from Kouenji.”<span class=\"pg\">p.100<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It&#x27;s on the move, it&#x27;s Kouenji!”<span class=\"pg\">p.101<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Go.”<span class=\"pg\">p.101<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Can you give me some time, Kouenji?” — the third-years call out; not Kiriyama alone.<span class=\"pg\">p.101<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I didn&#x27;t expect you to do so well in this special exam.”<span class=\"pg\">p.101<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You know what I mean, Kouenji. You&#x27;ve got too many points.”<span class=\"pg\">p.101<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I want you to stay where you are the rest of the day.”<span class=\"pg\">p.101<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Then you don&#x27;t have to worry about me, right?” — Kouenji.<span class=\"pg\">p.102<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It is a matter of precaution. Also, it is difficult for a third year student to accept the fact that he is competing for the highest position with you, a lonely student.”<span class=\"pg\">p.102<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> The plan is passive — surround, isolate, never touch; he trusts discipline over confrontation; the 7:00 designated-zone timing is his weapon; Kouenji bolts the moment the zone is revealed.<span class=\"pg\">p.100–102<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> His siege is intimidation, never contact; Kouenji flees the moment the zone appears.<span class=\"pg\">p.100–102<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Mikitani<\/b> His hothead; restrains him twice.<span class=\"pg\">p.100–102<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y2v4-p95-1\">← Before: Ch.4: The plan against Kouenji<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y2v4-p103-1\">→ After: Ch.4: The sleep revelation; the circle spreads<\/button><\/div><\/article>"},{"i":"sc-mikitani-y2v4-p100-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"kiriyama-ikuto kouenji-rokusuke mikitani","q":"mikitani the tent watch  the run he floats the idea of blocking kouenji at his tent  kiriyama shuts it down  he pushes a gps search  kouenji bolts when the zone announces  he gives chase   hey  why don t we go around him and block him before he leaves the tent  if we make it impossible for him to leave the tent  kouenji won t be able to move   if we interfere with his departure  we can delay the time it takes to reach the designated area  but what would your excuse be if a third party saw the situation  if you are going to interfere  you must refrain from doing something that can be easily recognized     why don t you do a gps search  anyway  there are a lot of points to spend     our tablets don t know where the teachers are  do not forget that the search is not absolute  as originally planned  we ll be settling in when kouenji clears the tent and starts moving  if you come across a freshman or sophomore  or an adult on your way to set a task  immediately open a distance of at least two meters from kouenji   do not shorten the distance to the point of making contact   it s on the move  it s kouenji   hey  hey   don t be scared  you will hurt yourself if you match kouenji s rhythm   this is not the time to relax  we have lost it   you may get the reward on a first come  first serve basis  but that s how far it goes  if kouenji chooses to flee  he will not be able to take his time to participate in the tasks  on the other hand  if he chooses to participate with impunity in the challenge  we will be able to catch up with him there     what is kouenji s position   i ve looked for it three times  but it hasn t moved at all   get up  kouenji  you ve been running for more than 10 days  so you took a nap from exhaustion  right  hothead   proposes the illegal surround  then a gps spend  then shouts at the runner  kiriyama restrains him twice  he chases anyway  he chases  he loses him  his handler  reined in at every step","h":"<article class=\"card\" id=\"sc-mikitani-y2v4-p100-1\"><h3><span class=\"ttl\"><a href=\"../../../people/mikitani.html#sc-mikitani-y2v4-p100-1\">The tent watch; the run<\/a><\/span><span class=\"meta\">Y2V4 · p.100–103<\/span><span class=\"by\">notes on <a href=\"../../../people/mikitani.html\">Mikitani<\/a><\/span><\/h3><p class=\"setup\">He floats the idea of blocking Kouenji at his tent; Kiriyama shuts it down; he pushes a GPS Search; Kouenji bolts when the zone announces; he gives chase.<\/p><p class=\"with\">with <a href=\"../../../people/kiriyama-ikuto.html\">Kiriyama Ikuto<\/a> · <a href=\"../../../people/kouenji-rokusuke.html\">Kōenji Rokusuke<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Mikitani<\/b> “Hey, why don&#x27;t we go around him and block him before he leaves the tent? If we make it impossible for him to leave the tent, Kouenji won&#x27;t be able to move.”<span class=\"pg\">p.100<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kiriyama Ikuto<\/b> “If we interfere with his departure, we can delay the time it takes to reach the designated area. But what would your excuse be if a third party saw the situation? If you are going to interfere, you must refrain from doing…”<span class=\"pg\">p.100<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Mikitani<\/b> “Why don&#x27;t you do a GPS search? Anyway, there are a lot of points to spend. ”<span class=\"pg\">p.100<\/span><\/li><\/ul><details class=\"more\"><summary>14 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “If we interfere with his departure, we can delay the time it takes to reach the designated area. But what would your excuse be if a third party saw the situation? If you are going to interfere, you must refrain from doing something that can be easily recognized. ”<span class=\"pg\">p.100<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Our tablets don&#x27;t know where the teachers are. Do not forget that the search is not absolute. As originally planned, we&#x27;ll be settling in when Kouenji clears the tent and starts moving. If you come across a freshman or sophomore, or an adult on your way to set a task, immediately open a distance of at least two meters from Kouenji.”<span class=\"pg\">p.100<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Do not shorten the distance to the point of making contact.”<span class=\"pg\">p.100<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It&#x27;s on the move, it&#x27;s Kouenji!”<span class=\"pg\">p.101<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Hey, hey!”<span class=\"pg\">p.102<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don&#x27;t be scared, you will hurt yourself if you match Kouenji&#x27;s rhythm.”<span class=\"pg\">p.102<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “This is not the time to relax! We have lost it!”<span class=\"pg\">p.102<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You may get the reward on a first come, first serve basis, but that&#x27;s how far it goes. If Kouenji chooses to flee, he will not be able to take his time to participate in the tasks. On the other hand, if he chooses to participate with impunity in the challenge, we will be able to catch up with him there. ”<span class=\"pg\">p.102<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What is Kouenji&#x27;s position?”<span class=\"pg\">p.103<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;ve looked for it three times, but it hasn&#x27;t moved at all.”<span class=\"pg\">p.103<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Get up, Kouenji! You&#x27;ve been running for more than 10 days, so you took a nap from exhaustion, right?”<span class=\"pg\">p.103<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Hothead — proposes the illegal surround, then a GPS spend, then shouts at the runner; Kiriyama restrains him twice; he chases anyway.<span class=\"pg\">p.100–103<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> He chases; he loses him.<span class=\"pg\">p.100–103<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kiriyama Ikuto<\/b> His handler; reined in at every step.<span class=\"pg\">p.100–103<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-mikitani-y2v4-p95-1\">← Before: Ch.4: Kiriyama&#x27;s spearhead; the Six Free Groups deal<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-mikitani-y2v4-p104-1\">→ After: The E3 English test; the circle forms<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y2v4-p103-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"mikitani kouenji-rokusuke kiriyama-ikuto","q":"kiriyama ikuto ch 4  the sleep revelation  the circle spreads six hours into the chase  kouenji is found asleep in broad daylight by the e3 task site  kiriyama s first doubt arrives when the rem hypersomnia claim reaches him   get up  kouenji  you ve been running for more than 10 days  so you took a nap from exhaustion  right   i m sure you will agree  i am a human being like you     if that s the case  then go ahead and take the rest of the day off  you must be exhausted from all this  you must listen to the kind advice of your elders   take the day off  that s kind of funny   don t  make an effort  if you could get rid of fatigue just with a little rest  no one would have a problem   you certainly look good  but like mikitani said  you ve run for the last 10 days or so with more energy than anyone  there s no question about it  since you ve probably repeatedly ranked first in the order of arrival  but even if you have extraordinary stamina  you should have reached your limit by now   i have a very short dream  i have an extremely low rem phase   the ideal average daily sleep time for a human being is about seven to eight hours  it is said that the ideal amount of sleep is between seven and eight hours a day  because more or less is not enough to maintain good health  however  those who sleep little are those who are predisposed to maintaining good health  even if they sleep less than six hours     it seemed strange to me to sleep in peace  but i suppose that is what there is    by the way  do you still need me   i don t care if you are physically strong or not  shut up    i m not here at all  don t worry about us   you seem quite belligerent when you say that   i m not one to accept advice  kiriyama   it s useless  i ll change my strategy  we will seal the matter  the rem claim breaks the math he ran on kouenji   he still cannot believe a loner can sustain this  orders the circle expanded for the third designated zone window  first impatience arises  his rem secret now terrifies kiriyama  he drops persuasion for containment","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y2v4-p103-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kiriyama-ikuto.html#sc-kiriyama-ikuto-y2v4-p103-1\">Ch.4: The sleep revelation; the circle spreads<\/a><\/span><span class=\"meta\">Y2V4 · p.103–106<\/span><span class=\"by\">notes on <a href=\"../../../people/kiriyama-ikuto.html\">Kiriyama Ikuto<\/a><\/span><\/h3><p class=\"setup\">Six hours into the chase, Kouenji is found asleep in broad daylight by the E3 task site; Kiriyama’s first doubt arrives when the REM hypersomnia claim reaches him.<\/p><p class=\"with\">with <a href=\"../../../people/mikitani.html\">Mikitani<\/a> · <a href=\"../../../people/kouenji-rokusuke.html\">Kōenji Rokusuke<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Mikitani<\/b> “Get up, Kouenji! You&#x27;ve been running for more than 10 days, so you took a nap from exhaustion, right?”<span class=\"pg\">p.103<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kōenji Rokusuke<\/b> “I&#x27;m sure you will agree. I am a human being like you. ”<span class=\"pg\">p.103<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Mikitani<\/b> “If that&#x27;s the case, then go ahead and take the rest of the day off. You must be exhausted from all this. You must listen to the kind advice of your elders.”<span class=\"pg\">p.104<\/span><\/li><\/ul><details class=\"more\"><summary>14 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Take the day off? That&#x27;s kind of funny.”<span class=\"pg\">p.104<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don&#x27;t… make an effort. If you could get rid of fatigue just with a little rest, no one would have a problem.”<span class=\"pg\">p.104<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You certainly look good. But like Mikitani said, you&#x27;ve run for the last 10 days or so with more energy than anyone. There&#x27;s no question about it, since you&#x27;ve probably repeatedly ranked first in the order of arrival. But even if you have extraordinary stamina, you should have reached your limit by now.”<span class=\"pg\">p.104<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I have a very short dream. I have an extremely low REM phase.”<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The ideal average daily sleep time for a human being is about seven to eight hours. It is said that the ideal amount of sleep is between seven and eight hours a day, because more or less is not enough to maintain good health. However, those who sleep little are those who are predisposed to maintaining good health, even if they sleep less than six hours. ”<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It seemed strange to me to sleep in peace, but I suppose that is what there is ...”<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “By the way, do you still need me?”<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t care if you are physically strong or not, shut up ...”<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;m not here at all, don&#x27;t worry about us.”<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You seem quite belligerent when you say that.”<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;m not one to accept advice, Kiriyama.”<span class=\"pg\">p.106<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It&#x27;s useless, I&#x27;ll change my strategy. We will seal the matter.”<span class=\"pg\">p.106<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> The REM claim breaks the math he ran on Kouenji — he still cannot believe a loner can sustain this; orders the circle expanded for the third-designated-zone window; first impatience arises.<span class=\"pg\">p.103–106<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> His REM secret now terrifies Kiriyama; he drops persuasion for containment.<span class=\"pg\">p.103–106<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y2v4-p100-1\">← Before: Ch.4: The morning siege; the departure<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y2v4-p106-1\">→ After: Ch.4: The circle strategy<\/button><\/div><\/article>"},{"i":"sc-kouenji-rokusuke-y2v4-p103-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"mikitani kiriyama-ikuto kouenji-rokusuke","q":"koenji rokusuke ch 4  the nap reveal  the rem claim tracked for six hours  found asleep in broad daylight  wakes laughing  the free groups surround him again at the e3 task site   get up  kouenji  you ve been running for more than 10 days  so you took a nap from exhaustion  right   i m sure you will agree  i am a human being like you     if that s the case  then go ahead and take the rest of the day off  you must be exhausted from all this  you must listen to the kind advice of your elders     take the day off  that s kind of funny     don t  make an effort  if you could get rid of fatigue just with a little rest  no one would have a problem     you certainly look good  but like mikitani said  you ve run for the last 10 days or so with more energy than anyone   i think that if you are reaching your limit  you are not in the realm of normal people   i have a very short dream  i have an extremely low rem phase     what  what is that rem phase  huh      mikitani  kiriyama s realization  kouenji s  very short dream  claim means the sleep math he ran is broken  kouenji poses the question of whether he is even needed   by the way  do you still need me   i don t care if you are physically strong or not  shut up    i m not here at all  don t worry about us   you seem quite belligerent when you say that   i m not one to accept advice  kiriyama   it may be true   it s useless  i ll change my strategy  we will seal the matter    reveals an extremely short rem sleep phase   inexhaustible stamina  sleeps on demand mid exam  the siege loses its math  the voice of the siege  he baits kouenji with rest and gets nowhere  his composure finally cracks   first impatience","h":"<article class=\"card\" id=\"sc-kouenji-rokusuke-y2v4-p103-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kouenji-rokusuke.html#sc-kouenji-rokusuke-y2v4-p103-1\">Ch.4: The nap reveal; the REM claim<\/a><\/span><span class=\"meta\">Y2V4 · p.103–106<\/span><span class=\"by\">notes on <a href=\"../../../people/kouenji-rokusuke.html\">Kōenji Rokusuke<\/a><\/span><\/h3><p class=\"setup\">Tracked for six hours; found asleep in broad daylight; wakes laughing; the Free Groups surround him again at the E3 task site.<\/p><p class=\"with\">with <a href=\"../../../people/mikitani.html\">Mikitani<\/a> · <a href=\"../../../people/kiriyama-ikuto.html\">Kiriyama Ikuto<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Mikitani<\/b> “Get up, Kouenji! You&#x27;ve been running for more than 10 days, so you took a nap from exhaustion, right?”<span class=\"pg\">p.103<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kōenji Rokusuke<\/b> “I&#x27;m sure you will agree. I am a human being like you. ”<span class=\"pg\">p.103<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Mikitani<\/b> “If that&#x27;s the case, then go ahead and take the rest of the day off. You must be exhausted from all this. You must listen to the kind advice of your elders. ”<span class=\"pg\">p.104<\/span><\/li><\/ul><details class=\"more\"><summary>17 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Take the day off? That&#x27;s kind of funny. ”<span class=\"pg\">p.104<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don&#x27;t… make an effort. If you could get rid of fatigue just with a little rest, no one would have a problem. ”<span class=\"pg\">p.104<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You certainly look good. But like Mikitani said, you&#x27;ve run for the last 10 days or so with more energy than anyone.”<span class=\"pg\">p.104<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I think that if you are reaching your limit, you are not in the realm of normal people.”<span class=\"pg\">p.104<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I have a very short dream. I have an extremely low REM phase. ”<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What? What is that REM phase, huh? ” — Mikitani.<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Kiriyama&#x27;s realization: Kouenji&#x27;s “very short dream” claim means the sleep-math he ran is broken; Kouenji poses the question of whether he is even needed.<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “By the way, do you still need me?”<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t care if you are physically strong or not, shut up ...”<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;m not here at all, don&#x27;t worry about us.”<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You seem quite belligerent when you say that.”<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;m not one to accept advice, Kiriyama.”<span class=\"pg\">p.106<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It may be true.”<span class=\"pg\">p.106<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It&#x27;s useless, I&#x27;ll change my strategy. We will seal the matter. ”<span class=\"pg\">p.106<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Reveals an extremely short REM sleep phase — inexhaustible stamina; sleeps on demand mid-exam; the siege loses its math.<span class=\"pg\">p.103–106<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Mikitani<\/b> The voice of the siege; he baits Kouenji with rest and gets nowhere.<span class=\"pg\">p.103–106<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kiriyama Ikuto<\/b> His composure finally cracks — first impatience.<span class=\"pg\">p.103–106<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kouenji-rokusuke-y2v4-p99-1\">← Before: Ch.4: Surrounded at dawn; he simply bolts<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kouenji-rokusuke-y2v4-p106-1\">→ After: Ch.4: The E3 English test; the circle closes<\/button><\/div><\/article>"},{"i":"sc-mikitani-y2v4-p104-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"kouenji-rokusuke kiriyama-ikuto dodo-michimichi mikitani","q":"mikitani the e3 english test  the circle forms  if that s the case  then go ahead and take the rest of the day off  you must be exhausted from all this  you must listen to the kind advice of your elders     take the day off  that s kind of funny     don t  make an effort  if you could get rid of fatigue just with a little rest  no one would have a problem     you certainly look good  but like mikitani said  you ve run for the last 10 days or so with more energy than anyone  there s no question about it  since you ve probably repeatedly ranked first in the order of arrival  but even if you have extraordinary stamina  you should have reached your limit by now     i think that if you are reaching your limit  you are not in the realm of normal people   i have a very short dream  i have an extremely low rem phase     what  what is that rem phase  huh     i don t care if you are physically strong or not  shut up    tch     i m the one in charge now  don t interrupt the circle  mikitani     kouenji  don t be so harsh   well  well  they re getting noisy  so  let me pick up the pace a bit   don t let him get away this time  surround him   no way  no way  no way    chase him  don t let him escape   wait  mikitani  don t act on your own   shut  i won t let him get away twice  catch him and drag him    breaks discipline to chase  is ordered back  dodo takes the e3 english task  kouenji second with 4 points  his pride as part of the circle collapses  his rebellion costs the siege its best shot  dodo took the e3 english task first  kouenji only second  he outpaces them by sprint  the e3 task is the best they get","h":"<article class=\"card\" id=\"sc-mikitani-y2v4-p104-1\"><h3><span class=\"ttl\"><a href=\"../../../people/mikitani.html#sc-mikitani-y2v4-p104-1\">The E3 English test; the circle forms<\/a><\/span><span class=\"meta\">Y2V4 · p.104–108<\/span><span class=\"by\">notes on <a href=\"../../../people/mikitani.html\">Mikitani<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/kouenji-rokusuke.html\">Kōenji Rokusuke<\/a> · <a href=\"../../../people/kiriyama-ikuto.html\">Kiriyama Ikuto<\/a> · <a href=\"../../../people/index.html#dodo-michimichi\">Dodo Michimichi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Mikitani<\/b> “If that&#x27;s the case, then go ahead and take the rest of the day off. You must be exhausted from all this. You must listen to the kind advice of your elders. ”<span class=\"pg\">p.104<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kōenji Rokusuke<\/b> “Take the day off? That&#x27;s kind of funny. ”<span class=\"pg\">p.104<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Mikitani<\/b> “Don&#x27;t… make an effort. If you could get rid of fatigue just with a little rest, no one would have a problem. ”<span class=\"pg\">p.104<\/span><\/li><\/ul><details class=\"more\"><summary>18 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “You certainly look good. But like Mikitani said, you&#x27;ve run for the last 10 days or so with more energy than anyone. There&#x27;s no question about it, since you&#x27;ve probably repeatedly ranked first in the order of arrival. But even if you have extraordinary stamina, you should have reached your limit by now. ”<span class=\"pg\">p.104<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I think that if you are reaching your limit, you are not in the realm of normal people.”<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I have a very short dream. I have an extremely low REM phase. ”<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What? What is that REM phase, huh? ”<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t care if you are physically strong or not, shut up ...”<span class=\"pg\">p.106<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Tch, ...”<span class=\"pg\">p.106<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;m the one in charge now. Don&#x27;t interrupt the circle, Mikitani. ”<span class=\"pg\">p.106<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Kouenji! Don&#x27;t be so harsh!”<span class=\"pg\">p.107<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, well, they&#x27;re getting noisy. So, let me pick up the pace a bit.”<span class=\"pg\">p.107<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don&#x27;t let him get away this time! Surround him!”<span class=\"pg\">p.107<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No way, no way, no way ...”<span class=\"pg\">p.107<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Chase him! Don&#x27;t let him escape!”<span class=\"pg\">p.107<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Wait, Mikitani, don&#x27;t act on your own!”<span class=\"pg\">p.107<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Shut! I won&#x27;t let him get away twice! Catch him and drag him! ”<span class=\"pg\">p.107<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Breaks discipline to chase; is ordered back; Dodo takes the E3 English task; Kouenji second with 4 points; his pride as part of the circle collapses.<span class=\"pg\">p.104–108<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kiriyama Ikuto<\/b> His rebellion costs the siege its best shot.<span class=\"pg\">p.104–108<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Dodo Michimichi<\/b> Dodo took the E3 English task first; Kouenji only second.<span class=\"pg\">p.108<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> He outpaces them by sprint; the E3 task is the best they get.<span class=\"pg\">p.103–108<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-mikitani-y2v4-p100-1\">← Before: The tent watch; the run<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-mikitani-y2v4-p109-1\">→ After: The end of the plan<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y2v4-p106-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"mikitani kouenji-rokusuke nagumo-miyabi kiriyama-ikuto","q":"kiriyama ikuto ch 4  the circle strategy the third designated zone is announced  kouenji walks off mid threat  kiriyama orders the 18 person circle spread wide  the e3 english task is one person and 8 points  dodo michimichi takes first  kouenji second with four points  the circle quietly fails to stop him even once   i m the one in charge now  don t interrupt the circle  mikitani   kouenji  don t be so harsh   well  well  they re getting noisy  so  let me pick up the pace a bit   shut  i won t let him get away twice  catch him and drag him   do not lose sight that the target is kouenji   there is a task at e3 that kouenji can participate in  but the reward is 8 points for first place or    this is your last warning  kouenji   only tomorrow  take our advice and stay put  that s it   if we can keep him at bay for a day  nagumo will be able to escape with the safe first place  the important thing is not to let kouenji take the top spot again   if we can keep him at bay for a day  nagumo will be able to escape with the safe first place  tactical flailing   the circle  the task blocking  all failures  his pride as a third year breaks  the teachers signal but the siege continues  he settles on two days of containment with nagumo s safe first as the prize  the e3 english task   dodo first  kouenji second with 4 points  the siege wins nothing  keep kouenji contained two days  nagumo s safe first is the goal now","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y2v4-p106-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kiriyama-ikuto.html#sc-kiriyama-ikuto-y2v4-p106-1\">Ch.4: The circle strategy<\/a><\/span><span class=\"meta\">Y2V4 · p.106–110<\/span><span class=\"by\">notes on <a href=\"../../../people/kiriyama-ikuto.html\">Kiriyama Ikuto<\/a><\/span><\/h3><p class=\"setup\">The third-designated zone is announced; Kouenji walks off mid-threat; Kiriyama orders the 18-person circle spread wide; the E3 English task is one-person and 8 points; Dodo Michimichi takes first, Kouenji second with four points; the circle quietly fails to stop him even once.<\/p><p class=\"with\">with <a href=\"../../../people/mikitani.html\">Mikitani<\/a> · <a href=\"../../../people/kouenji-rokusuke.html\">Kōenji Rokusuke<\/a> · <a href=\"../../../people/nagumo-miyabi.html\">Nagumo Miyabi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Kiriyama Ikuto<\/b> “I&#x27;m the one in charge now. Don&#x27;t interrupt the circle, Mikitani.”<span class=\"pg\">p.106<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Mikitani<\/b> “Kouenji! Don&#x27;t be so harsh!”<span class=\"pg\">p.107<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kōenji Rokusuke<\/b> “Well, well, they&#x27;re getting noisy. So, let me pick up the pace a bit.”<span class=\"pg\">p.107<\/span><\/li><\/ul><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Shut! I won&#x27;t let him get away twice! Catch him and drag him!”<span class=\"pg\">p.107<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Do not lose sight that the target is Kouenji.”<span class=\"pg\">p.107<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There is a task at E3 that Kouenji can participate in. But the reward is 8 points for first place or ...”<span class=\"pg\">p.108<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “This is your last warning, Kouenji.”<span class=\"pg\">p.109<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Only tomorrow. Take our advice and stay put. That&#x27;s it.”<span class=\"pg\">p.109<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If we can keep him at bay for a day, Nagumo will be able to escape with the safe first place. The important thing is not to let Kouenji take the top spot again.”<span class=\"pg\">p.109<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If we can keep him at bay for a day, Nagumo will be able to escape with the safe first place.”<span class=\"pg\">p.110<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Tactical flailing — the circle, the task-blocking, all failures; his pride as a third-year breaks; the teachers signal but the siege continues; he settles on two days of containment with Nagumo’s safe first as the prize.<span class=\"pg\">p.106–110<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> The E3 English task — Dodo first, Kouenji second with 4 points; the siege wins nothing.<span class=\"pg\">p.106–110<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> Keep Kouenji contained two days; Nagumo’s safe first is the goal now.<span class=\"pg\">p.109–110<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y2v4-p103-1\">← Before: Ch.4: The sleep revelation; the circle spreads<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y2v4-p110-1\">→ After: Ch.4: The walk-through; the plan that failed<\/button><\/div><\/article>"},{"i":"sc-kouenji-rokusuke-y2v4-p106-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"kiriyama-ikuto mikitani dodo-michimichi kouenji-rokusuke","q":"koenji rokusuke ch 4  the e3 english test  the circle closes the third designated zone is announced  kouenji walks off amid threats  18 third years form a circle  the e3 english test   8 points for first   opens at the task site  dodo takes first  kouenji second with 4 points   i m the one in charge now  don t interrupt the circle  mikitani     kouenji  don t be so harsh   well  well  they re getting noisy  so  let me pick up the pace a bit   don t let him get away this time  surround him   no way  no way  no way    chase him  don t let him escape   wait  mikitani  don t act on your own   shut  i won t let him get away twice  catch him and drag him    the task was an english test  content grades 1 3 alike  dodo michimichi  one of the most gifted third year students  took first  kouenji came in a close second and was awarded four points   they sure are working very hard     we cannot pretend to be something we are not    printed untagged  kiriyama or mikitani  not assigned   this is your last warning  kouenji   are you asking me for a favor   no  it s an order   it is a request that i cannot ignore  but what happens if i refuse   in the worst case  you will be expelled    mikitani   i don t obey anyone   then i will make you obey me  you understand  kouenji  right kiriyama     as long as kouenji obeys  i will leave it up to you  seals the one person english test with dodo s first place  kouenji s 4 points fall one short of first prize  he refuses  order  and fights alone  dodo took the e3 test  kouenji only second  his containment contains nothing  the circle is the only wall left","h":"<article class=\"card\" id=\"sc-kouenji-rokusuke-y2v4-p106-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kouenji-rokusuke.html#sc-kouenji-rokusuke-y2v4-p106-1\">Ch.4: The E3 English test; the circle closes<\/a><\/span><span class=\"meta\">Y2V4 · p.106–110<\/span><span class=\"by\">notes on <a href=\"../../../people/kouenji-rokusuke.html\">Kōenji Rokusuke<\/a><\/span><\/h3><p class=\"setup\">The third-designated zone is announced; Kouenji walks off amid threats; 18 third-years form a circle; the E3 English test — 8 points for first — opens at the task site; Dodo takes first, Kouenji second with 4 points.<\/p><p class=\"with\">with <a href=\"../../../people/kiriyama-ikuto.html\">Kiriyama Ikuto<\/a> · <a href=\"../../../people/mikitani.html\">Mikitani<\/a> · <a href=\"../../../people/index.html#dodo-michimichi\">Dodo Michimichi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Kiriyama Ikuto<\/b> “I&#x27;m the one in charge now. Don&#x27;t interrupt the circle, Mikitani. ”<span class=\"pg\">p.106<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Mikitani<\/b> “Kouenji! Don&#x27;t be so harsh!”<span class=\"pg\">p.107<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kōenji Rokusuke<\/b> “Well, well, they&#x27;re getting noisy. So, let me pick up the pace a bit.”<span class=\"pg\">p.107<\/span><\/li><\/ul><details class=\"more\"><summary>18 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Don&#x27;t let him get away this time! Surround him!”<span class=\"pg\">p.107<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No way, no way, no way ...”<span class=\"pg\">p.107<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Chase him! Don&#x27;t let him escape!”<span class=\"pg\">p.107<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Wait, Mikitani, don&#x27;t act on your own!”<span class=\"pg\">p.107<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Shut! I won&#x27;t let him get away twice! Catch him and drag him! ”<span class=\"pg\">p.107<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The task was an English test, content grades 1–3 alike; Dodo Michimichi, one of the most gifted third-year students, took first; Kouenji came in a close second and was awarded four points.<span class=\"pg\">p.108<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “They sure are working very hard.” / “We cannot pretend to be something we are not” — printed untagged; Kiriyama or Mikitani; not assigned.<span class=\"pg\">p.109<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “This is your last warning, Kouenji.”<span class=\"pg\">p.109<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Are you asking me for a favor?”<span class=\"pg\">p.110<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No, it&#x27;s an order.”<span class=\"pg\">p.110<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It is a request that I cannot ignore, but what happens if I refuse?”<span class=\"pg\">p.110<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “In the worst case, you will be expelled.” — Mikitani.<span class=\"pg\">p.110<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t obey anyone.”<span class=\"pg\">p.110<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Then I will make you obey me. You understand, Kouenji? Right…Kiriyama. ”<span class=\"pg\">p.110<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “As long as Kouenji obeys, I will leave it up to you.”<span class=\"pg\">p.110<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Seals the one-person English test with Dodo&#x27;s first place; Kouenji&#x27;s 4 points fall one short of first prize; he refuses “order” and fights alone.<span class=\"pg\">p.106–110<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Dodo Michimichi<\/b> Dodo took the E3 test; Kouenji only second.<span class=\"pg\">p.108<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kiriyama Ikuto<\/b> His containment contains nothing; the circle is the only wall left.<span class=\"pg\">p.106–110<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kouenji-rokusuke-y2v4-p103-1\">← Before: Ch.4: The nap reveal; the REM claim<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kouenji-rokusuke-y2v4-p111-1\">→ After: Ch.4: The walk-through<\/button><\/div><\/article>"},{"i":"sc-dodo-michimichi-y2v4-p108-1","v":"y2v4","y":2,"o":19,"k":"","w":"kouenji-rokusuke dodo-michimichi","q":"dodo michimichi dodo  first place in the e3 english task dodo michimichi  one of the most gifted third year students  takes first place in the exam s english test at e3  open to all grades at the same content level  while the third years  encirclement closes on koenji around him  the task was an english test  there were participants in grades one through three  the content level was the same across grades  the result was that dodo michimichi  one of the most gifted third year students  took first place  but kouenji came in a close second  and was awarded four points  the third years  best   a gifted english talent  even under the third years  siege he quietly takes the e3 test prize while koenji waits in second  outscored him by a narrow margin in the english test","h":"<article class=\"card\" id=\"sc-dodo-michimichi-y2v4-p108-1\"><h3><span class=\"ttl\">Dodo: first place in the E3 English task<\/span><span class=\"meta\">Y2V4 · p.108<\/span><span class=\"by\">notes on <a href=\"../../../people/index.html#dodo-michimichi\">Dodo Michimichi<\/a><\/span><\/h3><p class=\"setup\">Dodo Michimichi, one of the most gifted third-year students, takes first place in the exam&#x27;s English test at E3 (open to all grades at the same content level) while the third-years&#x27; encirclement closes on Kōenji around him.<\/p><p class=\"with\">with <a href=\"../../../people/kouenji-rokusuke.html\">Kōenji Rokusuke<\/a><\/p><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> The task was an English test; there were participants in grades one through three; the content level was the same across grades.<span class=\"pg\">p.108<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The result was that Dodo Michimichi, one of the most gifted third-year students, took first place, but Kouenji came in a close second, and was awarded four points.<span class=\"pg\">p.108<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> The third-years&#x27; best — a gifted English talent; even under the third-years&#x27; siege he quietly takes the E3 test prize while Kōenji waits in second.<span class=\"pg\">p.108<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> Outscored him by a narrow margin in the English test.<span class=\"pg\">p.108<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-mikitani-y2v4-p109-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"kiriyama-ikuto kouenji-rokusuke morooka mikitani","q":"mikitani the end of the plan  this is your last warning  kouenji   only tomorrow  take our advice and stay put  that s it   oh hey  nagumo wants us to keep him for two days    we should do it tomorrow and the day after tomorrow   the day after tomorrow  we will no longer be able to see the groups in the lead  i don t think there is any group that is going to come after us strongly  but we should concentrate on improving our own score instead of retaining the others     it is impossible for him to accept defeat   it depends on how you do it    do you think you can do it   i can do it  if i can do it  i ll get a ticket for class a     i m sure you heard us  i m going to ask you to stay here tomorrow and the next day     are you asking me for a favor   no  it s an order   it is a request that i cannot ignore  but what happens if i refuse   in the worst case  you will be expelled   i don t obey anyone   then i will make you obey me  you understand  kouenji  right kiriyama     i have told you  i told you to stay put     it is not a pretty situation  i don t like male sexuality     what would you do  if you try to push me away  i will take it as a declaration of war     oh i see   hey  wait   what  i think i have broken my arm     you have done something terrible  kouenji    printed untagged  mikitani or kiriyama  not assigned   you sound like a hit man   no matter what you say  it doesn t change the fact that you pushed morooka away    printed untagged  mikitani or kiriyama  not assigned   it seems that you are willing to hit us  your senpai  but if you did  you d be in big trouble right      printed untagged  mikitani or kiriyama  not assigned   you can not touch me   i have no intention of showing mercy to those who prevent me from moving forward  much less turning against me   what if we report it to the school   what s going to happen  or is it just going to be a stain on the name of the third year students who tried to sink a lone kouhai   i don t need to confirm that mikitani s watch is working properly  otherwise  they would not have been able to enter the challenge ahead of kouenji     it was about time  right  your group has put a damper on my chances of earning the order rewards     i m sorry  but you re not going to   go   i can t be nice to you all the time   does that mean you re going to turn against me   didn t you  mikitani  you really want to do it    ah  if that s the case  i ll go down with kouenji in my arms  let s do it     hey  hey  watch out   you too   it s not nice that you always follow me  it s not nice to have a dead leaf slapping my cheek over and over again     are you okay  mikitani   oh yeah  i m not hurt   even if i have to drop the reward for reaching the designated area  here i will nip the counterattack of third year students in the bud   now if you ll excuse me  bye   what the hell is that guy  is he really in high school   there is always someone who does not agree with your calculations  like nagumo   in the end  the only thing we can do is crawl on the ground like this forever   that monster of youth  he even made me look like an idiot  he made me look like an idiot  shit  shit   are you going to report my failure to nagumo   what do i win  i m someone who has already decided to win  don t worry  miki  i ve already assumed from the beginning that kouenji is out of this world  but there is always one weakness in every opponent  you know what they say  big is better than small    he hears the order or expelled line  takes the fall with three others  collapses head on with kouenji s groupmates  walks away asking  what the hell is that guy  is he really in high school  hits the ground with a fist  left wondering why nagumo even bothered  his plan fails  he never tattles  kiriyama covers for him  he fails to block him  broken spirited by skill without touching him","h":"<article class=\"card\" id=\"sc-mikitani-y2v4-p109-1\"><h3><span class=\"ttl\"><a href=\"../../../people/mikitani.html#sc-mikitani-y2v4-p109-1\">The end of the plan<\/a><\/span><span class=\"meta\">Y2V4 · p.109–115<\/span><span class=\"by\">notes on <a href=\"../../../people/mikitani.html\">Mikitani<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/kiriyama-ikuto.html\">Kiriyama Ikuto<\/a> · <a href=\"../../../people/kouenji-rokusuke.html\">Kōenji Rokusuke<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Kiriyama Ikuto<\/b> “This is your last warning, Kouenji.”<span class=\"pg\">p.109<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kiriyama Ikuto<\/b> “Only tomorrow. Take our advice and stay put. That&#x27;s it.”<span class=\"pg\">p.109<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Mikitani<\/b> “Oh hey, Nagumo wants us to keep him for two days. ......!? We should do it tomorrow and the day after tomorrow?”<span class=\"pg\">p.109<\/span><\/li><\/ul><details class=\"more\"><summary>49 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “The day after tomorrow, we will no longer be able to see the groups in the lead. I don&#x27;t think there is any group that is going to come after us strongly, but we should concentrate on improving our own score instead of retaining the others. ”<span class=\"pg\">p.109<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It is impossible for him to accept defeat”<span class=\"pg\">p.110<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It depends on how you do it.”<span class=\"pg\">p.110<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “… Do you think you can do it?”<span class=\"pg\">p.110<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I can do it. If I can do it, I&#x27;ll get a ticket for class A. ”<span class=\"pg\">p.110<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;m sure you heard us. I&#x27;m going to ask you to stay here tomorrow and the next day. ”<span class=\"pg\">p.110<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Are you asking me for a favor?”<span class=\"pg\">p.110<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No, it&#x27;s an order.”<span class=\"pg\">p.110<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It is a request that I cannot ignore, but what happens if I refuse?”<span class=\"pg\">p.110<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “In the worst case, you will be expelled.”<span class=\"pg\">p.110<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t obey anyone.”<span class=\"pg\">p.110<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Then I will make you obey me. You understand, Kouenji? Right…Kiriyama. ”<span class=\"pg\">p.110<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I have told you. I told you to stay put. ”<span class=\"pg\">p.110<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It is not a pretty situation. I don&#x27;t like male sexuality. ”<span class=\"pg\">p.111<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What would you do? If you try to push me away, I will take it as a declaration of war. ”<span class=\"pg\">p.111<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Oh I see.”<span class=\"pg\">p.111<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Hey, wait!”<span class=\"pg\">p.111<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What? I think I have broken my arm! ”<span class=\"pg\">p.111<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “You have done something terrible, Kouenji.” — printed untagged; Mikitani or Kiriyama; not assigned.<span class=\"pg\">p.112<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You sound like a hit man.”<span class=\"pg\">p.112<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “No matter what you say, it doesn&#x27;t change the fact that you pushed Morooka away.” — printed untagged; Mikitani or Kiriyama; not assigned.<span class=\"pg\">p.112<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “It seems that you are willing to hit us, your senpai. But if you did, you&#x27;d be in big trouble right? ” — printed untagged; Mikitani or Kiriyama; not assigned.<span class=\"pg\">p.112<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You can not touch me.”<span class=\"pg\">p.112<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I have no intention of showing mercy to those who prevent me from moving forward, much less turning against me.”<span class=\"pg\">p.112<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What if we report it to the school?”<span class=\"pg\">p.112<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What&#x27;s going to happen, or is it just going to be a stain on the name of the third year students who tried to sink a lone kouhai?”<span class=\"pg\">p.112<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t need to confirm that Mikitani&#x27;s watch is working properly. Otherwise, they would not have been able to enter the challenge ahead of Kouenji. ”<span class=\"pg\">p.112<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It was about time, right? Your group has put a damper on my chances of earning the order rewards. ”<span class=\"pg\">p.112<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;m sorry, but you&#x27;re not going to …… go.”<span class=\"pg\">p.112<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I can&#x27;t be nice to you all the time.”<span class=\"pg\">p.113<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Does that mean you&#x27;re going to turn against me?”<span class=\"pg\">p.113<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Didn&#x27;t you, Mikitani? You really want to do it.”<span class=\"pg\">p.113<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “… Ah. If that&#x27;s the case, I&#x27;ll go down with Kouenji in my arms. Let&#x27;s do it! ”<span class=\"pg\">p.113<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Hey, hey, watch out!”<span class=\"pg\">p.113<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You too!”<span class=\"pg\">p.113<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It&#x27;s not nice that you always follow me. It&#x27;s not nice to have a dead leaf slapping my cheek over and over again. ”<span class=\"pg\">p.114<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Are you okay, Mikitani?”<span class=\"pg\">p.114<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Oh yeah. I&#x27;m not hurt.”<span class=\"pg\">p.114<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Even if I have to drop the reward for reaching the designated area, here I will nip the counterattack of third year students in the bud.”<span class=\"pg\">p.114<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Now if you&#x27;ll excuse me. Bye.”<span class=\"pg\">p.115<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What the hell is that guy? Is he really in high school?”<span class=\"pg\">p.115<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There is always someone who does not agree with your calculations. Like Nagumo.”<span class=\"pg\">p.115<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “In the end, the only thing we can do is crawl on the ground like this forever?”<span class=\"pg\">p.115<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That monster of youth! He even made me look like an idiot! He made me look like an idiot! Shit! Shit!”<span class=\"pg\">p.115<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Are you going to report my failure to Nagumo?”<span class=\"pg\">p.115<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What do I win? I&#x27;m someone who has already decided to win. Don&#x27;t worry, Miki, I&#x27;ve already assumed from the beginning that Kouenji is out of this world. But there is always one weakness in every opponent. You know what they say, big is better than small. ”<span class=\"pg\">p.115<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> He hears the order-or-expelled line; takes the fall with three others; collapses head-on with Kouenji&#x27;s groupmates; walks away asking “What the hell is that guy? Is he really in high school?”; hits the ground with a fist; left wondering why Nagumo even bothered.<span class=\"pg\">p.109–115<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kiriyama Ikuto<\/b> His plan fails; he never tattles; Kiriyama covers for him.<span class=\"pg\">p.109–115<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> He fails to block him; broken spirited by skill without touching him.<span class=\"pg\">p.109–115<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-mikitani-y2v4-p104-1\">← Before: The E3 English test; the circle forms<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-mikitani-y2v4-p279-1\">→ After: Mikitani expelled with the third-years<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y2v4-p110-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"kouenji-rokusuke mikitani morooka nagumo-miyabi kiriyama-ikuto","q":"kiriyama ikuto ch 4  the walk through  the plan that failed at the last designated zone  kouenji is ordered to stay  mikitani grabs him  he simply walks through the circle   morooka breaks his arm on contact  kouenji doesn t even break stride   i m sure you heard us  i m going to ask you to stay here tomorrow and the next day   are you asking me for a favor   no  it s an order   it is a request that i cannot ignore  but what happens if i refuse   in the worst case  you will be expelled   i don t obey anyone   then i will make you obey me  you understand  kouenji  right kiriyama    mikitani   as long as kouenji obeys  i will leave it up to you   it is not a pretty situation  i don t like male sexuality   what would you do  if you try to push me away  i will take it as a declaration of war   oh i see  it was as if a large rock was slowly crashing into mikitani  and before he knew it  he was forced to move to the side to give way   what  i think i have broken my arm    morooka  not rostered   no matter what you say  it doesn t change the fact that you pushed morooka away    printed untagged  mikitani or kiriyama  not assigned   i have no intention of showing mercy to those who prevent me from moving forward  much less turning against me    ah  if that s the case  i ll go down with kouenji in my arms  let s do it   it s not nice that you always follow me  it s not nice to have a dead leaf slapping my cheek over and over again   i see  it is true that the current mikitani was prepared to go after you until the end  if he was shown such an overwhelming skill difference  his spirit would be broken  but you are the only one who can devise and perform the trick of breaking your opponent s heart without counterattacking    kiriyama s read of kouenji   even if i have to drop the reward for reaching the designated area  here i will nip the counterattack of third year students in the bud   i ll go then  if it s okay with you   now if you ll excuse me  bye   do what you want  kouenji   there is always someone who does not agree with your calculations  like nagumo  the siege fails completely   his own named plan collapses in 15 minutes of walking  morooka s arm is broken  kiriyama s final analysis is not panic  the design was deliberate   make kouenji think the third years are nothing  so he walks out feeling no threat  the  big is better than small  hint is his next lever  the containment plan collapses in 15 minutes  kouenji walks out untouched  the spearhead breaks first  his disappointment  kiriyama s counter plot is revealed to himself   weaken kouenji s threat perception  not his score","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y2v4-p110-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kiriyama-ikuto.html#sc-kiriyama-ikuto-y2v4-p110-1\">Ch.4: The walk-through; the plan that failed<\/a><\/span><span class=\"meta\">Y2V4 · p.110–115<\/span><span class=\"by\">notes on <a href=\"../../../people/kiriyama-ikuto.html\">Kiriyama Ikuto<\/a><\/span><\/h3><p class=\"setup\">At the last designated zone, Kouenji is ordered to stay; Mikitani grabs him; he simply walks through the circle — Morooka breaks his arm on contact; Kouenji doesn’t even break stride.<\/p><p class=\"with\">with <a href=\"../../../people/kouenji-rokusuke.html\">Kōenji Rokusuke<\/a> · <a href=\"../../../people/mikitani.html\">Mikitani<\/a> · <a href=\"../../../people/nagumo-miyabi.html\">Nagumo Miyabi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Kiriyama Ikuto<\/b> “I&#x27;m sure you heard us. I&#x27;m going to ask you to stay here tomorrow and the next day.”<span class=\"pg\">p.110<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kōenji Rokusuke<\/b> “Are you asking me for a favor?”<span class=\"pg\">p.110<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kiriyama Ikuto<\/b> “No, it&#x27;s an order.”<span class=\"pg\">p.110<\/span><\/li><\/ul><details class=\"more\"><summary>24 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “It is a request that I cannot ignore, but what happens if I refuse?”<span class=\"pg\">p.110<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “In the worst case, you will be expelled.”<span class=\"pg\">p.110<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t obey anyone.”<span class=\"pg\">p.110<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Then I will make you obey me. You understand, Kouenji? Right…Kiriyama.” — Mikitani.<span class=\"pg\">p.111<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “As long as Kouenji obeys, I will leave it up to you.”<span class=\"pg\">p.110<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It is not a pretty situation. I don&#x27;t like male sexuality.”<span class=\"pg\">p.111<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What would you do? If you try to push me away, I will take it as a declaration of war.”<span class=\"pg\">p.111<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Oh I see.”<span class=\"pg\">p.111<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> It was as if a large rock was slowly crashing into Mikitani, and before he knew it, he was forced to move to the side to give way.<span class=\"pg\">p.111<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What? I think I have broken my arm!” — Morooka (not rostered).<span class=\"pg\">p.111<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “No matter what you say, it doesn&#x27;t change the fact that you pushed Morooka away.” — printed untagged; Mikitani or Kiriyama; not assigned.<span class=\"pg\">p.112<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I have no intention of showing mercy to those who prevent me from moving forward, much less turning against me.”<span class=\"pg\">p.112<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “… Ah. If that&#x27;s the case, I&#x27;ll go down with Kouenji in my arms. Let&#x27;s do it!”<span class=\"pg\">p.113<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It&#x27;s not nice that you always follow me. It&#x27;s not nice to have a dead leaf slapping my cheek over and over again.”<span class=\"pg\">p.114<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I see. It is true that the current Mikitani was prepared to go after you until the end. If he was shown such an overwhelming skill difference, his spirit would be broken. But you are the only one who can devise and perform the trick of breaking your opponent&#x27;s heart without counterattacking.” — Kiriyama’s read of Kouenji.<span class=\"pg\">p.114<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Even if I have to drop the reward for reaching the designated area, here I will nip the counterattack of third year students in the bud.”<span class=\"pg\">p.114<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;ll go then, if it&#x27;s okay with you.”<span class=\"pg\">p.114<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Now if you&#x27;ll excuse me. Bye.”<span class=\"pg\">p.115<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Do what you want, Kouenji.”<span class=\"pg\">p.115<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There is always someone who does not agree with your calculations. Like Nagumo.”<span class=\"pg\">p.115<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> The siege fails completely — his own named plan collapses in 15 minutes of walking; Morooka’s arm is broken; Kiriyama’s final analysis is not panic: the design was deliberate — make Kouenji think the third-years are nothing, so he walks out feeling no threat; the “big is better than small” hint is his next lever.<span class=\"pg\">p.110–115<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> The containment plan collapses in 15 minutes; Kouenji walks out untouched.<span class=\"pg\">p.110–115<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Mikitani<\/b> The spearhead breaks first.<span class=\"pg\">p.110–115<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> His disappointment; Kiriyama’s counter-plot is revealed to himself — weaken Kouenji’s threat perception, not his score.<span class=\"pg\">p.109–115<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y2v4-p106-1\">← Before: Ch.4: The circle strategy<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y2v4-p207-1\">→ After: Kiriyama mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-kouenji-rokusuke-y2v4-p111-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"mikitani morooka kiriyama-ikuto kouenji-rokusuke","q":"koenji rokusuke ch 4  the walk through at the last designated zone  kouenji slowly spreads his arms and starts walking through the 18 person circle  morooka breaks his arm on collision  kouenji doesn t pause   it is not a pretty situation  i don t like male sexuality     what would you do  if you try to push me away  i will take it as a declaration of war     oh i see   what  i think i have broken my arm     you have done something terrible  kouenji    printed untagged  mikitani or kiriyama  not assigned   you sound like a hit man    kouenji   no matter what you say  it doesn t change the fact that you pushed morooka away    printed untagged  mikitani or kiriyama  not assigned   it seems that you are willing to hit us  your senpai  but if you did  you d be in big trouble right      printed untagged  mikitani or kiriyama  not assigned   you can not touch me   i have no intention of showing mercy to those who prevent me from moving forward  much less turning against me   what if we report it to the school   what s going to happen  or is it just going to be a stain on the name of the third year students who tried to sink a lone kouhai   i can t be nice to you all the time   does that mean you re going to turn against me   didn t you  mikitani  you really want to do it    ah  if that s the case  i ll go down with kouenji in my arms  let s do it     it s not nice that you always follow me  it s not nice to have a dead leaf slapping my cheek over and over again     are you okay  mikitani   even if i have to drop the reward for reaching the designated area  here i will nip the counterattack of third year students in the bud   are you going to report my failure to nagumo   now if you ll excuse me  bye  breaks the encirclement without raising a hand   morooka s arm is broken  everyone else s spirits are broken  he leaves with the designated area reward dropped  kiriyama s plan fails  his siege plan collapses in 15 minutes  kiriyama concedes the match  the spearhead breaks first  morooka is hospitalized","h":"<article class=\"card\" id=\"sc-kouenji-rokusuke-y2v4-p111-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kouenji-rokusuke.html#sc-kouenji-rokusuke-y2v4-p111-1\">Ch.4: The walk-through<\/a><\/span><span class=\"meta\">Y2V4 · p.111–115<\/span><span class=\"by\">notes on <a href=\"../../../people/kouenji-rokusuke.html\">Kōenji Rokusuke<\/a><\/span><\/h3><p class=\"setup\">At the last designated zone, Kouenji slowly spreads his arms and starts walking through the 18-person circle; Morooka breaks his arm on collision; Kouenji doesn&#x27;t pause.<\/p><p class=\"with\">with <a href=\"../../../people/mikitani.html\">Mikitani<\/a> · <a href=\"../../../people/kiriyama-ikuto.html\">Kiriyama Ikuto<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Kōenji Rokusuke<\/b> “It is not a pretty situation. I don&#x27;t like male sexuality. ”<span class=\"pg\">p.111<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Mikitani<\/b> “What would you do? If you try to push me away, I will take it as a declaration of war. ”<span class=\"pg\">p.111<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kōenji Rokusuke<\/b> “Oh I see.”<span class=\"pg\">p.111<\/span><\/li><\/ul><details class=\"more\"><summary>21 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “What? I think I have broken my arm! ”<span class=\"pg\">p.111<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “You have done something terrible, Kouenji.” — printed untagged; Mikitani or Kiriyama; not assigned.<span class=\"pg\">p.112<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You sound like a hit man.” — Kouenji.<span class=\"pg\">p.112<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “No matter what you say, it doesn&#x27;t change the fact that you pushed Morooka away.” — printed untagged; Mikitani or Kiriyama; not assigned.<span class=\"pg\">p.112<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “It seems that you are willing to hit us, your senpai. But if you did, you&#x27;d be in big trouble right? ” — printed untagged; Mikitani or Kiriyama; not assigned.<span class=\"pg\">p.112<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You can not touch me.”<span class=\"pg\">p.112<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I have no intention of showing mercy to those who prevent me from moving forward, much less turning against me.”<span class=\"pg\">p.112<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What if we report it to the school?”<span class=\"pg\">p.112<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What&#x27;s going to happen, or is it just going to be a stain on the name of the third year students who tried to sink a lone kouhai?”<span class=\"pg\">p.112<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I can&#x27;t be nice to you all the time.”<span class=\"pg\">p.113<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Does that mean you&#x27;re going to turn against me?”<span class=\"pg\">p.113<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Didn&#x27;t you, Mikitani? You really want to do it.”<span class=\"pg\">p.113<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “… Ah. If that&#x27;s the case, I&#x27;ll go down with Kouenji in my arms. Let&#x27;s do it! ”<span class=\"pg\">p.113<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It&#x27;s not nice that you always follow me. It&#x27;s not nice to have a dead leaf slapping my cheek over and over again. ”<span class=\"pg\">p.114<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Are you okay, Mikitani?”<span class=\"pg\">p.114<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Even if I have to drop the reward for reaching the designated area, here I will nip the counterattack of third year students in the bud.”<span class=\"pg\">p.114<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Are you going to report my failure to Nagumo?”<span class=\"pg\">p.115<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Now if you&#x27;ll excuse me. Bye.”<span class=\"pg\">p.115<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Breaks the encirclement without raising a hand — Morooka&#x27;s arm is broken; everyone else&#x27;s spirits are broken; he leaves with the designated-area reward dropped; Kiriyama&#x27;s plan fails.<span class=\"pg\">p.111–115<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kiriyama Ikuto<\/b> His siege plan collapses in 15 minutes; Kiriyama concedes the match.<span class=\"pg\">p.111–115<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Mikitani<\/b> The spearhead breaks first; Morooka is hospitalized.<span class=\"pg\">p.111–115<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kouenji-rokusuke-y2v4-p106-1\">← Before: Ch.4: The E3 English test; the circle closes<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kouenji-rokusuke-y2v4-p205-1\">→ After: Kōenji mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v4-p116-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"shiina-hiyori ishizaki-daichi ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 4  the six member group at the sunset at j10 just before 5 00 p m  he barely makes the last zone and spots the merged group   three girls from class 2 b and three more from another sophomore group  ishizaki daichi  takeko nishino  hitomi tsutsube  only hiyori notices him first and waves   what  isn t it ayanokouji kun   you look better than i thought   everyone has worked very hard  we have expanded our group to a maximum of six people   that s right  we have several priorities for the merger  and this is one of those groups   ayanokouji kun  how do you feel   yes  so far  so good   i don t think there is anything to worry about  but you have to be careful   i know   there are three days left   that s how it is  she doesn t ask his score   he reads her as convinced he won t be expelled  he sits with them watching the sea  their comfort feels strange and good  ryuen s class is changing little by little  she waves at him  she checks on him  they merge effortlessly  his side of the merged group waves from afar","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v4-p116-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v4-p116-1\">Ch.4: The six-member group at the sunset<\/a><\/span><span class=\"meta\">Y2V4 · p.116–118<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">At J10 just before 5:00 p.m., he barely makes the last zone and spots the merged group — three girls from Class 2-B and three more from another sophomore group (Ishizaki Daichi, Takeko Nishino, Hitomi Tsutsube); only Hiyori notices him first and waves.<\/p><p class=\"with\">with <a href=\"../../../people/shiina-hiyori.html\">Shiina Hiyori<\/a> · <a href=\"../../../people/ishizaki-daichi.html\">Ishizaki Daichi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Shiina Hiyori<\/b> “What? Isn&#x27;t it Ayanokouji-kun?”<span class=\"pg\">p.116<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Shiina Hiyori<\/b> “You look better than I thought.”<span class=\"pg\">p.116<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Shiina Hiyori<\/b> “Everyone has worked very hard. We have expanded our group to a maximum of six people.”<span class=\"pg\">p.116<\/span><\/li><\/ul><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “That&#x27;s right. We have several priorities for the merger, and this is one of those groups.”<span class=\"pg\">p.118<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ayanokouji-kun, how do you feel?”<span class=\"pg\">p.118<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yes. So far, so good.”<span class=\"pg\">p.118<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t think there is anything to worry about, but you have to be careful.”<span class=\"pg\">p.118<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I know.”<span class=\"pg\">p.118<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There are three days left.”<span class=\"pg\">p.118<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That&#x27;s how it is.”<span class=\"pg\">p.118<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> She doesn&#x27;t ask his score — he reads her as convinced he won&#x27;t be expelled; he sits with them watching the sea; their comfort feels strange and good; Ryūen&#x27;s class is changing little by little.<span class=\"pg\">p.116–118<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiina Hiyori<\/b> She waves at him; she checks on him; they merge effortlessly.<span class=\"pg\">p.116–118<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishizaki Daichi<\/b> His side of the merged group waves from afar.<span class=\"pg\">p.116<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p86-1\">← Before: Ch.3: The Shiranami night search; the walkie-talkie<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p119-1\">→ After: Ch.4: Ishizaki&#x27;s invitation to I9<\/button><\/div><\/article>"},{"i":"sc-ishizaki-daichi-y2v4-p116-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"ayanokouji-kiyotaka shiina-hiyori nishino-takeko tsube-hitomi ishizaki-daichi","q":"ishizaki daichi ch 4  the merged group  the j10 gatekeeper he and his group  nishino takeko  tsutsube hitomi  merge with hiyori s class 2 b group at j10  the merged group watches the sea  he calls ayanokoji over  he smiles happily when finally noticed  he camps at i9 with them  walks with them on the twelfth day   hey  ayanokouji   what the hell  don t get in my way   do not   no  good point  i d say you just can t read the air   sorry to interrupt   anyway  you don t have any more tests today  and you were planning to camp near i9  right   they are very close  don t they   why don t they go out  they can be couples and that s how ayanokoji comes to our class  right   ouch  that hurts  if you want to put ayanokouji in your class  don t you think it s necessary   well  what can i say    we are on the same wavelength   what do you mean   oh yeah  i don t know what it is  but i don t feel bad about being praised   that s all for now  ayanokouji  see you later  cheerful and socially fearless   calls him over mid sea watch  proposes his i9 camp  invites him to be a couple for his class  and cannot read the air  his merged group feels safe enough that ayanokoji almost believes their comfort is genuine  he is delighted to see him  invites him to camp and to join his class  his assigned merger partner  she steers the group  his groupmate  they trade barbs  his groupmate from the other class","h":"<article class=\"card\" id=\"sc-ishizaki-daichi-y2v4-p116-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ishizaki-daichi.html#sc-ishizaki-daichi-y2v4-p116-1\">Ch.4: The merged group; the J10 gatekeeper<\/a><\/span><span class=\"meta\">Y2V4 · p.116–125<\/span><span class=\"by\">notes on <a href=\"../../../people/ishizaki-daichi.html\">Ishizaki Daichi<\/a><\/span><\/h3><p class=\"setup\">He and his group (Nishino Takeko, Tsutsube Hitomi) merge with Hiyori&#x27;s Class 2-B group at J10; the merged group watches the sea; he calls Ayanokōji over; he smiles happily when finally noticed; he camps at I9 with them; walks with them on the twelfth day.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/shiina-hiyori.html\">Shiina Hiyori<\/a> · <a href=\"../../../people/nishino-takeko.html\">Nishino Takeko<\/a> · <a href=\"../../../people/index.html#tsube-hitomi\">Tsube Hitomi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ishizaki Daichi<\/b> “Hey, Ayanokouji!”<span class=\"pg\">p.119<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ishizaki Daichi<\/b> “What the hell? Don&#x27;t get in my way.”<span class=\"pg\">p.119<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ishizaki Daichi<\/b> “Do not…”<span class=\"pg\">p.119<\/span><\/li><\/ul><details class=\"more\"><summary>15 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “No. Good point? I&#x27;d say you just can&#x27;t read the air.”<span class=\"pg\">p.119<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Sorry to interrupt.”<span class=\"pg\">p.119<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Anyway, you don&#x27;t have any more tests today, and you were planning to camp near I9, right?”<span class=\"pg\">p.119<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “They are very close. Don&#x27;t they?”<span class=\"pg\">p.124<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Why don&#x27;t they go out? They can be couples and that&#x27;s how Ayanokoji comes to our class, right?”<span class=\"pg\">p.124<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ouch, that hurts. If you want to put Ayanokouji in your class, don&#x27;t you think it&#x27;s necessary?”<span class=\"pg\">p.124<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, what can I say? ... We are on the same wavelength.”<span class=\"pg\">p.124<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What do you mean?”<span class=\"pg\">p.124<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Oh yeah! I don&#x27;t know what it is, but I don&#x27;t feel bad about being praised!”<span class=\"pg\">p.125<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That&#x27;s all for now, Ayanokouji. See you later.”<span class=\"pg\">p.125<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Cheerful and socially fearless — calls him over mid-sea-watch, proposes his I9 camp, invites him to be a couple for his class, and cannot read the air; his merged group feels safe enough that Ayanokōji almost believes their comfort is genuine.<span class=\"pg\">p.116–125<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> He is delighted to see him; invites him to camp and to join his class.<span class=\"pg\">p.116–125<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiina Hiyori<\/b> His assigned merger partner; she steers the group.<span class=\"pg\">p.116–125<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nishino Takeko<\/b> His groupmate; they trade barbs.<span class=\"pg\">p.116–125<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsube Hitomi<\/b> His groupmate from the other class.<span class=\"pg\">p.116–125<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ishizaki-daichi-y2v4-p177-1\">→ After: Ch.5: The ambusher in the 3-on-1<\/button><\/div><\/article>"},{"i":"sc-isoyama-nagisa-y2v4-p116-1","v":"y2v4","y":2,"o":19,"k":"","w":"shiina-hiyori morofuji-rika ishizaki-daichi nishino-takeko tsube-hitomi isoyama-nagisa","q":"isoyama nagisa ch 4  the merged group at the sunset he and his class 2 b groupmates  morofuji rika  shiina hiyori  merge with ishizaki daichi s group  takeko nishino  hitomi tsutsube  at j10  hiyori does the talking  the group watches the sea at sunset  he camps at i9 with them  walks with them on the twelfth day  no dialogue printed for him  his presence is the merger s silent half  one of the six members  takes the merger without complaint  parts ways with ayanokoji on the twelfth day route walk  his groupmate  his groupmate  the merged group s leader  his merged groupmate  his merged groupmate","h":"<article class=\"card\" id=\"sc-isoyama-nagisa-y2v4-p116-1\"><h3><span class=\"ttl\"><a href=\"../../../people/isoyama-nagisa.html#sc-isoyama-nagisa-y2v4-p116-1\">Ch.4: The merged group at the sunset<\/a><\/span><span class=\"meta\">Y2V4 · p.116–125<\/span><span class=\"by\">notes on <a href=\"../../../people/isoyama-nagisa.html\">Isoyama Nagisa<\/a><\/span><\/h3><p class=\"setup\">He and his Class 2-B groupmates (Morofuji Rika, Shiina Hiyori) merge with Ishizaki Daichi&#x27;s group (Takeko Nishino, Hitomi Tsutsube) at J10; Hiyori does the talking; the group watches the sea at sunset; he camps at I9 with them; walks with them on the twelfth day.<\/p><p class=\"with\">with <a href=\"../../../people/shiina-hiyori.html\">Shiina Hiyori<\/a> · <a href=\"../../../people/morofuji-rika.html\">Morofuji Rika<\/a> · <a href=\"../../../people/ishizaki-daichi.html\">Ishizaki Daichi<\/a> · <a href=\"../../../people/nishino-takeko.html\">Nishino Takeko<\/a> · <a href=\"../../../people/index.html#tsube-hitomi\">Tsube Hitomi<\/a><\/p><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> No dialogue printed for him; his presence is the merger&#x27;s silent half.<span class=\"pg\">p.116–125<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> One of the six members; takes the merger without complaint; parts ways with Ayanokōji on the twelfth-day route walk.<span class=\"pg\">p.116–125<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiina Hiyori<\/b> His groupmate.<span class=\"pg\">p.116–125<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Morofuji Rika<\/b> His groupmate.<span class=\"pg\">p.116–125<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishizaki Daichi<\/b> The merged group&#x27;s leader.<span class=\"pg\">p.116–125<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nishino Takeko<\/b> His merged groupmate.<span class=\"pg\">p.116–125<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsube Hitomi<\/b> His merged groupmate.<span class=\"pg\">p.116–125<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-morofuji-rika-y2v4-p116-1","v":"y2v4","y":2,"o":19,"k":"","w":"shiina-hiyori isoyama-nagisa ishizaki-daichi nishino-takeko tsube-hitomi morofuji-rika","q":"morofuji rika ch 4  the merged group at the sunset she and her class 2 b groupmates  isoyama nagisa  shiina hiyori  merge with ishizaki daichi s group  takeko nishino  hitomi tsutsube  at j10  hiyori does the talking  the group watches the sea at sunset  she camps at i9 with them  walks with them on the twelfth day  no dialogue printed for her  her presence is the merger s silent half  one of the six members  takes the merger without complaint  parts ways with ayanokoji on the twelfth day route walk  her groupmate  her groupmate  the merged group s leader  her merged groupmate  her merged groupmate","h":"<article class=\"card\" id=\"sc-morofuji-rika-y2v4-p116-1\"><h3><span class=\"ttl\"><a href=\"../../../people/morofuji-rika.html#sc-morofuji-rika-y2v4-p116-1\">Ch.4: The merged group at the sunset<\/a><\/span><span class=\"meta\">Y2V4 · p.116–125<\/span><span class=\"by\">notes on <a href=\"../../../people/morofuji-rika.html\">Morofuji Rika<\/a><\/span><\/h3><p class=\"setup\">She and her Class 2-B groupmates (Isoyama Nagisa, Shiina Hiyori) merge with Ishizaki Daichi&#x27;s group (Takeko Nishino, Hitomi Tsutsube) at J10; Hiyori does the talking; the group watches the sea at sunset; she camps at I9 with them; walks with them on the twelfth day.<\/p><p class=\"with\">with <a href=\"../../../people/shiina-hiyori.html\">Shiina Hiyori<\/a> · <a href=\"../../../people/isoyama-nagisa.html\">Isoyama Nagisa<\/a> · <a href=\"../../../people/ishizaki-daichi.html\">Ishizaki Daichi<\/a> · <a href=\"../../../people/nishino-takeko.html\">Nishino Takeko<\/a> · <a href=\"../../../people/index.html#tsube-hitomi\">Tsube Hitomi<\/a><\/p><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> No dialogue printed for her; her presence is the merger&#x27;s silent half.<span class=\"pg\">p.116–125<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> One of the six members; takes the merger without complaint; parts ways with Ayanokōji on the twelfth-day route walk.<span class=\"pg\">p.116–125<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiina Hiyori<\/b> Her groupmate.<span class=\"pg\">p.116–125<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Isoyama Nagisa<\/b> Her groupmate.<span class=\"pg\">p.116–125<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishizaki Daichi<\/b> The merged group&#x27;s leader.<span class=\"pg\">p.116–125<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nishino Takeko<\/b> Her merged groupmate.<span class=\"pg\">p.116–125<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsube Hitomi<\/b> Her merged groupmate.<span class=\"pg\">p.116–125<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-nishino-takeko-y2v4-p116-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"ishizaki-daichi shiina-hiyori tsube-hitomi nishino-takeko","q":"nishino takeko ch 4  the merged group  the sharp tongued gatekeeper she and her group merge  the six of them watch the sea at sunset  she punches ishizaki for the couple theory and walks with them on the twelfth day   you re thinking about it a lot   i do not think so at all  you are the one who is so obsessed with ayanokouji kun   i don t think you are on the same wavelength  i don t think anyone is on the same wavelength as you  the group s razor tongue   knows ishizaki s crushes are ridiculous  protects ayanokoji from ishizaki s couple scheme with a straight face and a punch  her group leader  she swats him down  her class 2 b counterpart  her merged groupmate","h":"<article class=\"card\" id=\"sc-nishino-takeko-y2v4-p116-1\"><h3><span class=\"ttl\"><a href=\"../../../people/nishino-takeko.html#sc-nishino-takeko-y2v4-p116-1\">Ch.4: The merged group; the sharp-tongued gatekeeper<\/a><\/span><span class=\"meta\">Y2V4 · p.116–125<\/span><span class=\"by\">notes on <a href=\"../../../people/nishino-takeko.html\">Nishino Takeko<\/a><\/span><\/h3><p class=\"setup\">She and her group merge; the six of them watch the sea at sunset; she punches Ishizaki for the couple-theory and walks with them on the twelfth day.<\/p><p class=\"with\">with <a href=\"../../../people/ishizaki-daichi.html\">Ishizaki Daichi<\/a> · <a href=\"../../../people/shiina-hiyori.html\">Shiina Hiyori<\/a> · <a href=\"../../../people/index.html#tsube-hitomi\">Tsube Hitomi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Nishino Takeko<\/b> “You&#x27;re thinking about it a lot.”<span class=\"pg\">p.124<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nishino Takeko<\/b> “I do not think so at all. You are the one who is so obsessed with Ayanokouji-kun.”<span class=\"pg\">p.124<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nishino Takeko<\/b> “I don&#x27;t think you are on the same wavelength. I don&#x27;t think anyone is on the same wavelength as you.”<span class=\"pg\">p.124<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> The group&#x27;s razor tongue — knows Ishizaki&#x27;s crushes are ridiculous; protects Ayanokōji from Ishizaki&#x27;s couple-scheme with a straight face and a punch.<span class=\"pg\">p.116–125<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishizaki Daichi<\/b> Her group leader; she swats him down.<span class=\"pg\">p.116–125<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiina Hiyori<\/b> Her Class 2-B counterpart.<span class=\"pg\">p.116–125<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsube Hitomi<\/b> Her merged groupmate.<span class=\"pg\">p.116–125<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-shiina-hiyori-y2v4-p116-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"ayanokouji-kiyotaka ishizaki-daichi nishino-takeko tsube-hitomi isoyama-nagisa morofuji-rika shiina-hiyori","q":"shiina hiyori ch 4  the sunset circle  six members just before 5 00 p m  at j10 he spots a group of three girls from 2nd year class b   isoyama nagisa  morofuji rika  shiina hiyori   plus three more from another sophomore group  ishizaki daichi  takeko nishino  and hitomi tsutsube  six people  only hiyori notices him first and waves   what  isn t it ayanokouji kun   you look better than i thought   everyone has worked very hard  we have expanded our group to a maximum of six people   did you plan to join ishizaki and the others from the beginning   that s right  we have several priorities for the merger  and this is one of those groups   ayanokouji kun  how do you feel   yes  so far  so good   i don t think there is anything to worry about  but you have to be careful   i know   there are three days left   that s how it is   hey  ayanokouji   what the hell  don t get in my way   what  it s not that ayanokouji doesn t like it  right   do not   nothing happens  that is one of the good things about you  ishizaki kun   no  good point  i d say you just can t read the air   well   yes  that could be undeniable   sorry to interrupt   anyway  you don t have any more tests today  and you were planning to camp near i9  right   it s a great idea   isn t it good  ayanokouji kun seems quite harmless  notices him first and waves  engineered the six member merger with ishizaki s group  her priorities list included the merger  doesn t ask his score   convinced he won t be expelled  sits with him watching the sea  proposes i9 camping when he can t camp at j10  trusts him completely  watches the sea together  invites him to walk with them  leader of his assigned partner group  she supports his invitation to ayanokoji  her groupmate  they merged groups at the j10 site  the other class member of their group  integrated well  her class 2 b groupmate  her class 2 b groupmate","h":"<article class=\"card\" id=\"sc-shiina-hiyori-y2v4-p116-1\"><h3><span class=\"ttl\"><a href=\"../../../people/shiina-hiyori.html#sc-shiina-hiyori-y2v4-p116-1\">Ch.4: The sunset circle; six members<\/a><\/span><span class=\"meta\">Y2V4 · p.116–120<\/span><span class=\"by\">notes on <a href=\"../../../people/shiina-hiyori.html\">Shiina Hiyori<\/a><\/span><\/h3><p class=\"setup\">Just before 5:00 p.m. at J10 he spots a group of three girls from 2nd-year Class B — Isoyama Nagisa, Morofuji Rika, Shiina Hiyori — plus three more from another sophomore group: Ishizaki Daichi, Takeko Nishino, and Hitomi Tsutsube (six people); only Hiyori notices him first and waves.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/ishizaki-daichi.html\">Ishizaki Daichi<\/a> · <a href=\"../../../people/nishino-takeko.html\">Nishino Takeko<\/a> · <a href=\"../../../people/index.html#tsube-hitomi\">Tsube Hitomi<\/a> · <a href=\"../../../people/isoyama-nagisa.html\">Isoyama Nagisa<\/a> · <a href=\"../../../people/morofuji-rika.html\">Morofuji Rika<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Shiina Hiyori<\/b> “What? Isn&#x27;t it Ayanokouji-kun?”<span class=\"pg\">p.116<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Shiina Hiyori<\/b> “You look better than I thought.”<span class=\"pg\">p.116<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Shiina Hiyori<\/b> “Everyone has worked very hard. We have expanded our group to a maximum of six people.”<span class=\"pg\">p.116<\/span><\/li><\/ul><details class=\"more\"><summary>26 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Did you plan to join Ishizaki and the others from the beginning?”<span class=\"pg\">p.118<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That&#x27;s right. We have several priorities for the merger, and this is one of those groups.”<span class=\"pg\">p.118<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ayanokouji-kun, how do you feel?”<span class=\"pg\">p.118<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yes. So far, so good.”<span class=\"pg\">p.118<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t think there is anything to worry about, but you have to be careful.”<span class=\"pg\">p.118<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I know.”<span class=\"pg\">p.118<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There are three days left.”<span class=\"pg\">p.118<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That&#x27;s how it is.&quot;<span class=\"pg\">p.118<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Hey, Ayanokouji!”<span class=\"pg\">p.119<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What the hell? Don&#x27;t get in my way.”<span class=\"pg\">p.119<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What? It&#x27;s not that Ayanokouji doesn&#x27;t like it, right?”<span class=\"pg\">p.119<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Do not…”<span class=\"pg\">p.119<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Nothing happens. That is one of the good things about you, Ishizaki-kun.”<span class=\"pg\">p.119<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No. Good point? I&#x27;d say you just can&#x27;t read the air.”<span class=\"pg\">p.119<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well …… yes, that could be undeniable.”<span class=\"pg\">p.119<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Sorry to interrupt.”<span class=\"pg\">p.119<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Anyway, you don&#x27;t have any more tests today, and you were planning to camp near I9, right?”<span class=\"pg\">p.119<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It&#x27;s a great idea!”<span class=\"pg\">p.119<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Isn&#x27;t it good? Ayanokouji-kun seems quite harmless.”<span class=\"pg\">p.120<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Notices him first and waves; engineered the six-member merger with Ishizaki&#x27;s group (her priorities list included the merger); doesn&#x27;t ask his score — convinced he won&#x27;t be expelled; sits with him watching the sea; proposes I9 camping when he can&#x27;t camp at J10.<span class=\"pg\">p.116–120<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Trusts him completely; watches the sea together; invites him to walk with them.<span class=\"pg\">p.116–120<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishizaki Daichi<\/b> Leader of his assigned partner group; she supports his invitation to Ayanokōji.<span class=\"pg\">p.116–120<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nishino Takeko<\/b> Her groupmate; they merged groups at the J10 site.<span class=\"pg\">p.116–120<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsube Hitomi<\/b> The other-class member of their group; integrated well.<span class=\"pg\">p.116–120<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Isoyama Nagisa<\/b> Her Class 2-B groupmate.<span class=\"pg\">p.116–120<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Morofuji Rika<\/b> Her Class 2-B groupmate.<span class=\"pg\">p.116–120<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-shiina-hiyori-y2v4-p123-1\">→ After: Ch.4: Her quiet question; the parting<\/button><\/div><\/article>"},{"i":"sc-tsube-hitomi-y2v4-p116-1","v":"y2v4","y":2,"o":19,"k":"","w":"ishizaki-daichi shiina-hiyori nishino-takeko tsube-hitomi","q":"tsube hitomi ch 4  the merged group  the outsider who fit the only member of a different class  c  in the merged group   ishizaki daichi s group merged with hiyori s class 2 b group  she integrates quickly and camps with them at i9  no dialogue printed for her  her presence is the merger s silent half  integrated very well despite being the only different class member   the group s comfort surprises even ayanokoji  her group leader  her class 2 b groupmate  her merged groupmate","h":"<article class=\"card\" id=\"sc-tsube-hitomi-y2v4-p116-1\"><h3><span class=\"ttl\">Ch.4: The merged group; the outsider who fit<\/span><span class=\"meta\">Y2V4 · p.116–125<\/span><span class=\"by\">notes on <a href=\"../../../people/index.html#tsube-hitomi\">Tsube Hitomi<\/a><\/span><\/h3><p class=\"setup\">The only member of a different class (C) in the merged group — Ishizaki Daichi&#x27;s group merged with Hiyori&#x27;s Class 2-B group; she integrates quickly and camps with them at I9.<\/p><p class=\"with\">with <a href=\"../../../people/ishizaki-daichi.html\">Ishizaki Daichi<\/a> · <a href=\"../../../people/shiina-hiyori.html\">Shiina Hiyori<\/a> · <a href=\"../../../people/nishino-takeko.html\">Nishino Takeko<\/a><\/p><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> No dialogue printed for her; her presence is the merger&#x27;s silent half.<span class=\"pg\">p.116–125<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Integrated very well despite being the only different-class member — the group&#x27;s comfort surprises even Ayanokōji.<span class=\"pg\">p.116–118<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishizaki Daichi<\/b> Her group leader.<span class=\"pg\">p.116–125<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiina Hiyori<\/b> Her Class 2-B groupmate.<span class=\"pg\">p.116–125<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nishino Takeko<\/b> Her merged groupmate.<span class=\"pg\">p.116–125<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v4-p119-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"ishizaki-daichi shiina-hiyori ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 4  ishizaki s invitation to i9 he watches the sea with them  ishizaki finally notices him and beams  he grabs his shoulder and invites him to camp at i9  the rest of the group agrees on the spot   hey  ayanokouji   what the hell  don t get in my way   what  it s not that ayanokouji doesn t like it  right   do not   nothing happens  that is one of the good things about you  ishizaki kun   no  good point  i d say you just can t read the air   well   yes  that could be undeniable   sorry to interrupt   anyway  you don t have any more tests today  and you were planning to camp near i9  right   it s a great idea   it s a great idea   isn t it good  ayanokouji kun seems quite harmless  the atmosphere draws him out   no one asks questions  for a moment he almost forgets this is a survival exam  ichinose s class comfort leaks into ryuen s class  he invites him to i9 camping  the others readily agree","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v4-p119-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v4-p119-1\">Ch.4: Ishizaki&#x27;s invitation to I9<\/a><\/span><span class=\"meta\">Y2V4 · p.119–120<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">He watches the sea with them; Ishizaki finally notices him and beams; he grabs his shoulder and invites him to camp at I9; the rest of the group agrees on the spot.<\/p><p class=\"with\">with <a href=\"../../../people/ishizaki-daichi.html\">Ishizaki Daichi<\/a> · <a href=\"../../../people/shiina-hiyori.html\">Shiina Hiyori<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ishizaki Daichi<\/b> “Hey, Ayanokouji!”<span class=\"pg\">p.119<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ishizaki Daichi<\/b> “What the hell? Don&#x27;t get in my way.”<span class=\"pg\">p.119<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Shiina Hiyori<\/b> “What? It&#x27;s not that Ayanokouji doesn&#x27;t like it, right?”<span class=\"pg\">p.119<\/span><\/li><\/ul><details class=\"more\"><summary>11 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Do not…”<span class=\"pg\">p.119<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Nothing happens. That is one of the good things about you, Ishizaki-kun.”<span class=\"pg\">p.119<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No. Good point? I&#x27;d say you just can&#x27;t read the air.”<span class=\"pg\">p.119<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well …… yes, that could be undeniable.”<span class=\"pg\">p.119<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Sorry to interrupt.”<span class=\"pg\">p.119<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Anyway, you don&#x27;t have any more tests today, and you were planning to camp near I9, right?”<span class=\"pg\">p.119<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It&#x27;s a great idea!”<span class=\"pg\">p.119<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It&#x27;s a great idea!”<span class=\"pg\">p.119<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Isn&#x27;t it good? Ayanokouji-kun seems quite harmless.”<span class=\"pg\">p.120<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> The atmosphere draws him out — no one asks questions; for a moment he almost forgets this is a survival exam; Ichinose&#x27;s class comfort leaks into Ryūen&#x27;s class.<span class=\"pg\">p.119–120<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishizaki Daichi<\/b> He invites him to I9 camping; the others readily agree.<span class=\"pg\">p.119–120<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p116-1\">← Before: Ch.4: The six-member group at the sunset<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p120-1\">→ After: Ch.4: 2:30 a.m.; Nanase&#x27;s warning<\/button><\/div><\/article>"},{"i":"sc-amasawa-ichika-y2v4-p120-1","v":"y2v4","y":2,"o":19,"k":"","w":"amasawa-ichika","q":"amasawa ichika ch 4  the empty leak  mention records   if amasawa is advising him  there is a chance that he may see the truth     ayanokoji s thought   either amasawa  who knew of nanase s betrayal  pointed out the information leak  or the plan was going to go ahead today but was postponed or canceled due to some accident    ayanokoji","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v4-p120-1\"><h3><span class=\"ttl\"><a href=\"../../../people/amasawa-ichika.html#sc-amasawa-ichika-y2v4-p120-1\">Ch.4: The empty leak (mention records)<\/a><\/span><span class=\"meta\">Y2V4 · p.120–125<\/span><span class=\"by\">notes on <a href=\"../../../people/amasawa-ichika.html\">Amasawa Ichika<\/a><\/span><\/h3><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “If Amasawa is advising him, there is a chance that he may see the truth .......” — Ayanokōji&#x27;s thought.<span class=\"pg\">p.122<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Either Amasawa, who knew of Nanase&#x27;s betrayal, pointed out the information leak. Or the plan was going to go ahead today but was postponed or canceled due to some accident.” — Ayanokōji.<span class=\"pg\">p.125<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v4-p62-1\">← Before: Ch.3: Her name in the night (mention records)<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v4-p162-1\">→ After: Amasawa mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v4-p120-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"nanase-tsubasa housen-kazuomi tsubaki-sakurako ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 4  2 30 a m  nanase s warning during the night at i9  nanase slips to his tent at 2 30 a m  frightened   she was working with hosen all day  she came straight to him   it s me  nanase   i m fine  i was in i9 like you  in fact  i even saw you from afar at night  but since i was working with housen kun  so i decided to avoid contact   there is something i need to tell you as soon as possible  today  well  the date has already changed  so it was yesterday to be exact  but housen kun told me that on the twelfth day  the first years will make a great play on ayanokouji senpai   a great play  it sure isn t the only thing   no  no  let me tell you in order   i don t know  but tsubaki was the main person i spoke to on the walkie talkie   it s good that you told us the date and the details until the last moment   oh no  thanks for that  but that s enough for this uninhabited island exam  if you see a freshman moving around  you don t have to come tell me  and you don t have to help me   nevertheless   nanase  you have given me enough information  now you must do what you have to do as one of the group of housen and amasawa   if ayanokouji senpai says so  i understand   he deduces the first years  day 12 plan  force his withdrawal at the exam s end  seniors alone targeted  hosen feigning cooperation  he cuts nanase loose so she can protect her cover  her leak is his edge  he sends her away so she stays an operative  feigning cooperation  holds the walkie talkie  the intermediary named on the walkie talkie","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v4-p120-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v4-p120-1\">Ch.4: 2:30 a.m.; Nanase&#x27;s warning<\/a><\/span><span class=\"meta\">Y2V4 · p.120–122<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">During the night at I9, Nanase slips to his tent at 2:30 a.m., frightened — she was working with Hōsen all day; she came straight to him.<\/p><p class=\"with\">with <a href=\"../../../people/nanase-tsubasa.html\">Nanase Tsubasa<\/a> · <a href=\"../../../people/housen-kazuomi.html\">Hōsen Kazuomi<\/a> · <a href=\"../../../people/tsubaki-sakurako.html\">Tsubaki Sakurako<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> “It&#x27;s me, Nanase.”<span class=\"pg\">p.120<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> “I&#x27;m fine; I was in I9 like you. In fact, I even saw you from afar at night, but since I was working with Housen-kun, so I decided to avoid contact.”<span class=\"pg\">p.120<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> “There is something I need to tell you as soon as possible ...Today... well, the date has already changed, so it was yesterday to be exact, but Housen-kun told me that on the twelfth day, the first years will make a great play on…”<span class=\"pg\">p.120<\/span><\/li><\/ul><details class=\"more\"><summary>13 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “There is something I need to tell you as soon as possible ...Today... well, the date has already changed, so it was yesterday to be exact, but Housen-kun told me that on the twelfth day, the first years will make a great play on Ayanokouji-senpai.”<span class=\"pg\">p.120<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “A great play? It sure isn&#x27;t the only thing.”<span class=\"pg\">p.120<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No, no, let me tell you in order.”<span class=\"pg\">p.120<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t know, but Tsubaki was the main person I spoke to on the walkie-talkie.”<span class=\"pg\">p.121<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It&#x27;s good that you told us the date and the details until the last moment.”<span class=\"pg\">p.121<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Oh no, thanks for that, but that&#x27;s enough for this uninhabited island exam. If you see a freshman moving around, you don&#x27;t have to come tell me, and you don&#x27;t have to help me.”<span class=\"pg\">p.121<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Nevertheless...”<span class=\"pg\">p.122<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Nanase, you have given me enough information. Now you must do what you have to do as one of the group of Housen and Amasawa.”<span class=\"pg\">p.122<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If Ayanokouji senpai says so, I understand ...”<span class=\"pg\">p.122<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> He deduces the first-years&#x27; day-12 plan: force his withdrawal at the exam&#x27;s end; seniors alone targeted; Hōsen feigning cooperation; he cuts Nanase loose so she can protect her cover.<span class=\"pg\">p.120–122<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nanase Tsubasa<\/b> Her leak is his edge; he sends her away so she stays an operative.<span class=\"pg\">p.120–122<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> Feigning cooperation; holds the walkie-talkie.<span class=\"pg\">p.121<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsubaki Sakurako<\/b> The intermediary named on the walkie-talkie.<span class=\"pg\">p.121<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p119-1\">← Before: Ch.4: Ishizaki&#x27;s invitation to I9<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p123-1\">→ After: Ch.4: The quiet morning; the empty leak<\/button><\/div><\/article>"},{"i":"sc-housen-kazuomi-y2v4-p120-1","v":"y2v4","y":2,"o":19,"k":"","w":"housen-kazuomi","q":"hosen kazuomi ch 4  the feigning cooperator  housen kun told me that on the twelfth day  the first years will make a great play on ayanokouji senpai    nanase leaks to ayanokoji  housen pretended to cooperate with the first years to get close to her and never intended to deliver  her information  around the ninth day an errand boy from one of the first year groups showed up with a walkie talkie and asked for hosen s help again   he wants to force ayanokoji senpai to withdraw at the end of the exam  and to hunt down and remove seniors performing alone  specifics will come on the day  housen holds the walkie talkie but has no intention of cooperating","h":"<article class=\"card\" id=\"sc-housen-kazuomi-y2v4-p120-1\"><h3><span class=\"ttl\"><a href=\"../../../people/housen-kazuomi.html#sc-housen-kazuomi-y2v4-p120-1\">Ch.4: The feigning cooperator<\/a><\/span><span class=\"meta\">Y2V4 · p.120–122<\/span><span class=\"by\">notes on <a href=\"../../../people/housen-kazuomi.html\">Hōsen Kazuomi<\/a><\/span><\/h3><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “Housen-kun told me that on the twelfth day, the first years will make a great play on Ayanokouji-senpai.” — Nanase leaks to Ayanokōji; Housen pretended to cooperate with the first-years to get close to her and never intended to deliver.<span class=\"pg\">p.120<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Her information: around the ninth day an errand boy from one of the first-year groups showed up with a walkie-talkie and asked for Hōsen&#x27;s help again — he wants to force Ayanokōji-senpai to withdraw at the end of the exam, and to hunt down and remove seniors performing alone. Specifics will come on the day; Housen holds the walkie-talkie but has no intention of cooperating.<span class=\"pg\">p.121<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-housen-kazuomi-y2v4-p53-1\">← Before: Hōsen mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-housen-kazuomi-y2v4-p126-1\">→ After: Ch.5: The negotiation; the stalking invitation<\/button><\/div><\/article>"},{"i":"sc-ichinose-honami-y2v4-p120-1","v":"y2v4","y":2,"o":19,"k":"","w":"ichinose-honami","q":"ichinose honami ichinose mentioned in passing  this kind of environment is often seen in ichinose s class  but it seems that ryuuen s class is also starting to change little by little    ayanokoji","h":"<article class=\"card\" id=\"sc-ichinose-honami-y2v4-p120-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ichinose-honami.html#sc-ichinose-honami-y2v4-p120-1\">Ichinose mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.120<\/span><span class=\"by\">notes on <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “This kind of environment is often seen in Ichinose&#x27;s class, but it seems that Ryuuen&#x27;s class is also starting to change little by little.” — Ayanokōji.<span class=\"pg\">p.120<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y2v4-p89-1\">← Before: Ichinose mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y2v4-p162-1\">→ After: Ichinose mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v4-p120-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"ayanokouji-kiyotaka housen-kazuomi tsubaki-sakurako nanase-tsubasa","q":"nanase tsubasa ch 4  2 30 a m  nanase s warning in the middle of the night she slips to his tent   she was working with hosen all day  she came straight to him with the leak   it s me  nanase   i m fine  i was in i9 like you  in fact  i even saw you from afar at night  but since i was working with housen kun  so i decided to avoid contact   there is something i need to tell you as soon as possible  today  well  the date has already changed  so it was yesterday to be exact  but housen kun told me that on the twelfth day  the first years will make a great play on ayanokouji senpai   a great play  it sure isn t the only thing   no  no  let me tell you in order  she explains  around the ninth day an errand boy from one of the first year groups showed up with a walkie talkie and asked for hosen s help again   he wants to force ayanokoji senpai to withdraw at the exam s end  and to hunt down and remove seniors performing alone  specifics would be communicated on the day  hosen holds the walkie talkie but has no intention of cooperating   he s pretending to go along   who is in charge   i don t know  but tsubaki was the main person i spoke to on the walkie talkie   she didn t seem like the type that has long been outdoors   i agree with you  because i had the impression that class c was more focused on utomiya  but utomiya and housen don t get along  and when it comes to arguing  they quickly get into quarrels  so tsubaki may have been deliberately chosen to act as an intermediary   oh no  thanks for that  but that s enough for this uninhabited island exam  if you see a freshman moving around  you don t have to come tell me  and you don t have to help me   nevertheless   nanase  you have given me enough information  now you must do what you have to do as one of the group of housen and amasawa   if ayanokouji senpai says so  i understand   she risks her cover at 2 30 a m  to pass the leak  she knows hosen pretends to cooperate  she reports whatever she hears  he cuts her loose so she can protect her cover  her leak is his edge  he sends her away so she stays an operative  pretending to cooperate  holds the walkie talkie  the main person on the walkie talkie","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v4-p120-1\"><h3><span class=\"ttl\"><a href=\"../../../people/nanase-tsubasa.html#sc-nanase-tsubasa-y2v4-p120-1\">Ch.4: 2:30 a.m.; Nanase&#x27;s warning<\/a><\/span><span class=\"meta\">Y2V4 · p.120–122<\/span><span class=\"by\">notes on <a href=\"../../../people/nanase-tsubasa.html\">Nanase Tsubasa<\/a><\/span><\/h3><p class=\"setup\">In the middle of the night she slips to his tent — she was working with Hōsen all day; she came straight to him with the leak.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/housen-kazuomi.html\">Hōsen Kazuomi<\/a> · <a href=\"../../../people/tsubaki-sakurako.html\">Tsubaki Sakurako<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> “It&#x27;s me, Nanase.”<span class=\"pg\">p.120<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> “I&#x27;m fine; I was in I9 like you. In fact, I even saw you from afar at night, but since I was working with Housen-kun, so I decided to avoid contact.”<span class=\"pg\">p.120<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> “There is something I need to tell you as soon as possible ...Today... well, the date has already changed, so it was yesterday to be exact, but Housen-kun told me that on the twelfth day, the first years will make a great play on…”<span class=\"pg\">p.120<\/span><\/li><\/ul><details class=\"more\"><summary>16 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “There is something I need to tell you as soon as possible ...Today... well, the date has already changed, so it was yesterday to be exact, but Housen-kun told me that on the twelfth day, the first years will make a great play on Ayanokouji-senpai.”<span class=\"pg\">p.120<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “A great play? It sure isn&#x27;t the only thing.”<span class=\"pg\">p.120<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No, no, let me tell you in order.”<span class=\"pg\">p.120<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> She explains: around the ninth day an errand boy from one of the first-year groups showed up with a walkie-talkie and asked for Hōsen&#x27;s help again — he wants to force Ayanokōji-senpai to withdraw at the exam&#x27;s end, and to hunt down and remove seniors performing alone. Specifics would be communicated on the day; Hōsen holds the walkie-talkie but has no intention of cooperating — he&#x27;s pretending to go along.<span class=\"pg\">p.121<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Who is in charge?”<span class=\"pg\">p.121<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t know, but Tsubaki was the main person I spoke to on the walkie-talkie.”<span class=\"pg\">p.121<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “She didn&#x27;t seem like the type that has long been outdoors.”<span class=\"pg\">p.121<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I agree with you, because I had the impression that Class C was more focused on Utomiya. But Utomiya and Housen don&#x27;t get along, and when it comes to arguing, they quickly get into quarrels, so Tsubaki may have been deliberately chosen to act as an intermediary.”<span class=\"pg\">p.121<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Oh no, thanks for that, but that&#x27;s enough for this uninhabited island exam. If you see a freshman moving around, you don&#x27;t have to come tell me, and you don&#x27;t have to help me.”<span class=\"pg\">p.122<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Nevertheless...”<span class=\"pg\">p.122<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Nanase, you have given me enough information. Now you must do what you have to do as one of the group of Housen and Amasawa.”<span class=\"pg\">p.122<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If Ayanokouji senpai says so, I understand ...”<span class=\"pg\">p.122<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> She risks her cover at 2:30 a.m. to pass the leak; she knows Hōsen pretends to cooperate; she reports whatever she hears; he cuts her loose so she can protect her cover.<span class=\"pg\">p.120–122<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Her leak is his edge; he sends her away so she stays an operative.<span class=\"pg\">p.120–122<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> Pretending to cooperate; holds the walkie-talkie.<span class=\"pg\">p.120–121<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsubaki Sakurako<\/b> The main person on the walkie-talkie.<span class=\"pg\">p.121<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v4-p51-1\">← Before: Ch.2: Parting at area E3<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v4-p126-1\">→ After: Ch.5: The tent at day nine; the insult over her figure<\/button><\/div><\/article>"},{"i":"sc-takahashi-osamu-y2v4-p121-1","v":"y2v4","y":2,"o":19,"k":"","w":"takahashi-osamu","q":"takahashi osamu takahashi mentioned in passing  housen was summoned by takahashi  yagami  tsubaki  and utomiya    nanase s report   there is also the possibility that someone like yagami or takahashi is pulling the strings behind the scenes    ayanokoji","h":"<article class=\"card\" id=\"sc-takahashi-osamu-y2v4-p121-1\"><h3><span class=\"ttl\"><a href=\"../../../people/takahashi-osamu.html#sc-takahashi-osamu-y2v4-p121-1\">Takahashi mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.121<\/span><span class=\"by\">notes on <a href=\"../../../people/takahashi-osamu.html\">Takahashi Osamu<\/a><\/span><\/h3><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “Housen was summoned by Takahashi, Yagami, Tsubaki, and Utomiya...” — Nanase&#x27;s report.<span class=\"pg\">p.121<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “There is also the possibility that someone like Yagami or Takahashi is pulling the strings behind the scenes.” — Ayanokōji.<span class=\"pg\">p.121<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-takahashi-osamu-y2v4-p48-1\">← Before: Takahashi in the printed top-ten<\/button><\/div><\/article>"},{"i":"sc-tsubaki-sakurako-y2v4-p121-1","v":"y2v4","y":2,"o":19,"k":"","w":"tsubaki-sakurako","q":"tsubaki sakurako tsubaki mentioned in passing  i don t know  but tsubaki was the main person i spoke to on the walkie talkie    nanase names her as the coordinator   i agree with you  because i had the impression that class c was more focused on utomiya  but utomiya and housen don t get along  and when it comes to arguing  they quickly get into quarrels  so tsubaki may have been deliberately chosen to act as an intermediary    nanase","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y2v4-p121-1\"><h3><span class=\"ttl\"><a href=\"../../../people/tsubaki-sakurako.html#sc-tsubaki-sakurako-y2v4-p121-1\">Tsubaki mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.121<\/span><span class=\"by\">notes on <a href=\"../../../people/tsubaki-sakurako.html\">Tsubaki Sakurako<\/a><\/span><\/h3><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “I don&#x27;t know, but Tsubaki was the main person I spoke to on the walkie-talkie.” — Nanase names her as the coordinator.<span class=\"pg\">p.121<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “I agree with you, because I had the impression that Class C was more focused on Utomiya. But Utomiya and Housen don&#x27;t get along, and when it comes to arguing, they quickly get into quarrels, so Tsubaki may have been deliberately chosen to act as an intermediary.” — Nanase.<span class=\"pg\">p.121<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v4-p126-1\">→ After: Ch.5: The deal with Hōsen<\/button><\/div><\/article>"},{"i":"sc-utomiya-riku-y2v4-p121-1","v":"y2v4","y":2,"o":19,"k":"","w":"utomiya-riku","q":"utomiya riku utomiya mentioned in passing  housen was summoned by takahashi  yagami  tsubaki  and utomiya    nanase s report   i agree with you  because i had the impression that class c was more focused on utomiya    nanase   but utomiya and housen don t get along  and when it comes to arguing  they quickly get into quarrels  so tsubaki may have been deliberately chosen to act as an intermediary    nanase","h":"<article class=\"card\" id=\"sc-utomiya-riku-y2v4-p121-1\"><h3><span class=\"ttl\"><a href=\"../../../people/utomiya-riku.html#sc-utomiya-riku-y2v4-p121-1\">Utomiya mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.121<\/span><span class=\"by\">notes on <a href=\"../../../people/utomiya-riku.html\">Utomiya Riku<\/a><\/span><\/h3><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “Housen was summoned by Takahashi, Yagami, Tsubaki, and Utomiya...” — Nanase&#x27;s report.<span class=\"pg\">p.121<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “I agree with you, because I had the impression that Class C was more focused on Utomiya.” — Nanase.<span class=\"pg\">p.121<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “But Utomiya and Housen don&#x27;t get along, and when it comes to arguing, they quickly get into quarrels, so Tsubaki may have been deliberately chosen to act as an intermediary.” — Nanase.<span class=\"pg\">p.121<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-utomiya-riku-y2v4-p97-1\">← Before: Utomiya mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-utomiya-riku-y2v4-p128-1\">→ After: Ch.5: The negotiation; the scheme&#x27;s inside man<\/button><\/div><\/article>"},{"i":"sc-yagami-takuya-y2v4-p121-1","v":"y2v4","y":2,"o":19,"k":"","w":"yagami-takuya","q":"yagami takuya yagami mentioned in passing  housen was summoned by takahashi  yagami  tsubaki  and utomiya    nanase s report  the first years  coalition behind the day 12 play   there is also the possibility that someone like yagami or takahashi is pulling the strings behind the scenes    ayanokoji","h":"<article class=\"card\" id=\"sc-yagami-takuya-y2v4-p121-1\"><h3><span class=\"ttl\"><a href=\"../../../people/yagami-takuya.html#sc-yagami-takuya-y2v4-p121-1\">Yagami mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.121<\/span><span class=\"by\">notes on <a href=\"../../../people/yagami-takuya.html\">Yagami Takuya<\/a><\/span><\/h3><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “Housen was summoned by Takahashi, Yagami, Tsubaki, and Utomiya...” — Nanase&#x27;s report; the first-years&#x27; coalition behind the day-12 play.<span class=\"pg\">p.121<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “There is also the possibility that someone like Yagami or Takahashi is pulling the strings behind the scenes.” — Ayanokōji.<span class=\"pg\">p.121<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yagami-takuya-y2v4-p141-1\">→ After: Ch.5: The insurance tablet<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v4-p123-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"shiina-hiyori ishizaki-daichi nishino-takeko ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 4  the quiet morning  the empty leak at 6 00 am he checks gps   nothing unusual among the first years  he walks with hiyori s merged group on the twelfth day  hiyori confides she is scared  they part at the designated area junction   ayanokouji kun  do you ever feel lonely being in the exam   not especially  i feel more comfortable   i think   it s a bit lonely and scary   scared  huh  i can t imagine hiyori being scared   but i m still pretty scared  you know  that is why i am sincerely impressed with ayanokouji kun   surely   living on an uninhabited island alone is   impossible for me   they are very close  don t they   you re thinking about it a lot   i do not think so at all  you are the one who is so obsessed with ayanokouji kun   well  what can i say    we are on the same wavelength   i don t think you are on the same wavelength  i don t think anyone is on the same wavelength as you   that s not true  ishizaki kun has a determined look   it is what it is  i can t answer any more questions   so yes  in any case  it s good that shiina san praises you   oh yeah  i don t know what it is  but i don t feel bad about being praised   that s all for now  ayanokouji  see you later   ah  there are only a few days left  so don t lose your temper  the nanase information produced no freshmen movements  either the information leak was pointed out or the plan was postponed  day thirteen will be hot too  after missing two random designated zones in a row  he is down to 16th place  the last day will decide everything  she confides she is scared  they part on good terms","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v4-p123-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v4-p123-1\">Ch.4: The quiet morning; the empty leak<\/a><\/span><span class=\"meta\">Y2V4 · p.123–125<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">At 6:00 AM he checks GPS — nothing unusual among the first-years; he walks with Hiyori&#x27;s merged group on the twelfth day; Hiyori confides she is scared; they part at the designated-area junction.<\/p><p class=\"with\">with <a href=\"../../../people/shiina-hiyori.html\">Shiina Hiyori<\/a> · <a href=\"../../../people/ishizaki-daichi.html\">Ishizaki Daichi<\/a> · <a href=\"../../../people/nishino-takeko.html\">Nishino Takeko<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Shiina Hiyori<\/b> “Ayanokouji-kun, do you ever feel lonely being in the exam?”<span class=\"pg\">p.123<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Not especially. I feel more comfortable.”<span class=\"pg\">p.123<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Shiina Hiyori<\/b> “I think ...... It&#x27;s a bit lonely and scary.”<span class=\"pg\">p.123<\/span><\/li><\/ul><details class=\"more\"><summary>17 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Scared, huh? I can&#x27;t imagine Hiyori being scared.”<span class=\"pg\">p.123<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But I&#x27;m still pretty scared, you know. That is why I am sincerely impressed with Ayanokouji-kun.”<span class=\"pg\">p.123<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Surely ... living on an uninhabited island alone is ... impossible for me.”<span class=\"pg\">p.123<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “They are very close. Don&#x27;t they?”<span class=\"pg\">p.124<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You&#x27;re thinking about it a lot.”<span class=\"pg\">p.124<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I do not think so at all. You are the one who is so obsessed with Ayanokouji-kun.”<span class=\"pg\">p.124<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, what can I say? ... We are on the same wavelength.”<span class=\"pg\">p.124<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t think you are on the same wavelength. I don&#x27;t think anyone is on the same wavelength as you.”<span class=\"pg\">p.124<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That&#x27;s not true. Ishizaki-kun has a determined look.”<span class=\"pg\">p.124<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It is what it is. I can&#x27;t answer any more questions.”<span class=\"pg\">p.124<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “...So yes. In any case, it&#x27;s good that Shiina-san praises you.”<span class=\"pg\">p.125<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Oh yeah! I don&#x27;t know what it is, but I don&#x27;t feel bad about being praised!”<span class=\"pg\">p.125<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That&#x27;s all for now, Ayanokouji. See you later.”<span class=\"pg\">p.125<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ah. There are only a few days left, so don&#x27;t lose your temper.”<span class=\"pg\">p.125<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The Nanase information produced no freshmen movements; either the information leak was pointed out or the plan was postponed; day thirteen will be hot too.<span class=\"pg\">p.125<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> After missing two random designated zones in a row, he is down to 16th place; the last day will decide everything.<span class=\"pg\">p.125<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiina Hiyori<\/b> She confides she is scared; they part on good terms.<span class=\"pg\">p.123–125<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p120-1\">← Before: Ch.4: 2:30 a.m.; Nanase&#x27;s warning<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p126-1\">→ After: Ch.5: The siege from outside (mention records)<\/button><\/div><\/article>"},{"i":"sc-shiina-hiyori-y2v4-p123-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"ayanokouji-kiyotaka ishizaki-daichi nishino-takeko shiina-hiyori","q":"shiina hiyori ch 4  her quiet question  the parting walking beside him on the twelfth day  she confides she is scared   living alone on an uninhabited island feels impossible to her  he is the example she studies   ayanokouji kun  do you ever feel lonely being in the exam   not especially  i feel more comfortable   i think   it s a bit lonely and scary   scared  huh  i can t imagine hiyori being scared   but i m still pretty scared  you know  that is why i am sincerely impressed with ayanokouji kun   surely   living on an uninhabited island alone is   impossible for me   they are very close  don t they   why don t they go out  they can be couples and that s how ayanokoji comes to our class  right   you re thinking about it a lot   it s funny  isn t it  ishizaki kun   i do not think so at all  you are the one who is so obsessed with ayanokouji kun   well  what can i say    we are on the same wavelength   i don t think you are on the same wavelength  i don t think anyone is on the same wavelength as you   that s not true  ishizaki kun has a determined look   what do you mean   it is what it is  i can t answer any more questions   so yes  in any case  it s good that shiina san praises you   oh yeah  i don t know what it is  but i don t feel bad about being praised   that s all for now  ayanokouji  see you later   ah  there are only a few days left  so don t lose your temper  scared of the island  more impressed by ayanokoji than she shows  deflects ishizaki s couple theory with light laughter  parts with him with warmth  her private benchmark  he keeps walking with her brother s group pair down the path  laughs him off  she lets the couple talk slide","h":"<article class=\"card\" id=\"sc-shiina-hiyori-y2v4-p123-1\"><h3><span class=\"ttl\"><a href=\"../../../people/shiina-hiyori.html#sc-shiina-hiyori-y2v4-p123-1\">Ch.4: Her quiet question; the parting<\/a><\/span><span class=\"meta\">Y2V4 · p.123–125<\/span><span class=\"by\">notes on <a href=\"../../../people/shiina-hiyori.html\">Shiina Hiyori<\/a><\/span><\/h3><p class=\"setup\">Walking beside him on the twelfth day, she confides she is scared — living alone on an uninhabited island feels impossible to her; he is the example she studies.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/ishizaki-daichi.html\">Ishizaki Daichi<\/a> · <a href=\"../../../people/nishino-takeko.html\">Nishino Takeko<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Shiina Hiyori<\/b> “Ayanokouji-kun, do you ever feel lonely being in the exam?”<span class=\"pg\">p.123<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Not especially. I feel more comfortable.”<span class=\"pg\">p.123<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Shiina Hiyori<\/b> “I think ...... It&#x27;s a bit lonely and scary.”<span class=\"pg\">p.123<\/span><\/li><\/ul><details class=\"more\"><summary>20 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Scared, huh? I can&#x27;t imagine Hiyori being scared.”<span class=\"pg\">p.123<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But I&#x27;m still pretty scared, you know. That is why I am sincerely impressed with Ayanokouji-kun.”<span class=\"pg\">p.123<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Surely ... living on an uninhabited island alone is ... impossible for me.”<span class=\"pg\">p.123<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “They are very close. Don&#x27;t they?”<span class=\"pg\">p.124<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Why don&#x27;t they go out? They can be couples and that&#x27;s how Ayanokoji comes to our class, right?”<span class=\"pg\">p.124<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You&#x27;re thinking about it a lot.”<span class=\"pg\">p.124<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It&#x27;s funny, isn&#x27;t it, Ishizaki-kun?”<span class=\"pg\">p.124<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I do not think so at all. You are the one who is so obsessed with Ayanokouji-kun.”<span class=\"pg\">p.124<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, what can I say? ... We are on the same wavelength.”<span class=\"pg\">p.124<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t think you are on the same wavelength. I don&#x27;t think anyone is on the same wavelength as you.”<span class=\"pg\">p.124<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That&#x27;s not true. Ishizaki-kun has a determined look.”<span class=\"pg\">p.124<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What do you mean?”<span class=\"pg\">p.124<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It is what it is. I can&#x27;t answer any more questions.”<span class=\"pg\">p.124<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “...So yes. In any case, it&#x27;s good that Shiina-san praises you.”<span class=\"pg\">p.125<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Oh yeah! I don&#x27;t know what it is, but I don&#x27;t feel bad about being praised!”<span class=\"pg\">p.125<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That&#x27;s all for now, Ayanokouji. See you later.”<span class=\"pg\">p.125<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ah. There are only a few days left, so don&#x27;t lose your temper.”<span class=\"pg\">p.125<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Scared of the island, more impressed by Ayanokōji than she shows; deflects Ishizaki&#x27;s couple-theory with light laughter; parts with him with warmth.<span class=\"pg\">p.123–125<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Her private benchmark; he keeps walking with her brother&#x27;s-group pair down the path.<span class=\"pg\">p.123–125<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishizaki Daichi<\/b> Laughs him off; she lets the couple-talk slide.<span class=\"pg\">p.124–125<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-shiina-hiyori-y2v4-p116-1\">← Before: Ch.4: The sunset circle; six members<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v4-p126-1","v":"y2v4","y":2,"o":19,"k":"","w":"ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 5  the siege from outside  mention records   nanase left ayanokouji    the timeline resumes the day after nanase s departure   you seem to have had a lot of fun with ayanokouji  how have you been    hosen to nanase   it was a mistake for me to try to expel ayanokouji kun by myself  so i have come to ask for housen kun s help    nanase   busy is   you are trying to expel ayanokouji senpai    tsubaki to hosen   but how do you plan to expel him    tsubaki   defeat ayanokouji senpai  right    tsubaki   well  it s the only way    hosen   i have no right to stop you if you are willing to    utomiya   ayanokouji s camp is on e5  the first years are camped in d4 and e6    tsubaki s gps screenshot   tsubaki san  can we talk    yagami  the insurance tablet is aimed at ayanokoji   how can you be sure that this tablet really is from the same box as ayanokouji    yagami   if i manage to get ayanokouji senpai out with this insurance  what if i get 5 million points    yagami","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v4-p126-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v4-p126-1\">Ch.5: The siege from outside (mention records)<\/a><\/span><span class=\"meta\">Y2V4 · p.126–149<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><details class=\"more\"><summary>12 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “Nanase left Ayanokouji.” — the timeline resumes the day after Nanase’s departure.<span class=\"pg\">p.126<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “you seem to have had a lot of fun with Ayanokouji, how have you been?” — Hōsen to Nanase.<span class=\"pg\">p.126<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “It was a mistake for me to try to expel Ayanokouji-kun by myself. So I have come to ask for Housen-kun’s help.” — Nanase.<span class=\"pg\">p.127<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Busy is ...... you are trying to expel Ayanokouji-senpai?” — Tsubaki to Hōsen.<span class=\"pg\">p.134<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “but how do you plan to expel him?” — Tsubaki.<span class=\"pg\">p.134<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “defeat Ayanokouji-senpai, right?” — Tsubaki.<span class=\"pg\">p.136<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Well, it’s the only way.” — Hōsen.<span class=\"pg\">p.136<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “I have no right to stop you if you are willing to.” — Utomiya.<span class=\"pg\">p.138<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Ayanokouji’s camp is on E5; the first years are camped in D4 and E6.” — Tsubaki’s GPS screenshot.<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Tsubaki-san, can we talk?” — Yagami; the insurance tablet is aimed at Ayanokōji.<span class=\"pg\">p.141<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “How can you be sure that this tablet really is from the same box as Ayanokouji?” — Yagami.<span class=\"pg\">p.144<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “If I manage to get Ayanokouji-senpai out with this insurance, what if I get 5 million points...” — Yagami.<span class=\"pg\">p.145<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p123-1\">← Before: Ch.4: The quiet morning; the empty leak<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p142-1\">→ After: AK mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-housen-kazuomi-y2v4-p126-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"nanase-tsubasa katagiri utomiya-riku tsubaki-sakurako yagami-takuya housen-kazuomi","q":"hosen kazuomi ch 5  the negotiation  the stalking invitation alone in his tent at 7 a m  on day nine  hosen gets a visit from his groupmate nanase  he ridicules her body and her  woman s weapon  she pivots to asking his help against ayanokoji senpai   it s me  nanase   good morning  housen kun   what do you mean  we are a group and it is not unnatural for us to make contact   there is no  i was no match for him   a woman s weapon   i do not know what you re talking about   well  i really don t understand the relationship between the size of my breasts and my head   it was a mistake for me to try to expel ayanokouji kun by myself  so i have come to ask for housen kun s help  if you have a plan  let me hear it    i ll wait until you change your mind   it seems we have a visitor   huh    from class c  i m katagiri   i ll talk to him for you  what happens   i have brought something that i have to give to housen kun   here  take this  you can talk to utomiya kun   hah  you want to contact me through a little boy   i don t know if you are not aware of it or if you are ignoring it  but this is your first and last chance  okay   has someone told you  how funny you are   if you want to say no  say no  i m only discussing this to make sense  and i originally thought we could do this without you   then that s it  i will reject it   wait a minute  no one said anything about not cooperating   if you come here and beg me on your knees  i ll give you a hand  okay   i see  and   we should have a strategy to rescue the freshmen  1st year  soon   will you save the first years   ha  i don t care if those garbages disappear  don t tell me that this guy thinks i m going to make a move to save my classmates   just for fun  do i send errand boy  katagiri  back half dead   i m going to keep this for you  okay   there is a way to forcibly rescue groups from their situation  to do this  you will need as many helpers as possible  since it seems that those above are already using the same strategy  and we also need the help of the first year d class     i would love to help  but i have things to do  i m very busy   busy is   you are trying to expel ayanokouji senpai   the organizers of this test have made a proposal  they said they wouldn t mind bringing you down with an act of violence  housen kun  you are planning to forcibly defeat ayanokouji senpai  right   well  it s the only way   would they cross such a dangerous bridge  i don t think they work for free  much less utomiya   that voice came from the other side of the walkie talkie    utomiya s voice leaks into the walkie talkie  tsubaki deliberately releases the talk button to signal secrecy   do you mean that only you came up with the plan to violently withdraw ayanokouji  tsubaki   that is a question   if we follow you  no one will be expelled from our first year  can you guarantee it   i promise  and if something happens  i ll take the blame   sounds like a woman who can t eat   what will we do   we can do whatever we want  and the blame falls entirely on tsubaki  the ringleader  it s too good to be true   well  it s welcome  anyway  that s it    i m willing to help   because i want to protect the first year d class group too  please let me be by your side until i get more information from tsubaki san   do whatever you want  mocks his groupmate s body  plans to crush ayanokoji senpai with his own hands regardless of tsubaki s carrot   he s already decided hands on  his smiles grow creepier as the plan gets bloodier  lets nanase stay close so she can gather tsubaki s info   the two play along for private reasons  his groupmate  he mocks her but lets her shadow him  he threatens the errand boy with a beating  the walkie talkie ends up in his pocket  pretends to cooperate  secretly intends to do it alone with violence against ayanokoji senpai  negotiates over the walkie talkie  utomiya warns him not to touch katagiri  utomiya observes the conversation from the walkie talkie","h":"<article class=\"card\" id=\"sc-housen-kazuomi-y2v4-p126-1\"><h3><span class=\"ttl\"><a href=\"../../../people/housen-kazuomi.html#sc-housen-kazuomi-y2v4-p126-1\">Ch.5: The negotiation; the stalking invitation<\/a><\/span><span class=\"meta\">Y2V4 · p.126–139<\/span><span class=\"by\">notes on <a href=\"../../../people/housen-kazuomi.html\">Hōsen Kazuomi<\/a><\/span><\/h3><p class=\"setup\">Alone in his tent at 7 a.m. on day nine, Hōsen gets a visit from his groupmate Nanase; he ridicules her body and her &quot;woman&#x27;s weapon&quot;; she pivots to asking his help against Ayanokōji-senpai.<\/p><p class=\"with\">with <a href=\"../../../people/nanase-tsubasa.html\">Nanase Tsubasa<\/a> · <a href=\"../../../people/index.html#katagiri\">Katagiri<\/a> · <a href=\"../../../people/utomiya-riku.html\">Utomiya Riku<\/a> · <a href=\"../../../people/tsubaki-sakurako.html\">Tsubaki Sakurako<\/a> · <a href=\"../../../people/yagami-takuya.html\">Yagami Takuya<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> “It&#x27;s me, Nanase.”<span class=\"pg\">p.126<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> “Good morning, Housen-kun.”<span class=\"pg\">p.126<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> “What do you mean? We are a group and it is not unnatural for us to make contact.”<span class=\"pg\">p.126<\/span><\/li><\/ul><details class=\"more\"><summary>48 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “There is no .......I was no match for him.”<span class=\"pg\">p.126<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “A woman&#x27;s weapon.....?”<span class=\"pg\">p.126<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I do not know what you&#x27;re talking about”,<span class=\"pg\">p.127<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, I really don&#x27;t understand the relationship between the size of my breasts and my head.”<span class=\"pg\">p.127<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It was a mistake for me to try to expel Ayanokouji-kun by myself. So I have come to ask for Housen-kun&#x27;s help. If you have a plan, let me hear it.”<span class=\"pg\">p.127<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “...... I&#x27;ll wait until you change your mind.”<span class=\"pg\">p.127<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It seems we have a visitor.”<span class=\"pg\">p.128<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Huh, ...... from class C. I&#x27;m Katagiri.”<span class=\"pg\">p.128<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;ll talk to him for you. What happens?”<span class=\"pg\">p.128<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I have brought something that I have to give to Housen-kun.”<span class=\"pg\">p.128<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Here, take this. You can talk to Utomiya-kun.”<span class=\"pg\">p.128<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Hah. You want to contact me through a little boy.”<span class=\"pg\">p.128<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t know if you are not aware of it or if you are ignoring it, but this is your first and last chance, okay?”<span class=\"pg\">p.129<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Has someone told you? How funny you are.”<span class=\"pg\">p.130<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If you want to say no, say no. I&#x27;m only discussing this to make sense, and I originally thought we could do this without you.”<span class=\"pg\">p.130<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Then that&#x27;s it. I will reject it.”<span class=\"pg\">p.130<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Wait a minute. No one said anything about not cooperating.”<span class=\"pg\">p.130<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If you come here and beg me on your knees, I&#x27;ll give you a hand, okay?”<span class=\"pg\">p.130<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I see. And?”<span class=\"pg\">p.131<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “We should have a strategy to rescue the freshmen (1st year) soon.”<span class=\"pg\">p.131<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Will you save the first years?”<span class=\"pg\">p.131<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ha, I don&#x27;t care if those garbages disappear. Don&#x27;t tell me that this guy thinks I&#x27;m going to make a move to save my classmates?”<span class=\"pg\">p.131<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Just for fun, do I send errand boy ‘Katagiri’ back half dead?”<span class=\"pg\">p.132<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;m going to keep this for you, okay?”<span class=\"pg\">p.133<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There is a way to forcibly rescue groups from their situation. To do this, you will need as many helpers as possible. Since it seems that those above are already using the same strategy, and we also need the help of the first year D-class. ”<span class=\"pg\">p.134<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I would love to help, but I have things to do. I&#x27;m very busy.”<span class=\"pg\">p.134<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Busy is ...... you are trying to expel Ayanokouji-senpai?”<span class=\"pg\">p.135<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The organizers of this test have made a proposal. They said they wouldn&#x27;t mind bringing you down with an act of violence. Housen-kun, you are planning to forcibly defeat Ayanokouji-senpai, right?”<span class=\"pg\">p.136<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, it&#x27;s the only way.”<span class=\"pg\">p.136<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Would they cross such a dangerous bridge? I don&#x27;t think they work for free, much less Utomiya”<span class=\"pg\">p.136<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> &quot;That voice came from the other side of the walkie-talkie...&quot; — Utomiya&#x27;s voice leaks into the walkie-talkie; Tsubaki deliberately releases the talk button to signal secrecy.<span class=\"pg\">p.137<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Do you mean that only you came up with the plan to violently withdraw Ayanokouji? Tsubaki.”<span class=\"pg\">p.138<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That is a question?”<span class=\"pg\">p.138<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If we follow you, no one will be expelled from our first year. Can you guarantee it?”<span class=\"pg\">p.138<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I promise. And if something happens, I&#x27;ll take the blame.”<span class=\"pg\">p.138<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Sounds like a woman who can&#x27;t eat.”<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What will we do?”<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “We can do whatever we want, and the blame falls entirely on Tsubaki, the ringleader. It&#x27;s too good to be true.”<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, it&#x27;s welcome. Anyway, that&#x27;s it.”<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “...... I&#x27;m willing to help”<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Because I want to protect the first year D-class group too. Please let me be by your side until I get more information from Tsubaki-san.”<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Do whatever you want.”<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Mocks his groupmate&#x27;s body; plans to crush Ayanokōji-senpai with his own hands regardless of Tsubaki&#x27;s carrot — he&#x27;s already decided hands-on; his smiles grow creepier as the plan gets bloodier; lets Nanase stay close so she can gather Tsubaki&#x27;s info — the two play along for private reasons.<span class=\"pg\">p.126–139<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nanase Tsubasa<\/b> His groupmate; he mocks her but lets her shadow him.<span class=\"pg\">p.126–139<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Katagiri<\/b> He threatens the errand boy with a beating; the walkie-talkie ends up in his pocket.<span class=\"pg\">p.128–133<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsubaki Sakurako<\/b> Pretends to cooperate; secretly intends to do it alone with violence against Ayanokōji-senpai.<span class=\"pg\">p.126–139<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Utomiya Riku<\/b> Negotiates over the walkie-talkie; Utomiya warns him not to touch Katagiri.<span class=\"pg\">p.128–133<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yagami Takuya<\/b> Utomiya observes the conversation from the walkie-talkie.<span class=\"pg\">p.136<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-housen-kazuomi-y2v4-p120-1\">← Before: Ch.4: The feigning cooperator<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-housen-kazuomi-y2v4-p168-1\">→ After: Hōsen&#x27;s trap and his brutal fight with Ryūen<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v4-p126-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"housen-kazuomi tsubaki-sakurako nanase-tsubasa","q":"nanase tsubasa ch 5  the tent at day nine  the insult over her figure a shadow falls beside hosen s tent  she approaches as his groupmate to ask for housen s help with ayanokoji senpai  he mocks her body before listening   good morning  housen kun   oh   it s me  nanase   i know from your voice  what are you doing here   what do you mean  we are a group and it is not unnatural for us to make contact   i don t know if you can say that  you seem to have had a lot of fun with ayanokouji  how have you been   there is no  i was no match for him   ha  you didn t even use your woman s weapon to challenge him head on  did you   a woman s weapon   i do not know what you re talking about   you have big breasts  but you don t have any brain   well  i really don t understand the relationship between the size of my breasts and my head   it s enough  and that  did you come here just to make that report   it was a mistake for me to try to expel ayanokouji kun by myself  so i have come to ask for housen kun s help  if you have a plan  let me hear it   leave it  i ll do it myself    i ll wait until you change your mind   go to the designated area  for god s sake  the only thing you can do is avoid a penalty   it seems we have a visitor   i don t know what you re talking about  after the negotiation concludes  she reveals she stayed to tail him   and asks to be by his side until she learns more from tsubaki san  this would require repeated gps searches  he decided that if tsubaki was going to provide him with all these things  it would be in her best interest to do so   because i want to protect the first year d class group too  please let me be by your side until i get more information from tsubaki san   do whatever you want  she follows hosen relentlessly to tail tsubaki  hosen mocks her body  she stays close to the action   and reports back through the walkie talkie to ayanokoji  her group leader  he tolerates her shadowing him  her stakeout target   the information she wants","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v4-p126-1\"><h3><span class=\"ttl\"><a href=\"../../../people/nanase-tsubasa.html#sc-nanase-tsubasa-y2v4-p126-1\">Ch.5: The tent at day nine; the insult over her figure<\/a><\/span><span class=\"meta\">Y2V4 · p.126–133<\/span><span class=\"by\">notes on <a href=\"../../../people/nanase-tsubasa.html\">Nanase Tsubasa<\/a><\/span><\/h3><p class=\"setup\">A shadow falls beside Hōsen&#x27;s tent; she approaches as his groupmate to ask for Housen&#x27;s help with Ayanokōji-senpai; he mocks her body before listening. After the negotiation concludes, she reveals she stayed to tail him — and asks to be by his side until she learns more from Tsubaki-san.<\/p><p class=\"with\">with <a href=\"../../../people/housen-kazuomi.html\">Hōsen Kazuomi<\/a> · <a href=\"../../../people/tsubaki-sakurako.html\">Tsubaki Sakurako<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> “Good morning, Housen-kun.”<span class=\"pg\">p.126<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hōsen Kazuomi<\/b> “Oh?”<span class=\"pg\">p.126<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> “It&#x27;s me, Nanase.”<span class=\"pg\">p.126<\/span><\/li><\/ul><details class=\"more\"><summary>22 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “I know from your voice. What are you doing here?”<span class=\"pg\">p.126<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What do you mean? We are a group and it is not unnatural for us to make contact.”<span class=\"pg\">p.126<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t know if you can say that. You seem to have had a lot of fun with Ayanokouji, how have you been?”<span class=\"pg\">p.126<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There is no .......I was no match for him.”<span class=\"pg\">p.126<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ha, you didn&#x27;t even use your woman&#x27;s weapon to challenge him head on, did you?”<span class=\"pg\">p.126<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “A woman&#x27;s weapon.....?”<span class=\"pg\">p.126<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I do not know what you&#x27;re talking about”,<span class=\"pg\">p.127<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You have big breasts, but you don&#x27;t have any brain.”<span class=\"pg\">p.127<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, I really don&#x27;t understand the relationship between the size of my breasts and my head.”<span class=\"pg\">p.127<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It&#x27;s enough. And that? Did you come here just to make that report?”<span class=\"pg\">p.127<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It was a mistake for me to try to expel Ayanokouji-kun by myself. So I have come to ask for Housen-kun&#x27;s help. If you have a plan, let me hear it.”<span class=\"pg\">p.127<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Leave it, I&#x27;ll do it myself.”<span class=\"pg\">p.127<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “...... I&#x27;ll wait until you change your mind.”<span class=\"pg\">p.127<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Go to the designated area, for God&#x27;s sake. The only thing you can do is avoid a penalty.”<span class=\"pg\">p.127<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It seems we have a visitor.”<span class=\"pg\">p.128<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t know what you&#x27;re talking about”,<span class=\"pg\">p.127<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> This would require repeated GPS searches. He decided that if Tsubaki was going to provide him with all these things, it would be in her best interest to do so.<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Because I want to protect the first year D-class group too. Please let me be by your side until I get more information from Tsubaki-san.”<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Do whatever you want.”<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> She follows Hōsen relentlessly to tail Tsubaki; Hōsen mocks her body; she stays close to the action — and reports back through the walkie-talkie to Ayanokōji.<span class=\"pg\">p.126–139<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> Her group leader; he tolerates her shadowing him.<span class=\"pg\">p.126–139<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsubaki Sakurako<\/b> Her stakeout target — the information she wants.<span class=\"pg\">p.129–139<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v4-p120-1\">← Before: Ch.4: 2:30 a.m.; Nanase&#x27;s warning<\/button><\/div><\/article>"},{"i":"sc-tsubaki-sakurako-y2v4-p126-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"nanase-tsubasa housen-kazuomi utomiya-riku yagami-takuya tsubaki-sakurako","q":"tsubaki sakurako ch 5  the deal with hosen on day nine  tsubaki calls hosen on the walkie talkie to pitch a rescue plan for the sinking first year groups and an attack on ayanokoji  satoru like tsubaki stays calm  she intends to sacrifice herself if necessary   it s   because we need you to save us    tsubaki   are you saying you don t trust utomiya    utomiya   no  only with housen kun  it is a known fact that the two of you are on bad terms  and i am not willing to let the negotiations break out of unnecessary emotion    tsubaki   you already know that  right  four of the last ten groups are freshmen  also  the second group is first year d class  if the special exams end like this  the damage done to us freshmen and to housen kun s class will be great     one thing before answering  you re sure nanase is on our side  right     just so you know in a class d full of garbage  i am someone who could be useful    nanase   yes  so don t worry  but it s the right thing to do  i m going to bail out the last four current groups  as well as all the groups that are about to sink into the last five     you seem to take your time  although it is precious time    tsubaki   just for fun  do i send errand boy  katagiri  back half dead     don t get carried away  housen  if you put a hand on katagiri  you will see it with me    utomiya   that was a bit insistent    printed untagged  nanase or utomiya  not assigned   that s how i do it  now you know    hosen   i m sorry i made you wait   can we resume our discussion    tsubaki   you threatened him  right    tsubaki   it is difficult to be weak in a fight  because it is resolved before it begins  the same thing happens to you  you know  tsubaki      hosen   it s true that i can t win a fight if i go face to face  but not here    tsubaki   the head  the brain    tsubaki   there is a way to forcibly rescue groups from their situation  to do this  you will need as many helpers as possible  since it seems that those above are already using the same strategy  and we also need the help of the first year d class     i would love to help  but i have things to do  i m very busy   busy is   you are trying to expel ayanokouji senpai    tsubaki   that s what i mean  i don t care if the trash from my class disappears    but how do you plan to expel him  even on the morning of the eighth day  ayanokouji senpai continues to work alone  and yet it is not in the last 10 groups  the only conditions for being expelled from school are  according to the regulations  the only two options for this special exam  withdraw with the group or sink to the bottom of the score      tsubaki   it s true  some of them are already running out of food      utomiya   if the first five groups are defeated  it will be practically impossible to get ayanokouji senpai out of the school  right  you may think that rescuing the first years will also help ayanokouji senpai get expelled  right      tsubaki   so saving the first years  well  that doesn t sound so bad    let s hear how you do it    hosen   as i said before  we are going to stay together as one in our grade  like all the other students in the upper grades  we will absorb the sinking groups to the bottom and pick up where we left off with the groups we can afford  if need be  i could even use my hands to take homework from the group of sophomores and juniors sinking below      tsubaki   if it were so easy to assemble  we wouldn t have any problem  right  we have class a and class b  i don t think they will help class d and class c     i don t think we should worry about that  we have already decided to cooperate with each other  i m just waiting for housen s approval    tsubaki   it is not a bad idea  but there is no guarantee that you will win with it  after all  even if you use the same strategy  the scenario will be the same  the difference in experience  the result of losing the freshmen is unshakable     so is  at this rate  we may not be able to reduce the first year s sacrifice to zero      tsubaki   that s not what you were saying  didn t you think we were going to get all the first years out    tsubaki   i thought that the moment to make a move was when everyone started to get tired  we originally planned to do it between the eighth and the tenth day of the second half of the test  but something happened that we did not expect     and good  be specific about what you want me to do for you     the organizers of this test have made a proposal  they said they wouldn t mind bringing you down with an act of violence  housen kun  you are planning to forcibly defeat ayanokouji senpai  right     well  it s the only way   but it is difficult to keep ayanokoji senpai  who is always on the move in a solitary way  until now  housen kun has not been able to fulfill that opportunity  but it is different if there is a wide siege network  tsubaki mentioned that she would take on that role     i have been investigating how many of the first year students  including utomiya and housen  trust their ability to fight or use violence and have no resistance  if you surround him well  you can block his escape routes     do you want me to help you prepare the place   yes   would they cross such a dangerous bridge  i don t think they work for free  much less utomiya   of course  people who cooperate agree to do so for 500 000 points as a reward for success  i think it is a necessary expense to reduce housen kun s participation     wait  tsubaki  violence is forbidden as a general rule  would you act accordingly just to pay them 500 000     of course  you can t ask me to do this the first day  the second half of the test has been tough  both physically and mentally  student stress is considerable  we are all in a state of conflict between our desire to be comfortable and our desire to be radical  of course  i think they feel a strong resistance to taking the first blow  that is why i want to leave the leadership to you  housen kun     there are many people who want to ignore a red light in front of them  however  it is difficult to take the first step when there are other people s eyes  but if a person starts to cross  the situation changes     at that moment  it is either fight or lose both  i will take responsibility for expelling him as the brain that gave instructions to the first graders     i don t regret this school  so i feel like i can quit right away  i ve made sure all the guys in my group have private points and half price cards   people who can self destruct are scary  i have changed my mind     originally  when the special test was disclosed  i was the one who suggested that ayanokouji senpai be kicked out  you just went along with me  didn t you  utomiya kun     i see  so it is not a coincidence     if we follow you  no one will be expelled from our first year  can you guarantee it    hosen   i promise  and if something happens  i ll take the blame     did you take the recording correctly  is it not safe to have my testimony     and that  when are you going to do it     i can t tell you yet  i cannot easily divulge that information     that s what walkie talkies are for   that s what i mean    tsubaki   i ll get in touch when the time comes  thank you    tsubaki  she walks hosen through the whole plan  the four sunken first year groups  the absorb the sinking strategy  the 500 000 point bribe  the walkie talkie relay  the recording she has him make   she volunteers as ringleader and organizer  she stays composed  she expects to quit the school regardless  recruits him as the violent muscle  he only pretends to follow  her class 1 c partner  she reveals to him only what she must  fellow plotter  his  insurance  tablets  she clocks nanase as  useful  nanase is secretly ayanokoji s ally","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y2v4-p126-1\"><h3><span class=\"ttl\"><a href=\"../../../people/tsubaki-sakurako.html#sc-tsubaki-sakurako-y2v4-p126-1\">Ch.5: The deal with Hōsen<\/a><\/span><span class=\"meta\">Y2V4 · p.126–139<\/span><span class=\"by\">notes on <a href=\"../../../people/tsubaki-sakurako.html\">Tsubaki Sakurako<\/a><\/span><\/h3><p class=\"setup\">On day nine, Tsubaki calls Hōsen on the walkie-talkie to pitch a rescue plan for the sinking first-year groups and an attack on Ayanokōji; Satoru-like Tsubaki stays calm; she intends to sacrifice herself if necessary.<\/p><p class=\"with\">with <a href=\"../../../people/nanase-tsubasa.html\">Nanase Tsubasa<\/a> · <a href=\"../../../people/housen-kazuomi.html\">Hōsen Kazuomi<\/a> · <a href=\"../../../people/utomiya-riku.html\">Utomiya Riku<\/a> · <a href=\"../../../people/yagami-takuya.html\">Yagami Takuya<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Tsubaki Sakurako<\/b> “It&#x27;s ...... because we need you to save us.” — Tsubaki.<span class=\"pg\">p.130<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Tsubaki Sakurako<\/b> “Are you saying you don&#x27;t trust Utomiya?” — Utomiya.<span class=\"pg\">p.131<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Tsubaki Sakurako<\/b> “No, only with Housen-kun. It is a known fact that the two of you are on bad terms, and I am not willing to let the negotiations break out of unnecessary emotion.” — Tsubaki.<span class=\"pg\">p.131<\/span><\/li><\/ul><details class=\"more\"><summary>59 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “You already know that, right? Four of the last ten groups are freshmen. Also, the second group is first-year D class. If the special exams end like this, the damage done to us freshmen and to Housen-kun&#x27;s class will be great. ”<span class=\"pg\">p.132<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “One thing before answering. You&#x27;re sure Nanase is on our side, right? ”<span class=\"pg\">p.132<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Just so you know in a class D full of garbage, I am someone who could be useful.” — Nanase.<span class=\"pg\">p.132<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yes. So don&#x27;t worry, but it&#x27;s the right thing to do. I&#x27;m going to bail out the last four current groups, as well as all the groups that are about to sink into the last five. ”<span class=\"pg\">p.132<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You seem to take your time, although it is precious time.” — Tsubaki.<span class=\"pg\">p.132<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Just for fun, do I send errand boy ‘Katagiri’ back half dead? ”<span class=\"pg\">p.133<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don&#x27;t get carried away, Housen. If you put a hand on Katagiri, you will see it with me.” — Utomiya.<span class=\"pg\">p.133<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That was a bit insistent.” — printed untagged; Nanase or Utomiya; not assigned.<span class=\"pg\">p.133<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That&#x27;s how I do it. Now you know”. — Hōsen.<span class=\"pg\">p.133<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;m sorry I made you wait .. Can we resume our discussion?” — Tsubaki.<span class=\"pg\">p.133<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You threatened him, right?” — Tsubaki.<span class=\"pg\">p.133<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It is difficult to be weak in a fight, because it is resolved before it begins. The same thing happens to you, you know? Tsubaki. ” — Hōsen.<span class=\"pg\">p.133<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It&#x27;s true that I can&#x27;t win a fight if I go face to face. But not here.” — Tsubaki.<span class=\"pg\">p.133<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The head, the brain.” — Tsubaki.<span class=\"pg\">p.133<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There is a way to forcibly rescue groups from their situation. To do this, you will need as many helpers as possible. Since it seems that those above are already using the same strategy, and we also need the help of the first year D-class. ”<span class=\"pg\">p.134<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I would love to help, but I have things to do. I&#x27;m very busy.”<span class=\"pg\">p.134<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Busy is ...... you are trying to expel Ayanokouji-senpai?” — Tsubaki.<span class=\"pg\">p.135<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That&#x27;s what I mean. I don&#x27;t care if the trash from my class disappears ”<span class=\"pg\">p.135<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But how do you plan to expel him? Even on the morning of the eighth day, Ayanokouji-senpai continues to work alone. And yet it is not in the last 10 groups. The only conditions for being expelled from school are, according to the regulations, the only two options for this special exam: withdraw with the group or sink to the bottom of the score. ” — Tsubaki.<span class=\"pg\">p.135<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s true. Some of them are already running out of food. ” — Utomiya.<span class=\"pg\">p.135<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If the first five groups are defeated, it will be practically impossible to get Ayanokouji-senpai out of the school, right? You may think that rescuing the first years will also help Ayanokouji-senpai get expelled, right? ” — Tsubaki.<span class=\"pg\">p.135<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So saving the first years. Well, that doesn&#x27;t sound so bad. ...... Let&#x27;s hear how you do it.” — Hōsen.<span class=\"pg\">p.135<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “As I said before, we are going to stay together as one in our grade, like all the other students in the upper grades. We will absorb the sinking groups to the bottom and pick up where we left off with the groups we can afford. If need be, I could even use my hands to take homework from the group of sophomores and juniors sinking below. ” — Tsubaki.<span class=\"pg\">p.135<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If it were so easy to assemble, we wouldn&#x27;t have any problem, right? We have Class A and Class B. I don&#x27;t think they will help Class D and Class C. ”<span class=\"pg\">p.135<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t think we should worry about that. We have already decided to cooperate with each other. I&#x27;m just waiting for Housen&#x27;s approval” — Tsubaki.<span class=\"pg\">p.135<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It is not a bad idea, but there is no guarantee that you will win with it. After all, even if you use the same strategy, the scenario will be the same. The difference in experience, the result of losing the freshmen is unshakable. ”<span class=\"pg\">p.135<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So is. At this rate, we may not be able to reduce the first year&#x27;s sacrifice to zero. ” — Tsubaki.<span class=\"pg\">p.135<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That&#x27;s not what you were saying. Didn&#x27;t you think we were going to get all the first years out?” — Tsubaki.<span class=\"pg\">p.136<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I thought that the moment to make a move was when everyone started to get tired. We originally planned to do it between the eighth and the tenth day of the second half of the test, but something happened that we did not expect. ”<span class=\"pg\">p.136<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “And good? Be specific about what you want me to do for you. ”<span class=\"pg\">p.136<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The organizers of this test have made a proposal. They said they wouldn&#x27;t mind bringing you down with an act of violence. Housen-kun, you are planning to forcibly defeat Ayanokouji-senpai, right? ”<span class=\"pg\">p.137<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, it&#x27;s the only way.”<span class=\"pg\">p.137<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But it is difficult to keep Ayanokoji-senpai, who is always on the move in a solitary way. Until now, Housen-kun has not been able to fulfill that opportunity. But it is different if there is a wide siege network. Tsubaki mentioned that she would take on that role. ”<span class=\"pg\">p.137<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I have been investigating how many of the first-year students, including Utomiya and Housen, trust their ability to fight or use violence and have no resistance. If you surround him well, you can block his escape routes. ”<span class=\"pg\">p.138<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Do you want me to help you prepare the place?”<span class=\"pg\">p.137<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yes.”<span class=\"pg\">p.137<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Would they cross such a dangerous bridge? I don&#x27;t think they work for free, much less Utomiya”<span class=\"pg\">p.137<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Of course. People who cooperate agree to do so for 500,000 points as a reward for success. I think it is a necessary expense to reduce Housen-kun&#x27;s participation. ”<span class=\"pg\">p.137<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Wait, Tsubaki, Violence is forbidden as a general rule, would you act accordingly just to pay them 500,000? ”<span class=\"pg\">p.137<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Of course, you can&#x27;t ask me to do this the first day. The second half of the test has been tough, both physically and mentally. Student stress is considerable. We are all in a state of conflict between our desire to be comfortable and our desire to be radical. Of course, I think they feel a strong resistance to taking the first blow. That is why I want to leave the leadership to you, Housen-kun. ”<span class=\"pg\">p.137<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There are many people who want to ignore a red light in front of them. However, it is difficult to take the first step when there are other people&#x27;s eyes. But if a person starts to cross, the situation changes. ”<span class=\"pg\">p.137<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “At that moment, it is either fight or lose both. I will take responsibility for expelling him as the brain that gave instructions to the first graders... ”<span class=\"pg\">p.137<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t regret this school. So I feel like I can quit right away. I&#x27;ve made sure all the guys in my group have private points and half-price cards...”<span class=\"pg\">p.137<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “People who can self-destruct are scary. I have changed my mind. ”<span class=\"pg\">p.138<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Originally, when the special test was disclosed. I was the one who suggested that Ayanokouji-senpai be kicked out. You just went along with me, didn&#x27;t you, Utomiya-kun? ”<span class=\"pg\">p.138<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I see. So it is not a coincidence. ”<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If we follow you, no one will be expelled from our first year. Can you guarantee it?” — Hōsen.<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I promise. And if something happens, I&#x27;ll take the blame. ”<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Did you take the recording correctly? Is it not safe to have my testimony? ”<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “And that? When are you going to do it? ”<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I can&#x27;t tell you yet. I cannot easily divulge that information. ”<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That&#x27;s what walkie-talkies are for.”<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That&#x27;s what I mean.” — Tsubaki.<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;ll get in touch when the time comes, thank you.” — Tsubaki.<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> She walks Hōsen through the whole plan: the four sunken first-year groups, the absorb-the-sinking strategy, the 500,000-point bribe, the walkie-talkie relay, the recording she has him make — she volunteers as ringleader and organizer; she stays composed; she expects to quit the school regardless.<span class=\"pg\">p.126–139<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> Recruits him as the violent muscle; he only pretends to follow.<span class=\"pg\">p.126–139<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Utomiya Riku<\/b> Her Class 1-C partner; she reveals to him only what she must.<span class=\"pg\">p.130–138<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yagami Takuya<\/b> Fellow plotter; his “insurance” tablets.<span class=\"pg\">p.141–147<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nanase Tsubasa<\/b> She clocks Nanase as “useful”; Nanase is secretly Ayanokōji&#x27;s ally.<span class=\"pg\">p.132<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v4-p121-1\">← Before: Tsubaki mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v4-p140-1\">→ After: Ch.5: The day-13 briefing; the insurance tablet<\/button><\/div><\/article>"},{"i":"sc-katagiri-y2v4-p128-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"housen-kazuomi utomiya-riku nanase-tsubasa katagiri","q":"katagiri katagiri  the errand boy caught between hosen and utomiya a timid class c student approaches hosen s tent unannounced  he introduces himself and says he has something to give hosen kun   a walkie talkie so he can speak with utomiya   huh    from class c  i m katagiri   i have brought something that i have to give to housen kun   here  take this  you can talk to utomiya kun  he stays near the tent while hosen conducts the negotiation over the walkie talkie  utomiya and tsubaki warn hosen not to harm him  and hosen threatens to send  errand boy katagiri  back half dead  making him shrink in fear   damn  you re boring  you should leave   but the walkie talkie   nanase persuades him to leave the walkie talkie with hosen  terrified  he runs off  nervous and out of his depth   volunteered as a go between  flinches at hosen s intimidation  and is plainly terrified of being on the receiving end of his temper  hosen looms over him  threatens to beat him  and keeps the walkie talkie  utomiya warns hosen not to lay a hand on him  she talks him into leaving the walkie talkie with hosen","h":"<article class=\"card\" id=\"sc-katagiri-y2v4-p128-1\"><h3><span class=\"ttl\">Katagiri: the errand boy caught between Hōsen and Utomiya<\/span><span class=\"meta\">Y2V4 · p.128–133<\/span><span class=\"by\">notes on <a href=\"../../../people/index.html#katagiri\">Katagiri<\/a><\/span><\/h3><p class=\"setup\">A timid Class C student approaches Hōsen&#x27;s tent unannounced; he introduces himself and says he has something to give Hōsen-kun — a walkie-talkie so he can speak with Utomiya. He stays near the tent while Hōsen conducts the negotiation over the walkie-talkie; Utomiya and Tsubaki warn Hōsen not to harm him, and Hōsen threatens to send “errand boy Katagiri” back half dead, making him shrink in fear. Nanase persuades him to leave the walkie-talkie with Hōsen; terrified, he runs off.<\/p><p class=\"with\">with <a href=\"../../../people/housen-kazuomi.html\">Hōsen Kazuomi<\/a> · <a href=\"../../../people/utomiya-riku.html\">Utomiya Riku<\/a> · <a href=\"../../../people/nanase-tsubasa.html\">Nanase Tsubasa<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Katagiri<\/b> “Huh, ...... from class C. I&#x27;m Katagiri.”<span class=\"pg\">p.128<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Katagiri<\/b> “I have brought something that I have to give to Housen-kun.”<span class=\"pg\">p.128<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Katagiri<\/b> “Here, take this. You can talk to Utomiya-kun.”<span class=\"pg\">p.128<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Damn, you&#x27;re boring. You should leave.”<span class=\"pg\">p.132<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But the walkie-talkie ...”<span class=\"pg\">p.132<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Nervous and out of his depth — volunteered as a go-between, flinches at Hōsen&#x27;s intimidation, and is plainly terrified of being on the receiving end of his temper.<span class=\"pg\">p.128–133<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> Hōsen looms over him, threatens to beat him, and keeps the walkie-talkie.<span class=\"pg\">p.128–133<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Utomiya Riku<\/b> Utomiya warns Hōsen not to lay a hand on him.<span class=\"pg\">p.132<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nanase Tsubasa<\/b> She talks him into leaving the walkie-talkie with Hōsen.<span class=\"pg\">p.133<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-katagiri-y2v4-p139-1\">→ After: Katagiri mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-utomiya-riku-y2v4-p128-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"housen-kazuomi tsubaki-sakurako yagami-takuya utomiya-riku","q":"utomiya riku ch 5  the negotiation  the scheme s inside man utomiya  class 1 c s planner  sends katagiri with the walkie talkie to hosen  he negotiates over the radio from behind the line  he insists no one must touch katagiri    i didn t want to contact you  but i can t help but do it to carry out my plan   have you forgotten the sixth day   i took that fact into account   we should have a strategy to rescue the freshmen  1st year  soon   will you save the first years   wait a minute  no one said anything about not cooperating   what the hell is    i don t know what you re talking about  but what does it have to do with me   housen   i m not going to get any help from you  am i    do not be silly  who is going to bow down to you      are you saying you don t trust utomiya   it s true  some of them are already running out of food     i thought that making bad plays was pointless   there have been some students who have withdrawn so far this week  but so far there has been no group elimination  so it will be a difficult scenario for the rest of the week  and there could be an elimination of group somewhere   that s why we have a group of reserve tablets   wait  tsubaki  violence is forbidden as a general rule  would you act accordingly just to pay them 500 000      no  rather  i thought that making bad plays was pointless  i have been observing ayanokouji in my own way  and it is not just a coincidence that he has been the subject of 20 million  i think it s because it s clearly a rarity that he was the goal  even if you try to catch him within the rules  he will surely evade you  i have no right to stop you if you are willing to     what will we do   i m not sure what to think  but i m sure there s nothing wrong with following tsubaki s strategy  in any case  she intended to crush ayanokouji even if he was alone     we can do whatever we want  and the blame falls entirely on tsubaki  the ringleader  it s too good to be true     on the other hand  doesn t it seem suspicious that she sacrifices     well  it s welcome  anyway  that s it   what are you thinking  tsubaki    no  i just wanted to talk to you before the operation took place  it may be the last conversation with tsubaki so far     why didn t you use a walkie talkie to communicate with me   i guess so  i didn t even know what he was thinking  but i don t trust him at all     do you want to see the screenshot i took of one when i ran the gps search earlier   the arrangement is perfect  just as tsubaki planned   what happens   yesterday you suddenly disappeared  and where were you   in my case it was just a mistake   hey you two  could you please not get in trouble at a time like this  after all  we are friends  right     i too have stepped out of line and i apologize    a gift    of course  tsubaki s strategy is perfect  it s an alignment that leaves no room for ants to crawl out of bounds  we are challenging with the greatest strength that we can prepare freshmen  so i don t doubt our success  but don t you think it s better to take the preventive measures you can     we do not know where the designated area of ayanokouji senpai is  so we cannot predict his movements   you mean you know   how can you be sure that this tablet really is from the same box as ayanokouji   shouldn t he be there after all  i m sure i can go one on one with ayanokouji and win    that is enough for a normal opponent  but ayanokouji is a 20 million point opponent  so he is not an ordinary player  as long as housen made the first move  he could not gain an advantage  he must make the moves he can    he is the quiet chess master behind tsubaki s plan   he encourages the violence but keeps his own hands clean  he measures ayanokoji as a 20 million point opponent  he is the only first year tsubaki trusts  his partner in the plan  they stay in sync on paper  he sent the walkie talkie  warns tsubaki to leave katagiri alone  his class b ally  they treat each other as peers","h":"<article class=\"card\" id=\"sc-utomiya-riku-y2v4-p128-1\"><h3><span class=\"ttl\"><a href=\"../../../people/utomiya-riku.html#sc-utomiya-riku-y2v4-p128-1\">Ch.5: The negotiation; the scheme&#x27;s inside man<\/a><\/span><span class=\"meta\">Y2V4 · p.128–149<\/span><span class=\"by\">notes on <a href=\"../../../people/utomiya-riku.html\">Utomiya Riku<\/a><\/span><\/h3><p class=\"setup\">Utomiya, Class 1-C&#x27;s planner, sends Katagiri with the walkie-talkie to Hōsen; he negotiates over the radio from behind the line; he insists no one must touch Katagiri.<\/p><p class=\"with\">with <a href=\"../../../people/housen-kazuomi.html\">Hōsen Kazuomi<\/a> · <a href=\"../../../people/tsubaki-sakurako.html\">Tsubaki Sakurako<\/a> · <a href=\"../../../people/yagami-takuya.html\">Yagami Takuya<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Utomiya Riku<\/b> “... I didn&#x27;t want to contact you. But I can&#x27;t help but do it to carry out my plan.”<span class=\"pg\">p.129<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Utomiya Riku<\/b> “Have you forgotten the sixth day?”<span class=\"pg\">p.130<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Utomiya Riku<\/b> “I took that fact into account”<span class=\"pg\">p.130<\/span><\/li><\/ul><details class=\"more\"><summary>42 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “We should have a strategy to rescue the freshmen (1st year) soon.”<span class=\"pg\">p.130<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Will you save the first years?”<span class=\"pg\">p.130<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Wait a minute. No one said anything about not cooperating.”<span class=\"pg\">p.130<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What the hell is ......?”<span class=\"pg\">p.130<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t know what you&#x27;re talking about, but what does it have to do with me?”<span class=\"pg\">p.131<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…Housen”.<span class=\"pg\">p.131<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;m not going to get any help from you, am I?”<span class=\"pg\">p.131<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “ Do not be silly. Who is going to bow down to you? ”<span class=\"pg\">p.131<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “ Are you saying you don&#x27;t trust Utomiya?”<span class=\"pg\">p.132<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s true. Some of them are already running out of food. ”<span class=\"pg\">p.134<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…I thought that making bad plays was pointless...”<span class=\"pg\">p.135<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There have been some students who have withdrawn so far this week, but so far there has been no group elimination, so it will be a difficult scenario for the rest of the week, and there could be an elimination of group somewhere.”<span class=\"pg\">p.136<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That&#x27;s why we have a group of reserve tablets.”<span class=\"pg\">p.136<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Wait, Tsubaki, Violence is forbidden as a general rule, would you act accordingly just to pay them 500,000? ”<span class=\"pg\">p.137<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…… No. Rather, I thought that making bad plays was pointless... I have been observing Ayanokouji in my own way, and it is not just a coincidence that he has been the subject of 20 million. I think it&#x27;s because it&#x27;s clearly a rarity that he was the goal. Even if you try to catch him within the rules, he will surely evade you. I have no right to stop you if you are willing to. ”<span class=\"pg\">p.138<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What will we do?”<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;m not sure what to think, but I&#x27;m sure there&#x27;s nothing wrong with following Tsubaki&#x27;s strategy. In any case, she intended to crush Ayanokouji even if he was alone. ”<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “We can do whatever we want, and the blame falls entirely on Tsubaki, the ringleader. It&#x27;s too good to be true. ”<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “On the other hand, doesn&#x27;t it seem suspicious that she sacrifices…... ?”<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, it&#x27;s welcome. Anyway, that&#x27;s it.”<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What are you thinking? Tsubaki”<span class=\"pg\">p.140<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “ No, I just wanted to talk to you before the operation took place. It may be the last conversation with Tsubaki so far. ”<span class=\"pg\">p.140<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Why didn&#x27;t you use a walkie-talkie to communicate with me?”<span class=\"pg\">p.140<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I guess so. I didn&#x27;t even know what he was thinking, but I don&#x27;t trust him at all. ”<span class=\"pg\">p.140<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Do you want to see the screenshot I took of one when I ran the GPS search earlier?”<span class=\"pg\">p.140<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The arrangement is perfect, just as Tsubaki planned.”<span class=\"pg\">p.141<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What happens?.”<span class=\"pg\">p.141<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yesterday you suddenly disappeared, and where were you?”<span class=\"pg\">p.141<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “In my case it was just a mistake.”<span class=\"pg\">p.142<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Hey you two, could you please not get in trouble at a time like this? After all, we are friends, right? ”<span class=\"pg\">p.142<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I too have stepped out of line and I apologize.”<span class=\"pg\">p.142<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “ A gift?”<span class=\"pg\">p.142<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “ Of course, Tsubaki&#x27;s strategy is perfect. It&#x27;s an alignment that leaves no room for ants to crawl out of bounds. We are challenging with the greatest strength that we can prepare freshmen. So I don&#x27;t doubt our success. But don&#x27;t you think it&#x27;s better to take the preventive measures you can? ”<span class=\"pg\">p.142<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “We do not know where the designated area of Ayanokouji-senpai is, so we cannot predict his movements.”<span class=\"pg\">p.143<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You mean you know?”<span class=\"pg\">p.143<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “How can you be sure that this tablet really is from the same box as Ayanokouji?”<span class=\"pg\">p.144<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Shouldn&#x27;t he be there after all? I&#x27;m sure I can go one-on-one with Ayanokouji and win.”<span class=\"pg\">p.148<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “ That is enough for a normal opponent. But Ayanokouji is a 20 million point opponent, so he is not an ordinary player. As long as Housen made the first move, he could not gain an advantage, he must make the moves he can. ”<span class=\"pg\">p.148<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> He is the quiet chess master behind Tsubaki&#x27;s plan — he encourages the violence but keeps his own hands clean; he measures Ayanokōji as a 20-million-point opponent; he is the only first-year Tsubaki trusts.<span class=\"pg\">p.128–149<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsubaki Sakurako<\/b> His partner in the plan; they stay in sync on paper.<span class=\"pg\">p.128–149<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> He sent the walkie-talkie; warns Tsubaki to leave Katagiri alone.<span class=\"pg\">p.128–133<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yagami Takuya<\/b> His Class B ally; they treat each other as peers.<span class=\"pg\">p.141–149<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-utomiya-riku-y2v4-p121-1\">← Before: Utomiya mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-utomiya-riku-y2v4-p151-1\">→ After: Ch.5: The collapse; the walkie-talkie lost<\/button><\/div><\/article>"},{"i":"sc-katagiri-y2v4-p139-1","v":"y2v4","y":2,"o":19,"k":"","w":"katagiri","q":"katagiri katagiri mentioned in passing  the walkie talkie that was taken from katagiri was prepared for housen from the beginning    narration","h":"<article class=\"card\" id=\"sc-katagiri-y2v4-p139-1\"><h3><span class=\"ttl\">Katagiri mentioned in passing<\/span><span class=\"meta\">Y2V4 · p.139<\/span><span class=\"by\">notes on <a href=\"../../../people/index.html#katagiri\">Katagiri<\/a><\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “the walkie-talkie that was taken from Katagiri was prepared for Housen from the beginning.” — narration.<span class=\"pg\">p.139<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-katagiri-y2v4-p128-1\">← Before: Katagiri: the errand boy caught between Hōsen and Utomiya<\/button><\/div><\/article>"},{"i":"sc-tsubaki-sakurako-y2v4-p140-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"yagami-takuya utomiya-riku tsubaki-sakurako","q":"tsubaki sakurako ch 5  the day 13 briefing  the insurance tablet the morning of day thirteen  utomiya finds her staring at the sky  yagami arrives with an  insurance  tablet from the same box as ayanokoji s   offered for free in exchange for her success   what are you thinking  tsubaki    utomiya   i was doing a final review in my head  what do you want   no  i just wanted to talk to you before the operation took place  it may be the last conversation with tsubaki so far     why didn t you use a walkie talkie to communicate with me    utomiya   you can t know what they really think if you don t talk to them face to face  you already heard my exchange with housen so you know exactly what i mean     i guess so  i didn t even know what he was thinking  but i don t trust him at all     utomiya turned his face away  looking unhappy at the fact that she had been pointed out that way    narration   utomiya kun is the only one i can trust among the first year students  i wanted to ask you directly about the plan and for you to say what you thought    how s the preparation going    utomiya   do you want to see the screenshot i took of one when i ran the gps search earlier    tsubaki   the arrangement is perfect  just as tsubaki planned    utomiya   well  we have carefully prepared up to this point  the land is on our side     tsubaki san  can we talk   i have something i need you to hear   sorry  but wait  there is something i have to talk to yagami first    utomiya   what happens    yagami   yesterday you suddenly disappeared  and where were you    utomiya   sorry  my watch broke and i had to run back to the starting point   a malfunction  it is the second time    utomiya   it is outrageous to be suspected of conspiring just because your watch malfunctions  utomiya kun also had a clock failure a few days ago  right  doesn t that mean that you re also a suspect     hey you two  could you please not get in trouble at a time like this  after all  we are friends  right      tsubaki   as for me  i don t want to do anything irregular  but let me tell you something   from now on  tsubaki san is going to corner ayanokouji senpai while repeatedly using gps search to find out his position  but it is inevitable that she will consume a lot of points to do so  right     that s why we have a group of reserve tablets    tsubaki   but it is not very favorable that it is efficient  you know why   we do not know where the designated area of ayanokouji senpai is  so we cannot predict his movements    tsubaki   that s right  if you are able to read through ayanokouji senpai s movements if he went to a designated area  if he pursues a task or just escapes  what is the priority and what needs to be blocked  your efficiency will increase drastically       in my own way  i spent a lot of time researching to see if there was anything i could do to help  so  among the 12 squares  which squares does ayanokouji senpai belong to     you mean you know    tsubaki   yes  well  technically  it s not me  it s just this  tablet  that tells me   i borrowed it from a group of my friends from class b  first year  because the owner of this table is in the same square as ayanokouji senpai     i would appreciate it if you could lend me that tablet  considering the points that i am going to consume  i would like to refrain from wasting as much as possible  do you think it s ok   also if you do not accept this proposal  we will not be able to provide you with insurance   our first priority is to use tsubaki s strategy to pursue ayanokouji senpai and force him to retreat  however  that can end in failure for some reason  for example  if ayanokouji senpai works with a third party for the entire day  because you can t attack someone where there are other people s eyes     if something unexpected goes wrong  we switch to the method of letting them pass through the entire designated area to score points  and tomorrow  the last day  the 14th  we have three more movements  and we seal it     no  you can make them step on it up to 7 times  ayanokouji senpai s box passed a total of two times yesterday on the day 12  the third area being randomly designated d4 that went far  and then the fourth area designated d2  which they also did not step on  we have already confirmed that we have changed our focus to accept the challenge     let s say seven times  that s less than 28 points  an exaggerated score   ayanokouji senpai is still alone right now  we do not know how many points he has  but since he is alone  it will not be many  also  you can use gps search on our forays  if we get ahead of that and seal their assignments as well  there is more than enough chance that he will sink into the bottom five groups     if i manage to get ayanokouji senpai out with this insurance  what if i get 5 million points and tsubaki san and the others get 10 million points as their share  i m sure you will agree to share the remaining 5 million points with the group that failed     well  if you even have a tablet in the same box  there s no way he won t     what is that tablet    yagami   the tablet from ayanokouji senpai s box    tsubaki    what  when did you     tsubaki san you are beyond my imagination  you even came up with this insurance strategy       if so  i cannot accept the reward  i reject the 5 million points  then i ll be watching from a distance     thanks  it s honestly hard to do it when you re around people you don t trust  so i guess that helps    tsubaki   shouldn t he be there after all  i m sure i can go one on one with ayanokouji and win    utomiya   that s not good  utomiya kun is an indispensable member of the first year c class  also  there is the possibility that i will be judged in the same way when taking responsibility  leave ayanokouji senpai for the other children    tsubaki   once ayanokouji senpai s elimination is over  before the school finds out i m here  i ll defeat some independent 2nd and 3rd grade groups and let s go who i can target    tsubaki  at 7 00 am the test begins  she sends the five groups into the field  e6 group heads north  d4 group stays put  she keeps the plan tight  six gps scheduled groups plus the  insurance  tablets  she knows yagami is opportunistic  she plays along until it s too late to matter  yagami presses his own tablet  she lets him in on the box match  her only trusted first year  he is warned off a direct fight","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y2v4-p140-1\"><h3><span class=\"ttl\"><a href=\"../../../people/tsubaki-sakurako.html#sc-tsubaki-sakurako-y2v4-p140-1\">Ch.5: The day-13 briefing; the insurance tablet<\/a><\/span><span class=\"meta\">Y2V4 · p.140–149<\/span><span class=\"by\">notes on <a href=\"../../../people/tsubaki-sakurako.html\">Tsubaki Sakurako<\/a><\/span><\/h3><p class=\"setup\">The morning of day thirteen; Utomiya finds her staring at the sky; Yagami arrives with an “insurance” tablet from the same box as Ayanokōji&#x27;s — offered for free in exchange for her success.<\/p><p class=\"with\">with <a href=\"../../../people/yagami-takuya.html\">Yagami Takuya<\/a> · <a href=\"../../../people/utomiya-riku.html\">Utomiya Riku<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Tsubaki Sakurako<\/b> “What are you thinking? Tsubaki” — Utomiya.<span class=\"pg\">p.140<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Tsubaki Sakurako<\/b> “&#x27;I was doing a final review in my head. What do you want?&quot;”<span class=\"pg\">p.140<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Tsubaki Sakurako<\/b> “No, I just wanted to talk to you before the operation took place. It may be the last conversation with Tsubaki so far. ”<span class=\"pg\">p.140<\/span><\/li><\/ul><details class=\"more\"><summary>50 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Why didn&#x27;t you use a walkie-talkie to communicate with me?” — Utomiya.<span class=\"pg\">p.140<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You can&#x27;t know what they really think if you don&#x27;t talk to them face to face. You already heard my exchange with Housen so you know exactly what I mean. ”<span class=\"pg\">p.140<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I guess so. I didn&#x27;t even know what he was thinking, but I don&#x27;t trust him at all. ”<span class=\"pg\">p.140<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Utomiya turned his face away, looking unhappy at the fact that she had been pointed out that way.” — narration.<span class=\"pg\">p.140<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Utomiya-kun is the only one I can trust among the first-year students. I wanted to ask you directly about the plan and for you to say what you thought ”<span class=\"pg\">p.140<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “How&#x27;s the preparation going?” — Utomiya.<span class=\"pg\">p.140<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Do you want to see the screenshot I took of one when I ran the GPS search earlier?” — Tsubaki.<span class=\"pg\">p.140<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The arrangement is perfect, just as Tsubaki planned.” — Utomiya.<span class=\"pg\">p.141<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, we have carefully prepared up to this point. The land is on our side. ”<span class=\"pg\">p.141<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Tsubaki-san, can we talk?”<span class=\"pg\">p.141<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I have something I need you to hear.”<span class=\"pg\">p.141<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Sorry, but wait, there is something I have to talk to Yagami first.” — Utomiya.<span class=\"pg\">p.141<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What happens?.” — Yagami.<span class=\"pg\">p.141<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yesterday you suddenly disappeared, and where were you?” — Utomiya.<span class=\"pg\">p.141<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Sorry, my watch broke and I had to run back to the starting point”<span class=\"pg\">p.141<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “A malfunction? It is the second time.” — Utomiya.<span class=\"pg\">p.142<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It is outrageous to be suspected of conspiring just because your watch malfunctions. Utomiya-kun also had a clock failure a few days ago, right? Doesn&#x27;t that mean that you&#x27;re also a suspect? ”<span class=\"pg\">p.142<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Hey you two, could you please not get in trouble at a time like this? After all, we are friends, right? ” — Tsubaki.<span class=\"pg\">p.142<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “As for me, I don&#x27;t want to do anything irregular, but let me tell you something.”<span class=\"pg\">p.143<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “From now on, Tsubaki-san is going to corner Ayanokouji-senpai while repeatedly using GPS search to find out his position, but it is inevitable that she will consume a lot of points to do so, right? ”<span class=\"pg\">p.143<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That&#x27;s why we have a group of reserve tablets.” — Tsubaki.<span class=\"pg\">p.143<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But it is not very favorable that it is efficient. You know why?”<span class=\"pg\">p.143<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “We do not know where the designated area of Ayanokouji-senpai is, so we cannot predict his movements.” — Tsubaki.<span class=\"pg\">p.143<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That&#x27;s right. If you are able to read through Ayanokouji-senpai&#x27;s movements if he went to a designated area, if he pursues a task or just escapes, what is the priority and what needs to be blocked, your efficiency will increase drastically. . ”<span class=\"pg\">p.143<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “In my own way, I spent a lot of time researching to see if there was anything I could do to help. So, among the 12 squares, which squares does Ayanokouji-senpai belong to? ”<span class=\"pg\">p.143<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You mean you know?” — Tsubaki.<span class=\"pg\">p.143<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yes, well, technically, it&#x27;s not me, it&#x27;s just this &#x27;tablet&#x27; that tells me.”<span class=\"pg\">p.144<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I borrowed it from a group of my friends from class B, first year. Because the owner of this table is in the same square as Ayanokouji-senpai. ”<span class=\"pg\">p.144<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I would appreciate it if you could lend me that tablet. Considering the points that I am going to consume, I would like to refrain from wasting as much as possible. Do you think it&#x27;s OK?”<span class=\"pg\">p.144<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Also if you do not accept this proposal, we will not be able to provide you with insurance.”<span class=\"pg\">p.145<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “&#x27;Our first priority is to use Tsubaki&#x27;s strategy to pursue Ayanokouji-senpai and force him to retreat. However, that can end in failure for some reason. For example, if Ayanokouji-senpai works with a third party for the entire day. Because you can&#x27;t attack someone where there are other people&#x27;s eyes. ”<span class=\"pg\">p.145<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If something unexpected goes wrong, we switch to the method of letting them pass through the entire designated area to score points. And tomorrow, the last day, the 14th, we have three more movements, and we seal it. ”<span class=\"pg\">p.145<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No, you can make them step on it up to 7 times. Ayanokouji-senpai&#x27;s box passed a total of two times yesterday on the day 12, the third area being randomly designated D4 that went far, and then the fourth area designated D2, which they also did not step on. We have already confirmed that we have changed our focus to accept the challenge. ”<span class=\"pg\">p.145<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Let&#x27;s say seven times, that&#x27;s less than 28 points, an exaggerated score.”<span class=\"pg\">p.145<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ayanokouji-senpai is still alone right now. We do not know how many points he has, but since he is alone, it will not be many. Also, you can use GPS search on our forays. If we get ahead of that and seal their assignments as well, there is more than enough chance that he will sink into the bottom five groups. ”<span class=\"pg\">p.145<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If I manage to get Ayanokouji-senpai out with this insurance, what if I get 5 million points and Tsubaki-san and the others get 10 million points as their share? I&#x27;m sure you will agree to share the remaining 5 million points with the group that failed. ”<span class=\"pg\">p.146<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, if you even have a tablet in the same box, there&#x27;s no way he won&#x27;t. ”<span class=\"pg\">p.146<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What is that tablet?” — Yagami.<span class=\"pg\">p.146<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The tablet from Ayanokouji-senpai&#x27;s box.” — Tsubaki.<span class=\"pg\">p.146<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “ What? When did you...... ”<span class=\"pg\">p.146<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Tsubaki-san you are beyond my imagination. You even came up with this insurance strategy. ...... ”<span class=\"pg\">p.146<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If so, I cannot accept the reward, I reject the 5 million points. Then I&#x27;ll be watching from a distance. ”<span class=\"pg\">p.147<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “&#x27;Thanks, it&#x27;s honestly hard to do it when you&#x27;re around people you don&#x27;t trust, so I guess that helps.”&#x27; — Tsubaki.<span class=\"pg\">p.147<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Shouldn&#x27;t he be there after all? I&#x27;m sure I can go one-on-one with Ayanokouji and win.” — Utomiya.<span class=\"pg\">p.148<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That&#x27;s not good. Utomiya-kun is an indispensable member of the first-year C-Class. Also, there is the possibility that I will be judged in the same way when taking responsibility. Leave Ayanokouji-senpai for the other children.” — Tsubaki.<span class=\"pg\">p.148<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Once Ayanokouji-senpai&#x27;s elimination is over, Before the school finds out I&#x27;m here, I&#x27;ll defeat some independent 2nd and 3rd grade groups and let&#x27;s go who I can target.” — Tsubaki.<span class=\"pg\">p.149<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> At 7:00 AM the test begins; she sends the five groups into the field; E6 group heads north; D4 group stays put.<span class=\"pg\">p.149<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> She keeps the plan tight: six GPS-scheduled groups plus the &quot;insurance&quot; tablets; she knows Yagami is opportunistic; she plays along until it&#x27;s too late to matter.<span class=\"pg\">p.140–149<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yagami Takuya<\/b> Yagami presses his own tablet; she lets him in on the box-match.<span class=\"pg\">p.141–147<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Utomiya Riku<\/b> Her only trusted first-year; he is warned off a direct fight.<span class=\"pg\">p.140–149<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v4-p126-1\">← Before: Ch.5: The deal with Hōsen<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v4-p151-1\">→ After: Ch.5: The siege fails; the unseen commander<\/button><\/div><\/article>"},{"i":"sc-yagami-takuya-y2v4-p141-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"utomiya-riku tsubaki-sakurako yagami-takuya","q":"yagami takuya ch 5  the insurance tablet yagami approaches the first years on the morning of day thirteen to pitch his  insurance  he has a tablet from the same box as ayanokoji senpai s  borrowed from a class b first year friend   the tracking advantage  offered for free in exchange for his success   tsubaki san  can we talk   everything is ready  so at least we have time to talk       i have something i need you to hear   what happens    utomiya   yesterday you suddenly disappeared  and where were you    utomiya   sorry  my watch broke and i had to run back to the starting point   a malfunction  it is the second time    utomiya   it is outrageous to be suspected of conspiring just because your watch malfunctions  utomiya kun also had a clock failure a few days ago  right  doesn t that mean that you re also a suspect      the same happens to me   the same happens to me    duplicate row  remove   i had prepared a gift for tsubaki san regarding today s operation    a gift    tsubaki   the strategy to hunt down ayanokouji senpai hasn t always worked  right   what are you talking about  yagami  you think this operation will fail      i am not going to run an operation with the intention of failing    tsubaki   of course  tsubaki s strategy is perfect  it s an alignment that leaves no room for ants to crawl out of bounds  we are challenging with the greatest strength that we can prepare freshmen  so i don t doubt our success  but don t you think it s better to take the preventive measures you can     as for me  i don t want to do anything irregular  but let me tell you something   from now on  tsubaki san is going to corner ayanokouji senpai while repeatedly using gps search to find out his position  but it is inevitable that she will consume a lot of points to do so  right     that s why we have a group of reserve tablets   but it is not very favorable that it is efficient  you know why   we do not know where the designated area of ayanokouji senpai is  so we cannot predict his movements   that s right  if you are able to read through ayanokouji senpai s movements if he went to a designated area  if he pursues a task or just escapes  what is the priority and what needs to be blocked  your efficiency will increase drastically       in my own way  i spent a lot of time researching to see if there was anything i could do to help  so  among the 12 squares  which squares does ayanokouji senpai belong to     you mean you know   yes  well  technically  it s not me  it s just this  tablet  that tells me   i borrowed it from a group of my friends from class b  first year  because the owner of this table is in the same square as ayanokouji senpai     in other words  if you have this  you can find out ayanokouji senpai s movements today without any delay   i would appreciate it if you could lend me that tablet  considering the points that i am going to consume  i would like to refrain from wasting as much as possible  do you think it s ok   we are all in this together  tsubaki s success will lead to my success as well  also  utomiya and i have been fighting on behalf of the freshmen  but it has been difficult for us to get into the top three positions  in this situation  we have no choice but to work hard elsewhere     also if you do not accept this proposal  we will not be able to provide you with insurance   our first priority is to use tsubaki s strategy to pursue ayanokouji senpai and force him to retreat  however  that can end in failure for some reason  for example  if ayanokouji senpai works with a third party for the entire day  because you can t attack someone where there are other people s eyes     we don t have to worry about that  he s been basically on his own since the eighth day   but that doesn t mean that he is alone on 13th either   yes it s correct  and that   if something unexpected goes wrong  we switch to the method of letting them pass through the entire designated area to score points  and tomorrow  the last day  the 14th  we have three more movements  and we seal it     in other words  do you mean stepping on the penalty 5 times    utomiya   no  you can make them step on it up to 7 times  ayanokouji senpai s box passed a total of two times yesterday on the day 12  the third area being randomly designated d4 that went far  and then the fourth area designated d2  which they also did not step on  we have already confirmed that we have changed our focus to accept the challenge     let s say seven times  that s less than 28 points  an exaggerated score   ayanokouji senpai is still alone right now  we do not know how many points he has  but since he is alone  it will not be many  also  you can use gps search on our forays  if we get ahead of that and seal their assignments as well  there is more than enough chance that he will sink into the bottom five groups   well  it certainly is   if i manage to get ayanokouji senpai out with this insurance  what if i get 5 million points and tsubaki san and the others get 10 million points as their share  i m sure you will agree to share the remaining 5 million points with the group that failed     not a bad idea  don t you think  tsubaki    well  if you even have a tablet in the same box  there s no way he won t      tsubaki   the tablet from ayanokouji senpai s box    what  when did you     tsubaki san you are beyond my imagination  you even came up with this insurance strategy       then why didn t you say it   i don t like him for a moment  yagami kun had also devised the strategy of letting us pass through the designated area  i was going to pretend i didn t know what was going on  but it was so obvious     if so  i cannot accept the reward  i reject the 5 million points  then i ll be watching from a distance     thanks  it s honestly hard to do it when you re around people you don t trust  so i guess that helps  he borrows a tablet from the same box as ayanokoji senpai to track him without spending points  he pitches it as  insurance  and offers his services for free  he is turned down as distrusted  he offers to split 5 million private points  he stays at a distance  her fellow plotter  she takes his tablet and rejects his share  his class b ally  they scheme in the same group","h":"<article class=\"card\" id=\"sc-yagami-takuya-y2v4-p141-1\"><h3><span class=\"ttl\"><a href=\"../../../people/yagami-takuya.html#sc-yagami-takuya-y2v4-p141-1\">Ch.5: The insurance tablet<\/a><\/span><span class=\"meta\">Y2V4 · p.141–149<\/span><span class=\"by\">notes on <a href=\"../../../people/yagami-takuya.html\">Yagami Takuya<\/a><\/span><\/h3><p class=\"setup\">Yagami approaches the first-years on the morning of day thirteen to pitch his “insurance”: he has a tablet from the same box as Ayanokōji-senpai&#x27;s, borrowed from a Class B first-year friend — the tracking advantage, offered for free in exchange for his success.<\/p><p class=\"with\">with <a href=\"../../../people/utomiya-riku.html\">Utomiya Riku<\/a> · <a href=\"../../../people/tsubaki-sakurako.html\">Tsubaki Sakurako<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Yagami Takuya<\/b> “Tsubaki-san, can we talk?”<span class=\"pg\">p.141<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Yagami Takuya<\/b> “Everything is ready, so at least we have time to talk. ...... ”<span class=\"pg\">p.141<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Yagami Takuya<\/b> “I have something I need you to hear.”<span class=\"pg\">p.141<\/span><\/li><\/ul><details class=\"more\"><summary>50 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “What happens?.” — Utomiya.<span class=\"pg\">p.141<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yesterday you suddenly disappeared, and where were you?” — Utomiya.<span class=\"pg\">p.141<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Sorry, my watch broke and I had to run back to the starting point”<span class=\"pg\">p.141<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “A malfunction? It is the second time.” — Utomiya.<span class=\"pg\">p.142<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It is outrageous to be suspected of conspiring just because your watch malfunctions. Utomiya-kun also had a clock failure a few days ago, right? Doesn&#x27;t that mean that you&#x27;re also a suspect? ”<span class=\"pg\">p.142<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “ The same happens to me.”<span class=\"pg\">p.142<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The same happens to me.” — duplicate row, remove.<span class=\"pg\">p.142<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I had prepared a gift for Tsubaki-san regarding today&#x27;s operation.”<span class=\"pg\">p.142<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “ A gift?” — Tsubaki.<span class=\"pg\">p.142<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The strategy to hunt down Ayanokouji-senpai hasn&#x27;t always worked, right?”<span class=\"pg\">p.142<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What are you talking about, Yagami? You think this operation will fail ... ”<span class=\"pg\">p.142<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I am not going to run an operation with the intention of failing.” — Tsubaki.<span class=\"pg\">p.142<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Of course, Tsubaki&#x27;s strategy is perfect. It&#x27;s an alignment that leaves no room for ants to crawl out of bounds. We are challenging with the greatest strength that we can prepare freshmen. So I don&#x27;t doubt our success. But don&#x27;t you think it&#x27;s better to take the preventive measures you can? ”<span class=\"pg\">p.142<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “As for me, I don&#x27;t want to do anything irregular, but let me tell you something.”<span class=\"pg\">p.143<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “From now on, Tsubaki-san is going to corner Ayanokouji-senpai while repeatedly using GPS search to find out his position, but it is inevitable that she will consume a lot of points to do so, right? ”<span class=\"pg\">p.143<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That&#x27;s why we have a group of reserve tablets.”<span class=\"pg\">p.143<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But it is not very favorable that it is efficient. You know why?”<span class=\"pg\">p.143<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “We do not know where the designated area of Ayanokouji-senpai is, so we cannot predict his movements.”<span class=\"pg\">p.143<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That&#x27;s right. If you are able to read through Ayanokouji-senpai&#x27;s movements if he went to a designated area, if he pursues a task or just escapes, what is the priority and what needs to be blocked, your efficiency will increase drastically. . ”<span class=\"pg\">p.143<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “In my own way, I spent a lot of time researching to see if there was anything I could do to help. So, among the 12 squares, which squares does Ayanokouji-senpai belong to? ”<span class=\"pg\">p.143<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You mean you know?”<span class=\"pg\">p.144<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yes, well, technically, it&#x27;s not me, it&#x27;s just this &#x27;tablet&#x27; that tells me.”<span class=\"pg\">p.144<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I borrowed it from a group of my friends from class B, first year. Because the owner of this table is in the same square as Ayanokouji-senpai. ”<span class=\"pg\">p.144<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “In other words, if you have this, you can find out Ayanokouji-senpai&#x27;s movements today without any delay.”<span class=\"pg\">p.144<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I would appreciate it if you could lend me that tablet. Considering the points that I am going to consume, I would like to refrain from wasting as much as possible. Do you think it&#x27;s OK?”<span class=\"pg\">p.144<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “We are all in this together. Tsubaki&#x27;s success will lead to my success as well. Also, Utomiya and I have been fighting on behalf of the freshmen, but it has been difficult for us to get into the top three positions. In this situation, we have no choice but to work hard elsewhere. ”<span class=\"pg\">p.144<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Also if you do not accept this proposal, we will not be able to provide you with insurance.”<span class=\"pg\">p.145<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “&#x27;Our first priority is to use Tsubaki&#x27;s strategy to pursue Ayanokouji-senpai and force him to retreat. However, that can end in failure for some reason. For example, if Ayanokouji-senpai works with a third party for the entire day. Because you can&#x27;t attack someone where there are other people&#x27;s eyes. ”<span class=\"pg\">p.145<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “We don&#x27;t have to worry about that; he&#x27;s been basically on his own since the eighth day.”<span class=\"pg\">p.145<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But that doesn&#x27;t mean that he is alone on 13th either.”<span class=\"pg\">p.145<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yes it&#x27;s correct. And that?”<span class=\"pg\">p.145<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If something unexpected goes wrong, we switch to the method of letting them pass through the entire designated area to score points. And tomorrow, the last day, the 14th, we have three more movements, and we seal it. ”<span class=\"pg\">p.145<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “In other words, do you mean stepping on the penalty 5 times?” — Utomiya.<span class=\"pg\">p.145<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No, you can make them step on it up to 7 times. Ayanokouji-senpai&#x27;s box passed a total of two times yesterday on the day 12, the third area being randomly designated D4 that went far, and then the fourth area designated D2, which they also did not step on. We have already confirmed that we have changed our focus to accept the challenge. ”<span class=\"pg\">p.145<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Let&#x27;s say seven times, that&#x27;s less than 28 points, an exaggerated score.”<span class=\"pg\">p.145<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ayanokouji-senpai is still alone right now. We do not know how many points he has, but since he is alone, it will not be many. Also, you can use GPS search on our forays. If we get ahead of that and seal their assignments as well, there is more than enough chance that he will sink into the bottom five groups.”<span class=\"pg\">p.145<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, it certainly is.”<span class=\"pg\">p.146<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If I manage to get Ayanokouji-senpai out with this insurance, what if I get 5 million points and Tsubaki-san and the others get 10 million points as their share? I&#x27;m sure you will agree to share the remaining 5 million points with the group that failed. ”<span class=\"pg\">p.146<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Not a bad idea, don&#x27;t you think, Tsubaki?”<span class=\"pg\">p.146<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “ Well, if you even have a tablet in the same box, there&#x27;s no way he won&#x27;t. ” — Tsubaki.<span class=\"pg\">p.146<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The tablet from Ayanokouji-senpai&#x27;s box.”<span class=\"pg\">p.146<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “ What? When did you...... ”<span class=\"pg\">p.146<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Tsubaki-san you are beyond my imagination. You even came up with this insurance strategy. ...... ”<span class=\"pg\">p.146<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Then why didn&#x27;t you say it?”<span class=\"pg\">p.146<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t like him for a moment. Yagami-kun had also devised the strategy of letting us pass through the designated area. I was going to pretend I didn&#x27;t know what was going on, but it was so obvious. ”<span class=\"pg\">p.146<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If so, I cannot accept the reward, I reject the 5 million points. Then I&#x27;ll be watching from a distance. ”<span class=\"pg\">p.147<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “&#x27;Thanks, it&#x27;s honestly hard to do it when you&#x27;re around people you don&#x27;t trust, so I guess that helps.”&#x27;<span class=\"pg\">p.147<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> He borrows a tablet from the same box as Ayanokōji-senpai to track him without spending points; he pitches it as “insurance” and offers his services for free; he is turned down as distrusted; he offers to split 5 million private points; he stays at a distance.<span class=\"pg\">p.141–149<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsubaki Sakurako<\/b> Her fellow plotter; she takes his tablet and rejects his share.<span class=\"pg\">p.141–149<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Utomiya Riku<\/b> His Class B ally; they scheme in the same group.<span class=\"pg\">p.141–149<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yagami-takuya-y2v4-p121-1\">← Before: Yagami mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-yagami-takuya-y2v4-p151-1\">→ After: Ch.5: The failed siege; the fifth freeze<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v4-p142-1","v":"y2v4","y":2,"o":19,"k":"","w":"ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ak mentioned in passing  tsubaki san  can we talk    yagami approaches   i don t know who you are    yagami probes   it s not natural to want to drop out of school as soon as you enter school    tsubaki   i would be lying if i said i don t care    utomiya   hmm  not exactly    tsubaki   it was as yagami had said  but tsubaki felt stuck  why didn t she think that all the classes would unite to protect ayanokouji    narration   we just have to spend time attacking now  but second year students can t protect ayanokouji senpai all the time  right    yagami","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v4-p142-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v4-p142-1\">AK mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.142–157<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “Tsubaki-san, can we talk?” — Yagami approaches.<span class=\"pg\">p.142<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “I don&#x27;t know who you are?” — Yagami probes.<span class=\"pg\">p.143<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “It&#x27;s not natural to want to drop out of school as soon as you enter school.” — Tsubaki.<span class=\"pg\">p.147<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “I would be lying if I said I don&#x27;t care.” — Utomiya.<span class=\"pg\">p.148<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Hmm, not exactly.” — Tsubaki.<span class=\"pg\">p.149<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “It was as Yagami had said, but Tsubaki felt stuck. Why didn&#x27;t she think that all the classes would unite to protect Ayanokouji.” — narration.<span class=\"pg\">p.156<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “We just have to spend time attacking now, but second-year students can&#x27;t protect Ayanokouji-senpai all the time, right?” — Yagami.<span class=\"pg\">p.157<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p126-1\">← Before: Ch.5: The siege from outside (mention records)<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p151-1\">→ After: Ch.5: The siege morning; he runs south<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v4-p151-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"nanase-tsubasa tsubaki-sakurako ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 5  the siege morning  he runs south dawn of day thirteen  the gps shows the three first year named masterminds  utomiya  tsubaki  yagami  solidified at d4 e6  he knows they have his area from nanase s leak  he avoids the trap by running south  he ignores six designated areas to survive   on the move  huh   it seems that at least they know how to fight  he considers  a task would be a trap  the route south ignores bad weather and mountains  he opts to flee the designated area even if it drops him in the ranks  cool  informed  unrattled   he reads the siege from the leak and dodges it  her leak saves him  she commands the siege  her trap fails","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v4-p151-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v4-p151-1\">Ch.5: The siege morning; he runs south<\/a><\/span><span class=\"meta\">Y2V4 · p.151–152<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Dawn of day thirteen; the GPS shows the three first-year named masterminds (Utomiya, Tsubaki, Yagami) solidified at D4/E6; he knows they have his area from Nanase&#x27;s leak; he avoids the trap by running south; he ignores six designated areas to survive.<\/p><p class=\"with\">with <a href=\"../../../people/nanase-tsubasa.html\">Nanase Tsubasa<\/a> · <a href=\"../../../people/tsubaki-sakurako.html\">Tsubaki Sakurako<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “On the move, huh?”<span class=\"pg\">p.151<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “It seems that at least they know how to fight.”<span class=\"pg\">p.152<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> He considers: a task would be a trap; the route south ignores bad weather and mountains; he opts to flee the designated area even if it drops him in the ranks.<span class=\"pg\">p.151–152<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Cool, informed, unrattled — he reads the siege from the leak and dodges it.<span class=\"pg\">p.151–152<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nanase Tsubasa<\/b> Her leak saves him.<span class=\"pg\">p.151–152<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsubaki Sakurako<\/b> She commands the siege; her trap fails.<span class=\"pg\">p.151–152<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p142-1\">← Before: AK mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p153-1\">→ After: Ch.5: The GPS chase (mention records)<\/button><\/div><\/article>"},{"i":"sc-tsubaki-sakurako-y2v4-p151-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"yagami-takuya ayanokouji-kiyotaka tsubaki-sakurako","q":"tsubaki sakurako ch 5  the siege fails  the unseen commander at 7 00 am she orders the first years to close on ayanokoji  he flees south  she tracks him with 10 minute gps updates  the five groups she sent are boxed in by second years  yagami reports five frozen groups   on the move  huh    ayanokoji s interior as his group runs  not her line   if you can keep up with the movements  you will find a way to win with no contact    tsubaki   don t let him go out   it s so depressing    tsubaki   what s wrong  tsubaki san   what s wrong  tsubaki san   three of the five first year groups we sent have stopped moving  the three groups that stopped moving had one thing in common  they were all in the same position crossing paths with the sophomores     it certainly seems like a second year student is sabotaging them  but if it is   who   will it be   so you are saying that it is not just one particular class  but the entire second year that is doing the movement   these five groups do not understand why they have been ordered to stop us    tsubaki   we just have to spend time attacking now  but second year students can t protect ayanokouji senpai all the time  right  there are special tests   i think we should consider suspending the operation   i don t know who is directing everything  but i am here to show you that visual information is not everything    tsubaki   perhaps your commander has noticed the five first year groups we moved last night    tsubaki   now there is no one who can interfere  now you can do whatever you want    i told you  i told you that the information you see is not all there is    the plan collapses under the second years  coordination  she realizes ayanokoji contacted them ahead of time  she changes the search to 5 minute intervals  she pivots to leave the two following groups to their own devices  her siege is broken by his counter move  he escapes without contact  he watches her panic  she silences him","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y2v4-p151-1\"><h3><span class=\"ttl\"><a href=\"../../../people/tsubaki-sakurako.html#sc-tsubaki-sakurako-y2v4-p151-1\">Ch.5: The siege fails; the unseen commander<\/a><\/span><span class=\"meta\">Y2V4 · p.151–158<\/span><span class=\"by\">notes on <a href=\"../../../people/tsubaki-sakurako.html\">Tsubaki Sakurako<\/a><\/span><\/h3><p class=\"setup\">At 7:00 AM she orders the first-years to close on Ayanokōji; he flees south; she tracks him with 10-minute GPS updates; the five groups she sent are boxed in by second-years; Yagami reports five frozen groups.<\/p><p class=\"with\">with <a href=\"../../../people/yagami-takuya.html\">Yagami Takuya<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Tsubaki Sakurako<\/b> “If you can keep up with the movements, you will find a way to win with no contact.” — Tsubaki.<span class=\"pg\">p.153<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Tsubaki Sakurako<\/b> “Don&#x27;t let him go out.”<span class=\"pg\">p.154<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Tsubaki Sakurako<\/b> “It&#x27;s so depressing.” — Tsubaki.<span class=\"pg\">p.154<\/span><\/li><\/ul><details class=\"more\"><summary>16 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> &quot;On the move, huh?&quot; — Ayanokōji&#x27;s interior as his group runs; not her line.<span class=\"pg\">p.152<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What&#x27;s wrong, Tsubaki-san?”<span class=\"pg\">p.154<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What&#x27;s wrong, Tsubaki-san?”<span class=\"pg\">p.155<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Three of the five first-year groups we sent have stopped moving. The three groups that stopped moving had one thing in common: they were all in the same position crossing paths with the sophomores. ”<span class=\"pg\">p.155<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It certainly seems like a second year student is sabotaging them, but if it is ...... who ... will it be.”<span class=\"pg\">p.155<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So you are saying that it is not just one particular class, but the entire second year that is doing the movement?”<span class=\"pg\">p.156<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “These five groups do not understand why they have been ordered to stop us.” — Tsubaki.<span class=\"pg\">p.156<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “We just have to spend time attacking now, but second-year students can&#x27;t protect Ayanokouji-senpai all the time, right? There are special tests.”<span class=\"pg\">p.157<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I think we should consider suspending the operation.”<span class=\"pg\">p.157<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t know who is directing everything, but I am here to show you that visual information is not everything.” — Tsubaki.<span class=\"pg\">p.158<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Perhaps your commander has noticed the five first-year groups we moved last night.” — Tsubaki.<span class=\"pg\">p.158<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Now there is no one who can interfere. Now you can do whatever you want ”<span class=\"pg\">p.158<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I told you. I told you that the information you see is not all there is. ”<span class=\"pg\">p.158<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> The plan collapses under the second-years&#x27; coordination; she realizes Ayanokōji contacted them ahead of time; she changes the search to 5-minute intervals; she pivots to leave the two following groups to their own devices.<span class=\"pg\">p.151–158<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Her siege is broken by his counter-move; he escapes without contact.<span class=\"pg\">p.151–158<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yagami Takuya<\/b> He watches her panic; she silences him.<span class=\"pg\">p.154–158<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v4-p140-1\">← Before: Ch.5: The day-13 briefing; the insurance tablet<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v4-p159-1\">→ After: Tsubaki mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-utomiya-riku-y2v4-p151-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"tsubaki-sakurako yagami-takuya utomiya-riku","q":"utomiya riku ch 5  the collapse  the walkie talkie lost he is sent to hold position with the five frozen groups  the plan collapses  he drops the walkie talkie after kitou stops him  tsubaki is forced to abandon the island   it s true  but    what  did you say something   if so  i cannot accept the reward  i reject the 5 million points  then i ll be watching from a distance     not a bad idea  don t you think  tsubaki   hmm  not exactly  it is correct to say that we decided to carry out this operation because we were absolutely sure that housen kun would come on board  it seems that he was always willing to fight alone  still  if they didn t accept the case  i would just let utomiya kun go  either way  i made sure the atmosphere was perfect for one on one  now it only remains for the two to face each other  win or lose  and everything will be fine   what are you doing   what do you want on these roads   i m not going to let you pass from here   i ll tell you  i m not going to let you pass from here   didn t you follow my instructions   the objective has been reached   he went right in front of me    i ve gotten rid of that 2nd year weirdo  i should be pleased to see that tsubaki is in charge   so  how was tsubaki s plan   it failed as expected  even though ayanokouji senpai didn t bother to give advance notice  i m sure it was an old fashioned strategy that was never going to be successful from the beginning   i have to go  without inadvertently prolonging the matter  utomiya turns off the walkie talkie  very good  his walkie talkie is lost to kitou  she knows her plan has failed","h":"<article class=\"card\" id=\"sc-utomiya-riku-y2v4-p151-1\"><h3><span class=\"ttl\"><a href=\"../../../people/utomiya-riku.html#sc-utomiya-riku-y2v4-p151-1\">Ch.5: The collapse; the walkie-talkie lost<\/a><\/span><span class=\"meta\">Y2V4 · p.151–190<\/span><span class=\"by\">notes on <a href=\"../../../people/utomiya-riku.html\">Utomiya Riku<\/a><\/span><\/h3><p class=\"setup\">He is sent to hold position with the five frozen groups; the plan collapses; he drops the walkie-talkie after Kitou stops him; Tsubaki is forced to abandon the island.<\/p><p class=\"with\">with <a href=\"../../../people/tsubaki-sakurako.html\">Tsubaki Sakurako<\/a> · <a href=\"../../../people/yagami-takuya.html\">Yagami Takuya<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Utomiya Riku<\/b> “It&#x27;s true, but ......”<span class=\"pg\">p.155<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Tsubaki Sakurako<\/b> “What, did you say something?”<span class=\"pg\">p.158<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Yagami Takuya<\/b> “If so, I cannot accept the reward, I reject the 5 million points. Then I&#x27;ll be watching from a distance. ”<span class=\"pg\">p.160<\/span><\/li><\/ul><details class=\"more\"><summary>15 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Not a bad idea, don&#x27;t you think, Tsubaki?”<span class=\"pg\">p.167<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Hmm, not exactly. It is correct to say that we decided to carry out this operation because we were absolutely sure that Housen-kun would come on board. It seems that he was always willing to fight alone. Still, if they didn&#x27;t accept the case, I would just let Utomiya-kun go. Either way, I made sure the atmosphere was perfect for one-on-one. Now it only remains for the two to face each other, win or lose, and everything will be fine.”<span class=\"pg\">p.167<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What are you doing……?”<span class=\"pg\">p.185<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What do you want on these roads?”<span class=\"pg\">p.186<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;m not going to let you pass from here.”<span class=\"pg\">p.188<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;ll tell you. I&#x27;m not going to let you pass from here.”<span class=\"pg\">p.188<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Didn&#x27;t you follow my instructions?”<span class=\"pg\">p.189<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “.....The objective has been reached”<span class=\"pg\">p.189<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “He went right in front of me ..”<span class=\"pg\">p.189<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;ve gotten rid of that 2nd year weirdo. I should be pleased to see that Tsubaki is in charge.”<span class=\"pg\">p.190<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So, how was Tsubaki&#x27;s plan?”<span class=\"pg\">p.190<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It failed as expected. Even though Ayanokouji-senpai didn&#x27;t bother to give advance notice, I&#x27;m sure it was an old-fashioned strategy that was never going to be successful from the beginning.”<span class=\"pg\">p.190<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I have to go.” Without inadvertently prolonging the matter, Utomiya turns off the walkie-talkie<span class=\"pg\">p.190<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Very good.”<span class=\"pg\">p.190<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsubaki Sakurako<\/b> His walkie-talkie is lost to Kitou; she knows her plan has failed.<span class=\"pg\">p.185–190<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-utomiya-riku-y2v4-p128-1\">← Before: Ch.5: The negotiation; the scheme&#x27;s inside man<\/button><\/div><\/article>"},{"i":"sc-yagami-takuya-y2v4-p151-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"tsubaki-sakurako utomiya-riku yagami-takuya","q":"yagami takuya ch 5  the failed siege  the fifth freeze he reports from behind the lines  the five first year groups he sent freeze as the second years close in  tsubaki suspects a hidden second year commander  her plan collapses   three of the five first year groups we sent have stopped moving  the three groups that stopped moving had one thing in common  they were all in the same position crossing paths with the sophomores     it certainly seems like a second year student is sabotaging them  but if it is   who   will it be   so you re saying that it s not just one particular class that is doing this  but the entire second year class  it was as yagami had said  but tsubaki felt stuck   there are only two days left until the exam is finished  it s not strange that the other party is very attentive  i m sure you know that there is a bounty on your head  so they have probably been preparing the ground beforehand   we just have to spend time attacking now  but second year students can t protect ayanokouji senpai all the time  right  there are special tests   the other thing that worries me is that this group here is being easily mocked  although they move separately  it is not easy to capture the five groups   i don t think we should cross more dangerous bridges  if we force ourselves to help a group of people who are falling here  sooner or later they are destined to disappear   even if you force yourself to flee  you can always make up an excuse later  like you got scared because you got tangled up with the grown ups  if you had consulted me before    if you want to be tough  that s what i would say   but now that it s over  i ll tell you   it s actually the other way around   rumor has it that he has the ability similar to housen kun s  it means that he didn t want to face the current group from the beginning   the first is to find out what ayanokouji senpai is thinking  what do you like and what don t you like     he disliked contact with the early years more than going to his assigned area  he also avoided homework with the teachers and the second and third graders  what i get clear is that he has an extreme aversion to highlighting  and is willing to take a penalty to avoid it   if housen kun had not accepted this case  do you think this operation would not have been possible     i think we should consider suspending the operation    yagami   why   are you trying to force yourself to continue with this  it is dangerous   no  i won t  the five groups of students i m capturing right now can t do that     because it s the same anyway   is the same     yagami   perhaps your commander has noticed the five first year groups we moved last night  his plan runs on her tablet  he is exasperated by her tactics  she keeps him at arm s length  his class b ally  they scheme in the same group","h":"<article class=\"card\" id=\"sc-yagami-takuya-y2v4-p151-1\"><h3><span class=\"ttl\"><a href=\"../../../people/yagami-takuya.html#sc-yagami-takuya-y2v4-p151-1\">Ch.5: The failed siege; the fifth freeze<\/a><\/span><span class=\"meta\">Y2V4 · p.151–167<\/span><span class=\"by\">notes on <a href=\"../../../people/yagami-takuya.html\">Yagami Takuya<\/a><\/span><\/h3><p class=\"setup\">He reports from behind the lines; the five first-year groups he sent freeze as the second-years close in; Tsubaki suspects a hidden second-year commander; her plan collapses.<\/p><p class=\"with\">with <a href=\"../../../people/tsubaki-sakurako.html\">Tsubaki Sakurako<\/a> · <a href=\"../../../people/utomiya-riku.html\">Utomiya Riku<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Tsubaki Sakurako<\/b> “Three of the five first-year groups we sent have stopped moving. The three groups that stopped moving had one thing in common: they were all in the same position crossing paths with the sophomores. ”<span class=\"pg\">p.155<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Yagami Takuya<\/b> “It certainly seems like a second year student is sabotaging them, but if it is ...... who ... will it be.”<span class=\"pg\">p.155<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Yagami Takuya<\/b> “So you&#x27;re saying that it&#x27;s not just one particular class that is doing this, but the entire second-year class?”<span class=\"pg\">p.156<\/span><\/li><\/ul><details class=\"more\"><summary>21 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> It was as Yagami had said, but Tsubaki felt stuck.<span class=\"pg\">p.156<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There are only two days left until the exam is finished. It&#x27;s not strange that the other party is very attentive. I&#x27;m sure you know that there is a bounty on your head, so they have probably been preparing the ground beforehand.”<span class=\"pg\">p.157<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “We just have to spend time attacking now, but second-year students can&#x27;t protect Ayanokouji-senpai all the time, right? There are special tests.”<span class=\"pg\">p.157<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The other thing that worries me is that this group here is being easily mocked. Although they move separately, it is not easy to capture the five groups.”<span class=\"pg\">p.157<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t think we should cross more dangerous bridges. If we force ourselves to help a group of people who are falling here, sooner or later they are destined to disappear.”<span class=\"pg\">p.158<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Even if you force yourself to flee, you can always make up an excuse later, like you got scared because you got tangled up with the grown-ups. If you had consulted me before ”<span class=\"pg\">p.165<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If you want to be tough, that&#x27;s what I would say.”<span class=\"pg\">p.165<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But now that it&#x27;s over, I&#x27;ll tell you ...... it&#x27;s actually the other way around.”<span class=\"pg\">p.165<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Rumor has it that he has the ability similar to Housen-kun&#x27;s. It means that he didn&#x27;t want to face the current group from the beginning.”<span class=\"pg\">p.166<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The first is to find out what Ayanokouji-senpai is thinking. What do you like and what don&#x27;t you like? ”<span class=\"pg\">p.166<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “He disliked contact with the early years more than going to his assigned area. He also avoided homework with the teachers and the second and third graders. What I get clear is that he has an extreme aversion to highlighting, and is willing to take a penalty to avoid it.”<span class=\"pg\">p.166<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If Housen-kun had not accepted this case, do you think this operation would not have been possible? ”<span class=\"pg\">p.167<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I think we should consider suspending the operation.” — Yagami.<span class=\"pg\">p.167<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Why?”<span class=\"pg\">p.167<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Are you trying to force yourself to continue with this? It is dangerous.”<span class=\"pg\">p.167<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No, I won&#x27;t. The five groups of students I&#x27;m capturing right now can&#x27;t do that. ”<span class=\"pg\">p.167<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Because it&#x27;s the same anyway”<span class=\"pg\">p.167<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Is the same ......?” — Yagami.<span class=\"pg\">p.167<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Perhaps your commander has noticed the five first-year groups we moved last night.”<span class=\"pg\">p.167<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsubaki Sakurako<\/b> His plan runs on her tablet; he is exasperated by her tactics; she keeps him at arm&#x27;s length.<span class=\"pg\">p.151–167<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Utomiya Riku<\/b> His Class B ally; they scheme in the same group.<span class=\"pg\">p.151–167<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yagami-takuya-y2v4-p141-1\">← Before: Ch.5: The insurance tablet<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-yagami-takuya-y2v4-p184-1\">→ After: Yagami mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-nagumo-miyabi-y2v4-p152-1","v":"y2v4","y":2,"o":19,"k":"","w":"nagumo-miyabi","q":"nagumo miyabi nagumo mentioned in passing  the only option now is to flee until the freshmen run out of energy and give up the chase    ayanokoji s own position  nagumo is not on these pages but the third years are under nagumo s control    not only the first year students  but also the third year students  who are under nagumo s control  are the enemy","h":"<article class=\"card\" id=\"sc-nagumo-miyabi-y2v4-p152-1\"><h3><span class=\"ttl\"><a href=\"../../../people/nagumo-miyabi.html#sc-nagumo-miyabi-y2v4-p152-1\">Nagumo mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.152<\/span><span class=\"by\">notes on <a href=\"../../../people/nagumo-miyabi.html\">Nagumo Miyabi<\/a><\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “The only option now is to flee until the freshmen run out of energy and give up the chase.” — Ayanokōji&#x27;s own position; Nagumo is not on these pages but the third-years are under Nagumo&#x27;s control — “not only the first-year students, but also the third-year students, who are under Nagumo&#x27;s control, are the enemy.”<span class=\"pg\">p.152<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y2v4-p95-1\">← Before: Nagumo mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y2v4-p163-1\">→ After: Nagumo mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v4-p153-1","v":"y2v4","y":2,"o":19,"k":"","w":"ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 5  the gps chase  mention records   if you can keep up with the movements  you will find a way to win with no contact    tsubaki   9 a m  passes and ayanokouji s third step is confirmed    tsubaki s gps log   the tablet then indicated that ayanokouji s destination was d2  ayanokouji  who was fleeing towards c6 at the time    tsubaki s gps log   she instructed the group in c4 to target ayanokouji going down the mountain    tsubaki s gps log   ayanokouji tries to get out of b3  but 3 groups haven t got out of c4    tsubaki s gps log   the two groups that were chasing ayanokoji also stopped moving when they realized it    tsubaki s gps log   ayanokouji is running away  no  that s not possible    tsubaki  thinking aloud   i don t have the full strength to be able to manipulate and direct the other classes    tsubaki","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v4-p153-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v4-p153-1\">Ch.5: The GPS chase (mention records)<\/a><\/span><span class=\"meta\">Y2V4 · p.153–158<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “If you can keep up with the movements, you will find a way to win with no contact.” — Tsubaki.<span class=\"pg\">p.153<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “9 a.m. passes and Ayanokouji’s third step is confirmed.” — Tsubaki’s GPS log.<span class=\"pg\">p.153<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “the tablet then indicated that Ayanokouji’s destination was D2; Ayanokouji, who was fleeing towards C6 at the time...” — Tsubaki’s GPS log.<span class=\"pg\">p.153<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “she instructed the group in C4 to target Ayanokouji going down the mountain.” — Tsubaki’s GPS log.<span class=\"pg\">p.153<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Ayanokouji tries to get out of B3, but 3 groups haven’t got out of C4.” — Tsubaki’s GPS log.<span class=\"pg\">p.154<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “The two groups that were chasing Ayanokoji also stopped moving when they realized it.” — Tsubaki’s GPS log.<span class=\"pg\">p.155<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Ayanokouji is running away? No, that’s not possible.” — Tsubaki, thinking aloud.<span class=\"pg\">p.158<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “I don’t have the full strength to be able to manipulate and direct the other classes.” — Tsubaki.<span class=\"pg\">p.158<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p151-1\">← Before: Ch.5: The siege morning; he runs south<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p159-1\">→ After: Ch.5: The Sakayanagi bargain<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v4-p159-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"sakayanagi-arisu takemoto-shigeru tsukishiro nagumo-miyabi ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 5  the sakayanagi bargain three days earlier  on day ten at midnight  he calls sakayanagi on takemoto s walkie talkie and reveals the white room threat and nagumo s bounty  she agrees to freeze the first years in exchange for a  new favor   it seems that the classes are working well together   yes  i was able to contact ryuuen kun and horikita san  we are progressing smoothly  i haven t heard the details  but it seems that takemoto kun and the others were taken care of     your group is also making great strides  now you are in fifth place  you are in a position where you can aim high enough   not that there are no worries at all   have you seen ichinose san   no  i have not seen her even once during this exam  what happened   i got a call saying she was acting a little strange  she has been lost for several days and i am worried      so  what do you want from me   about the white room   it would have been better if you had told me before   because none of it was safe   so you want me to destroy that person named amasawa ichika   huh   actually there is one more thing  i have another big problem   i mean  in the near future  the first year students will take action against ayanokouji kun  right   that s what i mean  i want to ask sakayanagi to take care of it     but if it s the same white room student  i don t think it s possible for someone else to chase ayanokouji kun   the first years will probably try to force their entry  the most effective way to get rid of me is to exploit the fact that i am in a group completely alone  if they are in a position to do so  they will be able to block by force the assignment and  if they want to go further  obstruct movement to the designated area     i m sure you would be glad to hear it  besides  tsukishiro may be planning something   if possible  i want to focus on that     i understand the situation very well   don t worry  we already know all the scores for the group to which class a belongs   so   you ve had very close contact with them   it is very important to know which groups have problems and which groups have plenty of space  there are a number of groups that have some room for growth  but not enough to make it to the top 10  so even if you use gps search a few times per group  you can still get to the last day in plenty of time     all i have to do is stop the first years who are heading to ayanokouji kun  right   it would have been a bit boring exam just to help you complete the task  and besides  this story seems like something that could benefit me   it means that it is too big a commission for me to pay takemoto kun s debt   in other words  it will be a new   favor   right   i know it hurts to hear this  but if you get rid of them  i ll owe you a   favor    it s decided  well  then i ll get to work on my preparations   oh  and if you don t mind  can i keep this walkie talkie as a loan   of course i was going to do it anyway  it s easier to get things done if we can get in touch  then  could you return the walkie talkie to takemoto kun  i will tell the situation and tell him to give it to ayanokouji kun   well  now we have arrested the five suspicious groups  are we trying to identify the person who planned this attack    he pays for the night 10 favor with a promise of a bigger favor  he lets her in partially on the white room  he never lies about the bounty s existence   he just doesn t volunteer the rest  their bargain  she extracts a future favor  the walkie talkie relay runs through him  he reveals tsukishiro may be planning something else  the bounty is nagumo s price for tsukishiro","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v4-p159-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v4-p159-1\">Ch.5: The Sakayanagi bargain<\/a><\/span><span class=\"meta\">Y2V4 · p.159–165<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Three days earlier, on day ten at midnight, he calls Sakayanagi on Takemoto&#x27;s walkie-talkie and reveals the White Room threat and Nagumo&#x27;s bounty; she agrees to freeze the first-years in exchange for a &quot;new favor&quot;.<\/p><p class=\"with\">with <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a> · <a href=\"../../../people/takemoto-shigeru.html\">Takemoto Shigeru<\/a> · <a href=\"../../../people/tsukishiro.html\">Tsukishiro<\/a> · <a href=\"../../../people/nagumo-miyabi.html\">Nagumo Miyabi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “It seems that the classes are working well together.”<span class=\"pg\">p.161<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Yes. I was able to contact Ryuuen-kun and Horikita-san. We are progressing smoothly. I haven&#x27;t heard the details, but it seems that Takemoto-kun and the others were taken care of. ”<span class=\"pg\">p.161<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sakayanagi Arisu<\/b> “Your group is also making great strides, now you are in fifth place. You are in a position where you can aim high enough.”<span class=\"pg\">p.161<\/span><\/li><\/ul><details class=\"more\"><summary>33 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Not that there are no worries at all.”<span class=\"pg\">p.161<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Have you seen Ichinose-san?”<span class=\"pg\">p.162<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No, I have not seen her even once during this exam. What happened?”<span class=\"pg\">p.162<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I got a call saying she was acting a little strange. She has been lost for several days and I am worried ... ”<span class=\"pg\">p.162<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So, what do you want from me?”<span class=\"pg\">p.162<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “About the White Room.”<span class=\"pg\">p.163<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It would have been better if you had told me before.”<span class=\"pg\">p.163<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Because none of it was safe.”<span class=\"pg\">p.163<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So you want me to destroy that person named Amasawa Ichika?”<span class=\"pg\">p.163<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Huh?..”<span class=\"pg\">p.163<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Actually there is one more thing, I have another big problem.”<span class=\"pg\">p.163<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I mean, in the near future, the first-year students will take action against Ayanokouji-kun, right?”<span class=\"pg\">p.163<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That&#x27;s what I mean. I want to ask Sakayanagi to take care of it. ”<span class=\"pg\">p.163<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But if it&#x27;s the same White Room student, I don&#x27;t think it&#x27;s possible for someone else to chase Ayanokouji-kun.”<span class=\"pg\">p.163<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The first years will probably try to force their entry. The most effective way to get rid of me is to exploit the fact that I am in a group completely alone. If they are in a position to do so, they will be able to block by force the assignment and, if they want to go further, obstruct movement to the designated area. ”<span class=\"pg\">p.163<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;m sure you would be glad to hear it. Besides, Tsukishiro may be planning something .. If possible, I want to focus on that. ”<span class=\"pg\">p.163<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I understand the situation very well”<span class=\"pg\">p.163<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don&#x27;t worry. We already know all the scores for the group to which Class A belongs.”<span class=\"pg\">p.164<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So ... you&#x27;ve had very close contact with them.”<span class=\"pg\">p.164<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It is very important to know which groups have problems and which groups have plenty of space. There are a number of groups that have some room for growth, but not enough to make it to the top 10. So even if you use GPS search a few times per group, you can still get to the last day in plenty of time. ”<span class=\"pg\">p.164<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “All I have to do is stop the first years who are heading to Ayanokouji-kun, right?”<span class=\"pg\">p.164<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It would have been a bit boring exam just to help you complete the task, and besides, this story seems like something that could benefit me.”<span class=\"pg\">p.164<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It means that it is too big a commission for me to pay Takemoto-kun&#x27;s debt .. In other words, it will be a new &#x27; favor &#x27;, right?”<span class=\"pg\">p.164<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I know it hurts to hear this, but if you get rid of them, I&#x27;ll owe you a &#x27; favor &#x27;”<span class=\"pg\">p.164<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It&#x27;s decided. Well, then I&#x27;ll get to work on my preparations.”<span class=\"pg\">p.164<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Oh, and if you don&#x27;t mind, can I keep this walkie talkie as a loan?”<span class=\"pg\">p.164<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Of course I was going to do it anyway. It&#x27;s easier to get things done if we can get in touch. Then, could you return the walkie-talkie to Takemoto-kun? I will tell the situation and tell him to give it to Ayanokouji-kun”<span class=\"pg\">p.164<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, now we have arrested the five suspicious groups. Are we trying to identify the person who planned this attack? ”<span class=\"pg\">p.165<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> He pays for the night-10 favor with a promise of a bigger favor; he lets her in partially on the White Room; he never lies about the bounty&#x27;s existence — he just doesn&#x27;t volunteer the rest.<span class=\"pg\">p.159–165<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Their bargain; she extracts a future favor.<span class=\"pg\">p.159–165<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Takemoto Shigeru<\/b> The walkie-talkie relay runs through him.<span class=\"pg\">p.161–164<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsukishiro<\/b> He reveals Tsukishiro may be planning something else.<span class=\"pg\">p.163<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> The bounty is Nagumo&#x27;s price for Tsukishiro.<span class=\"pg\">p.163<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p153-1\">← Before: Ch.5: The GPS chase (mention records)<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p162-1\">→ After: Revealing Nanase&#x27;s role to Ryūen<\/button><\/div><\/article>"},{"i":"sc-sakayanagi-arisu-y2v4-p159-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"ayanokouji-kiyotaka takemoto-shigeru kitou-hayato sakayanagi-arisu","q":"sakayanagi arisu ch 5  the second grade countermove on the morning of day thirteen  with tsubaki setting her plan in motion  sakayanagi   sipping water  tablet in hand   has already dispatched five groups to freeze the first years  the night 10 call was her preparation   it seems they are on the move   it seems that the waiting time is over  so let s get started   in the last 12 days  the interior of the uninhabited island has undergone a gradual change in terrain  do you know what that is   students and teachers commute around the uninhabited island on a daily basis  in fact  don t you think tsukasaki kun uses it naturally to choose a safe and fast route     there is a more important meaning  because this is how we caught the group that was trying to protect ayanokouji senpai     takuya yagami kun  riku utomiya kun  and sakurako tsubaki san  i wonder who my adversary is  or is it the three of them     it seems that the classes are working well together   yes  i was able to contact ryuuen kun and horikita san  we are progressing smoothly  i haven t heard the details  but it seems that takemoto kun and the others were taken care of     your group is also making great strides  now you are in fifth place  you are in a position where you can aim high enough   not that there are no worries at all   have you seen ichinose san   no  i have not seen her even once during this exam  what happened   i got a call saying she was acting a little strange  she has been lost for several days and i am worried      so  what do you want from me   about the white room   it would have been better if you had told me before   because none of it was safe   so you want me to destroy that person named amasawa ichika   huh   actually there is one more thing  i have another big problem   i mean  in the near future  the first year students will take action against ayanokouji kun  right   that s what i mean  i want to ask sakayanagi to take care of it     but if it s the same white room student  i don t think it s possible for someone else to chase ayanokouji kun   the first years will probably try to force their entry  the most effective way to get rid of me is to exploit the fact that i am in a group completely alone  if they are in a position to do so  they will be able to block by force the assignment and  if they want to go further  obstruct movement to the designated area     i m sure you would be glad to hear it  besides  tsukishiro may be planning something   if possible  i want to focus on that     i understand the situation very well   it is inevitable that sakayanagi s workload will increase   i understand the situation very well   don t worry  we already know all the scores for the group to which class a belongs   so   you ve had very close contact with them   it is very important to know which groups have problems and which groups have plenty of space  there are a number of groups that have some room for growth  but not enough to make it to the top 10  so even if you use gps search a few times per group  you can still get to the last day in plenty of time     all i have to do is stop the first years who are heading to ayanokouji kun  right   it would have been a bit boring exam just to help you complete the task  and besides  this story seems like something that could benefit me   what do you mean   it means that it is too big a commission for me to pay takemoto kun s debt   in other words  it will be a new   favor   right   i know it hurts to hear this  but if you get rid of them  i ll owe you a   favor    it s decided  well  then i ll get to work on my preparations   oh  and if you don t mind  can i keep this walkie talkie as a loan   of course i was going to do it anyway  it s easier to get things done if we can get in touch  then  could you return the walkie talkie to takemoto kun  i will tell the situation and tell him to give it to ayanokouji kun    well  now we have arrested the five suspicious groups  are we trying to identify the person who planned this attack    the night 10 call  takemoto s group called her about ayanokoji s request  becomes the day 13 countermeasure  she freezes the three first year masterminds  five groups with gps lock  she lends him the walkie talkie and demands the debt be repaid with a  new favor    the white room story  turns every transaction into an asset  she enjoys the game  she gets the three first year masterminds  names handed to her on a plate  does the countermeasure for him as a favor favor  she relishes it  carries her channel into ayanokoji s group  she sends him to unmask the commander","h":"<article class=\"card\" id=\"sc-sakayanagi-arisu-y2v4-p159-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sakayanagi-arisu.html#sc-sakayanagi-arisu-y2v4-p159-1\">Ch.5: The second-grade countermove<\/a><\/span><span class=\"meta\">Y2V4 · p.159–165<\/span><span class=\"by\">notes on <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/span><\/h3><p class=\"setup\">On the morning of day thirteen, with Tsubaki setting her plan in motion, Sakayanagi — sipping water, tablet in hand — has already dispatched five groups to freeze the first-years; the night-10 call was her preparation.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/takemoto-shigeru.html\">Takemoto Shigeru<\/a> · <a href=\"../../../people/kitou-hayato.html\">Kitō Hayato<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Sakayanagi Arisu<\/b> “It seems they are on the move.”<span class=\"pg\">p.159<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sakayanagi Arisu<\/b> “It seems that the waiting time is over, so let&#x27;s get started.”<span class=\"pg\">p.159<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sakayanagi Arisu<\/b> “In the last 12 days, the interior of the uninhabited island has undergone a gradual change in terrain. Do you know what that is?”<span class=\"pg\">p.160<\/span><\/li><\/ul><details class=\"more\"><summary>42 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Students and teachers commute around the uninhabited island on a daily basis. In fact, don&#x27;t you think Tsukasaki-kun uses it naturally to choose a safe and fast route? ”<span class=\"pg\">p.160<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There is a more important meaning. Because this is how we caught the group that was trying to protect Ayanokouji-senpai. ”<span class=\"pg\">p.160<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Takuya Yagami-kun? Riku Utomiya-kun? and Sakurako Tsubaki-san? I wonder who my adversary is. Or is it the three of them? ”<span class=\"pg\">p.160<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It seems that the classes are working well together.”<span class=\"pg\">p.161<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yes. I was able to contact Ryuuen-kun and Horikita-san. We are progressing smoothly. I haven&#x27;t heard the details, but it seems that Takemoto-kun and the others were taken care of. ”<span class=\"pg\">p.161<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Your group is also making great strides, now you are in fifth place. You are in a position where you can aim high enough.”<span class=\"pg\">p.161<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Not that there are no worries at all.”<span class=\"pg\">p.161<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Have you seen Ichinose-san?”<span class=\"pg\">p.162<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No, I have not seen her even once during this exam. What happened?”<span class=\"pg\">p.162<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I got a call saying she was acting a little strange. She has been lost for several days and I am worried ... ”<span class=\"pg\">p.162<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So, what do you want from me?”<span class=\"pg\">p.162<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “About the White Room.”<span class=\"pg\">p.162<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It would have been better if you had told me before.”<span class=\"pg\">p.163<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Because none of it was safe.”<span class=\"pg\">p.163<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So you want me to destroy that person named Amasawa Ichika?”<span class=\"pg\">p.163<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Huh?..”<span class=\"pg\">p.163<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Actually there is one more thing, I have another big problem.”<span class=\"pg\">p.163<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I mean, in the near future, the first-year students will take action against Ayanokouji-kun, right?”<span class=\"pg\">p.163<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That&#x27;s what I mean. I want to ask Sakayanagi to take care of it. ”<span class=\"pg\">p.163<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But if it&#x27;s the same White Room student, I don&#x27;t think it&#x27;s possible for someone else to chase Ayanokouji-kun.”<span class=\"pg\">p.163<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The first years will probably try to force their entry. The most effective way to get rid of me is to exploit the fact that I am in a group completely alone. If they are in a position to do so, they will be able to block by force the assignment and, if they want to go further, obstruct movement to the designated area. ”<span class=\"pg\">p.163<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;m sure you would be glad to hear it. Besides, Tsukishiro may be planning something .. If possible, I want to focus on that. ”<span class=\"pg\">p.163<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I understand the situation very well”<span class=\"pg\">p.163<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It is inevitable that Sakayanagi&#x27;s workload will increase.”<span class=\"pg\">p.163<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I understand the situation very well”<span class=\"pg\">p.163<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don&#x27;t worry. We already know all the scores for the group to which Class A belongs.”<span class=\"pg\">p.164<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So ... you&#x27;ve had very close contact with them.”<span class=\"pg\">p.164<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It is very important to know which groups have problems and which groups have plenty of space. There are a number of groups that have some room for growth, but not enough to make it to the top 10. So even if you use GPS search a few times per group, you can still get to the last day in plenty of time. ”<span class=\"pg\">p.164<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “All I have to do is stop the first years who are heading to Ayanokouji-kun, right?”<span class=\"pg\">p.164<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It would have been a bit boring exam just to help you complete the task, and besides, this story seems like something that could benefit me.”<span class=\"pg\">p.164<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What do you mean?”<span class=\"pg\">p.164<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It means that it is too big a commission for me to pay Takemoto-kun&#x27;s debt .. In other words, it will be a new &#x27; favor &#x27;, right?”<span class=\"pg\">p.164<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I know it hurts to hear this, but if you get rid of them, I&#x27;ll owe you a &#x27; favor &#x27;”<span class=\"pg\">p.164<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It&#x27;s decided. Well, then I&#x27;ll get to work on my preparations.”<span class=\"pg\">p.164<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Oh, and if you don&#x27;t mind, can I keep this walkie talkie as a loan?”<span class=\"pg\">p.164<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Of course I was going to do it anyway. It&#x27;s easier to get things done if we can get in touch. Then, could you return the walkie-talkie to Takemoto-kun? I will tell the situation and tell him to give it to Ayanokouji-kun ”<span class=\"pg\">p.164<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, now we have arrested the five suspicious groups. Are we trying to identify the person who planned this attack? ”<span class=\"pg\">p.165<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The night-10 call (Takemoto&#x27;s group called her about Ayanokōji&#x27;s request) becomes the day-13 countermeasure; she freezes the three first-year masterminds&#x27; five groups with GPS lock; she lends him the walkie-talkie and demands the debt be repaid with a &quot;new favor&quot; — the White Room story.<span class=\"pg\">p.161–164<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Turns every transaction into an asset; she enjoys the game; she gets the three first-year masterminds&#x27; names handed to her on a plate.<span class=\"pg\">p.159–165<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Does the countermeasure for him as a favor-favor; she relishes it.<span class=\"pg\">p.161–165<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Takemoto Shigeru<\/b> Carries her channel into Ayanokōji&#x27;s group.<span class=\"pg\">p.161–164<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kitō Hayato<\/b> She sends him to unmask the commander.<span class=\"pg\">p.185–189<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sakayanagi-arisu-y2v4-p93-1\">← Before: Sakayanagi mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sakayanagi-arisu-y2v4-p191-1\">→ After: Sakayanagi mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-takemoto-shigeru-y2v4-p159-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"sakayanagi-arisu ayanokouji-kiyotaka shiranami-chihiro takemoto-shigeru","q":"takemoto shigeru ch 5  the walkie talkie relay at midnight three days earlier  at midnight of day ten  takemoto s group was contacted by sakayanagi via walkie talkie  he was deputized to call ayanokoji senpai to sakayanagi on the walkie talkie   the whole second year alliance quietly activating through him   what happened at this time  are you in trouble      sakayanagi   no  is not that  actually  ayanokouji wants to talk to you     ayanokouji kun    sakayanagi   i am in debt  i would appreciate it if you would let him talk to you   of course of course  please take charge      sakayanagi   wait a minute    sakayanagi   good night  ayanokouji kun    sakayanagi   sakayanagi    ayanokoji  he stays on the line with them   the walkie talkie relay stays in his group s hands while he listens to the whole white room and nagumo bounty conversation  he is made to hand the walkie talkie to ayanokoji afterward   with sakayanagi s blessing   as her personal loan to the second year commander  his channel into the island s alliance network  he owes her  he hands him the walkie talkie as per sakayanagi s instruction    no  shiranami is not present on these pages  the group leader is kobashi  takemoto is with kobashi   shiranami  their group was the one lost  sakayanagi s five frozen groups sealed the trap","h":"<article class=\"card\" id=\"sc-takemoto-shigeru-y2v4-p159-1\"><h3><span class=\"ttl\"><a href=\"../../../people/takemoto-shigeru.html#sc-takemoto-shigeru-y2v4-p159-1\">Ch.5: The walkie-talkie relay at midnight<\/a><\/span><span class=\"meta\">Y2V4 · p.159–164<\/span><span class=\"by\">notes on <a href=\"../../../people/takemoto-shigeru.html\">Takemoto Shigeru<\/a><\/span><\/h3><p class=\"setup\">Three days earlier, at midnight of day ten, Takemoto&#x27;s group was contacted by Sakayanagi via walkie-talkie; he was deputized to call Ayanokōji-senpai to Sakayanagi on the walkie-talkie — the whole second-year alliance quietly activating through him.<\/p><p class=\"with\">with <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/shiranami-chihiro.html\">Shiranami Chihiro<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Takemoto Shigeru<\/b> “What happened at this time? Are you in trouble? ” — Sakayanagi.<span class=\"pg\">p.161<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Takemoto Shigeru<\/b> “No, is not that. Actually, Ayanokouji wants to talk to you. ”<span class=\"pg\">p.161<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Takemoto Shigeru<\/b> “Ayanokouji-kun?” — Sakayanagi.<span class=\"pg\">p.161<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “I am in debt, I would appreciate it if you would let him talk to you.”<span class=\"pg\">p.161<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Of course…of course. Please take charge. ” — Sakayanagi.<span class=\"pg\">p.161<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Wait a minute.” — Sakayanagi.<span class=\"pg\">p.161<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Good night, Ayanokouji-kun”. — Sakayanagi.<span class=\"pg\">p.161<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Sakayanagi”. — Ayanokōji.<span class=\"pg\">p.161<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> He stays on the line with them — the walkie-talkie relay stays in his group&#x27;s hands while he listens to the whole White Room and Nagumo-bounty conversation; he is made to hand the walkie-talkie to Ayanokōji afterward — with Sakayanagi&#x27;s blessing — as her personal loan to the second-year commander.<span class=\"pg\">p.161–164<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> His channel into the island&#x27;s alliance network; he owes her.<span class=\"pg\">p.160–164<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> He hands him the walkie-talkie as per Sakayanagi&#x27;s instruction.<span class=\"pg\">p.161–164<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiranami Chihiro<\/b> — no, Shiranami is not present on these pages; the group leader is Kobashi? Takemoto is with Kobashi + Shiranami. Their group was the one lost; Sakayanagi&#x27;s five frozen groups sealed the trap.<span class=\"pg\">p.159–160<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-takemoto-shigeru-y2v4-p88-1\">← Before: Takemoto mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-tsubaki-sakurako-y2v4-p159-1","v":"y2v4","y":2,"o":19,"k":"","w":"tsubaki-sakurako","q":"tsubaki sakurako tsubaki mentioned in passing  tsubaki replied a bit dejected  and looked at the tablet again    narration   takuya yagami kun  riku utomiya kun  and sakurako tsubaki san  i wonder who my adversary is  or is it the three of them    sakayanagi","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y2v4-p159-1\"><h3><span class=\"ttl\"><a href=\"../../../people/tsubaki-sakurako.html#sc-tsubaki-sakurako-y2v4-p159-1\">Tsubaki mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.159–160<\/span><span class=\"by\">notes on <a href=\"../../../people/tsubaki-sakurako.html\">Tsubaki Sakurako<\/a><\/span><\/h3><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “Tsubaki replied a bit dejected, and looked at the tablet again.” — narration.<span class=\"pg\">p.159<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Takuya Yagami-kun? Riku Utomiya-kun? and Sakurako Tsubaki-san? I wonder who my adversary is. Or is it the three of them?” — Sakayanagi.<span class=\"pg\">p.160<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v4-p151-1\">← Before: Ch.5: The siege fails; the unseen commander<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v4-p165-1\">→ After: Ch.5: &quot;I caught the other group&quot;<\/button><\/div><\/article>"},{"i":"sc-sakura-airi-y2v4-p160-1","v":"y2v4","y":2,"o":19,"k":"","w":"sakura-airi","q":"sakura airi sakura not present the page locator matched  sakura  in year 2  vol  4  but these are  sakurako tsubaki  hits   the first year siege mastermind   not sakura airi  the roster row for sakura airi has zero page presence in this volume","h":"<article class=\"card\" id=\"sc-sakura-airi-y2v4-p160-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sakura-airi.html#sc-sakura-airi-y2v4-p160-1\">Sakura not present<\/a><\/span><span class=\"meta\">Y2V4 · p.160, 167, 186, 262<\/span><span class=\"by\">notes on <a href=\"../../../people/sakura-airi.html\">Sakura Airi<\/a><\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> The page locator matched “Sakura” in Year 2, Vol. 4, but these are “Sakurako Tsubaki” hits — the first-year siege mastermind — not Sakura Airi; the roster row for Sakura Airi has zero page presence in this volume.<span class=\"pg\">p.160, 167, 186, 262<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sakura-airi-y2v4-p278-1\">→ After: Sakura Airi mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-tsukasaki-taiga-y2v4-p160-1","v":"y2v4","y":2,"o":19,"k":"","w":"tsukasaki-taiga","q":"tsukasaki taiga tsukasaki mentioned in passing  students and teachers commute around the uninhabited island on a daily basis  in fact  don t you think tsukasaki kun uses it naturally to choose a safe and fast route      sakayanagi s point about tsukasaki s pathing","h":"<article class=\"card\" id=\"sc-tsukasaki-taiga-y2v4-p160-1\"><h3><span class=\"ttl\">Tsukasaki mentioned in passing<\/span><span class=\"meta\">Y2V4 · p.160<\/span><span class=\"by\">notes on <a href=\"../../../people/index.html#tsukasaki-taiga\">Tsukasaki Taiga<\/a><\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “Students and teachers commute around the uninhabited island on a daily basis. In fact, don&#x27;t you think Tsukasaki-kun uses it naturally to choose a safe and fast route? ” — Sakayanagi&#x27;s point about Tsukasaki&#x27;s pathing.<span class=\"pg\">p.160<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-amasawa-ichika-y2v4-p162-1","v":"y2v4","y":2,"o":19,"k":"","w":"amasawa-ichika","q":"amasawa ichika amasawa mentioned in passing  about the white room    ayanokoji to sakayanagi  the assassins story is known to her","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v4-p162-1\"><h3><span class=\"ttl\"><a href=\"../../../people/amasawa-ichika.html#sc-amasawa-ichika-y2v4-p162-1\">Amasawa mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.162<\/span><span class=\"by\">notes on <a href=\"../../../people/amasawa-ichika.html\">Amasawa Ichika<\/a><\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “About the White Room.” — Ayanokōji to Sakayanagi; the assassins story is known to her.<span class=\"pg\">p.162<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v4-p120-1\">← Before: Ch.4: The empty leak (mention records)<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v4-p220-1\">→ After: Ch.6: The I2 assignment; she stops Horikita<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v4-p162-1","v":"y2v4","y":2,"o":19,"k":"","w":"ryuuen-kakeru tsukishiro ayanokouji-kiyotaka","q":"ayanokoji kiyotaka revealing nanase s role to ryuen explains to ryuen that nanase was one of the assassins tsukishiro sent  and why the lower risk plus new risk tipped the balance   enlisting his help to stop hosen  shares intel selectively with ryuen to neutralize the threat without expelling anyone  his intervention leads to ryuen stopping hosen  informs him about nanase tsukishiro  ryuen agrees to intercept hosen  nanase was one of his sent assassins","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v4-p162-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v4-p162-1\">Revealing Nanase&#x27;s role to Ryūen<\/a><\/span><span class=\"meta\">Y2V4 · p.162–164<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Explains to Ryūen that Nanase was one of the assassins Tsukishiro sent, and why the lower risk plus new risk tipped the balance — enlisting his help to stop Hōsen.<\/p><p class=\"with\">with <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"../../../people/tsukishiro.html\">Tsukishiro<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Shares intel selectively with Ryūen to neutralize the threat without expelling anyone; his intervention leads to Ryūen stopping Hōsen.<span class=\"pg\">p.162–164<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Informs him about Nanase/Tsukishiro; Ryūen agrees to intercept Hōsen.<span class=\"pg\">p.162–164<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsukishiro<\/b> Nanase was one of his sent assassins.<span class=\"pg\">p.162<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p159-1\">← Before: Ch.5: The Sakayanagi bargain<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p166-1\">→ After: Ch.5: The countermove from outside (mention records)<\/button><\/div><\/article>"},{"i":"sc-ichinose-honami-y2v4-p162-1","v":"y2v4","y":2,"o":19,"k":"","w":"ichinose-honami","q":"ichinose honami ichinose mentioned in passing  have you seen ichinose san    ayanokoji asks sakayanagi  she is missing for several days   it was a strategy that could only be accomplished by joining forces with sakayanagi s class a  who had perfect control  and ichinose s c class  who would never betray her    ayanokoji","h":"<article class=\"card\" id=\"sc-ichinose-honami-y2v4-p162-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ichinose-honami.html#sc-ichinose-honami-y2v4-p162-1\">Ichinose mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.162–164<\/span><span class=\"by\">notes on <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/span><\/h3><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “Have you seen Ichinose-san?” — Ayanokōji asks Sakayanagi; she is missing for several days.<span class=\"pg\">p.162<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “it was a strategy that could only be accomplished by joining forces with Sakayanagi&#x27;s class A, who had perfect control, and Ichinose&#x27;s C-class, who would never betray her.” — Ayanokōji.<span class=\"pg\">p.164<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y2v4-p120-1\">← Before: Ichinose mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y2v4-p192-1\">→ After: Sakayanagi reports Ichinose missing<\/button><\/div><\/article>"},{"i":"sc-tsukishiro-y2v4-p162-1","v":"y2v4","y":2,"o":19,"k":"","w":"tsukishiro","q":"tsukishiro tsukishiro mentioned in passing  about the white room    ayanokoji to sakayanagi  the assassins story is known to her   besides  tsukishiro may be planning something   if possible  i want to focus on that    ayanokoji s caution  the bounty is nagumo s price for tsukishiro","h":"<article class=\"card\" id=\"sc-tsukishiro-y2v4-p162-1\"><h3><span class=\"ttl\"><a href=\"../../../people/tsukishiro.html#sc-tsukishiro-y2v4-p162-1\">Tsukishiro mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.162–163<\/span><span class=\"by\">notes on <a href=\"../../../people/tsukishiro.html\">Tsukishiro<\/a><\/span><\/h3><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “About the White Room.” — Ayanokōji to Sakayanagi; the assassins story is known to her.<span class=\"pg\">p.162<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Besides, Tsukishiro may be planning something .. If possible, I want to focus on that.” — Ayanokōji&#x27;s caution; the bounty is Nagumo&#x27;s price for Tsukishiro.<span class=\"pg\">p.163<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsukishiro-y2v4-p18-1\">← Before: Tsukishiro mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-tsukishiro-y2v4-p191-1\">→ After: Tsukishiro mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-nagumo-miyabi-y2v4-p163-1","v":"y2v4","y":2,"o":19,"k":"","w":"nagumo-miyabi","q":"nagumo miyabi nagumo mentioned in passing  i mean  in the near future  the first year students will take action against ayanokouji kun  right    ayanokoji tells sakayanagi about the bounty s origin  tsukishiro may be planning something else   besides  tsukishiro may be planning something   if possible  i want to focus on that    ayanokoji","h":"<article class=\"card\" id=\"sc-nagumo-miyabi-y2v4-p163-1\"><h3><span class=\"ttl\"><a href=\"../../../people/nagumo-miyabi.html#sc-nagumo-miyabi-y2v4-p163-1\">Nagumo mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.163<\/span><span class=\"by\">notes on <a href=\"../../../people/nagumo-miyabi.html\">Nagumo Miyabi<\/a><\/span><\/h3><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “I mean, in the near future, the first-year students will take action against Ayanokouji-kun, right?” — Ayanokōji tells Sakayanagi about the bounty&#x27;s origin; Tsukishiro may be planning something else.<span class=\"pg\">p.163<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Besides, Tsukishiro may be planning something .. If possible, I want to focus on that.” — Ayanokōji.<span class=\"pg\">p.163<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y2v4-p152-1\">← Before: Nagumo mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y2v4-p201-1\">→ After: Ch.6: The beach talk; he gets knocked out<\/button><\/div><\/article>"},{"i":"sc-tsubaki-sakurako-y2v4-p165-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"yagami-takuya utomiya-riku kitou-hayato tsubaki-sakurako","q":"tsubaki sakurako ch 5   i caught the other group  receiving the news of hosen s defeat  tsubaki mutters in interest  she sees utomiya is missing  her walkie talkie is taken by kitou after his fight with utomiya  she realizes her plan was a dead end   it didn t go very well  did it   even if you force yourself to flee  you can always make up an excuse later  like you got scared because you got tangled up with the grown ups  if you had consulted me before    so  you say this happened because i was negligent    tsubaki   it is not that my group has been caught  it is that i have caught the other group   rumor has it that he has the ability similar to housen kun s  it means that he didn t want to face the current group from the beginning    tsubaki   the only thing we should avoid is getting in the way of our efforts to eliminate ayanokouji senpai  and the only person capable of eliminating ayanokouji senpai  apart from utomiya kun  is housen kun     yagami   let me ask you one last question  if housen kun had not accepted this case  do you think this operation would not have been possible      tsubaki   hmm  not exactly  it is correct to say that we decided to carry out this operation because we were absolutely sure that housen kun would come on board  it seems that he was always willing to fight alone  still  if they didn t accept the case  i would just let utomiya kun go  either way  i made sure the atmosphere was perfect for one on one  now it only remains for the two to face each other  win or lose  and everything will be fine    tsubaki  she takes the failure with interest   the whole plan was a test  she expected the second years to stop housen  she reveals she never meant to confront ayanokoji directly  kitou s approach forces her to abandon the island  her second in command  she tolerates his halting loyalty  her one trusted partner  his walkie talkie is lost to kitou  he was sent to unmask her  utomiya drops the walkie talkie and kitou reads her voice  the plan dies","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y2v4-p165-1\"><h3><span class=\"ttl\"><a href=\"../../../people/tsubaki-sakurako.html#sc-tsubaki-sakurako-y2v4-p165-1\">Ch.5: &quot;I caught the other group&quot;<\/a><\/span><span class=\"meta\">Y2V4 · p.165–167<\/span><span class=\"by\">notes on <a href=\"../../../people/tsubaki-sakurako.html\">Tsubaki Sakurako<\/a><\/span><\/h3><p class=\"setup\">Receiving the news of Hōsen&#x27;s defeat, Tsubaki mutters in interest; she sees Utomiya is missing; her walkie-talkie is taken by Kitou after his fight with Utomiya; she realizes her plan was a dead end.<\/p><p class=\"with\">with <a href=\"../../../people/yagami-takuya.html\">Yagami Takuya<\/a> · <a href=\"../../../people/utomiya-riku.html\">Utomiya Riku<\/a> · <a href=\"../../../people/kitou-hayato.html\">Kitō Hayato<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Yagami Takuya<\/b> “It didn&#x27;t go very well, did it?”<span class=\"pg\">p.165<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Yagami Takuya<\/b> “Even if you force yourself to flee, you can always make up an excuse later, like you got scared because you got tangled up with the grown-ups. If you had consulted me before ”<span class=\"pg\">p.165<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Tsubaki Sakurako<\/b> “So, you say this happened because I was negligent?” — Tsubaki.<span class=\"pg\">p.165<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “It is not that my group has been caught, it is that I have caught the other group.”<span class=\"pg\">p.166<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Rumor has it that he has the ability similar to Housen-kun&#x27;s. It means that he didn&#x27;t want to face the current group from the beginning.” — Tsubaki.<span class=\"pg\">p.166<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The only thing we should avoid is getting in the way of our efforts to eliminate Ayanokouji-senpai. And the only person capable of eliminating Ayanokouji-Senpai, apart from Utomiya-kun, is Housen-kun ...” — Yagami.<span class=\"pg\">p.166<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Let me ask you one last question. If Housen-kun had not accepted this case, do you think this operation would not have been possible? ” — Tsubaki.<span class=\"pg\">p.167<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Hmm, not exactly. It is correct to say that we decided to carry out this operation because we were absolutely sure that Housen-kun would come on board. It seems that he was always willing to fight alone. Still, if they didn&#x27;t accept the case, I would just let Utomiya-kun go. Either way, I made sure the atmosphere was perfect for one-on-one. Now it only remains for the two to face each other, win or lose, and everything will be fine.” — Tsubaki.<span class=\"pg\">p.167<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> She takes the failure with interest — the whole plan was a test; she expected the second-years to stop Housen; she reveals she never meant to confront Ayanokōji directly; Kitou&#x27;s approach forces her to abandon the island.<span class=\"pg\">p.165–167<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yagami Takuya<\/b> Her second-in-command; she tolerates his halting loyalty.<span class=\"pg\">p.165–167<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Utomiya Riku<\/b> Her one trusted partner; his walkie-talkie is lost to Kitou.<span class=\"pg\">p.165–190<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kitō Hayato<\/b> He was sent to unmask her; Utomiya drops the walkie-talkie and Kitou reads her voice; the plan dies.<span class=\"pg\">p.184–189<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v4-p159-1\">← Before: Tsubaki mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v4-p166-1","v":"y2v4","y":2,"o":19,"k":"","w":"ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 5  the countermove from outside  mention records   the five groups sent to expel ayanokouji senpai    tsubaki   the siege of ayanokouji was conceived by sakurako tsubaki    narration   i found you  ayanokouji senpai    hosen   if ryuuen is in command  tablets and walkie talkies are essential    narration  ryuen s arrival   as long as he had that  he would not allow ayanokouji to lose  no matter if it was a fight or not    narration   not only ishizaki  but also albert    narration  the 3 on 1   even though ayanokouji senpai didn t bother to give advance notice    utomiya","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v4-p166-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v4-p166-1\">Ch.5: The countermove from outside (mention records)<\/a><\/span><span class=\"meta\">Y2V4 · p.166–190<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “the five groups sent to expel Ayanokouji-senpai.” — Tsubaki.<span class=\"pg\">p.166<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “The Siege of Ayanokouji was conceived by Sakurako Tsubaki.” — narration.<span class=\"pg\">p.167<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “I found you, Ayanokouji-senpai!” — Hōsen.<span class=\"pg\">p.168<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “If Ryuuen is in command, tablets and walkie-talkies are essential.” — narration; Ryūen’s arrival.<span class=\"pg\">p.170<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “as long as he had that, he would not allow Ayanokouji to lose, no matter if it was a fight or not.” — narration.<span class=\"pg\">p.176<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Not only Ishizaki, but also Albert...” — narration; the 3-on-1.<span class=\"pg\">p.177<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Even though Ayanokouji-senpai didn’t bother to give advance notice...” — Utomiya.<span class=\"pg\">p.190<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p162-1\">← Before: Revealing Nanase&#x27;s role to Ryūen<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p169-1\">→ After: AK mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-housen-kazuomi-y2v4-p168-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"ryuuen-kakeru tsubaki-sakurako nanase-tsubasa ishizaki-daichi yamada-albert housen-kazuomi","q":"hosen kazuomi hosen s trap and his brutal fight with ryuen pretends to follow tsubaki s instructions to surround ayanokoji  intending instead to attack him directly  but ayanokoji anticipated it  via nanase  and ryuen intercepts   housen   i know nanase came to see you to gently warn you   that s my line  housen  you have nothing to do here  do you    ryuen walks into ryuen s trap   a fierce brawler who dominates the one on one exchange with overwhelming punches  ryuen s warning then emergency alert sounds  but is outmaneuvered when ishizaki and albert  with broken disabled gps so unseen  restrain him  turning it into a 3 on 1 beating  stripped of his confidence  ryuen calls him a  shitty little fish  who can t fight alone in a real fight  he loses consciousness and retires with ryuen  his rival   ryuen stops him from reaching ayanokoji and defeats him with a setup  both retire together  pretends to follow her plan  drops out of her network when he makes his move  his classmate  her warning was secretly ayanokoji s tip off  restrains him from behind  part of the 3 on 1 trap  restrains his dominant arm   a man stronger than ryuen himself","h":"<article class=\"card\" id=\"sc-housen-kazuomi-y2v4-p168-1\"><h3><span class=\"ttl\"><a href=\"../../../people/housen-kazuomi.html#sc-housen-kazuomi-y2v4-p168-1\">Hōsen&#x27;s trap and his brutal fight with Ryūen<\/a><\/span><span class=\"meta\">Y2V4 · p.168–183<\/span><span class=\"by\">notes on <a href=\"../../../people/housen-kazuomi.html\">Hōsen Kazuomi<\/a><\/span><\/h3><p class=\"setup\">Pretends to follow Tsubaki&#x27;s instructions to surround Ayanokōji, intending instead to attack him directly; but Ayanokōji anticipated it (via Nanase), and Ryūen intercepts.<\/p><p class=\"with\">with <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"../../../people/tsubaki-sakurako.html\">Tsubaki Sakurako<\/a> · <a href=\"../../../people/nanase-tsubasa.html\">Nanase Tsubasa<\/a> · <a href=\"../../../people/ishizaki-daichi.html\">Ishizaki Daichi<\/a> · <a href=\"../../../people/yamada-albert.html\">Yamada Albert<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hōsen Kazuomi<\/b> “Housen.”<span class=\"pg\">p.168<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hōsen Kazuomi<\/b> “I know Nanase came to see you to gently warn you.”<span class=\"pg\">p.168<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hōsen Kazuomi<\/b> “That&#x27;s my line, Housen. You have nothing to do here, do you?” — Ryūen<span class=\"pg\">p.169<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Walks into Ryūen&#x27;s trap — a fierce brawler who dominates the one-on-one exchange with overwhelming punches (Ryūen&#x27;s Warning then Emergency Alert sounds), but is outmaneuvered when Ishizaki and Albert (with broken/disabled GPS so unseen) restrain him, turning it into a 3-on-1 beating; stripped of his confidence (Ryūen calls him a “shitty little fish” who can&#x27;t fight alone in a real fight), he loses consciousness and retires with Ryūen.<span class=\"pg\">p.168–183<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> His rival — Ryūen stops him from reaching Ayanokōji and defeats him with a setup; both retire together.<span class=\"pg\">p.168–183<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsubaki Sakurako<\/b> Pretends to follow her plan; drops out of her network when he makes his move.<span class=\"pg\">p.167–168<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nanase Tsubasa<\/b> His classmate; her warning was secretly Ayanokōji&#x27;s tip-off.<span class=\"pg\">p.168<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishizaki Daichi<\/b> Restrains him from behind; part of the 3-on-1 trap.<span class=\"pg\">p.177<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yamada Albert<\/b> Restrains his dominant arm — a man stronger than Ryūen himself.<span class=\"pg\">p.177<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-housen-kazuomi-y2v4-p126-1\">← Before: Ch.5: The negotiation; the stalking invitation<\/button><\/div><\/article>"},{"i":"sc-ryuuen-kakeru-y2v4-p168-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"housen-kazuomi ayanokouji-kiyotaka ryuuen-kakeru","q":"ryuen kakeru ch 5  the one on one running vigorously through the forest  hosen spots ryuen on the path ahead  ryuen blocks his way without effort   one man  alone   i found you  ayanokouji senpai   housen   i ve been waiting for this moment   get out of here  you re on my way   why are you here  ryuuen     that s my line  housen  you have nothing to do here  do you     eh    ha  so apparently what i m thinking comes from somewhere else   so it was not a coincidence that the other first years were retained by the second years   it s you  no  it is not like that     i m afraid i have something to do with it   i have a lot to do and my pockets are empty  if necessary  i will act as a mercenary soldier     you mean money  but what makes you think you can stop me     why do you think i can t do it   whoa   that s a pretty daring left hand you have there   don t give me that stinky breath  gorilla   you re a good talker  show me your pride and skill as a sophomore  will you  hey   oraa   you ve been barking and howling for less than ten seconds  haven t you  don t make me laugh   ha   you re a hard stone head fucking  aren t you made of a real stone there  damn gorilla   i guess i was expecting too much  you re not that good to me after all   i don t think you will find anyone with whom you are happy   i know you are here  because of ayanokouji  who was walking carefree behind you  let me take care of it   yes   so you re obsessed with ayanokouji too  huh  ryuuen   don t worry  i haven t finished with him  or should i say i haven t even started   i have never seen anyone stop my fist calmly  first of all  i don t think i ll ever see anyone who doesn t seem to be in pain while being stabbed with a knife     hey  it looks like you ve been having a lot of fun without me   you ve been busy falling asleep and getting up right   screw you   ha ha  that s what i thought  ryuuen  that s all you are   it seems like you re having fun  but do you think you ve already won   don t make me laugh  do you think you are at my level   at the end of the day  you are a man who can only get ahead with the help of the little ones    winning one on one isn t everything today  is it  in fact  in high school  the public s opinion of you and me was the same     it seems that you have been sneaking around and avoiding direct confrontation  it is n effort that makes you cry    he takes the hits without flinching   no color change  no fear  he baits hosen with pride and insults  he has pre disabled gps with ishizaki and albert waiting in ambush  he is fighting for a bigger prize than the fight itself  the gorilla  he draws him into a one on one that is secretly a trap  he knows why hosen is here  he owes him nothing but interest","h":"<article class=\"card\" id=\"sc-ryuuen-kakeru-y2v4-p168-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ryuuen-kakeru.html#sc-ryuuen-kakeru-y2v4-p168-1\">Ch.5: The one-on-one<\/a><\/span><span class=\"meta\">Y2V4 · p.168–173<\/span><span class=\"by\">notes on <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/span><\/h3><p class=\"setup\">Running vigorously through the forest, Hōsen spots Ryūen on the path ahead; Ryūen blocks his way without effort — one man, alone.<\/p><p class=\"with\">with <a href=\"../../../people/housen-kazuomi.html\">Hōsen Kazuomi<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hōsen Kazuomi<\/b> “I found you, Ayanokouji-senpai!”<span class=\"pg\">p.168<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Housen.”<span class=\"pg\">p.168<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hōsen Kazuomi<\/b> “I’ve been waiting for this moment!”<span class=\"pg\">p.168<\/span><\/li><\/ul><details class=\"more\"><summary>35 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Get out of here. You’re on my way.”<span class=\"pg\">p.169<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Why are you here? Ryuuen. ”<span class=\"pg\">p.169<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That’s my line, Housen. You have nothing to do here, do you? ”<span class=\"pg\">p.169<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Eh? ...... Ha, so apparently what I’m thinking comes from somewhere else.”<span class=\"pg\">p.169<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So it was not a coincidence that the other first years were retained by the second years.”<span class=\"pg\">p.169<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s you? No, it is not like that. ”<span class=\"pg\">p.169<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m afraid I have something to do with it.”<span class=\"pg\">p.170<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I have a lot to do and my pockets are empty. If necessary, I will act as a mercenary soldier. ”<span class=\"pg\">p.170<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You mean money. But what makes you think you can stop me? ”<span class=\"pg\">p.170<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Why do you think I can’t do it?”<span class=\"pg\">p.170<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Whoa ....., that’s a pretty daring left hand you have there.”<span class=\"pg\">p.170<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don’t give me that stinky breath, gorilla.”<span class=\"pg\">p.170<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You’re a good talker. Show me your pride and skill as a sophomore, will you? Hey!”<span class=\"pg\">p.170<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Oraa!”<span class=\"pg\">p.171<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You’ve been barking and howling for less than ten seconds, haven’t you? Don’t make me laugh.”<span class=\"pg\">p.171<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ha ...... you’re a hard stone head fucking. Aren’t you made of a real stone there? Damn gorilla.”<span class=\"pg\">p.171<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I guess I was expecting too much. You’re not that good to me after all.”<span class=\"pg\">p.171<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don’t think you will find anyone with whom you are happy.”<span class=\"pg\">p.171<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I know you are here, because of Ayanokouji, who was walking carefree behind you. Let me take care of it.”<span class=\"pg\">p.171<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yes?”<span class=\"pg\">p.171<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So you’re obsessed with Ayanokouji too, huh, Ryuuen?”<span class=\"pg\">p.172<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don’t worry. I haven’t finished with him, or should I say I haven’t even started.”<span class=\"pg\">p.172<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I have never seen anyone stop my fist calmly. First of all, I don’t think I’ll ever see anyone who doesn’t seem to be in pain while being stabbed with a knife. ”<span class=\"pg\">p.172<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Hey, it looks like you’ve been having a lot of fun without me.”<span class=\"pg\">p.172<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You’ve been busy falling asleep and getting up right?”<span class=\"pg\">p.173<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Screw you...”<span class=\"pg\">p.173<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ha ha! That’s what I thought, Ryuuen! That’s all you are!”<span class=\"pg\">p.173<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It seems like you’re having fun, but do you think you’ve already won?”<span class=\"pg\">p.173<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don’t make me laugh. Do you think you are at my level?”<span class=\"pg\">p.173<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “At the end of the day, you are a man who can only get ahead with the help of the little ones.”<span class=\"pg\">p.173<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “ Winning one-on-one isn’t everything today, is it? In fact, in high school, the public’s opinion of you and me was the same. ”<span class=\"pg\">p.173<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It seems that you have been sneaking around and avoiding direct confrontation. It is n effort that makes you cry. ”<span class=\"pg\">p.173<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> He takes the hits without flinching — no color change, no fear; he baits Hōsen with pride and insults; he has pre-disabled GPS with Ishizaki and Albert waiting in ambush; he is fighting for a bigger prize than the fight itself.<span class=\"pg\">p.168–173<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> The gorilla; he draws him into a one-on-one that is secretly a trap.<span class=\"pg\">p.168–173<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> He knows why Hōsen is here; he owes him nothing but interest.<span class=\"pg\">p.168–173<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ryuuen-kakeru-y2v4-p48-1\">← Before: Ryūen mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ryuuen-kakeru-y2v4-p174-1\">→ After: Ch.5: The third on one<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v4-p169-1","v":"y2v4","y":2,"o":19,"k":"","w":"ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ak mentioned in passing  i m afraid i have something to do with it    ryuen to hosen   so you re obsessed with ayanokouji too  huh  ryuuen    hosen   don t worry  i haven t finished with him  or should i say i haven t even started    ryuen to hosen","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v4-p169-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v4-p169-1\">AK mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.169–172<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “I&#x27;m afraid I have something to do with it.” — Ryūen to Hōsen.<span class=\"pg\">p.169<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “So you&#x27;re obsessed with Ayanokouji too, huh, Ryuuen?” — Hōsen.<span class=\"pg\">p.171<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Don&#x27;t worry. I haven&#x27;t finished with him, or should I say I haven&#x27;t even started.” — Ryūen to Hōsen.<span class=\"pg\">p.172<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p166-1\">← Before: Ch.5: The countermove from outside (mention records)<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p183-1\">→ After: Aftermath: Ryūen and Hōsen retire together<\/button><\/div><\/article>"},{"i":"sc-ryuuen-kakeru-y2v4-p174-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"housen-kazuomi ishizaki-daichi yamada-albert ryuuen-kakeru","q":"ryuen kakeru ch 5  the third on one dust and sand in hosen s eyes  he weathers it all  ishizaki and albert leap from the blind spot   disabled gps   and hold hosen  it becomes a 3 on 1   it has always been a common practice for the weak to fall in a fight   really   is so sweet   ah   it has always been a common practice for the weak to fall in a fight     seriously gorilla   i ll just admit i m proud of the fight    so ryuuen  i feel like i didn t enjoy   wait  you think you ve won   did i say that i lost to you even once   i ll admit that will power  but   you can t keep it forever   your body is sincere  it has had enough with this desperate situation   what the hell is wrong with you    you can t even stand  why are you so persistent  there is not a single advantage to being dumb here     the game is not over yet   are you sane    the teachers will come here  will you retire   if so  will you quit after all   you re going to play the victim just because you can t compete with your enemy  you re very pathetic  you re so pathetic  ryuuen   if you are afraid that i am the victim  why don t you go here   get me out of here   my gps is already off  there is nothing wrong with killing you before the teachers hurry up   kuku  i ll have to do that   if you don t feel like protecting yourself  you can go to bed   i don t think the tricks will work for me   what      don t bark so loud  gorilla  your execution is about to begin   it s a simple story  if you break your watch  the gps won t recognize it   are you going to do it 3 to 1  ah   he uses sand  a watch alarm  and the two friends   everything   nothing honorable  but the result is survival  he holds hosen until the teachers arrive  he never once shows pain  the plan was to protect ayanokoji senpai even if it costs him school  the gorilla  he goes unconscious after the 3 on 1  his ambusher   holds hosen s left arm  his ambusher   holds hosen s right dominant arm","h":"<article class=\"card\" id=\"sc-ryuuen-kakeru-y2v4-p174-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ryuuen-kakeru.html#sc-ryuuen-kakeru-y2v4-p174-1\">Ch.5: The third on one<\/a><\/span><span class=\"meta\">Y2V4 · p.174–178<\/span><span class=\"by\">notes on <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/span><\/h3><p class=\"setup\">Dust and sand in Hōsen&#x27;s eyes; he weathers it all; Ishizaki and Albert leap from the blind spot — disabled GPS — and hold Hōsen; it becomes a 3-on-1.<\/p><p class=\"with\">with <a href=\"../../../people/housen-kazuomi.html\">Hōsen Kazuomi<\/a> · <a href=\"../../../people/ishizaki-daichi.html\">Ishizaki Daichi<\/a> · <a href=\"../../../people/yamada-albert.html\">Yamada Albert<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hōsen Kazuomi<\/b> “It has always been a common practice for the weak to fall in a fight.”<span class=\"pg\">p.174<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> “Really!”<span class=\"pg\">p.174<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hōsen Kazuomi<\/b> “Is so sweet!”<span class=\"pg\">p.174<\/span><\/li><\/ul><details class=\"more\"><summary>27 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Ah!”<span class=\"pg\">p.174<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It has always been a common practice for the weak to fall in a fight. “<span class=\"pg\">p.174<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Seriously gorilla ... I’ll just admit I’m proud of the fight ...”<span class=\"pg\">p.175<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So Ryuuen. I feel like I didn’t enjoy.”<span class=\"pg\">p.175<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Wait. You think you’ve won.”<span class=\"pg\">p.175<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Did I say that I lost to you even once?”<span class=\"pg\">p.175<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’ll admit that will power, but ... You can’t keep it forever!”<span class=\"pg\">p.175<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Your body is sincere. It has had enough with this desperate situation.”<span class=\"pg\">p.176<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What the hell is wrong with you? . You can’t even stand, why are you so persistent? There is not a single advantage to being dumb here. ”<span class=\"pg\">p.176<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The game is not over yet.”<span class=\"pg\">p.176<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Are you sane? ... The teachers will come here, will you retire?”<span class=\"pg\">p.176<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If so, will you quit after all?”<span class=\"pg\">p.176<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You’re going to play the victim just because you can’t compete with your enemy, you’re very pathetic. You’re so pathetic, Ryuuen.”<span class=\"pg\">p.176<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If you are afraid that I am the victim, why don’t you go here?”<span class=\"pg\">p.177<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Get me out of here.”<span class=\"pg\">p.177<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “My GPS is already off. There is nothing wrong with killing you before the teachers hurry up.”<span class=\"pg\">p.177<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Kuku, I’ll have to do that”<span class=\"pg\">p.177<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If you don’t feel like protecting yourself, you can go to bed!”<span class=\"pg\">p.177<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don’t think the tricks will work for me!”<span class=\"pg\">p.177<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What ─── !?”<span class=\"pg\">p.177<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don’t bark so loud, Gorilla. Your execution is about to begin.”<span class=\"pg\">p.178<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s a simple story. If you break your watch, the GPS won’t recognize it.”<span class=\"pg\">p.178<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Are you going to do it 3 to 1? Ah !?”<span class=\"pg\">p.178<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> He uses sand, a watch alarm, and the two friends — everything — nothing honorable; but the result is survival: he holds Hōsen until the teachers arrive; he never once shows pain; the plan was to protect Ayanokōji-senpai even if it costs him school.<span class=\"pg\">p.174–178<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> The gorilla; he goes unconscious after the 3-on-1.<span class=\"pg\">p.174–178<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishizaki Daichi<\/b> His ambusher — holds Hōsen&#x27;s left arm.<span class=\"pg\">p.177–182<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yamada Albert<\/b> His ambusher — holds Hōsen&#x27;s right dominant arm.<span class=\"pg\">p.177–182<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ryuuen-kakeru-y2v4-p168-1\">← Before: Ch.5: The one-on-one<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ryuuen-kakeru-y2v4-p179-1\">→ After: Ch.5: Retirement together<\/button><\/div><\/article>"},{"i":"sc-ishizaki-daichi-y2v4-p177-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"housen-kazuomi yamada-albert ryuuen-kakeru ishizaki-daichi","q":"ishizaki daichi ch 5  the ambusher in the 3 on 1 disabled his gps early as part of ryuen s plan  he waits behind the trees with albert  when hosen turns  ishizaki grips his left arm  together they wrench the gorilla down   what      don t bark so loud  gorilla  your execution is about to begin    ryuen   shit    hosen   it s a simple story  if you break your watch  the gps won t recognize it    ryuen   no  no  no  no  we were just supporting you  hey  albert   you should get moving  the teachers could arrive at any moment   what about ryuen san    are you sure with that  he disables his gps for ryuen s plan  he and albert grab hosen s arms and hold him down while ryuen beats him  ryuen sends them to the starting point to swap watches and join the group before anyone notices  he is the one who gets sent off with albert  he holds hosen s left arm  ryuen sends him with albert to the starting point  his co ambusher  his target  he restrains him","h":"<article class=\"card\" id=\"sc-ishizaki-daichi-y2v4-p177-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ishizaki-daichi.html#sc-ishizaki-daichi-y2v4-p177-1\">Ch.5: The ambusher in the 3-on-1<\/a><\/span><span class=\"meta\">Y2V4 · p.177–183<\/span><span class=\"by\">notes on <a href=\"../../../people/ishizaki-daichi.html\">Ishizaki Daichi<\/a><\/span><\/h3><p class=\"setup\">Disabled his GPS early as part of Ryūen&#x27;s plan; he waits behind the trees with Albert; when Hōsen turns, Ishizaki grips his left arm; together they wrench the gorilla down.<\/p><p class=\"with\">with <a href=\"../../../people/housen-kazuomi.html\">Hōsen Kazuomi<\/a> · <a href=\"../../../people/yamada-albert.html\">Yamada Albert<\/a> · <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hōsen Kazuomi<\/b> “What ─── !?”<span class=\"pg\">p.177<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ishizaki Daichi<\/b> “Don’t bark so loud, Gorilla. Your execution is about to begin.” — Ryūen.<span class=\"pg\">p.177<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ishizaki Daichi<\/b> “Shit!!” — Hōsen.<span class=\"pg\">p.178<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “It’s a simple story. If you break your watch, the GPS won’t recognize it.” — Ryūen.<span class=\"pg\">p.178<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No, no, no, no! We were just supporting you! Hey, Albert!”<span class=\"pg\">p.182<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You should get moving. The teachers could arrive at any moment.”<span class=\"pg\">p.182<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What about Ryuen-san ...?”<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Are you sure with that?”<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> He disables his GPS for Ryūen&#x27;s plan; he and Albert grab Hōsen&#x27;s arms and hold him down while Ryūen beats him; Ryūen sends them to the starting point to swap watches and join the group before anyone notices; he is the one who gets sent off with Albert.<span class=\"pg\">p.177–183<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> He holds Hōsen&#x27;s left arm; Ryūen sends him with Albert to the starting point.<span class=\"pg\">p.177–183<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yamada Albert<\/b> His co-ambusher.<span class=\"pg\">p.177–183<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> His target; he restrains him.<span class=\"pg\">p.177–183<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ishizaki-daichi-y2v4-p116-1\">← Before: Ch.4: The merged group; the J10 gatekeeper<\/button><\/div><\/article>"},{"i":"sc-yamada-albert-y2v4-p177-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"housen-kazuomi ishizaki-daichi ryuuen-kakeru yamada-albert","q":"yamada albert ch 5  the ambusher in the 3 on 1 disabled his gps early as part of ryuen s plan  he waits behind the trees with ishizaki  when hosen s right dominant arm is exposed  albert grips it   the strongest arm in the class against the gorilla   what      don t bark so loud  gorilla  your execution is about to begin    ryuen   shit    hosen   it s a simple story  if you break your watch  the gps won t recognize it    ryuen   hey  big man   why the hell are you following ryuuen  eh    hosen   it is true that i am a man that ryuuen can t defeat even if he faced me once or twice   why then    hosen   you don t understand  housen  not only the monstrously powerful rise to the top   kuku  well  in albert s case  i d say it s just camaraderie   don t think you have won with this  ryuuen    hosen   but he s a great guy    i really thought he was a monster    ryuen   you would be a fool if you faced him   they have had to work a lot    ryuen   no  no  no  no  we were just supporting you  hey  albert    ishizaki   you should get moving  the teachers could arrive at any moment    ishizaki  he disables his gps for ryuen s plan and takes hosen s dominant arm in a 3 on 1 beating  he is bigger than ryuuen and could beat him once or twice  he follows ryuen by choice of camaraderie  not by fear  he keeps quiet while hosen barks threats  he waits in ambush for him  they win together  he is asked to leave housen   and he does  his co ambusher  they work in tandem  he and ishizaki restrain him until he goes unconscious","h":"<article class=\"card\" id=\"sc-yamada-albert-y2v4-p177-1\"><h3><span class=\"ttl\"><a href=\"../../../people/yamada-albert.html#sc-yamada-albert-y2v4-p177-1\">Ch.5: The ambusher in the 3-on-1<\/a><\/span><span class=\"meta\">Y2V4 · p.177–183<\/span><span class=\"by\">notes on <a href=\"../../../people/yamada-albert.html\">Yamada Albert<\/a><\/span><\/h3><p class=\"setup\">Disabled his GPS early as part of Ryūen&#x27;s plan; he waits behind the trees with Ishizaki; when Hōsen&#x27;s right dominant arm is exposed, Albert grips it — the strongest arm in the class against the gorilla.<\/p><p class=\"with\">with <a href=\"../../../people/housen-kazuomi.html\">Hōsen Kazuomi<\/a> · <a href=\"../../../people/ishizaki-daichi.html\">Ishizaki Daichi<\/a> · <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hōsen Kazuomi<\/b> “What ─── !?”<span class=\"pg\">p.177<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Yamada Albert<\/b> “Don’t bark so loud, Gorilla. Your execution is about to begin.” — Ryūen.<span class=\"pg\">p.177<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Yamada Albert<\/b> “Shit!!” — Hōsen.<span class=\"pg\">p.178<\/span><\/li><\/ul><details class=\"more\"><summary>16 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “It’s a simple story. If you break your watch, the GPS won’t recognize it.” — Ryūen.<span class=\"pg\">p.178<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Hey, big man ... Why the hell are you following Ryuuen? Eh?” — Hōsen.<span class=\"pg\">p.181<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It is true that I am a man that Ryuuen can’t defeat even if he faced me once or twice.”<span class=\"pg\">p.181<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Why then?” — Hōsen.<span class=\"pg\">p.181<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You don’t understand, Housen. Not only the monstrously powerful rise to the top.”<span class=\"pg\">p.181<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Kuku. Well, in Albert’s case, I’d say it’s just camaraderie”<span class=\"pg\">p.181<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don’t think you have won with this, Ryuuen!” — Hōsen.<span class=\"pg\">p.181<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But he’s a great guy. ...... I really thought he was a monster.” — Ryūen.<span class=\"pg\">p.182<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You would be a fool if you faced him.”<span class=\"pg\">p.182<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “They have had to work a lot.” — Ryūen.<span class=\"pg\">p.182<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No, no, no, no! We were just supporting you! Hey, Albert!” — Ishizaki.<span class=\"pg\">p.182<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You should get moving. The teachers could arrive at any moment.” — Ishizaki.<span class=\"pg\">p.182<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> He disables his GPS for Ryūen&#x27;s plan and takes Hōsen&#x27;s dominant arm in a 3-on-1 beating; he is bigger than Ryuuen and could beat him once or twice; he follows Ryūen by choice of camaraderie, not by fear; he keeps quiet while Hōsen barks threats.<span class=\"pg\">p.177–183<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> He waits in ambush for him; they win together; he is asked to leave Housen — and he does.<span class=\"pg\">p.177–183<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishizaki Daichi<\/b> His co-ambusher; they work in tandem.<span class=\"pg\">p.177–183<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> He and Ishizaki restrain him until he goes unconscious.<span class=\"pg\">p.177–183<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamada-albert-y2v4-p250-1\">→ After: Albert mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-ryuuen-kakeru-y2v4-p179-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"housen-kazuomi yamada-albert ishizaki-daichi katsuragi-kouhei ryuuen-kakeru","q":"ryuen kakeru ch 5  retirement together bloodied  barely standing   hosen unconscious  ishizaki and albert barely scratched  he compliments the gorilla  sits him on his knee  and they all head toward the starting point   ha  ha   damn     hosen   like a blow  a fall can make the difference between light and dark    narration   you never thought you d lose like this  but for me  the process doesn t matter  the last man standing is the winner   you had a guy like that as a subordinate   i didn t expect it   hey  big man   why the hell are you following ryuuen  eh   it is true that i am a man that ryuuen can t defeat even if he faced me once or twice    albert   you don t understand  housen  not only the monstrously powerful rise to the top   kuku  well  in albert s case  i d say it s just camaraderie    albert   don t think you have won with this  ryuuen   remember  even if you win here  the next time i see you  i will kill you immediately   i am not going to swallow your revenge of the gorilla  but if you are going to do it do it well it is not as simple as winning  winning is not as simple as it seems  if you go ahead  but you end up being expelled  you will you lose     what is it    huh    it was a tough fight     but he s a great guy    i really thought he was a monster   you would be a fool if you faced him    albert   they have had to work a lot    albert   no  no  no  no  we were just supporting you  hey  albert   you should get moving  the teachers could arrive at any moment   what about ryuen san    well  i m in this state  even if i wanted to continue  they wouldn t let me do it easily   i m going to retire together with housen   are you sure with that   i have left everything they need in the hands of katsuragi  although the first three groups have become more difficult to win   that is not the case   i ll tell you soon  go anyway now  he is battered   face rearranged  fists shredded   but his only regret is that hosen fought too well to make it fair  he retires with him to keep him from going after ayanokoji ever again  he lies about the reason later   something else awaits back at school  he beats him in a 3 on 1  he retires with him  all their plans are in his hands now  he sends them to the starting point with instructions to swap watches  he sends them to the starting point with instructions to swap watches","h":"<article class=\"card\" id=\"sc-ryuuen-kakeru-y2v4-p179-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ryuuen-kakeru.html#sc-ryuuen-kakeru-y2v4-p179-1\">Ch.5: Retirement together<\/a><\/span><span class=\"meta\">Y2V4 · p.179–183<\/span><span class=\"by\">notes on <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/span><\/h3><p class=\"setup\">Bloodied, barely standing — Hōsen unconscious; Ishizaki and Albert barely scratched; he compliments the gorilla, sits him on his knee, and they all head toward the starting point.<\/p><p class=\"with\">with <a href=\"../../../people/housen-kazuomi.html\">Hōsen Kazuomi<\/a> · <a href=\"../../../people/yamada-albert.html\">Yamada Albert<\/a> · <a href=\"../../../people/ishizaki-daichi.html\">Ishizaki Daichi<\/a> · <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> “Ha, ha ...... damn ......” — Hōsen.<span class=\"pg\">p.179<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hōsen Kazuomi<\/b> “Like a blow, a fall can make the difference between light and dark.” — narration.<span class=\"pg\">p.179<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> “You never thought you’d lose like this. But for me, the process doesn’t matter. The last man standing is the winner.”<span class=\"pg\">p.179<\/span><\/li><\/ul><details class=\"more\"><summary>27 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “You had a guy like that as a subordinate ... I didn’t expect it.”<span class=\"pg\">p.181<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Hey, big man ... Why the hell are you following Ryuuen? Eh?”<span class=\"pg\">p.181<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It is true that I am a man that Ryuuen can’t defeat even if he faced me once or twice.” — Albert.<span class=\"pg\">p.181<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You don’t understand, Housen. Not only the monstrously powerful rise to the top.”<span class=\"pg\">p.181<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Kuku. Well, in Albert’s case, I’d say it’s just camaraderie” — Albert.<span class=\"pg\">p.181<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don’t think you have won with this, Ryuuen!”<span class=\"pg\">p.181<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Remember, even if you win here, the next time I see you, I will kill you immediately.”<span class=\"pg\">p.182<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I am not going to swallow your revenge of the gorilla, but if you are going to do it....do it well It is not as simple as winning. Winning is not as simple as it seems. If you go ahead, but you end up being expelled, you will you lose. ”<span class=\"pg\">p.182<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What is it ...!”<span class=\"pg\">p.182<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Huh. ...... it was a tough fight. ”<span class=\"pg\">p.182<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But he’s a great guy. ...... I really thought he was a monster.”<span class=\"pg\">p.182<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You would be a fool if you faced him.” — Albert.<span class=\"pg\">p.182<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “They have had to work a lot.” — Albert.<span class=\"pg\">p.182<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No, no, no, no! We were just supporting you! Hey, Albert!”<span class=\"pg\">p.182<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You should get moving. The teachers could arrive at any moment.”<span class=\"pg\">p.182<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What about Ryuen-san ...?”<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, I’m in this state. Even if I wanted to continue, they wouldn’t let me do it easily.”<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m going to retire together with Housen”<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Are you sure with that?”<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I have left everything they need in the hands of Katsuragi. Although the first three groups have become more difficult to win”<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That is not the case.”<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’ll tell you soon. Go anyway now.”<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> He is battered — face rearranged, fists shredded — but his only regret is that Hōsen fought too well to make it fair; he retires with him to keep him from going after Ayanokōji ever again; he lies about the reason later — something else awaits back at school.<span class=\"pg\">p.179–183<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> He beats him in a 3-on-1; he retires with him.<span class=\"pg\">p.179–183<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Katsuragi Kōhei<\/b> All their plans are in his hands now.<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishizaki Daichi<\/b> He sends them to the starting point with instructions to swap watches.<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yamada Albert<\/b> He sends them to the starting point with instructions to swap watches.<span class=\"pg\">p.183<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ryuuen-kakeru-y2v4-p174-1\">← Before: Ch.5: The third on one<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v4-p183-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"ryuuen-kakeru housen-kazuomi ayanokouji-kiyotaka","q":"ayanokoji kiyotaka aftermath  ryuen and hosen retire together watches as ryuen  badly injured  decides to retire together with the unconscious hosen   the  only and most beautiful way  to stop him from returning to hunt ayanokoji   i m going to retire together with housen  understands ryuen s sacrifice  retiring to ensure hosen can t come after him again  tsubaki s plot collapses   hosen stopped  her first year groups neutralized   and she realizes her plan was doomed from early on  ryuen retires with hosen to protect ayanokoji s exam standing  neutralized   stops hunting ayanokoji","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v4-p183-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v4-p183-1\">Aftermath: Ryūen and Hōsen retire together<\/a><\/span><span class=\"meta\">Y2V4 · p.183–185<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Watches as Ryūen, badly injured, decides to retire together with the unconscious Hōsen — the “only and most beautiful way” to stop him from returning to hunt Ayanokōji.<\/p><p class=\"with\">with <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"../../../people/housen-kazuomi.html\">Hōsen Kazuomi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “I&#x27;m going to retire together with Housen”<span class=\"pg\">p.183<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Understands Ryūen&#x27;s sacrifice (retiring to ensure Hōsen can&#x27;t come after him again); Tsubaki&#x27;s plot collapses — Hōsen stopped, her first-year groups neutralized — and she realizes her plan was doomed from early on.<span class=\"pg\">p.183–185<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Ryūen retires with Hōsen to protect Ayanokōji&#x27;s exam standing.<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> Neutralized — stops hunting Ayanokōji.<span class=\"pg\">p.183<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p169-1\">← Before: AK mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p191-1\">→ After: Ch.6: Day thirteen dawn; the penalty chain<\/button><\/div><\/article>"},{"i":"sc-katsuragi-kouhei-y2v4-p183-1","v":"y2v4","y":2,"o":19,"k":"","w":"katsuragi-kouhei","q":"katsuragi kohei katsuragi mentioned in passing  i have left everything they need in the hands of katsuragi  although the first three groups have become more difficult to win    ryuen to ishizaki and albert  katsuragi holds the plans","h":"<article class=\"card\" id=\"sc-katsuragi-kouhei-y2v4-p183-1\"><h3><span class=\"ttl\"><a href=\"../../../people/katsuragi-kouhei.html#sc-katsuragi-kouhei-y2v4-p183-1\">Katsuragi mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.183<\/span><span class=\"by\">notes on <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a><\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “I have left everything they need in the hands of Katsuragi. Although the first three groups have become more difficult to win” — Ryūen to Ishizaki and Albert; Katsuragi holds the plans.<span class=\"pg\">p.183<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-katsuragi-kouhei-y2v4-p280-1\">→ After: Katsuragi mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-yagami-takuya-y2v4-p184-1","v":"y2v4","y":2,"o":19,"k":"","w":"yagami-takuya","q":"yagami takuya yagami mentioned in passing  yagami presses her  but tsubaki looks away and mutters with interest    narration   when she said that  yagami also pretended to notice utomiya s absence    narration   where sakurako tsubaki  hachi  takuya yagami and utomiya riku are    narration","h":"<article class=\"card\" id=\"sc-yagami-takuya-y2v4-p184-1\"><h3><span class=\"ttl\"><a href=\"../../../people/yagami-takuya.html#sc-yagami-takuya-y2v4-p184-1\">Yagami mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.184–186<\/span><span class=\"by\">notes on <a href=\"../../../people/yagami-takuya.html\">Yagami Takuya<\/a><\/span><\/h3><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “Yagami presses her, but Tsubaki looks away and mutters with interest.” — narration.<span class=\"pg\">p.184<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “When she said that, Yagami also pretended to notice Utomiya&#x27;s absence.” — narration.<span class=\"pg\">p.185<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “where Sakurako Tsubaki, Hachi, Takuya Yagami and Utomiya Riku are.” — narration.<span class=\"pg\">p.186<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yagami-takuya-y2v4-p151-1\">← Before: Ch.5: The failed siege; the fifth freeze<\/button><\/div><\/article>"},{"i":"sc-kitou-hayato-y2v4-p185-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"utomiya-riku sakayanagi-arisu tsubaki-sakurako kitou-hayato","q":"kito hayato ch 5  kitou unmasks the commander sakayanagi dispatches him to unmask whoever is directing the first years  siege  he runs through the forest and is blocked by a man on the road   utomiya riku  first year class c  utomiya attacks him   what do you want on these roads   i think you are kitou hayato senpai   a second year student from class a   i m in a hurry now   what is it   i m sorry  but i m not going to let you pass from here   what   what are you doing   i ll tell you  i m not going to let you pass from here   what is your name   1st year of class c  utomiya   i have no intention of showing any compassion even with a senpai   oh crap   didn t you follow my instructions    tsubaki s voice from the walkie talkie  tsubaki continues to do so  though she doubts she won t get an answer   what are you going to do     utomiya   the objective has been reached    it s me    utomiya answering the walkie talkie  he is sent to pin down the first year commander  utomiya attacks him  he dodges everything  utomiya s walkie talkie drops at his feet  he holds his position  he reads tsubaki s voice through it and walks away with the commander s identity confirmed  her agent  she tasked him to unmask the mastermind  he does it  he is the first year gatekeeper  utomiya attacks him and loses the walkie talkie  her voice leaks over the dropped walkie talkie  he identifies her as the commander","h":"<article class=\"card\" id=\"sc-kitou-hayato-y2v4-p185-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kitou-hayato.html#sc-kitou-hayato-y2v4-p185-1\">Ch.5: Kitou unmasks the commander<\/a><\/span><span class=\"meta\">Y2V4 · p.185–189<\/span><span class=\"by\">notes on <a href=\"../../../people/kitou-hayato.html\">Kitō Hayato<\/a><\/span><\/h3><p class=\"setup\">Sakayanagi dispatches him to unmask whoever is directing the first-years&#x27; siege; he runs through the forest and is blocked by a man on the road — Utomiya Riku, first year Class C; Utomiya attacks him.<\/p><p class=\"with\">with <a href=\"../../../people/utomiya-riku.html\">Utomiya Riku<\/a> · <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a> · <a href=\"../../../people/tsubaki-sakurako.html\">Tsubaki Sakurako<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Utomiya Riku<\/b> “What do you want on these roads?”<span class=\"pg\">p.186<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kitō Hayato<\/b> “I think you are Kitou Hayato-senpai ......, a second year student from class A”<span class=\"pg\">p.186<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kitō Hayato<\/b> “I&#x27;m in a hurry now”<span class=\"pg\">p.186<\/span><\/li><\/ul><details class=\"more\"><summary>18 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “……What is it”<span class=\"pg\">p.186<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;m sorry, but I&#x27;m not going to let you pass from here.”<span class=\"pg\">p.186<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What?”<span class=\"pg\">p.186<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What are you doing?”<span class=\"pg\">p.188<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;ll tell you. I&#x27;m not going to let you pass from here.”<span class=\"pg\">p.188<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What is your name?”<span class=\"pg\">p.188<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “1st year of class C, Utomiya”<span class=\"pg\">p.188<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I have no intention of showing any compassion even with a senpai.”<span class=\"pg\">p.188<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Oh crap……!”<span class=\"pg\">p.188<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Didn&#x27;t you follow my instructions?” — Tsubaki&#x27;s voice from the walkie-talkie.<span class=\"pg\">p.189<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Tsubaki continues to do so, though she doubts she won’t get an answer.<span class=\"pg\">p.189<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What are you going to do ...?” — Utomiya.<span class=\"pg\">p.189<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The objective has been reached”<span class=\"pg\">p.189<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “... It&#x27;s me.” — Utomiya answering the walkie-talkie.<span class=\"pg\">p.189<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> He is sent to pin down the first-year commander; Utomiya attacks him; he dodges everything; Utomiya&#x27;s walkie-talkie drops at his feet; he holds his position; he reads Tsubaki&#x27;s voice through it and walks away with the commander&#x27;s identity confirmed.<span class=\"pg\">p.185–189<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Her agent; she tasked him to unmask the mastermind; he does it.<span class=\"pg\">p.185–189<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Utomiya Riku<\/b> He is the first-year gatekeeper; Utomiya attacks him and loses the walkie-talkie.<span class=\"pg\">p.185–189<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsubaki Sakurako<\/b> Her voice leaks over the dropped walkie-talkie; he identifies her as the commander.<span class=\"pg\">p.189<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v4-p191-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"sakayanagi-arisu ichinose-honami ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 6  day thirteen dawn  the penalty chain waking at e3 on the last day  five freshmen groups circled him  housen unaccounted for  sakayanagi reports ichinose disappeared at dawn  the designated area h3 gives him no mercy   he will have to fight to reach it   good morning  ayanokouji kun  you had a lot of problems yesterday     thank you sakayanagi for saving me   do you agree with the penalty  you seem to have moved a lot during the night     i m sure sakayanagi is aware of my movements through the gps   the first designated area is h3  there is not much time  but i think i can do it     actually  i m in trouble  at dawn  ichinose san disappeared   no  it seems to be an involuntary action  the last few days she has been acting strange   but why did you contact me  i m sure there is nothing i can do to help you     actually  when i did a gps search to find out ichinose san s position  i found that it was at the same e3 as ayanokouji kun  however  it is the opposite d3 side   what was the final designated area of ichinose yesterday   it was d5  ichinose san arrived there  she started performing at dawn without telling anyone  and now she was here at e3 for some reason in the morning  i realized that we had lost a point  i checked with the people in the group  but there was no sign that anyone had used the gps search  it seems that ichinose used it  it is not known if her objective was e3 or a further area  but it is normal to think that she went to meet someone     i thought maybe it was to meet ayanokouji kun  but    i m sorry  but i don t know  i haven t seen ichinose in this special exam  if you wait  ichinose can get to f3 s side  sorry  i m in a hurry  what are you going to do   the first designated area we had to go to was e6  i ll discard the reward on a first come  first served basis  but i must ignore it  in the worst case  if you withdraw  it will not have a great negative effect on this last day     you are in trouble   accidents are destined to happen  you know  well  even if you let it  the special exam will be over in half a day  so i don t think there is any problem  if you ever see her  tell her about the situation    six consecutive missed areas  four consecutive penalties pending  he is pushed below the public visible line  he decides to ignore i2 s trap and head to i2 on suspicion alone  the walkie talkie relay  ichinose s disappearance disclosed  her disappearance is his problem only if she reaches him","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v4-p191-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v4-p191-1\">Ch.6: Day thirteen dawn; the penalty chain<\/a><\/span><span class=\"meta\">Y2V4 · p.191–194<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Waking at E3 on the last day; five freshmen groups circled him; Housen unaccounted for; Sakayanagi reports Ichinose disappeared at dawn; the designated area H3 gives him no mercy — he will have to fight to reach it.<\/p><p class=\"with\">with <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a> · <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Sakayanagi Arisu<\/b> “Good morning, Ayanokouji-kun. You had a lot of problems yesterday. ”<span class=\"pg\">p.192<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Thank you Sakayanagi for saving me”<span class=\"pg\">p.192<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sakayanagi Arisu<\/b> “Do you agree with the penalty? You seem to have moved a lot during the night. ”<span class=\"pg\">p.192<\/span><\/li><\/ul><details class=\"more\"><summary>16 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “I’m sure Sakayanagi is aware of my movements through the GPS.”<span class=\"pg\">p.192<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The first designated area is H3. There is not much time, but I think I can do it. ”<span class=\"pg\">p.192<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Actually, I’m in trouble. At dawn, Ichinose-san disappeared.”<span class=\"pg\">p.192<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No, it seems to be an involuntary action. The last few days she has been acting strange.”<span class=\"pg\">p.192<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But why did you contact me? I’m sure there is nothing I can do to help you. ”<span class=\"pg\">p.192<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Actually, when I did a GPS search to find out Ichinose-san’s position, I found that it was at the same E3 as Ayanokouji-kun. However, it is the opposite D3 side.”<span class=\"pg\">p.192<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What was the final designated area of Ichinose yesterday?”<span class=\"pg\">p.193<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It was D5. Ichinose-san arrived there. She started performing at dawn without telling anyone, and now she was here at E3 for some reason?....In the morning, I realized that we had lost a point. I checked with the people in the group, but there was no sign that anyone had used the GPS search. It seems that Ichinose used it. It is not known if her objective was E3 or a further area, but it is normal to think that she went to meet someone. ”<span class=\"pg\">p.193<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I thought maybe it was to meet Ayanokouji-kun, but ...”<span class=\"pg\">p.193<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m sorry, but I don’t know. I haven’t seen Ichinose in this special exam. If you wait, Ichinose can get to F3’s side, sorry, I’m in a hurry. What are you going to do?”<span class=\"pg\">p.193<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The first designated area we had to go to was E6. I’ll discard the reward on a first-come, first-served basis, but I must ignore it. In the worst case, if you withdraw, it will not have a great negative effect on this last day. ”<span class=\"pg\">p.193<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You are in trouble?”<span class=\"pg\">p.193<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Accidents are destined to happen, you know. Well, even if you let it, the special exam will be over in half a day, so I don’t think there is any problem. If you ever see her, tell her about the situation. ”<span class=\"pg\">p.193<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Six consecutive missed areas, four consecutive penalties pending; he is pushed below the public visible line; he decides to ignore I2&#x27;s trap and head to I2 on suspicion alone.<span class=\"pg\">p.191–194<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> The walkie-talkie relay; Ichinose&#x27;s disappearance disclosed.<span class=\"pg\">p.191–194<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Her disappearance is his problem only if she reaches him.<span class=\"pg\">p.192–194<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p183-1\">← Before: Aftermath: Ryūen and Hōsen retire together<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p191-2\">→ After: Last day: Ichinose&#x27;s four-hour walk; her confession<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v4-p191-2","v":"y2v4","y":2,"o":19,"k":"spoken","w":"sakayanagi-arisu ichinose-honami tsukishiro ayanokouji-kiyotaka","q":"ayanokoji kiyotaka last day  ichinose s four hour walk  her confession on the final day  reels from six consecutive missed areas  four penalties  sakayanagi warns via walkie talkie that ichinose has disappeared and was seen using gps near e3 d3   good morning  ayanokouji kun  you had a lot of problems yesterday   actually  i m in trouble  at dawn  ichinose san disappeared   i  i came here because i wanted to see you  ayanokouji kun   i have something i have to tell you  no matter what  ayanokouji kun   i  my watch broke  so i wanted to go back to the starting point to change it  and then  acting director tsukishiro  and shiba sensei  those two  they were there   if you re safe in the last day  ayanokouji kun  you ll be called to i2 and be buried   because i  because i like you  ayanokouji kun   thank you  ichinose   i think that there s still a few things that has to be addressed  and i don t think someone can answer yes or no in this state  deeply moved that ichinose walked 4  hours  exhausted and covered in mud  risking her classmates  expulsion to warn him of tsukishiro s i2 trap  accepts her confession graciously but can t reciprocate now  hides kei  deciding the exam climax isn t the place  realizes tsukishiro s move against him and resolves to go to i2  coming back from the dead  she confesses her love and warns him of the trap   a  watershed moment  for him  learned of his i2 trap via ichinose  warns him about ichinose  he asks her to relay word if seen","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v4-p191-2\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v4-p191-2\">Last day: Ichinose&#x27;s four-hour walk; her confession<\/a><\/span><span class=\"meta\">Y2V4 · p.191–201<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">On the final day, reels from six consecutive missed areas (four penalties); Sakayanagi warns via walkie-talkie that Ichinose has disappeared and was seen using GPS near E3/D3.<\/p><p class=\"with\">with <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a> · <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a> · <a href=\"../../../people/tsukishiro.html\">Tsukishiro<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Sakayanagi Arisu<\/b> “Good morning, Ayanokouji-kun. You had a lot of problems yesterday.”<span class=\"pg\">p.192<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Actually, I&#x27;m in trouble. At dawn, Ichinose-san disappeared.”<span class=\"pg\">p.192<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ichinose Honami<\/b> “I, I came here because I wanted to see you, Ayanokouji-kun.”<span class=\"pg\">p.195<\/span><\/li><\/ul><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “I have something I have to tell you, no matter what, Ayanokouji-kun!”<span class=\"pg\">p.196<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I, my watch broke, so I wanted to go back to the starting point to change it… And then, Acting Director Tsukishiro, and Shiba-sensei, those two, they were there…!”<span class=\"pg\">p.197<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If you&#x27;re safe in the last day, Ayanokouji-kun, you&#x27;ll be called to I2 and be buried.”<span class=\"pg\">p.197<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Because I, because I like you, Ayanokouji-kun…!”<span class=\"pg\">p.198<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “–Thank you, Ichinose.”<span class=\"pg\">p.199<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I think that there&#x27;s still a few things that has to be addressed, and I don&#x27;t think someone can answer yes or no in this state.”<span class=\"pg\">p.200<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Deeply moved that Ichinose walked 4+ hours, exhausted and covered in mud, risking her classmates&#x27; expulsion to warn him of Tsukishiro&#x27;s I2 trap; accepts her confession graciously but can&#x27;t reciprocate now (hides Kei), deciding the exam climax isn&#x27;t the place; realizes Tsukishiro&#x27;s move against him and resolves to go to I2 (“coming back from the dead”).<span class=\"pg\">p.191–201<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> She confesses her love and warns him of the trap — a “watershed moment” for him.<span class=\"pg\">p.191–201<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsukishiro<\/b> Learned of his I2 trap via Ichinose.<span class=\"pg\">p.197–201<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Warns him about Ichinose; he asks her to relay word if seen.<span class=\"pg\">p.192–193<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p191-1\">← Before: Ch.6: Day thirteen dawn; the penalty chain<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p202-1\">→ After: Ch.6: Nagumo on the beach; the guessing game<\/button><\/div><\/article>"},{"i":"sc-sakayanagi-arisu-y2v4-p191-1","v":"y2v4","y":2,"o":19,"k":"","w":"sakayanagi-arisu","q":"sakayanagi arisu sakayanagi mentioned in passing  sakayanagi reported that she had left immediately in the afternoon    ayanokoji   good morning  ayanokouji kun  you had a lot of problems yesterday    sakayanagi   the first designated area is h3  there is not much time  but i think i can do it    sakayanagi   according to sakayanagi  ichinose should have been in e3 now    ayanokoji   the walkie talkie that sakayanagi lent me was useful to the end    ayanokoji   the students who were sent to detain the freshmen were all outside of sakayanagi s group    narration","h":"<article class=\"card\" id=\"sc-sakayanagi-arisu-y2v4-p191-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sakayanagi-arisu.html#sc-sakayanagi-arisu-y2v4-p191-1\">Sakayanagi mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.191–280<\/span><span class=\"by\">notes on <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/span><\/h3><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “Sakayanagi reported that she had left immediately in the afternoon...” — Ayanokōji.<span class=\"pg\">p.191<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Good morning, Ayanokouji-kun. You had a lot of problems yesterday.” — Sakayanagi.<span class=\"pg\">p.192<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “The first designated area is H3. There is not much time, but I think I can do it.” — Sakayanagi.<span class=\"pg\">p.193<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “According to Sakayanagi, Ichinose should have been in E3 now.” — Ayanokōji.<span class=\"pg\">p.195<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “The walkie-talkie that Sakayanagi lent me was useful to the end.” — Ayanokōji.<span class=\"pg\">p.270<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “The students who were sent to detain the freshmen were all outside of Sakayanagi&#x27;s group.” — narration.<span class=\"pg\">p.280<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sakayanagi-arisu-y2v4-p159-1\">← Before: Ch.5: The second-grade countermove<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sakayanagi-arisu-y2v4-p276-1\">→ After: Sakayanagi&#x27;s promise; 3rd place<\/button><\/div><\/article>"},{"i":"sc-tsukishiro-y2v4-p191-1","v":"y2v4","y":2,"o":19,"k":"","w":"tsukishiro","q":"tsukishiro tsukishiro mentioned in passing  chapter 6  the man known as tsukishiro    the chapter heading   and then  acting director tsukishiro  and shiba sensei  those two  they were there    ichinose reports   if i told this to you  acting director tsukishiro would make my classmates drop out  but i can t turn my back on you no matter what    ichinose   i wouldn t have thought that tsukishiro would have gone to i2  tsukishiro had threatened ichinose  but even so  she was here  right before my eyes    ayanokoji   it s necessary for me to tell tsukishiro  that it wasn t the end of the road for me    ayanokoji   ichinose said that this was the place where tsukishiro prepared to bury me    ayanokoji   it was acting director tsukishiro s    nagumo   since the opponent was tsukishiro  in the worst case scenario  nagumo could lose everything he had built up and be expelled under his name    ayanokoji   if i didn t solve the issue of tsukishiro  i wouldn t be able to open a path to the road of the future    ayanokoji   the conversation about what happened in i2  i can t tell her about tsukishiro    ayanokoji","h":"<article class=\"card\" id=\"sc-tsukishiro-y2v4-p191-1\"><h3><span class=\"ttl\"><a href=\"../../../people/tsukishiro.html#sc-tsukishiro-y2v4-p191-1\">Tsukishiro mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.191, 197–202, 204, 210, 214, 274<\/span><span class=\"by\">notes on <a href=\"../../../people/tsukishiro.html\">Tsukishiro<\/a><\/span><\/h3><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “Chapter 6: The Man Known As Tsukishiro” — the chapter heading.<span class=\"pg\">p.191<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “And then, Acting Director Tsukishiro, and Shiba-sensei, those two, they were there…!” — Ichinose reports.<span class=\"pg\">p.197<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “If I told this to you… Acting Director Tsukishiro would make my classmates drop out… But I can&#x27;t turn my back on you no matter what.” — Ichinose.<span class=\"pg\">p.198<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “I wouldn&#x27;t have thought that Tsukishiro would have gone to I2. Tsukishiro had threatened Ichinose, but even so, she was here, right before my eyes.” — Ayanokōji.<span class=\"pg\">p.199<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “It&#x27;s necessary for me to tell Tsukishiro, that it wasn&#x27;t the end of the road for me.” — Ayanokōji.<span class=\"pg\">p.201<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Ichinose said that this was the place where Tsukishiro prepared to bury me.” — Ayanokōji.<span class=\"pg\">p.202<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “It was Acting Director Tsukishiro&#x27;s.” — Nagumo.<span class=\"pg\">p.204<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Since the opponent was Tsukishiro, in the worst-case scenario, Nagumo could lose everything he had built up and be expelled under his name.” — Ayanokōji.<span class=\"pg\">p.210<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “If I didn&#x27;t solve the issue of Tsukishiro, I wouldn&#x27;t be able to open a path to the road of the future.” — Ayanokōji.<span class=\"pg\">p.214<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “the conversation about what happened in I2. I can&#x27;t tell her about Tsukishiro.” — Ayanokōji.<span class=\"pg\">p.274<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsukishiro-y2v4-p162-1\">← Before: Tsukishiro mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-tsukishiro-y2v4-p252-1\">→ After: Tsukishiro&#x27;s final trap at I2; his defeat<\/button><\/div><\/article>"},{"i":"sc-ichinose-honami-y2v4-p192-1","v":"y2v4","y":2,"o":19,"k":"","w":"ichinose-honami","q":"ichinose honami sakayanagi reports ichinose missing  actually  i m in trouble  at dawn  ichinose san disappeared    sakayanagi   it was d5  ichinose san arrived there  she started performing at dawn without telling anyone  and now she was here at e3    sakayanagi   i had been thinking of using gps search to find out ichinose s location    ayanokoji","h":"<article class=\"card\" id=\"sc-ichinose-honami-y2v4-p192-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ichinose-honami.html#sc-ichinose-honami-y2v4-p192-1\">Sakayanagi reports Ichinose missing<\/a><\/span><span class=\"meta\">Y2V4 · p.192–194<\/span><span class=\"by\">notes on <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/span><\/h3><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “Actually, I&#x27;m in trouble. At dawn, Ichinose-san disappeared.” — Sakayanagi.<span class=\"pg\">p.192<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “It was D5. Ichinose-san arrived there. She started performing at dawn without telling anyone, and now she was here at E3...” — Sakayanagi.<span class=\"pg\">p.193<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “I had been thinking of using GPS search to find out Ichinose&#x27;s location...” — Ayanokōji.<span class=\"pg\">p.194<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y2v4-p162-1\">← Before: Ichinose mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y2v4-p195-1\">→ After: Ichinose&#x27;s confession at H3<\/button><\/div><\/article>"},{"i":"sc-ichinose-honami-y2v4-p195-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"ayanokouji-kiyotaka tsukishiro shiba-katsunori ichinose-honami","q":"ichinose honami ichinose s confession at h3 covered in mud and exhausted  walks 4  hours to h3 to find ayanokoji  having been threatened by tsukishiro shiba after her watch broke   ayanokouji kun   i  i came here because i wanted to see you  ayanokouji kun   i  i have something i have to tell you  no matter what  ayanokouji kun   i ve been troubled  troubled  i ve always been troubled  to protect my friends and classmates   if you re safe in the last day  ayanokouji kun  you ll be called to i2 and be buried   if i told this to you  acting director tsukishiro would make my classmates drop out  but i can t turn my back on you no matter what   because i  because i like you  ayanokouji kun   no  that s not right  that  eh  just now  why did i  eh  ehhhhhhhh   that  misunderstanding  it s not a misunderstanding   i like  you  desperate and selfless   prioritizes ayanokoji s safety over her classmates despite tsukishiro s threat  blurts out  i like you  in exhaustion  then panics  as if the words escaped her  and admits it was no misunderstanding  accepts his gentle refusal without disdain  warns him of the i2 trap and confesses her love  he thanks her but can t reciprocate now  threatened her   if she told anyone  her classmates would be forced to drop out  was with tsukishiro when her watch broke","h":"<article class=\"card\" id=\"sc-ichinose-honami-y2v4-p195-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ichinose-honami.html#sc-ichinose-honami-y2v4-p195-1\">Ichinose&#x27;s confession at H3<\/a><\/span><span class=\"meta\">Y2V4 · p.195–201<\/span><span class=\"by\">notes on <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/span><\/h3><p class=\"setup\">Covered in mud and exhausted, walks 4+ hours to H3 to find Ayanokōji, having been threatened by Tsukishiro/Shiba after her watch broke.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/tsukishiro.html\">Tsukishiro<\/a> · <a href=\"../../../people/shiba-katsunori.html\">Shiba Katsunori<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ichinose Honami<\/b> “Ayanokouji-kun———!”<span class=\"pg\">p.195<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ichinose Honami<\/b> “I, I came here because I wanted to see you, Ayanokouji-kun.”<span class=\"pg\">p.195<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ichinose Honami<\/b> “I, I have something I have to tell you, no matter what, Ayanokouji-kun!”<span class=\"pg\">p.196<\/span><\/li><\/ul><details class=\"more\"><summary>11 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;ve been troubled, troubled. I&#x27;ve always been troubled… to protect my friends and classmates…”<span class=\"pg\">p.196<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If you&#x27;re safe in the last day, Ayanokouji-kun, you&#x27;ll be called to I2 and be buried.”<span class=\"pg\">p.197<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If I told this to you… Acting Director Tsukishiro would make my classmates drop out… But I can&#x27;t turn my back on you no matter what.”<span class=\"pg\">p.198<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Because I, because I like you, Ayanokouji-kun…!”<span class=\"pg\">p.198<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No, that&#x27;s not right! That, eh, just now, why did I, eh, ehhhhhhhh!?”<span class=\"pg\">p.198<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…That…. misunderstanding… it&#x27;s not a misunderstanding…”<span class=\"pg\">p.200<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…I like… you…”<span class=\"pg\">p.200<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Desperate and selfless — prioritizes Ayanokōji&#x27;s safety over her classmates despite Tsukishiro&#x27;s threat, blurts out “I like you” in exhaustion (then panics, as if the words escaped her), and admits it was no misunderstanding; accepts his gentle refusal without disdain.<span class=\"pg\">p.195–201<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Warns him of the I2 trap and confesses her love; he thanks her but can&#x27;t reciprocate now.<span class=\"pg\">p.195–201<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsukishiro<\/b> Threatened her — if she told anyone, her classmates would be forced to drop out.<span class=\"pg\">p.197–198<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiba Katsunori<\/b> Was with Tsukishiro when her watch broke.<span class=\"pg\">p.197<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y2v4-p192-1\">← Before: Sakayanagi reports Ichinose missing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y2v4-p202-1\">→ After: Ichinose mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-shiba-katsunori-y2v4-p197-1","v":"y2v4","y":2,"o":19,"k":"","w":"shiba-katsunori","q":"shiba katsunori shiba mentioned in passing  i  my watch broke  so i wanted to go back to the starting point to change it  and then  acting director tsukishiro  and shiba sensei  those two  they were there    ichinose reports  tsukishiro and shiba were there when her watch broke   if i told this to you  acting director tsukishiro would make my classmates drop out  but i can t turn my back on you no matter what    ichinose","h":"<article class=\"card\" id=\"sc-shiba-katsunori-y2v4-p197-1\"><h3><span class=\"ttl\"><a href=\"../../../people/shiba-katsunori.html#sc-shiba-katsunori-y2v4-p197-1\">Shiba mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.197–198<\/span><span class=\"by\">notes on <a href=\"../../../people/shiba-katsunori.html\">Shiba Katsunori<\/a><\/span><\/h3><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “I, my watch broke, so I wanted to go back to the starting point to change it… And then, Acting Director Tsukishiro, and Shiba-sensei, those two, they were there…!” — Ichinose reports; Tsukishiro and Shiba were there when her watch broke.<span class=\"pg\">p.197<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “If I told this to you… Acting Director Tsukishiro would make my classmates drop out… But I can&#x27;t turn my back on you no matter what.” — Ichinose.<span class=\"pg\">p.198<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-shiba-katsunori-y2v4-p252-1\">→ After: Shiba and the I2 trap<\/button><\/div><\/article>"},{"i":"sc-karuizawa-kei-y2v4-p200-1","v":"y2v4","y":2,"o":19,"k":"","w":"karuizawa-kei","q":"karuizawa kei karuizawa mentioned in passing  and it s also necessary to avoid telling her about kei right now    his interior  ichinose has just confessed  he cannot tell her about kei in this moment  passing mention  she is the unspoken counterweight to ichinose s confession  her name is printed in his thoughts only","h":"<article class=\"card\" id=\"sc-karuizawa-kei-y2v4-p200-1\"><h3><span class=\"ttl\"><a href=\"../../../people/karuizawa-kei.html#sc-karuizawa-kei-y2v4-p200-1\">Karuizawa mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.200<\/span><span class=\"by\">notes on <a href=\"../../../people/karuizawa-kei.html\">Karuizawa Kei<\/a><\/span><\/h3><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “And it’s also necessary to avoid telling her about Kei right now.” — his interior; Ichinose has just confessed; he cannot tell her about Kei in this moment.<span class=\"pg\">p.200<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Passing mention; she is the unspoken counterweight to Ichinose’s confession; her name is printed in his thoughts only.<span class=\"pg\">p.200<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-nagumo-miyabi-y2v4-p201-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"ayanokouji-kiyotaka kouenji-rokusuke horikita-manabu nagumo-miyabi","q":"nagumo miyabi ch 6  the beach talk  he gets knocked out on the last day  ayanokoji walks to i2 and finds president nagumo standing on the beach with a tablet  the two of them talk   the bounty  horikita senpai  koenji  why ayanokoji is really here   ayanokouji  what a coincidence   don t worry  we are the only ones here   i was having fun on the beach at i4  life on this uninhabited island is coming to an end  after all   but i ll ask you the same thing  ayanokouji  this place is not a designated area and doesn t have an event  so why did you come here  did you meet up with honami   no  if you two are still together now  you would have spoken about quite a bit  but you are here by yourself  so it means you have a different objective  what s there at i2   your critical thinking ain t bad   don t blame me for the bounty  it wasn t my proposal in the first place   it was acting director tsukishiro s   since you know this much  i ll be blunt  the money s all from the acting director  i just lent the name of the student council president to him   it s an order from the acting director  so you had to accept it  but if it s the student council president i know  i think you would have refused such a proposal  right   if it s about the matter of the bounty  i wouldn t have accepted it  if it were a student other than you  but the one which he named was none other but you  the only man that horikita senpai trusted   answer me  ayanokouji  what do you plan to do next   don t worry about it  on this last day  i have completely overwhelmed koenji   although i do care what you re going to do  if you won t answer  then i ll change my question  let me see if you  who hold the expectations of horikita senpai  have the strength worthy of my expectations  which of course means that you ll have to get serious   let me guess your group s ranking at the end of the 12th day   you re ranked 11th  right   a little off  then you re ranked around 15th or 16th right   i joked around with that superpower stuff  i just guessed  assuming that you really have hidden your strength   in order not to attract attention  your ranking is a bit lower than 10th  but still  you ve maintained an upper ranking position  if i lose the battle against koenji  then you d have a chance to make a comeback   kurona from third year has been keeping the 10th place  right  i had him maintain that rank to block those who had been secretly saving points and aiming to make a comeback   if i want to earn points  whether that s 400 or 500 points  i can earn them  however  that s not interesting  right  now there s hope that he might beat the second and first years  besides  if he lost in the battle with me  we might be able to see his regretful expression   was it part of your plan  your command of the attack on koenji on the last day   i ve always doubted whether you were strong enough  but now i understand  you ve been granted the right to be crushed by me  so rejoice   then i would have to force you to appear on the front stage  which includes using the bounty   you think you can escape this easily  i won t let you go before you agree to a fight with me   president nagumo  although your abilities are different from president horikita s  it still allowed you to brilliantly stand at the top of this school  you maintained a top ranking in this special exam with ease  and it s no exaggeration to say you had complete control over it  even so  i plan to beat you   it s just that there are certain areas where you shouldn t step into  please understand   don t you understand what i said   i  the transceiver voice   nagumo  i ve gotten in the way of koenji s event three times in a row  please give me your next instructions    a 3rd year student reports   hey  nagumo  if you don t give instructions  your subordinates can t act  in order to drop koenji down to 2nd  isn t it necessary to continue with the attack until the end    he switches it off   what s important to me isn t koenji    he lunges  ayanokoji punches him once in the chest and he collapses  his warning alarm rings  ayanokoji hides him under a tree  20 30 minutes before someone finds him  he walks away to i2  he is a god among men on this island  he runs the third year lockdown to block comebacks  he enjoys unmasking ayanokoji to force him to  be  manabu s shadow  he loses to a single punch and goes down for good   without landing a blow  he came to measure ayanokoji against horikita manabu  he gets measured  he loses in a second  he is working to drop koenji down to second  he uses the 3rd years to do it  the transceiver men are his  he sees the ghost of manabu in ayanokoji  his whole approach is manabu s ghost","h":"<article class=\"card\" id=\"sc-nagumo-miyabi-y2v4-p201-1\"><h3><span class=\"ttl\"><a href=\"../../../people/nagumo-miyabi.html#sc-nagumo-miyabi-y2v4-p201-1\">Ch.6: The beach talk; he gets knocked out<\/a><\/span><span class=\"meta\">Y2V4 · p.201–214<\/span><span class=\"by\">notes on <a href=\"../../../people/nagumo-miyabi.html\">Nagumo Miyabi<\/a><\/span><\/h3><p class=\"setup\">On the last day, Ayanokōji walks to I2 and finds President Nagumo standing on the beach with a tablet; the two of them talk — the bounty, Horikita-senpai, Koenji, why Ayanokōji is really here.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/kouenji-rokusuke.html\">Kōenji Rokusuke<\/a> · <a href=\"../../../people/horikita-manabu.html\">Horikita Manabu<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Nagumo Miyabi<\/b> “Ayanokouji, what a coincidence.”<span class=\"pg\">p.202<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nagumo Miyabi<\/b> “Don’t worry. We are the only ones here.”<span class=\"pg\">p.202<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nagumo Miyabi<\/b> “I was having fun on the beach at I4. Life on this uninhabited island is coming to an end, after all.”<span class=\"pg\">p.203<\/span><\/li><\/ul><details class=\"more\"><summary>31 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “But I’ll ask you the same thing, Ayanokouji. This place is not a designated area and doesn’t have an event, so why did you come here? Did you meet up with Honami?”<span class=\"pg\">p.203<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No. If you two are still together now, you would have spoken about quite a bit. But you are here by yourself, so it means you have a different objective. What’s there at I2?”<span class=\"pg\">p.203<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Your critical thinking ain’t bad.”<span class=\"pg\">p.204<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don’t blame me for the bounty. It wasn’t my proposal in the first place.”<span class=\"pg\">p.204<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It was Acting Director Tsukishiro’s.”<span class=\"pg\">p.204<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Since you know this much, I’ll be blunt. The money’s all from the Acting Director. I just lent the name of the Student Council president to him.”<span class=\"pg\">p.204<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s an order from the Acting Director, so you had to accept it. But if it’s the Student Council President I know, I think you would have refused such a proposal, right?”<span class=\"pg\">p.204<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If it’s about the matter of the bounty, I wouldn’t have accepted it, if it were a student other than you. But the one which he named was none other but you, the only man that Horikita-senpai trusted.”<span class=\"pg\">p.204<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Answer me, Ayanokouji. What do you plan to do next?”<span class=\"pg\">p.205<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don’t worry about it. On this last day, I have completely overwhelmed Koenji.”<span class=\"pg\">p.205<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Although I do care what you’re going to do, if you won’t answer, then I’ll change my question. Let me see if you, who hold the expectations of Horikita-senpai, have the strength worthy of my expectations, which of course means that you’ll have to get serious.”<span class=\"pg\">p.205<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Let me guess your group’s ranking at the end of the 12th day.”<span class=\"pg\">p.207<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You’re ranked…11th, right?”<span class=\"pg\">p.208<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “A little off? Then you’re ranked around 15th or 16th right?”<span class=\"pg\">p.208<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I joked around with that superpower stuff. I just guessed, assuming that you really have hidden your strength.”<span class=\"pg\">p.208<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “In order not to attract attention, your ranking is a bit lower than 10th, but still, you’ve maintained an upper-ranking position. If I lose the battle against Koenji, then you’d have a chance to make a comeback.”<span class=\"pg\">p.208<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Kurona from third-year has been keeping the 10th place, right? I had him maintain that rank to block those who had been secretly saving points and aiming to make a comeback.”<span class=\"pg\">p.208<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If I want to earn points, whether that’s 400 or 500 points, I can earn them. However, that’s not interesting, right? Now there’s hope that he might beat the second and first-years. Besides, if he lost in the battle with me, we might be able to see his regretful expression.”<span class=\"pg\">p.209<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Was it part of your plan? Your command of the attack on Koenji on the last day?”<span class=\"pg\">p.209<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’ve always doubted whether you were strong enough, but now I understand. You’ve been granted the right to be crushed by me, so rejoice.”<span class=\"pg\">p.209<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Then I would have to force you to appear on the front stage, which includes using the bounty.”<span class=\"pg\">p.210<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You think you can escape this easily? I won’t let you go before you agree to a fight with me.”<span class=\"pg\">p.210<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “President Nagumo, although your abilities are different from President Horikita’s, it still allowed you to brilliantly stand at the top of this school. You maintained a top ranking in this special exam with ease, and it’s no exaggeration to say you had complete control over it. Even so, I plan to beat you.”<span class=\"pg\">p.212<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s just that there are certain areas where you shouldn’t step into. Please understand.”<span class=\"pg\">p.212<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don’t you understand what I said?”<span class=\"pg\">p.212<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I…!?”<span class=\"pg\">p.213<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The transceiver voice: “Nagumo, I’ve gotten in the way of Koenji’s event three times in a row. Please give me your next instructions.” — a 3rd-year student reports; “Hey, Nagumo, if you don’t give instructions, your subordinates can’t act. In order to drop Koenji down to 2nd, isn’t it necessary to continue with the attack until the end?” — he switches it off; “What’s important to me isn’t Koenji.” — he lunges; Ayanokōji punches him once in the chest and he collapses; his warning alarm rings; Ayanokōji hides him under a tree; 20–30 minutes before someone finds him; he walks away to I2.<span class=\"pg\">p.212–214<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> He is a god among men on this island; he runs the third-year lockdown to block comebacks; he enjoys unmasking Ayanokōji to force him to “be” Manabu&#x27;s shadow; he loses to a single punch and goes down for good — without landing a blow.<span class=\"pg\">p.201–214<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> He came to measure Ayanokōji against Horikita Manabu; he gets measured; he loses in a second.<span class=\"pg\">p.201–214<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> He is working to drop Koenji down to second; he uses the 3rd years to do it; the transceiver men are his.<span class=\"pg\">p.205–209<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> He sees the ghost of Manabu in Ayanokōji; his whole approach is Manabu&#x27;s ghost.<span class=\"pg\">p.205–209<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y2v4-p163-1\">← Before: Nagumo mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y2v4-p254-1\">→ After: Nagumo mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v4-p202-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"nagumo-miyabi ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 6  nagumo on the beach  the guessing game he crosses the rock field at i2 s border and spots president miyabi nagumo standing on the beach  tablet in hand  the third year s questioning  no one else around   ayanokouji  what a coincidence   president nagumo  why are you here   don t worry  we are the only ones here   i was having fun on the beach at i4  life on this uninhabited island is coming to an end  after all   is this the so called calmness of a king   but i ll ask you the same thing  ayanokouji  this place is not a designated area and doesn t have an event  so why did you come here  did you meet up with honami   is there a problem with that   no  if you two are still together now  you would have spoken about quite a bit  but you are here by yourself  so it means you have a different objective  what s there at i2   your critical thinking ain t bad   don t blame me for the bounty  it wasn t my proposal in the first place   it was acting director tsukishiro s   since you know this much  i ll be blunt  the money s all from the acting director  i just lent the name of the student council president to him   it s an order from the acting director  so you had to accept it  but if it s the student council president i know  i think you would have refused such a proposal  right   if it s about the matter of the bounty  i wouldn t have accepted it  if it were a student other than you  but the one which he named was none other but you  the only man that horikita senpai trusted   answer me  ayanokouji  what do you plan to do next   this has nothing to do with you  president nagumo  shouldn t you be concentrating on the end of the exam  the score difference between you and koenji should be small  if you don t go back  you won t get the arrival points  you won t be able to participate in some events  and that situation will stay the same   don t worry about it  on this last day  i have completely overwhelmed koenji   although i do care what you re going to do  if you won t answer  then i ll change my question  let me see if you  who hold the expectations of horikita senpai  have the strength worthy of my expectations  which of course means that you ll have to get serious  nagumo is unreadable  he wants to test ayanokoji for manabu s shadow  ayanokoji refuses to confirm anything  the stand off at the beach  nagumo reveals the bounty was tsukishiro s order","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v4-p202-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v4-p202-1\">Ch.6: Nagumo on the beach; the guessing game<\/a><\/span><span class=\"meta\">Y2V4 · p.202–207<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">He crosses the rock field at I2&#x27;s border and spots President Miyabi Nagumo standing on the beach, tablet in hand; the third-year&#x27;s questioning; no one else around.<\/p><p class=\"with\">with <a href=\"../../../people/nagumo-miyabi.html\">Nagumo Miyabi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Nagumo Miyabi<\/b> “Ayanokouji, what a coincidence.”<span class=\"pg\">p.202<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “President Nagumo, why are you here?”<span class=\"pg\">p.202<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nagumo Miyabi<\/b> “Don’t worry. We are the only ones here.”<span class=\"pg\">p.203<\/span><\/li><\/ul><details class=\"more\"><summary>17 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “I was having fun on the beach at I4. Life on this uninhabited island is coming to an end, after all.”<span class=\"pg\">p.203<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Is this the so-called calmness of a king?”<span class=\"pg\">p.203<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But I’ll ask you the same thing, Ayanokouji. This place is not a designated area and doesn’t have an event, so why did you come here? Did you meet up with Honami?”<span class=\"pg\">p.203<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Is there a problem with that?”<span class=\"pg\">p.203<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No. If you two are still together now, you would have spoken about quite a bit. But you are here by yourself, so it means you have a different objective. What’s there at I2?”<span class=\"pg\">p.203<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Your critical thinking ain’t bad.”<span class=\"pg\">p.204<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don’t blame me for the bounty. It wasn’t my proposal in the first place.”<span class=\"pg\">p.204<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It was Acting Director Tsukishiro’s.”<span class=\"pg\">p.204<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Since you know this much, I’ll be blunt. The money’s all from the Acting Director. I just lent the name of the Student Council president to him.”<span class=\"pg\">p.204<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s an order from the Acting Director, so you had to accept it. But if it’s the Student Council President I know, I think you would have refused such a proposal, right?”<span class=\"pg\">p.204<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If it’s about the matter of the bounty, I wouldn’t have accepted it, if it were a student other than you. But the one which he named was none other but you, the only man that Horikita-senpai trusted.”<span class=\"pg\">p.204<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Answer me, Ayanokouji. What do you plan to do next?”<span class=\"pg\">p.205<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “This has nothing to do with you, President Nagumo. Shouldn’t you be concentrating on the end of the exam? The score difference between you and Koenji should be small. If you don’t go back, you won’t get the arrival points, you won’t be able to participate in some events, and that situation will stay the same.”<span class=\"pg\">p.205<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don’t worry about it. On this last day, I have completely overwhelmed Koenji.”<span class=\"pg\">p.205<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Although I do care what you’re going to do, if you won’t answer, then I’ll change my question. Let me see if you, who hold the expectations of Horikita-senpai, have the strength worthy of my expectations, which of course means that you’ll have to get serious.”<span class=\"pg\">p.205<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Nagumo is unreadable; he wants to test Ayanokōji for Manabu&#x27;s shadow; Ayanokōji refuses to confirm anything.<span class=\"pg\">p.202–207<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> The stand-off at the beach; Nagumo reveals the bounty was Tsukishiro&#x27;s order.<span class=\"pg\">p.202–207<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p191-2\">← Before: Last day: Ichinose&#x27;s four-hour walk; her confession<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p208-1\">→ After: Ch.6: The superpower trick; Nagumo knocked down<\/button><\/div><\/article>"},{"i":"sc-ichinose-honami-y2v4-p202-1","v":"y2v4","y":2,"o":19,"k":"","w":"ichinose-honami","q":"ichinose honami ichinose mentioned in passing  ichinose said that this was the place where tsukishiro prepared to bury me    ayanokoji   did you meet up with honami    nagumo","h":"<article class=\"card\" id=\"sc-ichinose-honami-y2v4-p202-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ichinose-honami.html#sc-ichinose-honami-y2v4-p202-1\">Ichinose mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.202–203<\/span><span class=\"by\">notes on <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/span><\/h3><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “Ichinose said that this was the place where Tsukishiro prepared to bury me.” — Ayanokōji.<span class=\"pg\">p.202<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Did you meet up with Honami?” — Nagumo.<span class=\"pg\">p.203<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y2v4-p195-1\">← Before: Ichinose&#x27;s confession at H3<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y2v4-p252-1\">→ After: Ichinose mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-horikita-manabu-y2v4-p204-1","v":"y2v4","y":2,"o":19,"k":"","w":"horikita-manabu","q":"horikita manabu nagumo sees ayanokoji as manabu s man  so nagumo did indeed see me as one of horikita manabu s people    ayanokoji s interior on the beach  nagumo has just admitted the bounty was tsukishiro s order and named ayanokoji  the only man that horikita senpai trusted","h":"<article class=\"card\" id=\"sc-horikita-manabu-y2v4-p204-1\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-manabu.html#sc-horikita-manabu-y2v4-p204-1\">Nagumo sees Ayanokōji as Manabu&#x27;s man<\/a><\/span><span class=\"meta\">Y2V4 · p.204<\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-manabu.html\">Horikita Manabu<\/a><\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “So Nagumo did indeed see me as one of Horikita Manabu’s people.” — Ayanokōji&#x27;s interior on the beach; Nagumo has just admitted the bounty was Tsukishiro&#x27;s order and named Ayanokōji “the only man that Horikita-senpai trusted”.<span class=\"pg\">p.204<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-manabu-y2v4-p97-1\">← Before: Manabu named in the Kiriyama camp<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-manabu-y2v4-p209-1\">→ After: The chase behind the fight<\/button><\/div><\/article>"},{"i":"sc-kouenji-rokusuke-y2v4-p205-1","v":"y2v4","y":2,"o":19,"k":"","w":"kouenji-rokusuke","q":"koenji rokusuke koenji mentioned in passing  in order to drop koenji down to 2nd  isn t it necessary to continue with the attack until the end    the interceptors  transceiver  nagumo switched it off   although the fierce koenji still had a chance of reversing it  this was undoubtedly a tough battle    narration   well  he certainly exceeded my expectations  as he was the only one who made me take an offensive move in the exam    nagumo   managing the entire third year to take all the arrival bonus points and the events  this is something only the student council president can do    nagumo   all the other years that show off by being in the top 3 ranks will be erased  as a result  kouenji could only get arrival points    nagumo   if koenji were to maintain his current pace and keep diligently racking up points  he d end up with a final score of around 350  so if i wanted to bridge the gap  i d have to earn close to 40 points per day for the rest of the exam    ayanokoji   koenji senpai sure is amazing  isn t he  giving president nagumo a run for his money all by himself    nanase  she says this to him   in the battle with me  we might be able to see his regretful expression    nagumo","h":"<article class=\"card\" id=\"sc-kouenji-rokusuke-y2v4-p205-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kouenji-rokusuke.html#sc-kouenji-rokusuke-y2v4-p205-1\">Kōenji mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.205–213<\/span><span class=\"by\">notes on <a href=\"../../../people/kouenji-rokusuke.html\">Kōenji Rokusuke<\/a><\/span><\/h3><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “In order to drop Koenji down to 2nd, isn’t it necessary to continue with the attack until the end?” — the interceptors’ transceiver; Nagumo switched it off.<span class=\"pg\">p.213<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Although the fierce Koenji still had a chance of reversing it, this was undoubtedly a tough battle.” — narration.<span class=\"pg\">p.205<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Well, he certainly exceeded my expectations, as he was the only one who made me take an offensive move in the exam.” — Nagumo.<span class=\"pg\">p.206<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Managing the entire third year to take all the arrival bonus points and the events. This is something only the student council president can do.” — Nagumo.<span class=\"pg\">p.206<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “All the other years that show off by being in the top 3 ranks will be erased. As a result, Kouenji could only get arrival points.” — Nagumo.<span class=\"pg\">p.207<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “If Kōenji were to maintain his current pace and keep diligently racking up points, he&#x27;d end up with a final score of around 350, so if I wanted to bridge the gap, I&#x27;d have to earn close to 40 points per day for the rest of the exam.” — Ayanokōji.<span class=\"pg\">p.208<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Kōenji-senpai sure is amazing, isn&#x27;t he? Giving President Nagumo a run for his money all by himself.” — Nanase (she says this to him).<span class=\"pg\">p.209<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “in the battle with me, we might be able to see his regretful expression.” — Nagumo.<span class=\"pg\">p.212<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kouenji-rokusuke-y2v4-p111-1\">← Before: Ch.4: The walk-through<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kouenji-rokusuke-y2v4-p281-1\">→ After: Kōenji wins first place alone<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y2v4-p207-1","v":"y2v4","y":2,"o":19,"k":"","w":"kiriyama-ikuto","q":"kiriyama ikuto kiriyama mentioned in passing  the vacant space vice president kiriyama left intentionally open was reserved for you    nagumo explains the beach flags setup   however  it was surprising to see how kiriyama s group was left standing at the end of    narration","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y2v4-p207-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kiriyama-ikuto.html#sc-kiriyama-ikuto-y2v4-p207-1\">Kiriyama mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.207, 280<\/span><span class=\"by\">notes on <a href=\"../../../people/kiriyama-ikuto.html\">Kiriyama Ikuto<\/a><\/span><\/h3><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “the vacant space Vice President Kiriyama left intentionally open was reserved for you.” — Nagumo explains the Beach Flags setup.<span class=\"pg\">p.207<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “However, it was surprising to see how Kiriyama&#x27;s group was left standing at the end of” — narration.<span class=\"pg\">p.280<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y2v4-p110-1\">← Before: Ch.4: The walk-through; the plan that failed<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v4-p208-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"nagumo-miyabi ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 6  the superpower trick  nagumo knocked down nagumo pulls a transceiver and guesses his ranking    11th    misses by 5  the trap is the 3rd year lockout plan  kuronaga holds 10th to block comebacks  ayanokoji reveals he s 16th  nagumo is furious  his watch rings a warning  ayanokoji shoves him hard   let me guess your group s ranking at the end of the 12th day   you re ranked 11th  right   a little off  then you re ranked around 15th or 16th right   yeah  truly admirable of you   i joked around with that superpower stuff  i just guessed  assuming that you really have hidden your strength   in order not to attract attention  your ranking is a bit lower than 10th  but still  you ve maintained an upper ranking position  if i lose the battle against koenji  then you d have a chance to make a comeback   kurona from third year has been keeping the 10th place  right  i had him maintain that rank to block those who had been secretly saving points and aiming to make a comeback   if i want to earn points  whether that s 400 or 500 points  i can earn them  however  that s not interesting  right  now there s hope that he might beat the second and first years  besides  if he lost in the battle with me  we might be able to see his regretful expression   in order not to attract attention  i would lurk around this rank before day 12   have you noticed  from the very start  this wasn t possible   i ve always doubted whether you were strong enough  but now i understand  you ve been granted the right to be crushed by me  so rejoice   was it part of your plan  your command of the attack on koenji on the last day   unfortunately  the leader of class 2 d is horikita  even if there s a special exam that competes with the third years  i won t fight you   then i would have to force you to appear on the front stage  which includes using the bounty   you think you can escape this easily  i won t let you go before you agree to a fight with me   president nagumo  although your abilities are different from president horikita s  it still allowed you to brilliantly stand at the top of this school  you maintained a top ranking in this special exam with ease  and it s no exaggeration to say you had complete control over it  even so  i plan to beat you   it s just that there are certain areas where you shouldn t step into  please understand   huh  don t be ridiculous  you presume to give me orders   it s because you have the status of being a senpai worthy of my respect that i am not going to be lenient here   ah  what are you doing   urgh   don t you understand what i said   i   ah  you  the transceiver kept nagumo s allies intercepting koenji three times  he switches it off  he lunges  ayanokoji drops him with one punch to the chest  his warning alarm sounds  ayanokoji hides him under a tree  20 30 minutes before rescue  he walks to i2  he collapses the 3rd year king in one punch  the game is now in his hands  the showdown ended in a second   ayanokoji wins the beach fight by forfeit  nagumo is dragged out of the equation before i2","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v4-p208-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v4-p208-1\">Ch.6: The superpower trick; Nagumo knocked down<\/a><\/span><span class=\"meta\">Y2V4 · p.208–214<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Nagumo pulls a transceiver and guesses his ranking — “11th” — misses by 5; the trap is the 3rd-year lockout plan; Kuronaga holds 10th to block comebacks; Ayanokōji reveals he&#x27;s 16th; Nagumo is furious; his watch rings a warning; Ayanokōji shoves him hard.<\/p><p class=\"with\">with <a href=\"../../../people/nagumo-miyabi.html\">Nagumo Miyabi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Nagumo Miyabi<\/b> “Let me guess your group’s ranking at the end of the 12th day.”<span class=\"pg\">p.207<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nagumo Miyabi<\/b> “You’re ranked…11th, right?”<span class=\"pg\">p.208<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nagumo Miyabi<\/b> “A little off? Then you’re ranked around 15th or 16th right?”<span class=\"pg\">p.208<\/span><\/li><\/ul><details class=\"more\"><summary>24 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Yeah. Truly admirable of you.”<span class=\"pg\">p.208<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I joked around with that superpower stuff. I just guessed, assuming that you really have hidden your strength.”<span class=\"pg\">p.208<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “In order not to attract attention, your ranking is a bit lower than 10th, but still, you’ve maintained an upper-ranking position. If I lose the battle against Koenji, then you’d have a chance to make a comeback.”<span class=\"pg\">p.208<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Kurona from third-year has been keeping the 10th place, right? I had him maintain that rank to block those who had been secretly saving points and aiming to make a comeback.”<span class=\"pg\">p.208<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If I want to earn points, whether that’s 400 or 500 points, I can earn them. However, that’s not interesting, right? Now there’s hope that he might beat the second and first-years. Besides, if he lost in the battle with me, we might be able to see his regretful expression.”<span class=\"pg\">p.209<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “In order not to attract attention, I would lurk around this rank before Day 12.”<span class=\"pg\">p.209<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Have you noticed? From the very start, this wasn’t possible.”<span class=\"pg\">p.209<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’ve always doubted whether you were strong enough, but now I understand. You’ve been granted the right to be crushed by me, so rejoice.”<span class=\"pg\">p.209<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Was it part of your plan? Your command of the attack on Koenji on the last day?”<span class=\"pg\">p.209<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Unfortunately, the leader of Class 2-D is Horikita. Even if there’s a special exam that competes with the third-years, I won’t fight you.”<span class=\"pg\">p.210<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Then I would have to force you to appear on the front stage, which includes using the bounty.”<span class=\"pg\">p.210<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You think you can escape this easily? I won’t let you go before you agree to a fight with me.”<span class=\"pg\">p.210<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “President Nagumo, although your abilities are different from President Horikita’s, it still allowed you to brilliantly stand at the top of this school. You maintained a top ranking in this special exam with ease, and it’s no exaggeration to say you had complete control over it. Even so, I plan to beat you.”<span class=\"pg\">p.212<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s just that there are certain areas where you shouldn’t step into. Please understand.”<span class=\"pg\">p.212<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Huh?…. Don’t be ridiculous. You presume to give me orders?”<span class=\"pg\">p.212<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s because you have the status of being a senpai worthy of my respect that I am not going to be lenient here.”<span class=\"pg\">p.212<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ah? What are you doing—”<span class=\"pg\">p.212<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Urgh….!?”<span class=\"pg\">p.212<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don’t you understand what I said?”<span class=\"pg\">p.212<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I…!?”<span class=\"pg\">p.213<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ah, you…!!!”<span class=\"pg\">p.213<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The transceiver kept Nagumo&#x27;s allies intercepting Koenji three times; he switches it off; he lunges; Ayanokōji drops him with one punch to the chest; his warning alarm sounds; Ayanokōji hides him under a tree; 20-30 minutes before rescue; he walks to I2.<span class=\"pg\">p.212–214<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> He collapses the 3rd-year king in one punch; the game is now in his hands.<span class=\"pg\">p.212–214<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> The showdown ended in a second — Ayanokōji wins the beach fight by forfeit; Nagumo is dragged out of the equation before I2.<span class=\"pg\">p.208–214<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p202-1\">← Before: Ch.6: Nagumo on the beach; the guessing game<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p215-1\">→ After: Ch.6: The I2 blocks, from outside (mention records)<\/button><\/div><\/article>"},{"i":"sc-horikita-manabu-y2v4-p209-1","v":"y2v4","y":2,"o":19,"k":"","w":"horikita-manabu","q":"horikita manabu the chase behind the fight  nagumo  who had been chasing after horikita manabu  wanted to see his shadow on me    ayanokoji s interior just before the i2 confrontation","h":"<article class=\"card\" id=\"sc-horikita-manabu-y2v4-p209-1\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-manabu.html#sc-horikita-manabu-y2v4-p209-1\">The chase behind the fight<\/a><\/span><span class=\"meta\">Y2V4 · p.209<\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-manabu.html\">Horikita Manabu<\/a><\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “Nagumo, who had been chasing after Horikita Manabu, wanted to see his shadow on me.” — Ayanokōji&#x27;s interior just before the I2 confrontation.<span class=\"pg\">p.209<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-manabu-y2v4-p204-1\">← Before: Nagumo sees Ayanokōji as Manabu&#x27;s man<\/button><\/div><\/article>"},{"i":"sc-horikita-suzune-y2v4-p214-1","v":"y2v4","y":2,"o":19,"k":"narration","w":"ayanokouji-kiyotaka horikita-suzune","q":"horikita suzune ch 6  the note  she marches north day thirteen at dawn  she heads north toward i2 ignoring her designated area i7  the destination is written on a note found folded in her tent this morning    noon   k a   expelled   i2    beautiful handwriting  foreign paper  the initials of ayanokoji kiyotaka   i2 referred to an area on the uninhabited island  and noon was the time   expelled  and  k a   if we consider this to be the meaning  then at noon today  ayanokouji will be expelled at i2  she knows exactly what the note means and cannot ignore it  she burns a gps search and follows his signal f3 g3 to i2  her designated area i7 is sacrificed  she convinces herself it is a clue from someone else  not a trap   someone who cares  she drops her own exam goal to tail him to i2","h":"<article class=\"card\" id=\"sc-horikita-suzune-y2v4-p214-1\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-suzune.html#sc-horikita-suzune-y2v4-p214-1\">Ch.6: The note; she marches north<\/a><\/span><span class=\"meta\">Y2V4 · p.214–216<\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/span><\/h3><p class=\"setup\">Day thirteen at dawn, she heads north toward I2 ignoring her designated area I7; the destination is written on a note found folded in her tent this morning — “Noon”, “K.A”, “Expelled”, “I2” — beautiful handwriting, foreign paper, the initials of Ayanokōji Kiyotaka.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Horikita Suzune<\/b> “I2 referred to an area on the uninhabited island, and noon was the time.”<span class=\"pg\">p.215<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Horikita Suzune<\/b> “Expelled”, and “K.A”.<span class=\"pg\">p.215<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Horikita Suzune<\/b> “If we consider this to be the meaning, then at noon today, Ayanokouji will be expelled at I2…”<span class=\"pg\">p.215<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> She knows exactly what the note means and cannot ignore it; she burns a GPS Search and follows his signal F3→G3 to I2; her designated area I7 is sacrificed; she convinces herself it is a clue from someone else, not a trap — someone who cares.<span class=\"pg\">p.214–216<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> She drops her own exam goal to tail him to I2.<span class=\"pg\">p.214–216<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y2v4-p67-1\">← Before: Horikita mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y2v4-p216-1\">→ After: Ch.6: Ibuki catches up; the score game<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v4-p215-1","v":"y2v4","y":2,"o":19,"k":"","w":"ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 6  the i2 blocks  from outside  mention records   then at noon today  ayanokouji will be expelled at i2    horikita s reading of the folded note   but the fact that ayanokouji kun s gps signal was on e3 made me a bit worried    horikita   it s ayanokouji    the translation s own annotation  kept as printed   did she feel there was no need to apologize to me for the way she treated ayanokouji kun  and the things she did    horikita s thought   it s best not to say anything unnecessary about ayanokouji kun    horikita   games  what are you planning to involve me and ayanokouji kun in    horikita   you obviously don t know anything about ayanokouji senpai  you re just acting like his partner because you re in the same class    amasawa   he ayanokouji was my first friend    horikita s interior   i m going to i2 to help ayanokouji kun    horikita   don t kid me  how could ayanokouji senpai need your help    amasawa   i ll do that  as long as your motive isn t to stop me from going to ayanokouji kun    horikita   who are you  you seem to know the ayanokouji kun in the past    horikita   you aren t worthy for ayanokouji senpai to rely on    amasawa   if ayanokouji kun was here  in the same situation as i was  what would he do    horikita   ah  by the way  i don t think you need to go after ayanokouji senpai anymore    amasawa","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v4-p215-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v4-p215-1\">Ch.6: The I2 blocks, from outside (mention records)<\/a><\/span><span class=\"meta\">Y2V4 · p.215–251<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><details class=\"more\"><summary>15 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “then at noon today, Ayanokouji will be expelled at I2…” — Horikita’s reading of the folded note.<span class=\"pg\">p.215<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “but the fact that Ayanokouji-kun’s GPS signal was on E3 made me a bit worried.” — Horikita.<span class=\"pg\">p.216<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “(it&#x27;s ayanokouji)” — the translation’s own annotation; kept as printed.<span class=\"pg\">p.218<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Did she feel there was no need to apologize to me for the way she treated Ayanokouji-kun, and the things she did?” — Horikita’s thought.<span class=\"pg\">p.222<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “It’s best not to say anything unnecessary about Ayanokouji-kun.” — Horikita.<span class=\"pg\">p.223<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Games? What are you planning to involve me and Ayanokouji-kun in?” — Horikita.<span class=\"pg\">p.226<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “you obviously don’t know anything about Ayanokouji-senpai. You’re just acting like his partner because you’re in the same class.” — Amasawa.<span class=\"pg\">p.227<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “he…Ayanokouji was my first...friend.” — Horikita’s interior.<span class=\"pg\">p.228<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “I’m going to I2 to help Ayanokouji-kun.” — Horikita.<span class=\"pg\">p.229<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Don’t kid me, how could Ayanokouji-senpai need your help?” — Amasawa.<span class=\"pg\">p.230<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “I’ll do that, as long as your motive isn’t to stop me from going to Ayanokouji-kun.” — Horikita.<span class=\"pg\">p.233<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Who are you? You seem to know the Ayanokouji-kun in the past…” — Horikita.<span class=\"pg\">p.235<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “you aren’t worthy for Ayanokouji-senpai to rely on.” — Amasawa.<span class=\"pg\">p.236<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “If Ayanokouji-kun was here, in the same situation as I was, what would he do?” — Horikita.<span class=\"pg\">p.245<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Ah, by the way, I don’t think you need to go after Ayanokouji-senpai anymore.” — Amasawa.<span class=\"pg\">p.251<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p208-1\">← Before: Ch.6: The superpower trick; Nagumo knocked down<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p231-1\">→ After: AK mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-horikita-suzune-y2v4-p216-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"ibuki-mio horikita-suzune","q":"horikita suzune ch 6  ibuki catches up  the score game on the border i4 i3 she spots a girl glaring at her from behind   ibuki  panting  spent three gps searches to find her  they fence over their scores for a while   ah  finally caught up  wait  horikita   why are you here   score  show me the score   wait  what are you on about   didn t i say  i m not going to lose to you in this special exam   there s no need to confirm it now though  the exam isn t over yet   after the exam is over  nobody will know if the school will publish all the scores  right   maybe so  after all  it s only the top and bottom ranking groups that really matter   huh  then why don t you look at it   this is so stupid  i can t believe it  you purposely came here for this  seriously  how many times did you use gps search    3 times  because you were right next to me  i thought this would be the only time where i could do this   poor you   i don t need your sympathy  tell me your score  i ve got 131 points   thanks for telling me so casually  but i want to say two things  first  i can t guarantee that you re telling me your real score   second  even if you disclose your real score  i won t tell you my score   huh  what did you just say  are you saying the same thing as that bastard   although we re both 2nd years  we re enemies  i don t want to risk leaking information   i know now  you re scared after hearing my score  you re losing  right   as for whether i m winning or losing  i m not going to answer that either   how about you just admit it  admit that you can t beat my score   fine then  just go back to your exam    you re so irritating  come on  just show me your score   i ve conceded defeat  aren t you satisfied   i want to know your real score  i want to know by how big of a margin i beat you   how dull   it s important to me   sorry  i m in a hurry   are you running away   i m rushing to get to my designated area  so it would be a bit strange to describe it as running away   do you have a designated area in the north  or are you just chasing me   what i want to know now is your score  if i know that  i will go back to my designated area too   i lost to you   ah  admit it  you finally admit to losing   no  i mean i lost to your persistence  my score is 145 points  it s a pity that even though you came here in person  i still win   you won against me  if you won  give me proof  proof  she shows her tablet to ibuki   145 points  the psychological price of confirming the gap  ibuki screams  she waves her off and keeps walking  her sworn rival  reveals her own score only to end the chase","h":"<article class=\"card\" id=\"sc-horikita-suzune-y2v4-p216-1\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-suzune.html#sc-horikita-suzune-y2v4-p216-1\">Ch.6: Ibuki catches up; the score game<\/a><\/span><span class=\"meta\">Y2V4 · p.216–220<\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/span><\/h3><p class=\"setup\">On the border I4/I3 she spots a girl glaring at her from behind — Ibuki, panting; spent three GPS searches to find her; they fence over their scores for a while.<\/p><p class=\"with\">with <a href=\"../../../people/ibuki-mio.html\">Ibuki Mio<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ibuki Mio<\/b> “Ah! Finally caught up! Wait, Horikita!”<span class=\"pg\">p.216<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “…Why are you here?”<span class=\"pg\">p.216<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ibuki Mio<\/b> “Score, show me the score.”<span class=\"pg\">p.217<\/span><\/li><\/ul><details class=\"more\"><summary>34 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Wait, what are you on about?”<span class=\"pg\">p.217<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Didn’t I say? I’m not going to lose to you in this special exam.”<span class=\"pg\">p.217<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There’s no need to confirm it now though? The exam isn’t over yet.”<span class=\"pg\">p.217<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “After the exam is over, nobody will know if the school will publish all the scores, right?”<span class=\"pg\">p.217<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Maybe so. After all, it’s only the top and bottom ranking groups that really matter.”<span class=\"pg\">p.218<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Huh? Then why don’t you look at it?”<span class=\"pg\">p.218<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “This is so stupid, I can’t believe it… You purposely came here for this, seriously? How many times did you use GPS search?”<span class=\"pg\">p.218<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “… 3 times. Because you were right next to me, I thought this would be the only time where I could do this.”<span class=\"pg\">p.218<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Poor you.”<span class=\"pg\">p.218<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don’t need your sympathy, tell me your score, I’ve got 131 points!”<span class=\"pg\">p.218<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Thanks for telling me so casually. But I want to say two things. First, I can’t guarantee that you’re telling me your real score.”<span class=\"pg\">p.218<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Second, even if you disclose your real score, I won’t tell you my score.”<span class=\"pg\">p.218<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Huh? What did you just say? Are you saying the same thing as that bastard?”<span class=\"pg\">p.218<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Although we’re both 2nd years, we’re enemies. I don’t want to risk leaking information.”<span class=\"pg\">p.218<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I know now. You’re scared after hearing my score? You’re losing, right?”<span class=\"pg\">p.219<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “As for whether I’m winning or losing, I’m not going to answer that either.”<span class=\"pg\">p.219<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “How about you just admit it? Admit that you can’t beat my score.”<span class=\"pg\">p.219<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Fine then, just go back to your exam.”<span class=\"pg\">p.219<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “… You’re so irritating. Come on, just show me your score!”<span class=\"pg\">p.219<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’ve conceded defeat, aren’t you satisfied?”<span class=\"pg\">p.219<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I want to know your real score. I want to know by how big of a margin I beat you.”<span class=\"pg\">p.219<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “How dull…”<span class=\"pg\">p.219<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s important to me.”<span class=\"pg\">p.219<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Sorry, I’m in a hurry.”<span class=\"pg\">p.219<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Are you running away?”<span class=\"pg\">p.219<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m rushing to get to my designated area, so it would be a bit strange to describe it as running away.”<span class=\"pg\">p.219<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Do you have a designated area in the north? Or are you just chasing me?”<span class=\"pg\">p.220<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What I want to know now is your score. If I know that, I will go back to my designated area too.”<span class=\"pg\">p.220<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…I lost to you.”<span class=\"pg\">p.220<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ah, admit it? You finally admit to losing?”<span class=\"pg\">p.220<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No, I mean I lost to your persistence. My score is 145 points. It’s a pity that even though you came here in person, I still win.”<span class=\"pg\">p.220<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You won against me? If you won, give me proof, proof.”<span class=\"pg\">p.220<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> She shows her tablet to Ibuki — 145 points; the psychological price of confirming the gap: Ibuki screams; she waves her off and keeps walking.<span class=\"pg\">p.216–220<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ibuki Mio<\/b> Her sworn rival; reveals her own score only to end the chase.<span class=\"pg\">p.216–220<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y2v4-p214-1\">← Before: Ch.6: The note; she marches north<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y2v4-p220-1\">→ After: Ch.6: Amasawa stops her<\/button><\/div><\/article>"},{"i":"sc-ibuki-mio-y2v4-p216-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"horikita-suzune ibuki-mio","q":"ibuki mio ch 6  she catches horikita at i4 i3 border she spots horikita ahead and runs after her   she used 3 gps searches  she demands horikita s score  she declares her own first  131 points   why are you here   ah  finally caught up  wait  horikita   score  show me the score   wait  what are you on about   didn t i say  i m not going to lose to you in this special exam   there s no need to confirm it now though  the exam isn t over yet   after the exam is over  nobody will know if the school will publish all the scores  right   maybe so  after all  it s only the top and bottom ranking groups that really matter   so  let me confirm it now   this is so stupid  i can t believe it  you purposely came here for this  seriously  how many times did you use gps search    3 times  because you were right next to me  i thought this would be the only time where i could do this   poor you   i don t need your sympathy  tell me your score  i ve got 131 points   thanks for telling me so casually  but i want to say two things  first  i can t guarantee that you re telling me your real score   huh  then why don t you look at it   second  even if you disclose your real score  i won t tell you my score   huh  what did you just say  are you saying the same thing as that bastard   although we re both 2nd years  we re enemies  i don t want to risk leaking information   i know now  you re scared after hearing my score  you re losing  right   as for whether i m winning or losing  i m not going to answer that either   how about you just admit it  admit that you can t beat my score   fine then  just go back to your exam    you re so irritating  come on  just show me your score   i ve conceded defeat  aren t you satisfied   i want to know your real score  i want to know by how big of a margin i beat you   how dull   it s important to me   sorry  i m in a hurry   are you running away   i m rushing to get to my designated area  so it would be a bit strange to describe it as running away   what i want to know now is your score  if i know that  i will go back to my designated area too   i lost to you   ah  admit it  you finally admit to losing   no  i mean i lost to your persistence  my score is 145 points  it s a pity that even though you came here in person  i still win   are you guys ever going to stop talking   ah  seriously  well that sucks   if you re satisfied now  go along to your designated area  on the last day  the score you ll get is twice as high  so you still have a chance to bounce back   yeah  but  what do you mean by abandoning the designated area   indeed  the winner and loser will be decided at the end of this uninhabited island exam  if you say you re going to stop now  i won t hesitate to make a comeback for good   ibuki  this is a great opportunity  i m in a state where i can t score right now   yeah  but  what do you mean by abandoning the designated area  she learns horikita is giving up the designated area   she can win after all if horikita stops trying  no   she sees the situation and accepts it  her rival  she blindsides her with gps searches and scheme talk  horikita is unimpressed","h":"<article class=\"card\" id=\"sc-ibuki-mio-y2v4-p216-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ibuki-mio.html#sc-ibuki-mio-y2v4-p216-1\">Ch.6: She catches Horikita<\/a><\/span><span class=\"meta\">Y2V4 · p.216–226<\/span><span class=\"by\">notes on <a href=\"../../../people/ibuki-mio.html\">Ibuki Mio<\/a><\/span><\/h3><p class=\"setup\">At I4/I3 border she spots Horikita ahead and runs after her — she used 3 GPS searches; she demands Horikita&#x27;s score; she declares her own first: 131 points.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “…Why are you here?”<span class=\"pg\">p.216<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ibuki Mio<\/b> “Ah! Finally caught up! Wait, Horikita!”<span class=\"pg\">p.216<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ibuki Mio<\/b> “Score, show me the score.”<span class=\"pg\">p.217<\/span><\/li><\/ul><details class=\"more\"><summary>40 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Wait, what are you on about?”<span class=\"pg\">p.217<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Didn’t I say? I’m not going to lose to you in this special exam.”<span class=\"pg\">p.217<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There’s no need to confirm it now though? The exam isn’t over yet.”<span class=\"pg\">p.217<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “After the exam is over, nobody will know if the school will publish all the scores, right?”<span class=\"pg\">p.217<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Maybe so. After all, it’s only the top and bottom ranking groups that really matter.”<span class=\"pg\">p.218<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So, let me confirm it now.”<span class=\"pg\">p.218<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “This is so stupid, I can’t believe it… You purposely came here for this, seriously? How many times did you use GPS search?”<span class=\"pg\">p.218<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “… 3 times. Because you were right next to me, I thought this would be the only time where I could do this.”<span class=\"pg\">p.218<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Poor you.”<span class=\"pg\">p.218<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don’t need your sympathy, tell me your score, I’ve got 131 points!”<span class=\"pg\">p.218<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Thanks for telling me so casually. But I want to say two things. First, I can’t guarantee that you’re telling me your real score.”<span class=\"pg\">p.218<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Huh? Then why don’t you look at it?”<span class=\"pg\">p.218<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Second, even if you disclose your real score, I won’t tell you my score.”<span class=\"pg\">p.218<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Huh? What did you just say? Are you saying the same thing as that bastard?”<span class=\"pg\">p.218<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Although we’re both 2nd years, we’re enemies. I don’t want to risk leaking information.”<span class=\"pg\">p.218<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I know now. You’re scared after hearing my score? You’re losing, right?”<span class=\"pg\">p.219<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “As for whether I’m winning or losing, I’m not going to answer that either.”<span class=\"pg\">p.219<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “How about you just admit it? Admit that you can’t beat my score.”<span class=\"pg\">p.219<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Fine then, just go back to your exam.”<span class=\"pg\">p.219<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “… You’re so irritating. Come on, just show me your score!”<span class=\"pg\">p.219<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’ve conceded defeat, aren’t you satisfied?”<span class=\"pg\">p.219<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I want to know your real score. I want to know by how big of a margin I beat you.”<span class=\"pg\">p.219<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “How dull…”<span class=\"pg\">p.219<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s important to me.”<span class=\"pg\">p.219<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Sorry, I’m in a hurry.”<span class=\"pg\">p.219<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Are you running away?”<span class=\"pg\">p.219<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m rushing to get to my designated area, so it would be a bit strange to describe it as running away.”<span class=\"pg\">p.219<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What I want to know now is your score. If I know that, I will go back to my designated area too.”<span class=\"pg\">p.220<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…I lost to you.”<span class=\"pg\">p.220<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ah, admit it? You finally admit to losing?”<span class=\"pg\">p.220<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No, I mean I lost to your persistence. My score is 145 points. It’s a pity that even though you came here in person, I still win.”<span class=\"pg\">p.220<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Are you guys ever going to stop talking?”<span class=\"pg\">p.224<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ah, seriously? Well that sucks.”<span class=\"pg\">p.224<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If you’re satisfied now, go along to your designated area. On the last day, the score you’ll get is twice as high, so you still have a chance to bounce back.”<span class=\"pg\">p.225<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yeah, but… What do you mean by abandoning the designated area?”<span class=\"pg\">p.225<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Indeed, the winner and loser will be decided at the end of this uninhabited island exam. If you say you’re going to stop now, I won’t hesitate to make a comeback for good.”<span class=\"pg\">p.225<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ibuki, this is a great opportunity. I’m in a state where I can’t score right now.”<span class=\"pg\">p.225<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yeah, but… What do you mean by abandoning the designated area?”<span class=\"pg\">p.225<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> She learns Horikita is giving up the designated area — she can win after all if Horikita stops trying? No — she sees the situation and accepts it.<span class=\"pg\">p.225<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Her rival; she blindsides her with GPS searches and scheme-talk; Horikita is unimpressed.<span class=\"pg\">p.216–226<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ibuki-mio-y2v4-p79-1\">← Before: Ch.3: The backpack check<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ibuki-mio-y2v4-p227-1\">→ After: Ch.6: The 2-on-1 with Horikita<\/button><\/div><\/article>"},{"i":"sc-amasawa-ichika-y2v4-p220-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"horikita-suzune ibuki-mio amasawa-ichika","q":"amasawa ichika ch 6  the i2 assignment  she stops horikita she appears out of thin air with a childlike smile in front of horikita and ibuki   she has been detailed to keep them away from i2  she savors every second of it   found you   hello  horikita senpai   class 1 a s amasawa ichika   you guys don t need to mind me  just continue doing your own thing  okay   that s not okay  we re talking about something personal   is sudo senpai okay  horikita senpai   well  thanks for saving him  i m grateful   didn t i say that you re a nuisance  i have business with her  so get out of here   business  didn t ibuki senpai run over here without permission   i want to ask you a question  where are you going  horikita senpai   right now  i m standing and chatting with ibuki san  so when i finish with her  i ll immediately rush to f3   it s not good to lie  horikita senpai  your designated area isn t in this direction right   what do you mean  are you trying to make me fall into a trap using strange methods   misleading is useless though  the designated area you were supposed to go to is i7  isn t it   isn t it a given to be wary of the people trying to frame ayanokouji kun   oh  so that s it  perhaps   where are you planning to go  horikita senpai  it s not i2  is it   paper  is that for me   it s a string of irregularly arranged words   noon   k a   expelled   i2   i really hate  how you like to play games  even to this extent   this  i don t know  because i m just one of the bystanders  just like you   ayanokouji may be expelled  it s not hard to understand it like that   there s something i got out of our conversation  something s gonna happen at i2  otherwise  you wouldn t try so hard to stop me here   about ayanokouji senpai s situation  you don t know anything about that  right  horikita senpai   that s right  i know ayanokouji senpai very well  why is he so handsome  so smart  and so much stronger than anyone else   then  what do you know  horikita senpai   do you think you can help  horikita senpai   don t kid me  how could ayanokouji senpai need your help   i can t let you go over there  horikita senpai   do you think you get past me   well  your determination has been conveyed to me  i ll only wait until you put your backpack down   let me tell you something first  i have experience with martial arts   ah  you really are an information warrior   let me also say right now that i m super powerful  so you better keep that in mind   since you said you re going to meet up with ayanokouji senpai  i ll play with you for a bit  she dominates the conversation   she knows horikita s designated area is i7  knows the note s contents without owning them  and dismisses horikita s little sister like admiration for ayanokoji with surgical contempt  she fights with a smirk  she is physically in excellent shape but carries an unseen injury  she bullies her to tears  she fights her for fun  the other half of her audience  she ignores her rudely","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v4-p220-1\"><h3><span class=\"ttl\"><a href=\"../../../people/amasawa-ichika.html#sc-amasawa-ichika-y2v4-p220-1\">Ch.6: The I2 assignment; she stops Horikita<\/a><\/span><span class=\"meta\">Y2V4 · p.220–231<\/span><span class=\"by\">notes on <a href=\"../../../people/amasawa-ichika.html\">Amasawa Ichika<\/a><\/span><\/h3><p class=\"setup\">She appears out of thin air with a childlike smile in front of Horikita and Ibuki — she has been detailed to keep them away from I2; she savors every second of it.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/ibuki-mio.html\">Ibuki Mio<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Amasawa Ichika<\/b> “Found you.”<span class=\"pg\">p.220<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Amasawa Ichika<\/b> “Hello, Horikita-senpai!”<span class=\"pg\">p.221<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Amasawa Ichika<\/b> “Class 1-A’s Amasawa Ichika.”<span class=\"pg\">p.221<\/span><\/li><\/ul><details class=\"more\"><summary>35 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “You guys don’t need to mind me, just continue doing your own thing, okay~~?”<span class=\"pg\">p.221<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That’s not okay, we’re talking about something personal.”<span class=\"pg\">p.221<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Is Sudo-senpai okay? Horikita-senpai.”<span class=\"pg\">p.221<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “….Well, thanks for saving him, I’m grateful.”<span class=\"pg\">p.222<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Didn’t I say that you’re a nuisance? I have business with her, so get out of here.”<span class=\"pg\">p.222<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Business? Didn’t Ibuki-senpai run over here without permission?”<span class=\"pg\">p.222<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I want to ask you a question. Where are you going, Horikita-senpai?”<span class=\"pg\">p.222<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Right now, I’m standing and chatting with Ibuki-san, so when I finish with her, I’ll immediately rush to F3.”<span class=\"pg\">p.222<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s not good to lie, Horikita-senpai! Your designated area isn’t in this direction right?”<span class=\"pg\">p.223<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What do you mean? Are you trying to make me fall into a trap using strange methods?”<span class=\"pg\">p.223<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Misleading is useless though. The designated area you were supposed to go to is I7, isn’t it?”<span class=\"pg\">p.223<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Isn’t it a given to be wary of the people trying to frame Ayanokouji-kun?”<span class=\"pg\">p.223<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Oh, so that’s it. Perhaps.”<span class=\"pg\">p.223<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Where are you planning to go, Horikita-senpai? It’s not I2, is it?”<span class=\"pg\">p.224<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…Paper? Is that for me?”<span class=\"pg\">p.226<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s a string of irregularly arranged words… “Noon”, “K.A”, “Expelled”, “I2”.”<span class=\"pg\">p.226<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I really hate… how you like to play games, even to this extent…”<span class=\"pg\">p.226<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “This, I don’t know. Because I’m just one of the bystanders, just like you.”<span class=\"pg\">p.226<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ayanokouji may be expelled. It’s not hard to understand it like that.”<span class=\"pg\">p.226<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There’s something I got out of our conversation. Something’s gonna happen at I2. Otherwise, you wouldn’t try so hard to stop me here.”<span class=\"pg\">p.227<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “About Ayanokouji-senpai’s situation. You don’t know anything about that, right, Horikita-senpai?”<span class=\"pg\">p.227<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That’s right. I know Ayanokouji-senpai very well. Why is he so handsome, so smart… and so much stronger than anyone else?”<span class=\"pg\">p.227<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Then, what do you know, Horikita-senpai?”<span class=\"pg\">p.228<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Do you think you can help? Horikita-senpai.”<span class=\"pg\">p.228<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don’t kid me, how could Ayanokouji-senpai need your help?”<span class=\"pg\">p.230<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I can’t let you go over there, Horikita-senpai.”<span class=\"pg\">p.230<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Do you think you get past me?”<span class=\"pg\">p.230<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well~ Your determination has been conveyed to me. I’ll only wait until you put your backpack down.”<span class=\"pg\">p.230<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Let me tell you something first. I have experience with martial arts.”<span class=\"pg\">p.231<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…Ah, you really are an information warrior.”<span class=\"pg\">p.231<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Let me also say right now that I’m super powerful, so you better keep that in mind.”<span class=\"pg\">p.231<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Since you said you’re going to meet up with Ayanokouji-senpai, I’ll play with you for a bit.”<span class=\"pg\">p.231<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> She dominates the conversation — she knows Horikita&#x27;s designated area is I7, knows the note&#x27;s contents without owning them, and dismisses Horikita&#x27;s little-sister-like admiration for Ayanokōji with surgical contempt; she fights with a smirk; she is physically in excellent shape but carries an unseen injury.<span class=\"pg\">p.220–231<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> She bullies her to tears; she fights her for fun.<span class=\"pg\">p.220–231<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ibuki Mio<\/b> The other half of her audience; she ignores her rudely.<span class=\"pg\">p.220–231<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v4-p162-1\">← Before: Amasawa mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v4-p232-1\">→ After: Ch.6: The 1-on-1 demonstration<\/button><\/div><\/article>"},{"i":"sc-horikita-suzune-y2v4-p220-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"amasawa-ichika ibuki-mio horikita-suzune","q":"horikita suzune ch 6  amasawa stops her the two girls part ways  amasawa appears from nowhere with a childlike smile and stops horikita  reveals the note is hers and she staked her own position to be here   found you   hello  horikita senpai   who are you   class 1 a s amasawa ichika   you guys don t need to mind me  just continue doing your own thing  okay   that s not okay  we re talking about something personal   you re a nuisance   is sudo senpai okay  horikita senpai   well  thanks for saving him  i m grateful   didn t i say that you re a nuisance  i have business with her  so get out of here   business  didn t ibuki senpai run over here without permission   even if that s the case  it s still fine   what s your purpose  amasawa san   fine   i want to ask you a question  where are you going  horikita senpai   right now  i m standing and chatting with ibuki san  so when i finish with her  i ll immediately rush to f3   it s not good to lie  horikita senpai  your designated area isn t in this direction right   what do you mean  are you trying to make me fall into a trap using strange methods   misleading is useless though  the designated area you were supposed to go to is i7  isn t it   isn t it a given to be wary of the people trying to frame ayanokouji kun   oh  so that s it  perhaps   where are you planning to go  horikita senpai  it s not i2  is it   you ve seen through a lot  huh  but i decided to go to i2 because of what happened this morning  you re really observant  aren t you   ibuki san   ah  seriously  well that sucks   if you re satisfied now  go along to your designated area  on the last day  the score you ll get is twice as high  so you still have a chance to bounce back   yeah  but  what do you mean by abandoning the designated area   ibuki  this is a great opportunity  i m in a state where i can t score right now   indeed  the winner and loser will be decided at the end of this uninhabited island exam  if you say you re going to stop now  i won t hesitate to make a comeback for good   i m going to i2 now  what are you going to do   why are you going to such an irrelevant area as i2  there s not even an event there  is this something you should be doing during a special exam   don t tell me you don t know why   what do you mean   don t play dumb  what s the purpose in throwing this piece of paper in the tent when i was asleep   paper  is that for me   it s a string of irregularly arranged words   noon   k a   expelled   i2   i really hate  how you like to play games  even to this extent   games  what are you planning to involve me and ayanokouji kun in   this  i don t know  because i m just one of the bystanders  just like you   don t misunderstand  you appearing in front of me is the best proof that you wrote this   looking at those 4 words  what kind of bad feeling are you experiencing   ayanokouji may be expelled  it s not hard to understand it like that   there s something i got out of our conversation  something s gonna happen at i2  otherwise  you wouldn t try so hard to stop me here   about ayanokouji senpai s situation  you don t know anything about that  right  horikita senpai   so  are you saying that you know him better than i do   that s right  i know ayanokouji senpai very well  why is he so handsome  so smart  and so much stronger than anyone else   then  what do you know  horikita senpai   yeah  it s true  i probably know nothing about him  i can t deny that   but   from now until graduation  i want to continue understanding him better  as my classmate  as a friend  more than you are now   do you think you can help  horikita senpai   maybe i m not strong enough right now  but i intend to help him when he s in trouble   don t kid me  how could ayanokouji senpai need your help   that s true  at least for now   one more thing  i learned that you genuinely don t want me to go to i2  which means you re not the one who wrote that   i can t let you go over there  horikita senpai   the more you try to stop me  the more i must go to i2  from your tone of voice  shouldn t he be having a hard time now   do you think you get past me   yes  i do think i can get past you   well  your determination has been conveyed to me  i ll only wait until you put your backpack down   let me tell you something first  i have experience with martial arts   i already knew that   ah  you really are an information warrior   let me also say right now that i m super powerful  so you better keep that in mind  she admits she knows almost nothing about him   amasawa is the information warrior who knows him deeply  she sets i2 as her own destination  amasawa physically blocks her  horikita strips to a fighting stance  the note writer  she challenges horikita physically  she taunts her with amasawa level knowledge of ayanokoji  sends her to i7 to save her from the aftermath","h":"<article class=\"card\" id=\"sc-horikita-suzune-y2v4-p220-1\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-suzune.html#sc-horikita-suzune-y2v4-p220-1\">Ch.6: Amasawa stops her<\/a><\/span><span class=\"meta\">Y2V4 · p.220–226<\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/span><\/h3><p class=\"setup\">The two girls part ways; Amasawa appears from nowhere with a childlike smile and stops Horikita; reveals the note is hers and she staked her own position to be here.<\/p><p class=\"with\">with <a href=\"../../../people/amasawa-ichika.html\">Amasawa Ichika<\/a> · <a href=\"../../../people/ibuki-mio.html\">Ibuki Mio<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Amasawa Ichika<\/b> “Found you.”<span class=\"pg\">p.220<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Amasawa Ichika<\/b> “Hello, Horikita-senpai!”<span class=\"pg\">p.221<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “…Who are you?”<span class=\"pg\">p.221<\/span><\/li><\/ul><details class=\"more\"><summary>64 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Class 1-A’s Amasawa Ichika.”<span class=\"pg\">p.221<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You guys don’t need to mind me, just continue doing your own thing, okay~~?”<span class=\"pg\">p.221<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That’s not okay, we’re talking about something personal.”<span class=\"pg\">p.221<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You’re a nuisance.”<span class=\"pg\">p.221<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Is Sudo-senpai okay? Horikita-senpai.”<span class=\"pg\">p.221<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “….Well, thanks for saving him, I’m grateful.”<span class=\"pg\">p.222<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Didn’t I say that you’re a nuisance? I have business with her, so get out of here.”<span class=\"pg\">p.222<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Business? Didn’t Ibuki-senpai run over here without permission?”<span class=\"pg\">p.222<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Even if that’s the case, it’s still fine.”<span class=\"pg\">p.222<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What’s your purpose, Amasawa-san?”<span class=\"pg\">p.222<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Fine.”<span class=\"pg\">p.222<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I want to ask you a question. Where are you going, Horikita-senpai?”<span class=\"pg\">p.222<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Right now, I’m standing and chatting with Ibuki-san, so when I finish with her, I’ll immediately rush to F3.”<span class=\"pg\">p.222<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s not good to lie, Horikita-senpai! Your designated area isn’t in this direction right?”<span class=\"pg\">p.223<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What do you mean? Are you trying to make me fall into a trap using strange methods?”<span class=\"pg\">p.223<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Misleading is useless though. The designated area you were supposed to go to is I7, isn’t it?”<span class=\"pg\">p.223<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Isn’t it a given to be wary of the people trying to frame Ayanokouji-kun?”<span class=\"pg\">p.223<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Oh, so that’s it. Perhaps.”<span class=\"pg\">p.223<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Where are you planning to go, Horikita-senpai? It’s not I2, is it?”<span class=\"pg\">p.224<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You’ve seen through a lot, huh. But I decided to go to I2 because of what happened this morning. You’re really observant, aren’t you?”<span class=\"pg\">p.224<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ibuki-san.”<span class=\"pg\">p.224<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ah, seriously? Well that sucks.”<span class=\"pg\">p.224<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If you’re satisfied now, go along to your designated area. On the last day, the score you’ll get is twice as high, so you still have a chance to bounce back.”<span class=\"pg\">p.225<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yeah, but… What do you mean by abandoning the designated area?”<span class=\"pg\">p.225<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ibuki, this is a great opportunity. I’m in a state where I can’t score right now.”<span class=\"pg\">p.225<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Indeed, the winner and loser will be decided at the end of this uninhabited island exam. If you say you’re going to stop now, I won’t hesitate to make a comeback for good.”<span class=\"pg\">p.225<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m going to I2 now, what are you going to do?”<span class=\"pg\">p.226<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Why are you going to such an irrelevant area as I2? There’s not even an event there. Is this something you should be doing during a special exam?”<span class=\"pg\">p.226<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don’t tell me you don’t know why?”<span class=\"pg\">p.226<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What do you mean?”<span class=\"pg\">p.226<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don’t play dumb, what’s the purpose in throwing this piece of paper in the tent when I was asleep?”<span class=\"pg\">p.226<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…Paper? Is that for me?”<span class=\"pg\">p.226<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s a string of irregularly arranged words… “Noon”, “K.A”, “Expelled”, “I2”.”<span class=\"pg\">p.226<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I really hate… how you like to play games, even to this extent…”<span class=\"pg\">p.226<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Games? What are you planning to involve me and Ayanokouji-kun in?”<span class=\"pg\">p.226<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “This, I don’t know. Because I’m just one of the bystanders, just like you.”<span class=\"pg\">p.226<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don’t misunderstand. You appearing in front of me is the best proof that you wrote this.”<span class=\"pg\">p.226<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Looking at those 4 words, what kind of bad feeling are you experiencing?”<span class=\"pg\">p.226<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ayanokouji may be expelled. It’s not hard to understand it like that.”<span class=\"pg\">p.226<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There’s something I got out of our conversation. Something’s gonna happen at I2. Otherwise, you wouldn’t try so hard to stop me here.”<span class=\"pg\">p.227<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “About Ayanokouji-senpai’s situation. You don’t know anything about that, right, Horikita-senpai?”<span class=\"pg\">p.227<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So, are you saying that you know him better than I do?”<span class=\"pg\">p.227<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That’s right. I know Ayanokouji-senpai very well. Why is he so handsome, so smart… and so much stronger than anyone else?”<span class=\"pg\">p.227<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Then, what do you know, Horikita-senpai?”<span class=\"pg\">p.228<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yeah, it’s true. I probably know nothing about him. I can’t deny that.”<span class=\"pg\">p.228<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But?”<span class=\"pg\">p.228<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “from now until graduation, I want to continue understanding him better, as my classmate… As a friend, more than you are now.”<span class=\"pg\">p.228<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Do you think you can help? Horikita-senpai.”<span class=\"pg\">p.229<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Maybe I’m not strong enough right now, but I intend to help him when he’s in trouble.”<span class=\"pg\">p.229<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don’t kid me, how could Ayanokouji-senpai need your help?”<span class=\"pg\">p.230<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That’s true, at least for now.”<span class=\"pg\">p.230<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “One more thing, I learned that you genuinely don’t want me to go to I2, which means you’re not the one who wrote that.”<span class=\"pg\">p.230<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I can’t let you go over there, Horikita-senpai.”<span class=\"pg\">p.230<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The more you try to stop me, the more I must go to I2. From your tone of voice, shouldn’t he be having a hard time now?”<span class=\"pg\">p.230<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Do you think you get past me?”<span class=\"pg\">p.230<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yes, I do think I can get past you.”<span class=\"pg\">p.230<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well~ Your determination has been conveyed to me. I’ll only wait until you put your backpack down.”<span class=\"pg\">p.230<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Let me tell you something first. I have experience with martial arts.”<span class=\"pg\">p.231<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I already knew that.”<span class=\"pg\">p.231<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…Ah, you really are an information warrior.”<span class=\"pg\">p.231<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Let me also say right now that I’m super powerful, so you better keep that in mind.”<span class=\"pg\">p.231<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> She admits she knows almost nothing about him — Amasawa is the information warrior who knows him deeply; she sets I2 as her own destination; Amasawa physically blocks her; Horikita strips to a fighting stance.<span class=\"pg\">p.220–231<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Amasawa Ichika<\/b> The note writer; she challenges Horikita physically; she taunts her with Amasawa-level knowledge of Ayanokōji.<span class=\"pg\">p.220–231<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ibuki Mio<\/b> Sends her to I7 to save her from the aftermath.<span class=\"pg\">p.224–226<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y2v4-p216-1\">← Before: Ch.6: Ibuki catches up; the score game<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y2v4-p232-1\">→ After: Ch.6: Amasawa&#x27;s demonstration<\/button><\/div><\/article>"},{"i":"sc-ibuki-mio-y2v4-p227-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"amasawa-ichika horikita-suzune ibuki-mio","q":"ibuki mio ch 6  the 2 on 1 with horikita amasawa appeared and beat horikita senseless  ibuki returns at the last second and grabs her fist  they form a group of two to protect each other  amasawa plays with them   ahah  do you call that fighting   the one who beat you is me  and so i don t want you losing to some first year i don t know in front of me   i m amasawa ichika  please remember my name  ibuki senpai   i ve got a bad memory  if you want me to remember  you d better impress me a little  yeah   ahaha  that seems a little interesting   i ll have fun with her  so you go where you want to go   what are you talking about  you worked hard in this special exam just to beat me  right   aren t you going to give up on the designated area as well  in that case  even if i comeback and get the w  there s no point in it   she s incredibly powerful  you might regret it later  is that okay   what  are you saying that i ll lose   she s a formidable opponent   i don t see me losing to ibuki senpai at all   i have faith that i m stronger   who s going to fight  hurry up and decide   i will fight her   this is my fight  it s none of your business   talking about how strong your opponent is and now you re messing around like this  did you bang your head or something   i ve thought about it  and if you ask me  you can t win against her   stop joking around  don t decide before it even happens   that s the truth  i couldn t do anything  so there s no way you can win against her   if you don t want to lose  if you want to break this stalemate  show me your resolve  form a group with me  if something happens to one of us and have to withdraw  the group will still survive  that s the only way to effectively prevent the withdrawal   are you kidding me  why would i form a group with someone like you   didn t i just say  i need you to come to an understanding  if you haven t yet  then don t join this fight   so annoying   it s alright if you don t like it  but i d like to rely on you if you re going to join the fight   this sucks  but it wouldn t be much fun if you ll be forced to drop out because of some 1st years   it s not a bad strategy  if separate students form a group  it s true that if something happens to one of them  they can still avoid being expelled   but there s just one thing you thought incorrectly  horikita senpai   incorrect  what exactly do you mean   it s alright for one person to withdraw  which means  it s okay for me to break one of you   so which one should i destroy first   let s go  ibuki  you go to the left   don t order me around   alrightly  let s stop for a while   what s going on  this 1st year   seriously   ibuki  don t get too careless   let go of me   didn t i tell you to stop   ah   okay  let s start over   aren t you the same as me   i m not like you  i went for it knowing that it would turn out that way  in order to reassess my strategy   excuses  how lame   huh  impossible   if you don t then there s no point  you should understand how strong amasawa san is  neither you or i cannot beat her alone   even if that s the case  i won t follow your instructions   now that you re my partner  follow my instructions  you can do that  right   your fighting sense is comparable to me  no  i think you are slightly better than me   huh  so sudden  so you gonna admit losing   however  your fighting style is specialized for one on one fights  and i am more familiar with how to fight with strong opponents two on one  the word cooperation may be unsuited for you  but lend me your strength   you are equal or stronger than me in terms of fighting  but that s it  in other areas  we are not on the same level  you are not good at academics  you can t lead your class  and you can t cooperate with others  i don t want to be mean  but calling yourself my rival is just you being narcissistic   it s about time for you to change yourself as well  isn t it  mio ibuki san   what was that all about   if you keep fighting alone like this  you will surely be in danger of expulsion at some point   not a big deal  if that happens   which means it ll be your complete loss to me  is that fine   huh   if you get expelled halfway  you can t be considered my rival  you need to persist til the very end  and grow into a rival that can pose a threat to me   arghh  i know  i know  so shut up  i will only listen to you here  that s enough  right   good   so  what should i do   like before  we attack amasawa san at the same time  however  actually hitting her is of secondary importance  i want you to dodge her attacks  make sure not to get caught  and continue to attack   hitting her is of secondary importance  what use would that be   if my guess is correct that will be our chance to win  when i give you the signal  attack with all you ve got   what are you talking about   it s all over  if you think i m lying  go ahead and see for yourself   i m thinking  if ayanokouji s in danger  i can taunt him next to you   yeah  i ll go  her archenemy  she fights her side by side  the first year who fights them both and then walks away laughing  she shields the pre fight bruise knowledge with a grin","h":"<article class=\"card\" id=\"sc-ibuki-mio-y2v4-p227-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ibuki-mio.html#sc-ibuki-mio-y2v4-p227-1\">Ch.6: The 2-on-1 with Horikita<\/a><\/span><span class=\"meta\">Y2V4 · p.227–251<\/span><span class=\"by\">notes on <a href=\"../../../people/ibuki-mio.html\">Ibuki Mio<\/a><\/span><\/h3><p class=\"setup\">Amasawa appeared and beat Horikita senseless; Ibuki returns at the last second and grabs her fist; they form a group of two to protect each other; Amasawa plays with them.<\/p><p class=\"with\">with <a href=\"../../../people/amasawa-ichika.html\">Amasawa Ichika<\/a> · <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Amasawa Ichika<\/b> “Ahah…. Do you call that fighting?”<span class=\"pg\">p.237<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ibuki Mio<\/b> “The one who beat you is me, and so I don’t want you losing to some first year I don’t know in front of me.”<span class=\"pg\">p.237<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Amasawa Ichika<\/b> “I’m Amasawa Ichika. Please remember my name, Ibuki-senpai.”<span class=\"pg\">p.237<\/span><\/li><\/ul><details class=\"more\"><summary>68 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “I’ve got a bad memory. If you want me to remember, you’d better impress me a little, yeah?”<span class=\"pg\">p.237<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ahaha, that seems a little interesting.”<span class=\"pg\">p.237<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’ll have fun with her, so you go where you want to go.”<span class=\"pg\">p.237<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What are you talking about? You worked hard in this special exam just to beat me, right?”<span class=\"pg\">p.237<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Aren’t you going to give up on the designated area as well? In that case, even if I comeback and get the W, there’s no point in it.”<span class=\"pg\">p.237<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “She’s incredibly powerful. You might regret it later, is that okay?”<span class=\"pg\">p.238<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What? Are you saying that I’ll lose?”<span class=\"pg\">p.238<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “She’s a formidable opponent.”<span class=\"pg\">p.238<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don’t see me losing to Ibuki-senpai at all.”<span class=\"pg\">p.238<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I have faith that I’m stronger.”<span class=\"pg\">p.238<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Who’s going to fight? Hurry up and decide~~”<span class=\"pg\">p.238<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I will fight her.”<span class=\"pg\">p.238<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “This is my fight. It’s none of your business.”<span class=\"pg\">p.238<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Talking about how strong your opponent is and now you’re messing around like this? Did you bang your head or something?”<span class=\"pg\">p.238<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’ve thought about it, and if you ask me, you can’t win against her.”<span class=\"pg\">p.239<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Stop joking around. Don’t decide before it even happens.”<span class=\"pg\">p.239<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That’s the truth. I couldn’t do anything, so there’s no way you can win against her.”<span class=\"pg\">p.239<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If you don’t want to lose, if you want to break this stalemate, show me your resolve. Form a group with me. If something happens to one of us and have to withdraw, the group will still survive. That’s the only way to effectively prevent the withdrawal.”<span class=\"pg\">p.239<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Are you kidding me? Why would I form a group with someone like you?”<span class=\"pg\">p.239<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Didn’t I just say? I need you to come to an understanding. If you haven’t yet, then don’t join this fight.”<span class=\"pg\">p.239<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So annoying…”<span class=\"pg\">p.239<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s alright if you don’t like it, but I’d like to rely on you if you’re going to join the fight.”<span class=\"pg\">p.239<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “This sucks. But it wouldn’t be much fun if you’ll be forced to drop out because of some 1st years.”<span class=\"pg\">p.239<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s not a bad strategy. If separate students form a group, it’s true that if something happens to one of them, they can still avoid being expelled.”<span class=\"pg\">p.241<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But there’s just one thing you thought incorrectly, Horikita-senpai.”<span class=\"pg\">p.241<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Incorrect? What exactly do you mean?”<span class=\"pg\">p.241<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s alright for one person to withdraw, which means, it’s okay for me to break one of you.”<span class=\"pg\">p.241<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So which one should I destroy first—?”<span class=\"pg\">p.241<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Let’s go, Ibuki! You go to the left!”<span class=\"pg\">p.242<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don’t order me around!”<span class=\"pg\">p.242<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Alrightly, let’s stop for a while.”<span class=\"pg\">p.243<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What’s going on, this 1st year….!”<span class=\"pg\">p.243<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Seriously…”<span class=\"pg\">p.243<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ibuki, don’t get too careless.”<span class=\"pg\">p.243<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Let go of me!”<span class=\"pg\">p.243<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Didn’t I tell you to stop?”<span class=\"pg\">p.244<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ah!!”<span class=\"pg\">p.244<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Okay, let’s start over.”<span class=\"pg\">p.245<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Aren’t you the same as me?”<span class=\"pg\">p.245<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m not like you, I went for it knowing that it would turn out that way… In order to reassess my strategy.”<span class=\"pg\">p.244<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Excuses, how lame.”<span class=\"pg\">p.245<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Huh? Impossible.”<span class=\"pg\">p.246<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If you don’t then there’s no point. You should understand how strong Amasawa-san is. Neither you or I cannot beat her alone.”<span class=\"pg\">p.246<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Even if that’s the case, I won’t follow your instructions.”<span class=\"pg\">p.246<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Now that you’re my partner, follow my instructions. You can do that, right?”<span class=\"pg\">p.245<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Your fighting sense is comparable to me. No, I think you are slightly better than me.”<span class=\"pg\">p.246<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Huh, so sudden. So you gonna admit losing?”<span class=\"pg\">p.246<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “However, your fighting style is specialized for one-on-one fights, and I am more familiar with how to fight with strong opponents two-on-one. The word cooperation may be unsuited for you, but lend me your strength.”<span class=\"pg\">p.246<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You are equal or stronger than me in terms of fighting, but that’s it. In other areas, we are not on the same level. You are not good at academics, you can’t lead your class, and you can’t cooperate with others. I don’t want to be mean, but calling yourself my rival is just you being narcissistic.”<span class=\"pg\">p.246<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s about time for you to change yourself as well, isn’t it? Mio Ibuki-san.”<span class=\"pg\">p.246<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…What was that all about?”<span class=\"pg\">p.246<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If you keep fighting alone like this, you will surely be in danger of expulsion at some point.”<span class=\"pg\">p.246<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Not a big deal, if that happens.”<span class=\"pg\">p.246<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Which means it’ll be your complete loss to me. Is that fine?”<span class=\"pg\">p.246<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Huh?”<span class=\"pg\">p.246<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If you get expelled halfway, you can’t be considered my rival. You need to persist til the very end, and grow into a rival that can pose a threat to me.”<span class=\"pg\">p.246<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Arghh, I know, I know, so shut up. I will only listen to you here. That’s enough, right?”<span class=\"pg\">p.246<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Good.”<span class=\"pg\">p.246<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So, what should I do?”<span class=\"pg\">p.246<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Like before, we attack Amasawa-san at the same time. However, actually hitting her is of secondary importance. I want you to dodge her attacks, make sure not to get caught, and continue to attack.”<span class=\"pg\">p.247<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Hitting her is of secondary importance? What use would that be?”<span class=\"pg\">p.247<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If my guess is correct…that will be our chance to win. When I give you the signal, attack with all you’ve got.”<span class=\"pg\">p.247<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What are you talking about?”<span class=\"pg\">p.251<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s all over. If you think I’m lying, go ahead and see for yourself.”<span class=\"pg\">p.251<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m thinking, if Ayanokouji’s in danger, I can taunt him next to you.”<span class=\"pg\">p.252<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yeah, I’ll go.”<span class=\"pg\">p.251<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Her archenemy; she fights her side by side.<span class=\"pg\">p.216–252<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Amasawa Ichika<\/b> The first-year who fights them both and then walks away laughing; she shields the pre-fight bruise knowledge with a grin.<span class=\"pg\">p.237–251<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ibuki-mio-y2v4-p216-1\">← Before: Ch.6: She catches Horikita<\/button><\/div><\/article>"},{"i":"sc-kushida-kikyou-y2v4-p227-1","v":"y2v4","y":2,"o":19,"k":"","w":"kushida-kikyou","q":"kushida kikyo kushida mentioned in passing named in the context of the exam  named in the context of the exam  passing mentions  not a distinct scene presence  passing mention only","h":"<article class=\"card\" id=\"sc-kushida-kikyou-y2v4-p227-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kushida-kikyou.html#sc-kushida-kikyou-y2v4-p227-1\">Kushida mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.227, 236<\/span><span class=\"by\">notes on <a href=\"../../../people/kushida-kikyou.html\">Kushida Kikyō<\/a><\/span><\/h3><p class=\"setup\">Named in the context of the exam. Named in the context of the exam.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Passing mentions; not a distinct scene presence.<span class=\"pg\">p.227, 236<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Passing mention only.<span class=\"pg\">p.227, 236<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v4-p231-1","v":"y2v4","y":2,"o":19,"k":"","w":"ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ak mentioned in passing  let me tell you something first  i have experience with martial arts    amasawa","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v4-p231-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v4-p231-1\">AK mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.231<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “Let me tell you something first. I have experience with martial arts.” — Amasawa.<span class=\"pg\">p.231<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p215-1\">← Before: Ch.6: The I2 blocks, from outside (mention records)<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p252-1\">→ After: The showdown at I2: Ayanokōji vs Tsukishiro and Shiba<\/button><\/div><\/article>"},{"i":"sc-amasawa-ichika-y2v4-p232-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"horikita-suzune amasawa-ichika","q":"amasawa ichika ch 6  the 1 on 1 demonstration fight at the i2 border  she unleashes a body slam and a rib kick on horikita  then pins her  she fights with minimal movement  almost lazily  horikita is devastated  amasawa laughs   huh   what s impossible  huh   kgh   oh no  you can t take this lightly  okay  i ll give you some time to recover  stand up   you thought i just used judo  didn t you  that s too naive of you   who are you  you seem to know the ayanokouji kun in the past    horikita   who are you  you seem to know the ayanokouji kun in the past   how should i say this  you really are a disappointment  you aren t as good as i thought you are  horikita senpai  it s because of this that ayanokouji senpai didn t seek your help   when you say you want to help him  it actually is to find out what ayanokouij senpai thinks about how you aren t being trusted by him   still  even kushida senpai is more discerning   i also just said  horikita senpai  you aren t worthy for ayanokouji senpai to rely on   do you know what i mean by that   kushida san  why did you say her name   stand up  horikita senpai  i no longer want to talk to you  it s annoying me  so let s end this  she fights with a smile  uses minimal movement  and savors dominating horikita  she probes horikita s knowledge of ayanokoji for fun  she lands nothing clean   she already took a beating before this fight  and it shows  she breaks her in a demonstration of martial arts superiority  the p 249 bruise    i just had a fight  before i fought you senpais    she took the beating before this fight  the person who hurt her is never named on these pages  her stamina is low because of it","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v4-p232-1\"><h3><span class=\"ttl\"><a href=\"../../../people/amasawa-ichika.html#sc-amasawa-ichika-y2v4-p232-1\">Ch.6: The 1-on-1 demonstration<\/a><\/span><span class=\"meta\">Y2V4 · p.232–236<\/span><span class=\"by\">notes on <a href=\"../../../people/amasawa-ichika.html\">Amasawa Ichika<\/a><\/span><\/h3><p class=\"setup\">Fight at the I2 border; she unleashes a body-slam and a rib-kick on Horikita, then pins her; she fights with minimal movement, almost lazily; Horikita is devastated; Amasawa laughs.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “Huh?!”<span class=\"pg\">p.232<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Amasawa Ichika<\/b> “What’s impossible, huh?”<span class=\"pg\">p.232<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “Kgh-!”<span class=\"pg\">p.232<\/span><\/li><\/ul><details class=\"more\"><summary>14 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Oh no, you can’t take this lightly. Okay, I’ll give you some time to recover, stand up.”<span class=\"pg\">p.232<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You thought I just used judo, didn’t you? That’s too naive of you.”<span class=\"pg\">p.234<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Who are you? You seem to know the Ayanokouji-kun in the past…” — Horikita.<span class=\"pg\">p.235<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Who are you? You seem to know the Ayanokouji-kun in the past…”<span class=\"pg\">p.235<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “How should I say this? You really are a disappointment. You aren’t as good as I thought you are, Horikita-senpai. It’s because of this that Ayanokouji-senpai didn’t seek your help.”<span class=\"pg\">p.235<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “When you say you want to help him, it actually is to find out what Ayanokouij-senpai thinks about how you aren’t being trusted by him.”<span class=\"pg\">p.235<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Still, even Kushida-senpai is more discerning.”<span class=\"pg\">p.236<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I also just said, Horikita-senpai, you aren’t worthy for Ayanokouji-senpai to rely on.”<span class=\"pg\">p.236<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Do you know what I mean by that?”<span class=\"pg\">p.236<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Kushida-san? Why did you say her name?”<span class=\"pg\">p.236<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Stand up, Horikita-senpai. I no longer want to talk to you. It’s annoying me. So let’s end this.”<span class=\"pg\">p.236<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> She fights with a smile, uses minimal movement, and savors dominating Horikita; she probes Horikita&#x27;s knowledge of Ayanokōji for fun; she lands nothing clean — she already took a beating before this fight, and it shows.<span class=\"pg\">p.232–236<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> She breaks her in a demonstration of martial arts superiority.<span class=\"pg\">p.232–236<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The p.249 bruise — “I just had a fight, before I fought you senpais.” — she took the beating before this fight; the person who hurt her is never named on these pages; her stamina is low because of it.<span class=\"pg\">p.249<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v4-p220-1\">← Before: Ch.6: The I2 assignment; she stops Horikita<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v4-p237-1\">→ After: Ch.6: The 2-on-1; the decision to let them pass<\/button><\/div><\/article>"},{"i":"sc-horikita-suzune-y2v4-p232-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"amasawa-ichika horikita-suzune","q":"horikita suzune ch 6  amasawa s demonstration fight at i2 s border  amasawa fights with minimal movement  horikita is smashed to the ground in one throw  a kick to her ribs  amasawa pins her down like a game   huh   impossible   what s impossible  huh   kgh   oh no  you can t take this lightly  okay  i ll give you some time to recover  stand up   i ll do that  as long as your motive isn t to stop me from going to ayanokouji kun   again   you thought i just used judo  didn t you  that s too naive of you   the 1st years this year  they aren t cute at all   who are you  you seem to know the ayanokouji kun in the past   how do you expect me to tell you about these things  senpai   how should i say this  you really are a disappointment  you aren t as good as i thought you are  horikita senpai  it s because of this that ayanokouji senpai didn t seek your help   when you say you want to help him  it actually is to find out what ayanokouij senpai thinks about how you aren t being trusted by him   maybe so   i also just said  horikita senpai  you aren t worthy for ayanokouji senpai to rely on   even so  this shouldn t come from your mouth  but his   do you know what i mean by that   still  even kushida senpai is more discerning   kushida san  why did you say her name   stand up  horikita senpai  i no longer want to talk to you  it s annoying me  so let s end this  she goes down repeatedly   body throw  rib kick  no stamina left  amasawa fights like she s playing  she pieces together that amasawa suffered a fight before this one  she cannot guess who hurt her   but the answer must be someone ayanokoji knows  the fight  amasawa dominates her completely","h":"<article class=\"card\" id=\"sc-horikita-suzune-y2v4-p232-1\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-suzune.html#sc-horikita-suzune-y2v4-p232-1\">Ch.6: Amasawa&#x27;s demonstration<\/a><\/span><span class=\"meta\">Y2V4 · p.232–236<\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/span><\/h3><p class=\"setup\">Fight at I2&#x27;s border; Amasawa fights with minimal movement; Horikita is smashed to the ground in one throw; a kick to her ribs; Amasawa pins her down like a game.<\/p><p class=\"with\">with <a href=\"../../../people/amasawa-ichika.html\">Amasawa Ichika<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “Huh?!”<span class=\"pg\">p.232<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “Impossible…”<span class=\"pg\">p.232<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Amasawa Ichika<\/b> “What’s impossible, huh?”<span class=\"pg\">p.232<\/span><\/li><\/ul><details class=\"more\"><summary>19 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Kgh-!”<span class=\"pg\">p.232<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Oh no, you can’t take this lightly. Okay, I’ll give you some time to recover, stand up.”<span class=\"pg\">p.232<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’ll do that, as long as your motive isn’t to stop me from going to Ayanokouji-kun.”<span class=\"pg\">p.233<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Again.”<span class=\"pg\">p.234<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You thought I just used judo, didn’t you? That’s too naive of you.”<span class=\"pg\">p.234<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The 1st years this year, they aren’t cute at all…”<span class=\"pg\">p.235<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Who are you? You seem to know the Ayanokouji-kun in the past…”<span class=\"pg\">p.235<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “How do you expect me to tell you about these things, senpai?”<span class=\"pg\">p.235<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “How should I say this? You really are a disappointment. You aren’t as good as I thought you are, Horikita-senpai. It’s because of this that Ayanokouji-senpai didn’t seek your help.”<span class=\"pg\">p.235<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “When you say you want to help him, it actually is to find out what Ayanokouij-senpai thinks about how you aren’t being trusted by him.”<span class=\"pg\">p.235<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…Maybe so.”<span class=\"pg\">p.236<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I also just said, Horikita-senpai, you aren’t worthy for Ayanokouji-senpai to rely on.”<span class=\"pg\">p.236<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Even so, this shouldn’t come from your mouth, but his.”<span class=\"pg\">p.236<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Do you know what I mean by that?”<span class=\"pg\">p.236<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Still, even Kushida-senpai is more discerning.”<span class=\"pg\">p.236<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Kushida-san? Why did you say her name?”<span class=\"pg\">p.236<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Stand up, Horikita-senpai. I no longer want to talk to you. It’s annoying me. So let’s end this.”<span class=\"pg\">p.236<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> She goes down repeatedly — body throw, rib kick, no stamina left; Amasawa fights like she&#x27;s playing; she pieces together that Amasawa suffered a fight before this one; she cannot guess who hurt her — but the answer must be someone Ayanokōji knows.<span class=\"pg\">p.232–236<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Amasawa Ichika<\/b> The fight; Amasawa dominates her completely.<span class=\"pg\">p.232–236<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y2v4-p220-1\">← Before: Ch.6: Amasawa stops her<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y2v4-p237-1\">→ After: Ch.6: The 2-on-1; the way opens<\/button><\/div><\/article>"},{"i":"sc-amasawa-ichika-y2v4-p237-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"horikita-suzune ibuki-mio amasawa-ichika","q":"amasawa ichika ch 6  the 2 on 1  the decision to let them pass horikita and ibuki form a group of two  they attack in waves  amasawa enjoys the feints and the pressure  she starts to tire  her old injuries show  she opens the path and leaves laughing   ahah  do you call that fighting   i m amasawa ichika  please remember my name  ibuki senpai   ahaha  that seems a little interesting   what are you talking about  you worked hard in this special exam just to beat me  right   i don t see me losing to ibuki senpai at all   who s going to fight  hurry up and decide   it s not a bad strategy  if separate students form a group  it s true that if something happens to one of them  they can still avoid being expelled   but there s just one thing you thought incorrectly  horikita senpai   it s alright for one person to withdraw  which means  it s okay for me to break one of you   so which one should i destroy first   alrightly  let s stop for a while   didn t i tell you to stop   okay  let s start over   aren t you the same as me   excuses  how lame   ahhhhh  have i been exposed  my physique is actually unexpectedly weak then   i just had a fight  before i fought you senpais   sorry  but i can t believe you  who is it   oi  what are you doing   it seems like it s over  it s a bit interesting  but it s going to be a while again   where  well  to the designated area i guess  after all  there s still a special exam going on   ah  by the way  i don t think you need to go after ayanokouji senpai anymore   it s all over  if you think i m lying  go ahead and see for yourself   why don t you go and confirm it yourself  but it might be too late for you to regret it by then  though  she opens the path deliberately   she was never intending to kill them  she gives up on the i2 intercept after both her injuries surface  she warns them that ayanokoji is finished  she walks away laughing about the interest being a while again  she goes from bully to spectator   she enjoys the 2 on 1  she never intends to lose or to kill anyone  she lets them pass the moment her body gives out  she leaves knowing they are too late for i2   or so she claims  she breaks her  then lets her walk to i2   a hint that the i2 endgame is already decided  the unexpected second half of her audience  she takes them both on","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v4-p237-1\"><h3><span class=\"ttl\"><a href=\"../../../people/amasawa-ichika.html#sc-amasawa-ichika-y2v4-p237-1\">Ch.6: The 2-on-1; the decision to let them pass<\/a><\/span><span class=\"meta\">Y2V4 · p.237–251<\/span><span class=\"by\">notes on <a href=\"../../../people/amasawa-ichika.html\">Amasawa Ichika<\/a><\/span><\/h3><p class=\"setup\">Horikita and Ibuki form a group of two; they attack in waves; Amasawa enjoys the feints and the pressure; she starts to tire; her old injuries show; she opens the path and leaves laughing.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/ibuki-mio.html\">Ibuki Mio<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Amasawa Ichika<\/b> “Ahah…. Do you call that fighting?”<span class=\"pg\">p.237<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Amasawa Ichika<\/b> “I’m Amasawa Ichika. Please remember my name, Ibuki-senpai.”<span class=\"pg\">p.237<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Amasawa Ichika<\/b> “Ahaha, that seems a little interesting.”<span class=\"pg\">p.237<\/span><\/li><\/ul><details class=\"more\"><summary>25 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “What are you talking about? You worked hard in this special exam just to beat me, right?”<span class=\"pg\">p.237<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don’t see me losing to Ibuki-senpai at all.”<span class=\"pg\">p.238<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Who’s going to fight? Hurry up and decide~~”<span class=\"pg\">p.238<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s not a bad strategy. If separate students form a group, it’s true that if something happens to one of them, they can still avoid being expelled.”<span class=\"pg\">p.241<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But there’s just one thing you thought incorrectly, Horikita-senpai.”<span class=\"pg\">p.241<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s alright for one person to withdraw, which means, it’s okay for me to break one of you.”<span class=\"pg\">p.241<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So which one should I destroy first—?”<span class=\"pg\">p.241<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Alrightly, let’s stop for a while.”<span class=\"pg\">p.241<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Didn’t I tell you to stop?”<span class=\"pg\">p.244<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Okay, let’s start over.”<span class=\"pg\">p.244<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Aren’t you the same as me?”<span class=\"pg\">p.245<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Excuses, how lame.”<span class=\"pg\">p.245<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ahhhhh, have I been exposed? My physique is actually unexpectedly weak then.”<span class=\"pg\">p.248<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I just had a fight, before I fought you senpais.”<span class=\"pg\">p.249<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Sorry, but I can’t believe you. Who is it?”<span class=\"pg\">p.249<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Oi, what are you doing!”<span class=\"pg\">p.250<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It seems like it’s over. It’s a bit interesting, but it’s going to be a while again.”<span class=\"pg\">p.250<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Where? Well, to the designated area i guess. After all, there’s still a special exam going on.”<span class=\"pg\">p.251<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ah, by the way, I don’t think you need to go after Ayanokouji-senpai anymore.”<span class=\"pg\">p.251<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s all over. If you think I’m lying, go ahead and see for yourself.”<span class=\"pg\">p.251<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Why don’t you go and confirm it yourself? But it might be too late for you to regret it by then, though.”<span class=\"pg\">p.251<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> She opens the path deliberately — she was never intending to kill them; she gives up on the I2 intercept after both her injuries surface; she warns them that Ayanokōji is finished; she walks away laughing about the interest being a while again.<span class=\"pg\">p.250–251<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> She goes from bully to spectator — she enjoys the 2-on-1; she never intends to lose or to kill anyone; she lets them pass the moment her body gives out; she leaves knowing they are too late for I2 — or so she claims.<span class=\"pg\">p.237–251<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> She breaks her, then lets her walk to I2 — a hint that the I2 endgame is already decided.<span class=\"pg\">p.237–251<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ibuki Mio<\/b> The unexpected second half of her audience; she takes them both on.<span class=\"pg\">p.237–251<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v4-p232-1\">← Before: Ch.6: The 1-on-1 demonstration<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v4-p253-1\">→ After: Ch.6–Epilogue: The I2 aftermath (mention records)<\/button><\/div><\/article>"},{"i":"sc-horikita-suzune-y2v4-p237-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"amasawa-ichika ibuki-mio horikita-suzune","q":"horikita suzune ch 6  the 2 on 1  the way opens ibuki returns at the last second and grabs amasawa s fist  amasawa mocks her  horikita hatches the 2 on 1 plan  the two form a group  they overwhelm amasawa with feints  amasawa s old injuries surface  she retreats laughing and opens the path   you  why   ahah  do you call that fighting   the one who beat you is me  and so i don t want you losing to some first year i don t know in front of me   i m amasawa ichika  please remember my name  ibuki senpai   i ve got a bad memory  if you want me to remember  you d better impress me a little  yeah   ahaha  that seems a little interesting   i ll have fun with her  so you go where you want to go   what are you talking about  you worked hard in this special exam just to beat me  right   aren t you going to give up on the designated area as well  in that case  even if i comeback and get the w  there s no point in it   she s incredibly powerful  you might regret it later  is that okay   what  are you saying that i ll lose   she s a formidable opponent   i don t see me losing to ibuki senpai at all   i have faith that i m stronger   who s going to fight  hurry up and decide   i will fight her   this is my fight  it s none of your business   talking about how strong your opponent is and now you re messing around like this  did you bang your head or something   i ve thought about it  and if you ask me  you can t win against her   stop joking around  don t decide before it even happens   that s the truth  i couldn t do anything  so there s no way you can win against her   then prove it  right here in front of me   what for   if you don t want to lose  if you want to break this stalemate  show me your resolve  form a group with me  if something happens to one of us and have to withdraw  the group will still survive  that s the only way to effectively prevent the withdrawal   are you kidding me  why would i form a group with someone like you   didn t i just say  i need you to come to an understanding  if you haven t yet  then don t join this fight   so annoying   it s alright if you don t like it  but i d like to rely on you if you re going to join the fight   this sucks  but it wouldn t be much fun if you ll be forced to drop out because of some 1st years   it s not a bad strategy  if separate students form a group  it s true that if something happens to one of them  they can still avoid being expelled   but there s just one thing you thought incorrectly  horikita senpai   incorrect  what exactly do you mean   it s alright for one person to withdraw  which means  it s okay for me to break one of you   like before  we attack amasawa san at the same time  however  actually hitting her is of secondary importance  i want you to dodge her attacks  make sure not to get caught  and continue to attack   you are equal or stronger than me in terms of fighting  but that s it  in other areas  we are not on the same level  you are not good at academics  you can t lead your class  and you can t cooperate with others  i don t want to be mean  but calling yourself my rival is just you being narcissistic   ahhhhh  have i been exposed  my physique is actually unexpectedly weak then   i just had a fight  before i fought you senpais   hah  hah  heheh  amasawa  i ll admit that you re strong  but it seems like your stamina isn t infinite   ah  ah   ah  that worked really well   do you want to know who caused it  could it be housen kun   sorry  but i can t believe you  who is it   oi  what are you doing   yeah  i was too careless   it seems like it s over  it s a bit interesting  but it s going to be a while again   what are you talking about   where  well  to the designated area i guess  after all  there s still a special exam going on   ah  by the way  i don t think you need to go after ayanokouji senpai anymore   why   it s all over  if you think i m lying  go ahead and see for yourself   what are you going to do  you going to go after ayanokouji  that s why you fought with amasawa  right   yeah  i ll go   then i ll go too   i m thinking  if ayanokouji s in danger  i can taunt him next to you   you really are a bad person  she turns defeat into a shared project  ibuki joins the group merge to save her own pride  together they feint and counter amasawa  the first to crack is amasawa s stamina  ibuki and she head to i2  she now knows someone already fought amasawa before them  her momentary ally  the school hates them both  they fight together  she knows about the earlier fight that left the bruise  amasawa opens the path to i2 to watch them leave","h":"<article class=\"card\" id=\"sc-horikita-suzune-y2v4-p237-1\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-suzune.html#sc-horikita-suzune-y2v4-p237-1\">Ch.6: The 2-on-1; the way opens<\/a><\/span><span class=\"meta\">Y2V4 · p.237–251<\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/span><\/h3><p class=\"setup\">Ibuki returns at the last second and grabs Amasawa&#x27;s fist; Amasawa mocks her; Horikita hatches the 2-on-1 plan; the two form a group; they overwhelm Amasawa with feints; Amasawa&#x27;s old injuries surface; she retreats laughing and opens the path.<\/p><p class=\"with\">with <a href=\"../../../people/amasawa-ichika.html\">Amasawa Ichika<\/a> · <a href=\"../../../people/ibuki-mio.html\">Ibuki Mio<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “You, why….”<span class=\"pg\">p.237<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Amasawa Ichika<\/b> “Ahah…. Do you call that fighting?”<span class=\"pg\">p.237<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ibuki Mio<\/b> “The one who beat you is me, and so I don’t want you losing to some first year I don’t know in front of me.”<span class=\"pg\">p.237<\/span><\/li><\/ul><details class=\"more\"><summary>55 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “I’m Amasawa Ichika. Please remember my name, Ibuki-senpai.”<span class=\"pg\">p.237<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’ve got a bad memory. If you want me to remember, you’d better impress me a little, yeah?”<span class=\"pg\">p.237<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ahaha, that seems a little interesting.”<span class=\"pg\">p.237<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’ll have fun with her, so you go where you want to go.”<span class=\"pg\">p.237<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What are you talking about? You worked hard in this special exam just to beat me, right?”<span class=\"pg\">p.237<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Aren’t you going to give up on the designated area as well? In that case, even if I comeback and get the W, there’s no point in it.”<span class=\"pg\">p.237<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “She’s incredibly powerful. You might regret it later, is that okay?”<span class=\"pg\">p.238<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What? Are you saying that I’ll lose?”<span class=\"pg\">p.238<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “She’s a formidable opponent.”<span class=\"pg\">p.238<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don’t see me losing to Ibuki-senpai at all.”<span class=\"pg\">p.238<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I have faith that I’m stronger.”<span class=\"pg\">p.238<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Who’s going to fight? Hurry up and decide~~”<span class=\"pg\">p.238<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I will fight her.”<span class=\"pg\">p.238<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “This is my fight. It’s none of your business.”<span class=\"pg\">p.238<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Talking about how strong your opponent is and now you’re messing around like this? Did you bang your head or something?”<span class=\"pg\">p.239<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’ve thought about it, and if you ask me, you can’t win against her.”<span class=\"pg\">p.239<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Stop joking around. Don’t decide before it even happens.”<span class=\"pg\">p.239<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That’s the truth. I couldn’t do anything, so there’s no way you can win against her.”<span class=\"pg\">p.239<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Then prove it, right here in front of me….”<span class=\"pg\">p.239<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What for?”<span class=\"pg\">p.239<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If you don’t want to lose, if you want to break this stalemate, show me your resolve. Form a group with me. If something happens to one of us and have to withdraw, the group will still survive. That’s the only way to effectively prevent the withdrawal.”<span class=\"pg\">p.239<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Are you kidding me? Why would I form a group with someone like you?”<span class=\"pg\">p.239<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Didn’t I just say? I need you to come to an understanding. If you haven’t yet, then don’t join this fight.”<span class=\"pg\">p.239<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So annoying…”<span class=\"pg\">p.239<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s alright if you don’t like it, but I’d like to rely on you if you’re going to join the fight.”<span class=\"pg\">p.239<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “This sucks. But it wouldn’t be much fun if you’ll be forced to drop out because of some 1st years.”<span class=\"pg\">p.239<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s not a bad strategy. If separate students form a group, it’s true that if something happens to one of them, they can still avoid being expelled.”<span class=\"pg\">p.241<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But there’s just one thing you thought incorrectly, Horikita-senpai.”<span class=\"pg\">p.241<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Incorrect? What exactly do you mean?”<span class=\"pg\">p.241<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s alright for one person to withdraw, which means, it’s okay for me to break one of you.”<span class=\"pg\">p.241<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Like before, we attack Amasawa-san at the same time. However, actually hitting her is of secondary importance. I want you to dodge her attacks, make sure not to get caught, and continue to attack.”<span class=\"pg\">p.245<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You are equal or stronger than me in terms of fighting, but that’s it. In other areas, we are not on the same level. You are not good at academics, you can’t lead your class, and you can’t cooperate with others. I don’t want to be mean, but calling yourself my rival is just you being narcissistic.”<span class=\"pg\">p.246<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ahhhhh, have I been exposed? My physique is actually unexpectedly weak then.”<span class=\"pg\">p.248<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I just had a fight, before I fought you senpais.”<span class=\"pg\">p.249<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Hah, hah…. Heheh, Amasawa…. I’ll admit that you’re strong, but it seems like your stamina isn’t infinite.”<span class=\"pg\">p.248<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ah! Ah!”<span class=\"pg\">p.248<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ah… That worked really well…”<span class=\"pg\">p.248<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Do you want to know who caused it? Could it be Housen-kun—?”<span class=\"pg\">p.249<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Sorry, but I can’t believe you. Who is it?”<span class=\"pg\">p.249<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Oi, what are you doing!”<span class=\"pg\">p.250<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…Yeah, I was too careless.”<span class=\"pg\">p.250<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It seems like it’s over. It’s a bit interesting, but it’s going to be a while again.”<span class=\"pg\">p.250<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What are you talking about?”<span class=\"pg\">p.251<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Where? Well, to the designated area i guess. After all, there’s still a special exam going on.”<span class=\"pg\">p.251<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ah, by the way, I don’t think you need to go after Ayanokouji-senpai anymore.”<span class=\"pg\">p.251<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…Why?”<span class=\"pg\">p.251<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s all over. If you think I’m lying, go ahead and see for yourself.”<span class=\"pg\">p.251<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What are you going to do? You going to go after Ayanokouji? That’s why you fought with Amasawa, right?”<span class=\"pg\">p.251<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yeah, I’ll go.”<span class=\"pg\">p.251<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Then I’ll go too.”<span class=\"pg\">p.251<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m thinking, if Ayanokouji’s in danger, I can taunt him next to you.”<span class=\"pg\">p.252<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You really are a bad person.”<span class=\"pg\">p.252<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> She turns defeat into a shared project; Ibuki joins the group-merge to save her own pride; together they feint-and-counter Amasawa; the first to crack is Amasawa&#x27;s stamina; Ibuki and she head to I2; she now knows someone already fought Amasawa before them.<span class=\"pg\">p.237–252<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ibuki Mio<\/b> Her momentary ally; the school hates them both; they fight together.<span class=\"pg\">p.237–252<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Amasawa Ichika<\/b> She knows about the earlier fight that left the bruise; Amasawa opens the path to I2 to watch them leave.<span class=\"pg\">p.237–252<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y2v4-p232-1\">← Before: Ch.6: Amasawa&#x27;s demonstration<\/button><\/div><\/article>"},{"i":"sc-yamada-albert-y2v4-p250-1","v":"y2v4","y":2,"o":19,"k":"","w":"yamada-albert","q":"yamada albert albert mentioned in passing named in the context of the exam  passing mention  not a distinct scene presence  passing mention only","h":"<article class=\"card\" id=\"sc-yamada-albert-y2v4-p250-1\"><h3><span class=\"ttl\"><a href=\"../../../people/yamada-albert.html#sc-yamada-albert-y2v4-p250-1\">Albert mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.250<\/span><span class=\"by\">notes on <a href=\"../../../people/yamada-albert.html\">Yamada Albert<\/a><\/span><\/h3><p class=\"setup\">Named in the context of the exam.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Passing mention; not a distinct scene presence.<span class=\"pg\">p.250<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Passing mention only.<span class=\"pg\">p.250<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamada-albert-y2v4-p177-1\">← Before: Ch.5: The ambusher in the 3-on-1<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v4-p252-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"tsukishiro shiba-katsunori kiryuin-fuuka sakayanagi-arisu amasawa-ichika ayanokouji-kiyotaka","q":"ayanokoji kiyotaka the showdown at i2  ayanokoji vs tsukishiro and shiba at i2 s tip  finds tsukishiro  in a sweater  and shiba waiting   tsukishiro s final trap to  bury  him  with no watch signal there   you have decided to take a very strong approach  acting director tsukishiro   you wouldn t call it unfair a two against one  right   i would have killed you now  but your reaction time is not normal    you are still a complicated person  acting director tsukishiro   it would have been easier if it was like a children s fight   let s solve this  acting director   you are an undeniable masterpiece   how did you know    tsukishiro  on the hidden stun gun  did you really try to expel me  fights the two adults  tsukishiro and shiba  both far stronger than their stated combat ratings   tsukishiro s  4  was disinformation  nearly overwhelmed in a 2 on 1 with kiryuin s help  she holds shiba  analyzes their timing  deduces tsukishiro s hidden stun gun from a glance at his feet  and beats him   targeting the nose to induce tears  then an uppercut  tsukishiro s last trump  a boat  is neutralized because ayanokoji had secretly called mashima and chabashira via sakayanagi s walkie talkie  reporting a class a and d student in danger  forcing their teachers to respond  defeats him in a one on one after seeing through his tricks  tsukishiro admits defeat but hints he hasn t shown everything  and delivers a message disqualifying amasawa from the white room  fights him alongside tsukishiro  held off by kiryuin  she appears  watch deliberately broken  and helps hold shiba    protect my kouhai  ayanokoji praises her  lent him the walkie talkie that saved him  tsukishiro s message disqualifies her for disobeying orders   free to stay or leave  ayanokoji doubts the white room matter is over","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v4-p252-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v4-p252-1\">The showdown at I2: Ayanokōji vs Tsukishiro and Shiba<\/a><\/span><span class=\"meta\">Y2V4 · p.252–272<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">At I2&#x27;s tip, finds Tsukishiro (in a sweater) and Shiba waiting — Tsukishiro&#x27;s final trap to “bury” him, with no watch signal there.<\/p><p class=\"with\">with <a href=\"../../../people/tsukishiro.html\">Tsukishiro<\/a> · <a href=\"../../../people/shiba-katsunori.html\">Shiba Katsunori<\/a> · <a href=\"../../../people/kiryuin-fuuka.html\">Kiryuin Fuuka<\/a> · <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a> · <a href=\"../../../people/amasawa-ichika.html\">Amasawa Ichika<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “You have decided to take a very strong approach, Acting Director Tsukishiro.”<span class=\"pg\">p.252<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Tsukishiro<\/b> “You wouldn&#x27;t call it unfair a two against one, right?”<span class=\"pg\">p.256<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Tsukishiro<\/b> “I would have killed you now, but your reaction time is not normal.”<span class=\"pg\">p.260<\/span><\/li><\/ul><details class=\"more\"><summary>12 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “...... You are still a complicated person, Acting Director Tsukishiro.”<span class=\"pg\">p.260<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It would have been easier if it was like a children&#x27;s fight.”<span class=\"pg\">p.261<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Let&#x27;s solve this, Acting Director.”<span class=\"pg\">p.265<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You are an undeniable masterpiece.”<span class=\"pg\">p.267<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “How did you know?” — Tsukishiro, on the hidden stun gun<span class=\"pg\">p.268<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Did you really try to expel me?”<span class=\"pg\">p.271<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Fights the two adults (Tsukishiro and Shiba, both far stronger than their stated combat ratings — Tsukishiro&#x27;s “4” was disinformation), nearly overwhelmed in a 2-on-1 with Kiryūin&#x27;s help (she holds Shiba); analyzes their timing, deduces Tsukishiro&#x27;s hidden stun gun from a glance at his feet, and beats him — targeting the nose to induce tears, then an uppercut. Tsukishiro&#x27;s last trump (a boat) is neutralized because Ayanokōji had secretly called Mashima and Chabashira via Sakayanagi&#x27;s walkie-talkie (reporting a Class A and D student in danger, forcing their teachers to respond).<span class=\"pg\">p.252–272<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsukishiro<\/b> Defeats him in a one-on-one after seeing through his tricks; Tsukishiro admits defeat but hints he hasn&#x27;t shown everything, and delivers a message disqualifying Amasawa from the White Room.<span class=\"pg\">p.252–272<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiba Katsunori<\/b> Fights him alongside Tsukishiro; held off by Kiryūin.<span class=\"pg\">p.256–270<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kiryuin Fuuka<\/b> She appears (watch deliberately broken) and helps hold Shiba — “protect my kouhai”; Ayanokōji praises her.<span class=\"pg\">p.261–272<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Lent him the walkie-talkie that saved him.<span class=\"pg\">p.269<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Amasawa Ichika<\/b> Tsukishiro&#x27;s message disqualifies her for disobeying orders — free to stay or leave; Ayanokōji doubts the White Room matter is over.<span class=\"pg\">p.272<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p231-1\">← Before: AK mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p276-1\">→ After: After the exam: Sakayanagi&#x27;s promise with Ryūen<\/button><\/div><\/article>"},{"i":"sc-ichinose-honami-y2v4-p252-1","v":"y2v4","y":2,"o":19,"k":"","w":"ichinose-honami","q":"ichinose honami ichinose mentioned in passing  it was designed so that even if ichinose hadn t come to me  i would have gone to the place    ayanokoji   but ichinose and nagumo could also be seen around here    ayanokoji   what happened to nagumo kun and ichinose san    tsukishiro   it was a mistake to threaten ichinose halfway  if you were going to do this you should have handled it thoroughly    ayanokoji","h":"<article class=\"card\" id=\"sc-ichinose-honami-y2v4-p252-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ichinose-honami.html#sc-ichinose-honami-y2v4-p252-1\">Ichinose mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.252–270<\/span><span class=\"by\">notes on <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/span><\/h3><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “it was designed so that even if Ichinose hadn&#x27;t come to me, I would have gone to the place.” — Ayanokōji.<span class=\"pg\">p.252<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “but Ichinose and Nagumo could also be seen around here.” — Ayanokōji.<span class=\"pg\">p.254<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “What happened to Nagumo-kun and Ichinose-san?” — Tsukishiro.<span class=\"pg\">p.255<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “It was a mistake to threaten Ichinose halfway. If you were going to do this you should have handled it thoroughly.” — Ayanokōji.<span class=\"pg\">p.270<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y2v4-p202-1\">← Before: Ichinose mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y2v4-p280-1\">→ After: Ichinose mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-shiba-katsunori-y2v4-p252-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"ayanokouji-kiyotaka tsukishiro kiryuin-fuuka shiba-katsunori","q":"shiba katsunori shiba and the i2 trap he waits at i2 s tip with tsukishiro   the final trap to  bury  ayanokoji where there s no watch signal   you have decided to take a very strong approach  acting director tsukishiro   i can t seem to do anything about it  this is the best option i can do     so what will happen to me after this   if possible  we would like you to follow our instructions and come on board with us  it would be a way to declare a voluntary withdrawal of ayanokouji kiyotaka  it would fit perfectly    do you think i would choose to go voluntarily to the ship   do you think i would choose to go voluntarily to the ship   certainly  if you re honest  you didn t have to come to an uninhabited island   if i used a weapon or something like that  it would be easy to take control here  but unfortunately  you are a valuable commodity  it is my duty to bring you back safe and sound  so i have decided that what i need is only my fists     so the only way to avoid expulsion is to take it   that is what is going to happen   what happened to nagumo kun and ichinose san   nagumo has stopped moving  and ichinose has already moved away  so there is nothing to worry about   you wouldn t call it unfair a two against one  right  after all  you are the best in the white room  i m even a little nervous about this     it s a good idea  but i m not sure it s the correct solution ayanokouji kun    you are still a complicated person  acting director tsukishiro   i would have killed you now  but your reaction time is not normal   it would have been easier if it was like a children s fight  purely fighting and fighting only with our strength and power  but we adults do not hesitate to take the best measures not to lose  even if it is something dirty  and it is not something well seen     how is your analysis going  ayanokouji kun    i wonder what the acting director and the classroom teacher do with a student in such a deserted place  what are they doing  i would love to hear about it   of course  as your senpai  shouldn t it be normal for me to protect my kouhai     if you can attract them for 1 second or 2 seconds  you are welcome   i ll tell you  i ll hold them for a minute or two at least  but ayanokouji  can t you show me more   i am a lady  what do you think      are you serious   even so  my position is still that of a priest  you know  i can t do such a disturbing thing  he is tsukishiro s partner   a class d first year teacher  combat 6  he waits in the back  his role is to hold ayanokoji from behind  kiryuin baits him  he holds back honestly to give tsukishiro the i2 duel  he accepts the loss with a quiet bow  strangely  i couldn t take it anymore  his superior  they fight together as a 2 on 1 against a student  she holds him off for a minute or two and declines to finish him  he takes her hold without crushing her  the student he was told to bury  he loses on points  not on will","h":"<article class=\"card\" id=\"sc-shiba-katsunori-y2v4-p252-1\"><h3><span class=\"ttl\"><a href=\"../../../people/shiba-katsunori.html#sc-shiba-katsunori-y2v4-p252-1\">Shiba and the I2 trap<\/a><\/span><span class=\"meta\">Y2V4 · p.252–272<\/span><span class=\"by\">notes on <a href=\"../../../people/shiba-katsunori.html\">Shiba Katsunori<\/a><\/span><\/h3><p class=\"setup\">He waits at I2&#x27;s tip with Tsukishiro — the final trap to “bury” Ayanokōji where there&#x27;s no watch signal.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/tsukishiro.html\">Tsukishiro<\/a> · <a href=\"../../../people/kiryuin-fuuka.html\">Kiryuin Fuuka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “You have decided to take a very strong approach, Acting Director Tsukishiro.”<span class=\"pg\">p.252<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Tsukishiro<\/b> “I can&#x27;t seem to do anything about it. This is the best option I can do. ”<span class=\"pg\">p.252<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “So what will happen to me after this?”<span class=\"pg\">p.252<\/span><\/li><\/ul><details class=\"more\"><summary>26 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “If possible, we would like you to follow our instructions and come on board with us. It would be a way to declare a voluntary withdrawal of Ayanokouji Kiyotaka, it would fit perfectly ”.<span class=\"pg\">p.253<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Do you think I would choose to go voluntarily to the ship?”<span class=\"pg\">p.253<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Do you think I would choose to go voluntarily to the ship?”<span class=\"pg\">p.253<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Certainly. If you&#x27;re honest, you didn&#x27;t have to come to an uninhabited island.”<span class=\"pg\">p.254<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If I used a weapon or something like that, it would be easy to take control here, but unfortunately, you are a valuable commodity. It is my duty to bring you back safe and sound, so I have decided that what I need is only my fists. ”<span class=\"pg\">p.254<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So the only way to avoid expulsion is to take it.”<span class=\"pg\">p.254<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That is what is going to happen”<span class=\"pg\">p.254<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What happened to Nagumo-kun and Ichinose-san?”<span class=\"pg\">p.255<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Nagumo has stopped moving, and Ichinose has already moved away, so there is nothing to worry about.”<span class=\"pg\">p.255<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You wouldn&#x27;t call it unfair a two against one, right? After all, you are the best in the White Room. I&#x27;m even a little nervous about this. ”<span class=\"pg\">p.256<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It&#x27;s a good idea, but I&#x27;m not sure it&#x27;s the correct solution Ayanokouji-kun.”<span class=\"pg\">p.258<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “...... You are still a complicated person, Acting Director Tsukishiro.”<span class=\"pg\">p.260<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I would have killed you now, but your reaction time is not normal.”<span class=\"pg\">p.260<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It would have been easier if it was like a children&#x27;s fight, purely fighting and fighting only with our strength and power. But we adults do not hesitate to take the best measures not to lose, even if it is something dirty, and it is not something well seen. ”<span class=\"pg\">p.261<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “How is your analysis going? Ayanokouji-kun ”<span class=\"pg\">p.261<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I wonder what the Acting Director and the classroom teacher do with a student in such a deserted place. What are they doing? I would love to hear about it”.<span class=\"pg\">p.262<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Of course. As your senpai, shouldn&#x27;t it be normal for me to protect my kouhai? ”<span class=\"pg\">p.263<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If you can attract them for 1 second or 2 seconds, you are welcome.”<span class=\"pg\">p.263<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;ll tell you. I&#x27;ll hold them for a minute or two at least. But Ayanokouji, can&#x27;t you show me more?”<span class=\"pg\">p.263<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I am a lady. What do you think? ”<span class=\"pg\">p.264<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “...... Are you serious?”<span class=\"pg\">p.265<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Even so, my position is still that of a priest, you know? I can&#x27;t do such a disturbing thing.”<span class=\"pg\">p.270<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> He is Tsukishiro&#x27;s partner — a Class D first-year teacher, combat 6; he waits in the back; his role is to hold Ayanokōji from behind; Kiryūin baits him; he holds back honestly to give Tsukishiro the I2 duel; he accepts the loss with a quiet bow (“Strangely, I couldn&#x27;t take it anymore”).<span class=\"pg\">p.252–272<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsukishiro<\/b> His superior; they fight together as a 2-on-1 against a student.<span class=\"pg\">p.252–272<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kiryuin Fuuka<\/b> She holds him off for a minute or two and declines to finish him; he takes her hold without crushing her.<span class=\"pg\">p.261–270<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> The student he was told to bury; he loses on points, not on will.<span class=\"pg\">p.252–272<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-shiba-katsunori-y2v4-p197-1\">← Before: Shiba mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-tsukishiro-y2v4-p252-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"ayanokouji-kiyotaka shiba-katsunori amasawa-ichika kiryuin-fuuka tsukishiro","q":"tsukishiro tsukishiro s final trap at i2  his defeat waits at i2 s tip with shiba for ayanokoji   the final trap to  bury  him where there s no watch signal   you wouldn t call it unfair a two against one  right  after all  you are the best in the   do not worry  it s only shiba and i who will fight against you   i would have killed you now  but your reaction time is not normal   it would have been easier if it was like a children s fight  purely fighting and fighting only with our strength and power   i admit it  considering that you are a second year high school boy in front of me  you are an undeniable masterpiece   i don t like being hard on people  but i m having a lot of fun   even so  my position is still that of a priest  you know   you are overestimating me  i did everything in my power to get you out of school according to the instructions of my superiors   amasawa ichika  you are disqualified for disobeying your orders   nothing has occurred here  ayanokouji kun and i just had a chat  the formidable  acting director    a skilled fighter who intentionally understated his combat rating  4  as disinformation  fights with shiba in a coordinated 2 on 1  uses a hidden stun gun and a waiting boat as trump cards  defeated by ayanokoji  with kiryuin s aid and teachers summoned  he concedes gracefully but implies he hasn t revealed everything  and declares amasawa disqualified from the white room  his target  acknowledges him as a  masterpiece  after losing  his accomplice in the trap  disqualifies her for disobeying orders    no more places to return to  third year who interrupts and holds shiba","h":"<article class=\"card\" id=\"sc-tsukishiro-y2v4-p252-1\"><h3><span class=\"ttl\"><a href=\"../../../people/tsukishiro.html#sc-tsukishiro-y2v4-p252-1\">Tsukishiro&#x27;s final trap at I2; his defeat<\/a><\/span><span class=\"meta\">Y2V4 · p.252–272<\/span><span class=\"by\">notes on <a href=\"../../../people/tsukishiro.html\">Tsukishiro<\/a><\/span><\/h3><p class=\"setup\">Waits at I2&#x27;s tip with Shiba for Ayanokōji — the final trap to “bury” him where there&#x27;s no watch signal.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/shiba-katsunori.html\">Shiba Katsunori<\/a> · <a href=\"../../../people/amasawa-ichika.html\">Amasawa Ichika<\/a> · <a href=\"../../../people/kiryuin-fuuka.html\">Kiryuin Fuuka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Tsukishiro<\/b> “You wouldn&#x27;t call it unfair a two against one, right? After all, you are the best in the”<span class=\"pg\">p.256<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Tsukishiro<\/b> “Do not worry. It&#x27;s only Shiba and I who will fight against you.”<span class=\"pg\">p.256<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Tsukishiro<\/b> “I would have killed you now, but your reaction time is not normal.”<span class=\"pg\">p.260<\/span><\/li><\/ul><details class=\"more\"><summary>12 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “It would have been easier if it was like a children&#x27;s fight, purely fighting and fighting only with our strength and power.”<span class=\"pg\">p.261<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I admit it, considering that you are a second year high school boy in front of me. You are an undeniable masterpiece.”<span class=\"pg\">p.267<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t like being hard on people, but I&#x27;m having a lot of fun.”<span class=\"pg\">p.267<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Even so, my position is still that of a priest, you know?”<span class=\"pg\">p.270<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You are overestimating me. I did everything in my power to get you out of school according to the instructions of my superiors.”<span class=\"pg\">p.271<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Amasawa Ichika, you are disqualified for disobeying your orders.”<span class=\"pg\">p.272<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Nothing has occurred here. Ayanokouji-kun and I just had a chat.”<span class=\"pg\">p.272<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> The formidable “acting director” — a skilled fighter who intentionally understated his combat rating (“4”) as disinformation, fights with Shiba in a coordinated 2-on-1, uses a hidden stun gun and a waiting boat as trump cards; defeated by Ayanokōji (with Kiryūin&#x27;s aid and teachers summoned), he concedes gracefully but implies he hasn&#x27;t revealed everything, and declares Amasawa disqualified from the White Room.<span class=\"pg\">p.252–272<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> His target; acknowledges him as a “masterpiece” after losing.<span class=\"pg\">p.252–272<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiba Katsunori<\/b> His accomplice in the trap.<span class=\"pg\">p.252–270<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Amasawa Ichika<\/b> Disqualifies her for disobeying orders — “no more places to return to.”<span class=\"pg\">p.272<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kiryuin Fuuka<\/b> Third-year who interrupts and holds Shiba.<span class=\"pg\">p.261–270<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsukishiro-y2v4-p191-1\">← Before: Tsukishiro mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-tsukishiro-y2v4-p278-1\">→ After: Tsukishiro after the fight<\/button><\/div><\/article>"},{"i":"sc-amasawa-ichika-y2v4-p253-1","v":"y2v4","y":2,"o":19,"k":"","w":"amasawa-ichika","q":"amasawa ichika ch 6 epilogue  the i2 aftermath  mention records   due to the fact that he had no contact with us  perhaps he was an amasawa watchdog    ayanokoji s read of shiba   so  regarding unplanned actions  amasawa seems to be blocking the movement    tsukishiro   it did not seem that amasawa ally with acting director tsukishiro    ayanokoji   may i ask you to give a message to amasawa san    ayanokoji to tsukishiro   amasawa ichika  you are disqualified for disobeying your orders  there will be no more places to return to    tsukishiro   i also found out that amasawa ichika is a white room student    ayanokoji   there is no way of knowing if this is a coordinated strategy or if amasawa is acting alone    ayanokoji","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v4-p253-1\"><h3><span class=\"ttl\"><a href=\"../../../people/amasawa-ichika.html#sc-amasawa-ichika-y2v4-p253-1\">Ch.6–Epilogue: The I2 aftermath (mention records)<\/a><\/span><span class=\"meta\">Y2V4 · p.253–282<\/span><span class=\"by\">notes on <a href=\"../../../people/amasawa-ichika.html\">Amasawa Ichika<\/a><\/span><\/h3><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “Due to the fact that he had no contact with us, perhaps he was an Amasawa watchdog.” — Ayanokōji&#x27;s read of Shiba.<span class=\"pg\">p.253<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “So, regarding unplanned actions, Amasawa seems to be blocking the movement.” — Tsukishiro.<span class=\"pg\">p.255<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “it did not seem that Amasawa ally with Acting Director Tsukishiro.” — Ayanokōji.<span class=\"pg\">p.256<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “May I ask you to give a message to Amasawa-san” — Ayanokōji to Tsukishiro.<span class=\"pg\">p.271<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Amasawa Ichika, you are disqualified for disobeying your orders. There will be no more places to return to.” — Tsukishiro.<span class=\"pg\">p.272<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “I also found out that Amasawa Ichika is a White Room student.” — Ayanokōji.<span class=\"pg\">p.282<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “There is no way of knowing if this is a coordinated strategy or if Amasawa is acting alone” — Ayanokōji.<span class=\"pg\">p.282<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v4-p237-1\">← Before: Ch.6: The 2-on-1; the decision to let them pass<\/button><\/div><\/article>"},{"i":"sc-nagumo-miyabi-y2v4-p254-1","v":"y2v4","y":2,"o":19,"k":"","w":"nagumo-miyabi","q":"nagumo miyabi nagumo mentioned in passing  nagumo has stopped moving  and ichinose has already moved away  so there is nothing to worry about    tsukishiro   what happened to nagumo kun and ichinose san    tsukishiro asks shiba","h":"<article class=\"card\" id=\"sc-nagumo-miyabi-y2v4-p254-1\"><h3><span class=\"ttl\"><a href=\"../../../people/nagumo-miyabi.html#sc-nagumo-miyabi-y2v4-p254-1\">Nagumo mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.254–255<\/span><span class=\"by\">notes on <a href=\"../../../people/nagumo-miyabi.html\">Nagumo Miyabi<\/a><\/span><\/h3><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “Nagumo has stopped moving, and Ichinose has already moved away, so there is nothing to worry about.” — Tsukishiro.<span class=\"pg\">p.254<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “What happened to Nagumo-kun and Ichinose-san?” — Tsukishiro asks Shiba.<span class=\"pg\">p.255<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y2v4-p201-1\">← Before: Ch.6: The beach talk; he gets knocked out<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y2v4-p273-1\">→ After: Nagumo mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-chabashira-sae-y2v4-p268-1","v":"y2v4","y":2,"o":19,"k":"","w":"chabashira-sae","q":"chabashira sae chabashira and the boat  if you look closely at the end of the small boat  you could see mashima sensei and chabashira sensei  and that s how tsukishiro found out    narration   if they had checked all the students by gps  would the rescue have arrived and changed the situation  now  from the map  you can see that a student from class a and another from class d from the second year have lost the gps response of their watches  i think it was more of a question of trust      tsukishiro notes the rescue was inevitable   in the end  the boat landed and mashima sensei and chabashirasensei got off    narration   nothing has occurred here  ayanokouji kun and i just had a chat    tsukishiro to the teachers  the fight is made invisible by him","h":"<article class=\"card\" id=\"sc-chabashira-sae-y2v4-p268-1\"><h3><span class=\"ttl\"><a href=\"../../../people/chabashira-sae.html#sc-chabashira-sae-y2v4-p268-1\">Chabashira and the boat<\/a><\/span><span class=\"meta\">Y2V4 · p.268–272<\/span><span class=\"by\">notes on <a href=\"../../../people/chabashira-sae.html\">Chabashira Sae<\/a><\/span><\/h3><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “If you look closely at the end of the small boat, you could see Mashima-sensei and Chabashira-sensei. And that&#x27;s how Tsukishiro found out.” — narration.<span class=\"pg\">p.268<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “If they had checked all the students by GPS, would the rescue have arrived and changed the situation? Now, from the map, you can see that a student from class A and another from class D from the second year have lost the GPS response of their watches. I think it was more of a question of trust. ” — Tsukishiro notes the rescue was inevitable.<span class=\"pg\">p.269<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “In the end, the boat landed and Mashima-sensei and Chabashirasensei got off.” — narration.<span class=\"pg\">p.270<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Nothing has occurred here. Ayanokouji-kun and I just had a chat.” — Tsukishiro to the teachers; the fight is made invisible by him.<span class=\"pg\">p.272<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-chabashira-sae-y2v4-p271-1\">→ After: Chabashira and the rescue<\/button><\/div><\/article>"},{"i":"sc-mashima-tomonari-y2v4-p268-1","v":"y2v4","y":2,"o":19,"k":"","w":"mashima-tomonari","q":"mashima tomonari mashima lands the rescue boat  if you look closely at the end of the small boat  you could see mashima sensei and chabashira sensei  and that s how tsukishiro found out    narration   when you find out that it is the 2nd a class and the 2nd d class  you have no choice but to bring your class teacher  even if you don t want to    narration  the teachers are brought in because of the broken watch rule   i was watching the fight between shiba and her  although it was out of the corner of my eye and she could hold out well  even if she only defended herself    narration   in the end  the boat landed and mashima sensei and chabashirasensei got off    narration","h":"<article class=\"card\" id=\"sc-mashima-tomonari-y2v4-p268-1\"><h3><span class=\"ttl\"><a href=\"../../../people/mashima-tomonari.html#sc-mashima-tomonari-y2v4-p268-1\">Mashima lands the rescue boat<\/a><\/span><span class=\"meta\">Y2V4 · p.268–272<\/span><span class=\"by\">notes on <a href=\"../../../people/mashima-tomonari.html\">Mashima Tomonari<\/a><\/span><\/h3><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “If you look closely at the end of the small boat, you could see Mashima-sensei and Chabashira-sensei. And that&#x27;s how Tsukishiro found out.” — narration.<span class=\"pg\">p.268<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “When you find out that it is the 2nd A class and the 2nd D class, you have no choice but to bring your class teacher, even if you don&#x27;t want to.” — narration; the teachers are brought in because of the broken-watch rule.<span class=\"pg\">p.269<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “I was watching the fight between Shiba and her, although it was out of the corner of my eye and she could hold out well, even if she only defended herself.” — narration.<span class=\"pg\">p.270<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “In the end, the boat landed and Mashima-sensei and Chabashirasensei got off.” — narration.<span class=\"pg\">p.270<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-mashima-tomonari-y2v4-p271-1\">→ After: Mashima lands the rescue<\/button><\/div><\/article>"},{"i":"sc-chabashira-sae-y2v4-p271-1","v":"y2v4","y":2,"o":19,"k":"","w":"chabashira-sae","q":"chabashira sae chabashira and the rescue  nothing has occurred here  ayanokouji kun and i just had a chat    tsukishiro to the teachers  the boat crew includes chabashira sensei","h":"<article class=\"card\" id=\"sc-chabashira-sae-y2v4-p271-1\"><h3><span class=\"ttl\"><a href=\"../../../people/chabashira-sae.html#sc-chabashira-sae-y2v4-p271-1\">Chabashira and the rescue<\/a><\/span><span class=\"meta\">Y2V4 · p.271<\/span><span class=\"by\">notes on <a href=\"../../../people/chabashira-sae.html\">Chabashira Sae<\/a><\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “Nothing has occurred here. Ayanokouji-kun and I just had a chat.” — Tsukishiro to the teachers; the boat crew includes Chabashira-sensei.<span class=\"pg\">p.271<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-chabashira-sae-y2v4-p268-1\">← Before: Chabashira and the boat<\/button><\/div><\/article>"},{"i":"sc-mashima-tomonari-y2v4-p271-1","v":"y2v4","y":2,"o":19,"k":"","w":"mashima-tomonari","q":"mashima tomonari mashima lands the rescue  in the end  the boat landed and mashima sensei and chabashirasensei got off    narration   then let s go  the students haven t finished their special exams yet    mashima chabashira head to the ship","h":"<article class=\"card\" id=\"sc-mashima-tomonari-y2v4-p271-1\"><h3><span class=\"ttl\"><a href=\"../../../people/mashima-tomonari.html#sc-mashima-tomonari-y2v4-p271-1\">Mashima lands the rescue<\/a><\/span><span class=\"meta\">Y2V4 · p.271–272<\/span><span class=\"by\">notes on <a href=\"../../../people/mashima-tomonari.html\">Mashima Tomonari<\/a><\/span><\/h3><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “In the end, the boat landed and Mashima-sensei and Chabashirasensei got off.” — narration.<span class=\"pg\">p.271<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Then let&#x27;s go. The students haven&#x27;t finished their special exams yet.” — Mashima/Chabashira head to the ship.<span class=\"pg\">p.272<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-mashima-tomonari-y2v4-p268-1\">← Before: Mashima lands the rescue boat<\/button><\/div><\/article>"},{"i":"sc-nagumo-miyabi-y2v4-p273-1","v":"y2v4","y":2,"o":19,"k":"","w":"nagumo-miyabi","q":"nagumo miyabi nagumo mentioned in passing  miyabi nagumo was no longer there    ayanokoji","h":"<article class=\"card\" id=\"sc-nagumo-miyabi-y2v4-p273-1\"><h3><span class=\"ttl\"><a href=\"../../../people/nagumo-miyabi.html#sc-nagumo-miyabi-y2v4-p273-1\">Nagumo mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.273<\/span><span class=\"by\">notes on <a href=\"../../../people/nagumo-miyabi.html\">Nagumo Miyabi<\/a><\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “Miyabi Nagumo was no longer there.” — Ayanokōji.<span class=\"pg\">p.273<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y2v4-p254-1\">← Before: Nagumo mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y2v4-p279-1\">→ After: Nagumo mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v4-p276-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"ryuuen-kakeru sakayanagi-arisu ayanokouji-kiyotaka","q":"ayanokoji kiyotaka after the exam  sakayanagi s promise with ryuen back on the ship after two weeks  learns the bottom five groups were notified in advance  so they can pay to avoid expulsion  on deck sees ryuen  face covered in scars from hosen  and sakayanagi talking   i m sorry to interrupt you  but don t forget the promise you made to me  okay  and some money   of course  ryuuen kun  please tell me when the time comes   promise  learns sakayanagi promised ryuen a favor if he asked   which is why he confronted hosen  the wish is  like strangling yourself in the near future   a dangerous promise  realizes this explains ryuen s cooperation  she explains the promise to ryuen and thanks ayanokoji for the gps timing help  looks forward to a future rematch  collected on his promise from sakayanagi  both he and hosen were removed for treatment","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v4-p276-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v4-p276-1\">After the exam: Sakayanagi&#x27;s promise with Ryūen<\/a><\/span><span class=\"meta\">Y2V4 · p.276–278<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Back on the ship after two weeks; learns the bottom five groups were notified in advance (so they can pay to avoid expulsion); on deck sees Ryūen (face covered in scars from Hōsen) and Sakayanagi talking.<\/p><p class=\"with\">with <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> “I&#x27;m sorry to interrupt you, but don&#x27;t forget the promise you made to me, okay? And some money.”<span class=\"pg\">p.276<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sakayanagi Arisu<\/b> “Of course, Ryuuen-kun. Please tell me when the time comes.”<span class=\"pg\">p.277<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Promise?”<span class=\"pg\">p.276<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Inference, not stated<\/span> Learns Sakayanagi promised Ryūen a favor if he asked — which is why he confronted Hōsen; the wish is “like strangling yourself in the near future” (a dangerous promise); realizes this explains Ryūen&#x27;s cooperation.<span class=\"pg\">p.277<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> She explains the promise to Ryūen and thanks Ayanokōji for the GPS-timing help; looks forward to a future rematch.<span class=\"pg\">p.277–278<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Collected on his promise from Sakayanagi; both he and Hōsen were removed for treatment.<span class=\"pg\">p.276–277<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p252-1\">← Before: The showdown at I2: Ayanokōji vs Tsukishiro and Shiba<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p278-1\">→ After: Results: 15 third-years expelled; Kōenji wins 1st<\/button><\/div><\/article>"},{"i":"sc-sakayanagi-arisu-y2v4-p276-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"ryuuen-kakeru ayanokouji-kiyotaka sakayanagi-arisu","q":"sakayanagi arisu sakayanagi s promise  3rd place  of course  ryuuen kun  please tell me when the time comes   i told him that if he asked me for a favor  i would grant it to him   that wish is like strangling yourself in the near future   i get it  ayanokouji kun now wants to lead a quiet life as much as possible   do not rush  we still have almost a year and a half of school life left  made a dangerous open ended promise to ryuen  a favor that may strangle the asker  which secured his help against hosen  placed 3rd with her seven member group  261 pts  having kept her members clear of the dangerous assignments  thanks ayanokoji and looks forward to a future rematch  telling him not to rush  her promise bought his cooperation against hosen  thanks him for the gps timing help  promises a future chance to compete","h":"<article class=\"card\" id=\"sc-sakayanagi-arisu-y2v4-p276-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sakayanagi-arisu.html#sc-sakayanagi-arisu-y2v4-p276-1\">Sakayanagi&#x27;s promise; 3rd place<\/a><\/span><span class=\"meta\">Y2V4 · p.276–278<\/span><span class=\"by\">notes on <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Sakayanagi Arisu<\/b> “Of course, Ryuuen-kun. Please tell me when the time comes.”<span class=\"pg\">p.277<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sakayanagi Arisu<\/b> “I told him that if he asked me for a favor, I would grant it to him.”<span class=\"pg\">p.277<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sakayanagi Arisu<\/b> “that wish is like strangling yourself in the near future.”<span class=\"pg\">p.277<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “I get it. Ayanokouji-kun now wants to lead a quiet life as much as possible.”<span class=\"pg\">p.278<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Do not rush. We still have almost a year and a half of school life left.”<span class=\"pg\">p.278<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Made a dangerous open-ended promise to Ryūen (a favor that may strangle the asker), which secured his help against Hōsen; placed 3rd with her seven-member group (261 pts), having kept her members clear of the dangerous assignments; thanks Ayanokōji and looks forward to a future rematch, telling him not to rush.<span class=\"pg\">p.276–278<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Her promise bought his cooperation against Hōsen.<span class=\"pg\">p.276–277<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Thanks him for the GPS-timing help; promises a future chance to compete.<span class=\"pg\">p.277–278<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sakayanagi-arisu-y2v4-p191-1\">← Before: Sakayanagi mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v4-p278-1","v":"y2v4","y":2,"o":19,"k":"","w":"hirata-yousuke kouenji-rokusuke nagumo-miyabi ayanokouji-kiyotaka","q":"ayanokoji kiyotaka results  15 third years expelled  koenji wins 1st class d gathers to eat  hirata notes with heartfelt relief that no second year class d group was absent and everyone is present   key to avoiding expulsion  at 8 p m  sasaki announces 13 students dropped out but no group was entirely absent  the five withdrawn groups are all third years  3 d mutou  3 d kawakami  3 c shinonome  3 c katsumata  3 b mikitani    15 students expelled  shocking everyone  nagumo failed to save them  tsukishiro  calm despite the fight  announces  3rd sakayanagi s seven member group  261 pts  2nd nagumo  325 pts  1st koenji alone  327 pts    a 2 point margin  koenji gains 300 class points  1 million private points and a protection point  and is granted immunity until graduation  notes koenji s feat of winning alone under the harshest conditions  wonders if nagumo s walkie talkie partner s voice  which he didn t answer  would have reversed 1st 2nd   but it can t be known  relieved all of class d survived  wins first place alone  ayanokoji acknowledges it  and horikita celebrates the 300 class points toward class a  takes 2nd  his failure to answer his partner s walkie talkie may have cost him 1st","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v4-p278-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v4-p278-1\">Results: 15 third-years expelled; Kōenji wins 1st<\/a><\/span><span class=\"meta\">Y2V4 · p.278–282<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Class D gathers to eat; Hirata notes with heartfelt relief that no second-year Class D group was absent and everyone is present — key to avoiding expulsion.<\/p><p class=\"with\">with <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a> · <a href=\"../../../people/kouenji-rokusuke.html\">Kōenji Rokusuke<\/a> · <a href=\"../../../people/nagumo-miyabi.html\">Nagumo Miyabi<\/a><\/p><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Detail<\/span> At 8 p.m., Sasaki announces 13 students dropped out but no group was entirely absent; the five withdrawn groups are all third-years (3-D Mutou, 3-D Kawakami, 3-C Shinonome, 3-C Katsumata, 3-B Mikitani) — 15 students expelled, shocking everyone (Nagumo failed to save them).<span class=\"pg\">p.279<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> Tsukishiro (calm despite the fight) announces: 3rd Sakayanagi&#x27;s seven-member group (261 pts), 2nd Nagumo (325 pts), 1st Kōenji alone (327 pts) — a 2-point margin; Kōenji gains 300 class points, 1 million private points and a Protection Point, and is granted immunity until graduation.<span class=\"pg\">p.280–281<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Notes Kōenji&#x27;s feat of winning alone under the harshest conditions; wonders if Nagumo&#x27;s walkie-talkie partner&#x27;s voice (which he didn&#x27;t answer) would have reversed 1st/2nd — but it can&#x27;t be known.<span class=\"pg\">p.281–282<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Relieved all of Class D survived.<span class=\"pg\">p.278<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> Wins first place alone; Ayanokōji acknowledges it, and Horikita celebrates the 300 class points toward Class A.<span class=\"pg\">p.281–282<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> Takes 2nd; his failure to answer his partner&#x27;s walkie-talkie may have cost him 1st.<span class=\"pg\">p.281–282<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p276-1\">← Before: After the exam: Sakayanagi&#x27;s promise with Ryūen<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p282-1\">→ After: Closing: Amasawa&#x27;s side, lingering mysteries<\/button><\/div><\/article>"},{"i":"sc-hirata-yousuke-y2v4-p278-1","v":"y2v4","y":2,"o":19,"k":"","w":"hirata-yousuke","q":"hirata yosuke hirata mentioned in passing named in the context of the exam results  passing mention  not a distinct scene presence  passing mention only","h":"<article class=\"card\" id=\"sc-hirata-yousuke-y2v4-p278-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hirata-yousuke.html#sc-hirata-yousuke-y2v4-p278-1\">Hirata mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.278<\/span><span class=\"by\">notes on <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a><\/span><\/h3><p class=\"setup\">Named in the context of the exam results.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Passing mention; not a distinct scene presence.<span class=\"pg\">p.278<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Passing mention only.<span class=\"pg\">p.278<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-sakura-airi-y2v4-p278-1","v":"y2v4","y":2,"o":19,"k":"","w":"sakura-airi","q":"sakura airi sakura airi mentioned in passing  if we re all here  it means that haruka and airi s group were safe too    hirata s interior  the second year class d line held   airi  is printed on this page and is not otherwise identified on this page  identity attribution to sakura airi is plausible but not printed  kept as an unassigned mention","h":"<article class=\"card\" id=\"sc-sakura-airi-y2v4-p278-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sakura-airi.html#sc-sakura-airi-y2v4-p278-1\">Sakura Airi mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.278<\/span><span class=\"by\">notes on <a href=\"../../../people/sakura-airi.html\">Sakura Airi<\/a><\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “If we&#x27;re all here, it means that Haruka and Airi&#x27;s group were safe too.” — Hirata&#x27;s interior; the second-year Class D line held; &quot;Airi&quot; is printed on this page and is not otherwise identified on this page; identity attribution to Sakura Airi is plausible but not printed; kept as an unassigned mention.<span class=\"pg\">p.278<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sakura-airi-y2v4-p160-1\">← Before: Sakura not present<\/button><\/div><\/article>"},{"i":"sc-tsukishiro-y2v4-p278-1","v":"y2v4","y":2,"o":19,"k":"","w":"tsukishiro","q":"tsukishiro tsukishiro after the fight from what ayanokoji can see  the only crew member on the boat is the pilot   the trap is dead weight now  at 8 p m  sasaki announces the results  the five withdrawn groups are all third years   15 students expelled  tsukishiro is calm despite the beating he took at i2  tsukishiro announces  3rd place   sakayanagi s seven member group  261 points  2nd place   nagumo  325 points  1st place   koenji  alone  327 points  a 2 point margin","h":"<article class=\"card\" id=\"sc-tsukishiro-y2v4-p278-1\"><h3><span class=\"ttl\"><a href=\"../../../people/tsukishiro.html#sc-tsukishiro-y2v4-p278-1\">Tsukishiro after the fight<\/a><\/span><span class=\"meta\">Y2V4 · p.278–280<\/span><span class=\"by\">notes on <a href=\"../../../people/tsukishiro.html\">Tsukishiro<\/a><\/span><\/h3><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> From what Ayanokōji can see, the only crew member on the boat is the pilot — the trap is dead weight now.<span class=\"pg\">p.278<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> At 8 p.m., Sasaki announces the results; the five withdrawn groups are all third-years — 15 students expelled; Tsukishiro is calm despite the beating he took at I2.<span class=\"pg\">p.279<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Tsukishiro announces: 3rd place — Sakayanagi’s seven-member group, 261 points; 2nd place — Nagumo, 325 points; 1st place — Kōenji, alone, 327 points; a 2-point margin.<span class=\"pg\">p.280–281<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsukishiro-y2v4-p252-1\">← Before: Tsukishiro&#x27;s final trap at I2; his defeat<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-tsukishiro-y2v4-p282-1\">→ After: Tsukishiro mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-mikitani-y2v4-p279-1","v":"y2v4","y":2,"o":19,"k":"","w":"mikitani","q":"mikitani mikitani expelled with the third years  the 3rd d mutou class  the 3rd d kawakami class  the 3rd c shinonome class  the 3rd c katsumata class  and the 3rd b mikitani class  for a total of 15 people","h":"<article class=\"card\" id=\"sc-mikitani-y2v4-p279-1\"><h3><span class=\"ttl\"><a href=\"../../../people/mikitani.html#sc-mikitani-y2v4-p279-1\">Mikitani expelled with the third-years<\/a><\/span><span class=\"meta\">Y2V4 · p.279<\/span><span class=\"by\">notes on <a href=\"../../../people/mikitani.html\">Mikitani<\/a><\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “The 3rd D Mutou class, the 3rd D Kawakami class, the 3rd C Shinonome class, the 3rd C Katsumata class, and the 3rd B Mikitani class. For a total of 15 people.”<span class=\"pg\">p.279<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-mikitani-y2v4-p109-1\">← Before: The end of the plan<\/button><\/div><\/article>"},{"i":"sc-nagumo-miyabi-y2v4-p279-1","v":"y2v4","y":2,"o":19,"k":"","w":"nagumo-miyabi","q":"nagumo miyabi nagumo mentioned in passing  they had assumed that nagumo would be the one to rescue them  i also thought that however    narration   2nd place  2nd year group class a nagumo miyabi  325 points    the results announcement   today i remember the figure of miyabi nagumo who took the trouble to    ayanokoji","h":"<article class=\"card\" id=\"sc-nagumo-miyabi-y2v4-p279-1\"><h3><span class=\"ttl\"><a href=\"../../../people/nagumo-miyabi.html#sc-nagumo-miyabi-y2v4-p279-1\">Nagumo mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.279–282<\/span><span class=\"by\">notes on <a href=\"../../../people/nagumo-miyabi.html\">Nagumo Miyabi<\/a><\/span><\/h3><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “They had assumed that Nagumo would be the one to rescue them. I also thought that...however...” — narration.<span class=\"pg\">p.279<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “2nd place, 2nd year Group Class A Nagumo Miyabi. 325 points” — the results announcement.<span class=\"pg\">p.281<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Today I remember the figure of Miyabi Nagumo who took the trouble to...” — Ayanokōji.<span class=\"pg\">p.282<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nagumo-miyabi-y2v4-p273-1\">← Before: Nagumo mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-sasaki-y2v4-p279-1","v":"y2v4","y":2,"o":19,"k":"","w":"sasaki","q":"sasaki sasaki announces the exam results named only   the class 3 a teacher calls the students to order and announces the results  including the list of students ranking in the bottom fifteen","h":"<article class=\"card\" id=\"sc-sasaki-y2v4-p279-1\"><h3><span class=\"ttl\">Sasaki announces the exam results<\/span><span class=\"meta\">Y2V4 · p.279<\/span><span class=\"by\">notes on <a href=\"../../../people/index.html#sasaki\">Sasaki<\/a><\/span><\/h3><p class=\"setup\">Named only — the Class 3-A teacher calls the students to order and announces the results, including the list of students ranking in the bottom fifteen.<\/p><\/article>"},{"i":"sc-ichinose-honami-y2v4-p280-1","v":"y2v4","y":2,"o":19,"k":"","w":"ichinose-honami","q":"ichinose honami ichinose mentioned in passing  on the last day  ichinose left the team in the middle of the tournament  but the effect was not so serious    narration","h":"<article class=\"card\" id=\"sc-ichinose-honami-y2v4-p280-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ichinose-honami.html#sc-ichinose-honami-y2v4-p280-1\">Ichinose mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.280<\/span><span class=\"by\">notes on <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “on the last day, Ichinose left the team in the middle of the tournament, but the effect was not so serious.” — narration.<span class=\"pg\">p.280<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y2v4-p252-1\">← Before: Ichinose mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-katsuragi-kouhei-y2v4-p280-1","v":"y2v4","y":2,"o":19,"k":"","w":"katsuragi-kouhei","q":"katsuragi kohei katsuragi mentioned in passing the results  3rd place   sakayanagi s seven member group  261 points  2nd place   nagumo  325  1st place   koenji alone  327","h":"<article class=\"card\" id=\"sc-katsuragi-kouhei-y2v4-p280-1\"><h3><span class=\"ttl\"><a href=\"../../../people/katsuragi-kouhei.html#sc-katsuragi-kouhei-y2v4-p280-1\">Katsuragi mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.280<\/span><span class=\"by\">notes on <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a><\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> The results: 3rd place — Sakayanagi’s seven-member group, 261 points; 2nd place — Nagumo, 325; 1st place — Kōenji alone, 327.<span class=\"pg\">p.280<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-katsuragi-kouhei-y2v4-p183-1\">← Before: Katsuragi mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-kouenji-rokusuke-y2v4-p281-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"horikita-suzune nagumo-miyabi kouenji-rokusuke","q":"koenji rokusuke koenji wins first place alone announced 1st place with 327 points  just 2 ahead of nagumo    the only group to win alone  hailed by all students   you really have done it  kouenji kun   i m sure you understand  right   yes  that s right  now let s go up again    do not say foolishness    horikita wins first alone under the harshest conditions  gaining 300 class points  1 million private points and a protection point  as promised he s granted immunity until graduation  do whatever he wanted  remains utterly self focused  already talking of ascending again  while horikita celebrates the 300 points toward reaching class a and warns him not to cause trouble this month  his class leader   their deal grants him freedom  she celebrates the class points but rebukes his  foolishness  beat him by 2 points","h":"<article class=\"card\" id=\"sc-kouenji-rokusuke-y2v4-p281-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kouenji-rokusuke.html#sc-kouenji-rokusuke-y2v4-p281-1\">Kōenji wins first place alone<\/a><\/span><span class=\"meta\">Y2V4 · p.281–282<\/span><span class=\"by\">notes on <a href=\"../../../people/kouenji-rokusuke.html\">Kōenji Rokusuke<\/a><\/span><\/h3><p class=\"setup\">Announced 1st place with 327 points (just 2 ahead of Nagumo) — the only group to win alone, hailed by all students.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/nagumo-miyabi.html\">Nagumo Miyabi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “You really have done it, Kouenji-kun.”<span class=\"pg\">p.281<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kōenji Rokusuke<\/b> “I&#x27;m sure you understand, right?”<span class=\"pg\">p.281<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kōenji Rokusuke<\/b> “Yes, that&#x27;s right. Now let&#x27;s go up again.”<span class=\"pg\">p.282<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “... Do not say foolishness.” — Horikita<span class=\"pg\">p.282<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Wins first alone under the harshest conditions, gaining 300 class points, 1 million private points and a Protection Point; as promised he&#x27;s granted immunity until graduation (“do whatever he wanted”); remains utterly self-focused, already talking of ascending again, while Horikita celebrates the 300 points toward reaching Class A and warns him not to cause trouble this month.<span class=\"pg\">p.281–282<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> His class leader — their deal grants him freedom; she celebrates the class points but rebukes his “foolishness.”<span class=\"pg\">p.281–282<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> Beat him by 2 points.<span class=\"pg\">p.281<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kouenji-rokusuke-y2v4-p205-1\">← Before: Kōenji mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v4-p282-1","v":"y2v4","y":2,"o":19,"k":"","w":"amasawa-ichika tsukishiro ayanokouji-kiyotaka","q":"ayanokoji kiyotaka closing  amasawa s side  lingering mysteries no second year was expelled   a  miraculous  summer survived  confirms amasawa ichika is a white room student who now seems to be on his side  not tsukishiro s  though whether coordinated or betrayal is unknown  notes unresolved mysteries and that the summer may not end quietly  revealed as a white room student  apparently now his ally  his opponent   the white room threat isn t over","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v4-p282-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v4-p282-1\">Closing: Amasawa&#x27;s side, lingering mysteries<\/a><\/span><span class=\"meta\">Y2V4 · p.282<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/amasawa-ichika.html\">Amasawa Ichika<\/a> · <a href=\"../../../people/tsukishiro.html\">Tsukishiro<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> No second-year was expelled — a “miraculous” summer survived; confirms Amasawa Ichika is a White Room student who now seems to be on his side (not Tsukishiro&#x27;s), though whether coordinated or betrayal is unknown; notes unresolved mysteries and that the summer may not end quietly.<span class=\"pg\">p.282<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Amasawa Ichika<\/b> Revealed as a White Room student, apparently now his ally.<span class=\"pg\">p.282<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsukishiro<\/b> His opponent — the White Room threat isn&#x27;t over.<span class=\"pg\">p.282<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p278-1\">← Before: Results: 15 third-years expelled; Kōenji wins 1st<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p283-1\">→ After: AK mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-tsukishiro-y2v4-p282-1","v":"y2v4","y":2,"o":19,"k":"","w":"tsukishiro","q":"tsukishiro tsukishiro mentioned in passing  the battle against tsukishiro will end here for now  but the    the afterword  kept as printed","h":"<article class=\"card\" id=\"sc-tsukishiro-y2v4-p282-1\"><h3><span class=\"ttl\"><a href=\"../../../people/tsukishiro.html#sc-tsukishiro-y2v4-p282-1\">Tsukishiro mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.282–283<\/span><span class=\"by\">notes on <a href=\"../../../people/tsukishiro.html\">Tsukishiro<\/a><\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “The battle against Tsukishiro will end here for now, but the” — the afterword (kept as printed).<span class=\"pg\">p.282–283<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsukishiro-y2v4-p278-1\">← Before: Tsukishiro after the fight<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v4-p283-1","v":"y2v4","y":2,"o":19,"k":"","w":"ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ak mentioned in passing  there may or may not be changes in the love life of ayanokouji and the other    the closing monologue  kept as printed","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v4-p283-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v4-p283-1\">AK mentioned in passing<\/a><\/span><span class=\"meta\">Y2V4 · p.283<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “there may or may not be changes in the love life of Ayanokouji and the other” — the closing monologue (kept as printed).<span class=\"pg\">p.283<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v4-p282-1\">← Before: Closing: Amasawa&#x27;s side, lingering mysteries<\/button><\/div><\/article>"}];
